            if (!receipt.exists() || String(receipt.val()) !== payload) throw new Error('Team Leader account read-back did not match the requested state.');
            safeLocalRemove(PENDING_PREFIX + key);
            safeLocalRemove(PENDING_DELETE_PREFIX + key);
            safeLocalRemove(key);
            if (!fbKvCache) fbKvCache = {};
