            const namesByTeam = new Map([[TEAM_CWH, new Set()], [TEAM_ALBERTSONS, new Set()]]);
            for (const entry of entries) {
                if (!entry || !entry.id || !entry.team || !entry.name) throw new Error('The POD directory contains an invalid entry.');
                if (ids.has(entry.id)) throw new Error('The POD directory contains a duplicate internal POD ID.');
                ids.add(entry.id);
                const names = namesByTeam.get(entry.team) || new Set();
                const nameKey = normalizePodDirectoryName(entry.name).toLowerCase();
                if (names.has(nameKey)) throw new Error(`${entry.name} already exists in ${teamGroupById(entry.team).label}.`);
                names.add(nameKey);
                namesByTeam.set(entry.team, names);
            }
            for (const id of SYSTEM_POD_IDS) if (!ids.has(id)) throw new Error(`Protected system POD ${id} cannot be removed.`);
