            if (exact && exact.overrideKind === TODAY_SHIFT_ASSIGNMENT_KIND && exact.name === name && exact.date === dateStr && exact.pod === pod) return exact;
            const matches = Object.values(allShiftOverrides || {}).filter(item => item && item.overrideKind === TODAY_SHIFT_ASSIGNMENT_KIND && item.name === name && item.date === dateStr && item.pod === pod);
            matches.sort((a,b) => String(b.updatedAt || b.createdAt || '').localeCompare(String(a.updatedAt || a.createdAt || '')));
            return matches[0] || null;
