        function createBlobVersion() {
            return createMutationToken();
        }

        async function writeSharedBlobRemote(key, payload, version) {
            if (!fbDb) throw new Error('Live database is unavailable.');
            const vKey = BLOB_VERSION_KEYS[key];
            if (!vKey) throw new Error('Unknown shared-data key: ' + key);
            const kvRef = fbDb.ref('kv');
            const updates = {};
            updates[fbEncodeKey(key)] = payload;
            updates[fbEncodeKey(vKey)] = version;




            if (kvRef && typeof kvRef.update === 'function') {
                await withTimeout(
                    kvRef.update(updates),
                    FIREBASE_WRITE_TIMEOUT_MS,
                    'Timed out saving shared live data.'
                );
            } else {
                await withTimeout(
                    fbDb.ref('kv/' + fbEncodeKey(key)).set(payload),
                    FIREBASE_WRITE_TIMEOUT_MS,
                    'Timed out saving shared live data.'
                );
                await withTimeout(
                    fbDb.ref('kv/' + fbEncodeKey(vKey)).set(version),
                    FIREBASE_WRITE_TIMEOUT_MS,
                    'Timed out saving the shared-data version.'
                );
            }
        }

        async function saveBlobWithBackup(key, payload, options = {}) {
            const baseVersion = blobVersionVarGet(key);
            const newVersion = createBlobVersion();
            const vKey = BLOB_VERSION_KEYS[key];
            let previousPending = null;
            try { previousPending = JSON.parse(safeLocalGet(PENDING_PREFIX + key) || 'null'); } catch (e) {}
            const acceptedBaseVersions = Array.from(new Set([
                baseVersion,
                ...(previousPending && Array.isArray(previousPending.acceptedBaseVersions) ? previousPending.acceptedBaseVersions : []),
                previousPending && previousPending.baseVersion,
                previousPending && previousPending.targetVersion
            ].filter(value => value !== null && value !== undefined)));
            const pending = JSON.stringify({
                payload,
                baseVersion,
                targetVersion: newVersion,
                acceptedBaseVersions
            });

            safeLocalSet(PENDING_PREFIX + key, pending);
            markPendingMutation();
            safeLocalSet(key, payload);
            safeLocalSet(vKey, newVersion);
            safeLocalRemove(PENDING_DELETE_PREFIX + key);
            safeLocalRemove(PENDING_DELETE_PREFIX + vKey);
            publishUpdate();





            if (!fbDb || fbConnected === false) {
                return { localSaved:true, remoteSaved:false, queued:true, version:newVersion };
            }
            const remoteWrite = writeSharedBlobRemote(key, payload, newVersion).then(() => {
                const currentRaw = safeLocalGet(PENDING_PREFIX + key);
                let currentTarget = null;
                try { currentTarget = currentRaw ? JSON.parse(currentRaw).targetVersion : null; } catch (e) {}


                if (!currentRaw || currentTarget === newVersion) {
                    blobVersionVarSet(key, newVersion);
                    safeLocalRemove(PENDING_PREFIX + key);
                }
                if (fbConnected !== true) setLiveConnectionState(true, 'shared-write');
                return { localSaved:true, remoteSaved:true, queued:false, version:newVersion };
            }).catch((error) => {
                handleStorageError(error, 'shared-write-failed');
                return { localSaved:true, remoteSaved:false, queued:true, version:newVersion, error };
            });
            if (options && options.awaitRemote === true) return await remoteWrite;
            void remoteWrite;
            return { localSaved:true, remoteSaved:false, queued:true, version:newVersion };
        }

        async function readSharedBlobServerReceipt(key) {
            const vKey = BLOB_VERSION_KEYS[key];
            if (!fbDb || !vKey) throw new Error(`Live ${key} storage is unavailable.`);
            const [dataSnap, versionSnap] = await withTimeout(
                Promise.all([
                    fbDb.ref('kv/' + fbEncodeKey(key)).once('value'),
                    fbDb.ref('kv/' + fbEncodeKey(vKey)).once('value')
                ]),
                FIREBASE_READ_TIMEOUT_MS,
                `Timed out reading the live ${key} receipt.`
            );
            return {
                payload:dataSnap.exists() ? String(dataSnap.val()) : null,
                version:versionSnap.exists() ? String(versionSnap.val()) : null
            };
        }

        async function saveSharedBlobStrict(key, payload, options = {}) {
            const vKey = BLOB_VERSION_KEYS[key];
            if (!vKey) throw new Error('Unknown shared-data key: ' + key);
            if (!fbDb || fbConnected !== true) throw new Error(`A live Firebase connection is required to update ${key}.`);
            const before = await readSharedBlobServerReceipt(key);
            if (options.expectedVersion !== undefined && options.expectedVersion !== null && String(before.version || '') !== String(options.expectedVersion || '')) {
                throw new Error(`${key} changed on another session before this update. Refresh and try again.`);
            }
            const newVersion = createBlobVersion();
            await writeSharedBlobRemote(key, payload, newVersion);
            const receipt = await readSharedBlobServerReceipt(key);
            if (receipt.payload !== String(payload) || String(receipt.version || '') !== String(newVersion)) {
                throw new Error(`${key} write was not confirmed by an exact Firebase read-back.`);
            }
            blobVersionVarSet(key, newVersion);
            safeLocalSet(key, payload);
            safeLocalSet(vKey, newVersion);
            safeLocalRemove(PENDING_PREFIX + key);
            safeLocalRemove(PENDING_PREFIX + vKey);
            safeLocalRemove(PENDING_DELETE_PREFIX + key);
            safeLocalRemove(PENDING_DELETE_PREFIX + vKey);
            if (!fbKvCache) fbKvCache = {};
            fbKvCache[key] = payload;
            fbKvCache[vKey] = newVersion;
            lastServerConfirmedWriteAt = typeof getTrueNowMs === 'function' ? getTrueNowMs() : Date.now();
            publishUpdate();
            return { remoteSaved:true, queued:false, version:newVersion, previousVersion:before.version, receipt };
        }

