        function dedupeSurnameStubs(loaded) {
            const byPod = {};
            loaded.forEach(e => {
                const pod = e.pod || '';
                (byPod[pod] = byPod[pod] || []).push(e);
            });
            const toRemove = new Set();
            Object.values(byPod).forEach(group => {



                const hasCorrectedNerieGuigue = group.some(e =>
                    (e.pod || '') === 'POD 0' &&
                    (e.name || '').trim().toLowerCase() === 'nerie guigue'
                );
                if (hasCorrectedNerieGuigue) {
                    group.forEach(e => {
                        if ((e.name || '').trim().toLowerCase() === 'guige') toRemove.add(e);
                    });
                }
                group.forEach(short => {
                    const shortName = (short.name || '').trim();
                    if (!shortName) return;
                    const shortLower = shortName.toLowerCase();
                    const hasFuller = group.some(full => {
                        if (full === short) return false;
                        const fullLower = (full.name || '').trim().toLowerCase();
                        if (!fullLower || fullLower.length <= shortLower.length) return false;




                        return fullLower.endsWith(' ' + shortLower);
                    });
                    if (hasFuller) toRemove.add(short);
                });
            });
            if (!toRemove.size) return loaded;
            return loaded.filter(e => !toRemove.has(e));
        }







