        async function saveRecord(dateStr, name, rec, options = {}) {
            const recordKey = dateStr + '|' + name;
            const existing = allRecords[recordKey] || {};
            const isPunchSave = options && (options.source === 'punch' || options.source === 'operator-punch');
            const isOperatorPunch = isPunchSave && options.source === 'operator-punch';
            const punchFieldsForPermission = ['timeIn','startBreak','endBreak','logOut'];
            const requestedPunchChange = punchFieldsForPermission.some(field => String(existing[field] || '') !== String((rec && rec[field]) || ''));
            const requestedCreditOverrideChange = getManualCreditOverrideMinutes(existing) !== getManualCreditOverrideMinutes(rec || {});
            const requestedPod = (rec && rec.pod) || existing.pod || podOf(name) || lockedPod || '';

            if (!isPunchSave && requestedPunchChange) {
                TrinoPermissions.require('attendance.agent.timestamps.edit', { name, pod:requestedPod }, 'Only an authenticated Admin or the assigned Team Leader for this POD can edit agent attendance timestamps.');
            }
            if (!isPunchSave && requestedCreditOverrideChange) {
                TrinoPermissions.require('attendance.agent.credit.override', { name, pod:requestedPod }, 'Only an authenticated Admin or the assigned Team Leader for this POD can override final credited hours.');
            }
            if (isOperatorPunch) {
                TrinoPermissions.require('attendance.agent.manage', { name, pod:requestedPod }, 'Only an authenticated Admin or the assigned Team Leader for this POD can record an Agent override punch.');
            } else if (!isAdmin && isTeamLeader && isPunchSave) {
                throw new Error('Team Leaders may record Agent punches only through the authorized remote-override workflow.');
            }

            const resolvedPod = (rec && rec.pod) || existing.pod || podOf(name) ||
                (activePod !== ALL_PODS_LABEL ? activePod : null);
            let storedRec = resolvedPod ? { ...rec, pod: resolvedPod } : { ...rec };
            if (resolvedPod) storedRec.team = attendanceTeamId(storedRec, name, resolvedPod);

            if (!storedRec.logOut && existing && existing.forcedLogoutRequestId) {
                ['status','statusLabel','attendanceStatus','shiftStatus','lastAttendanceAction','forcedLogout','forcedLogoutAt','forcedLogoutBy','forcedLogoutRole','forcedLogoutRequestId','forcedLogoutClosedOpenBreak']
                    .forEach(field => { delete storedRec[field]; });
            }
            if (!storedRec.logOut) {
                delete storedRec.manualCreditOverrideMinutes;
                delete storedRec.manualCreditOverrideBy;
                delete storedRec.manualCreditOverrideAt;
                delete storedRec.manualCreditOverrideReason;
            }
            const ndEnabledForRecord = nightDiffEnabledForRecord(storedRec, name, resolvedPod);
            if (ndEnabledForRecord && storedRec.timeIn && storedRec.logOut) {
                storedRec.nightDiffMinutes = computeNightDiffMinutes(storedRec, dateStr, resolvedPod, { includeOpen:false });
                storedRec.nightDiffRuleVersion = NIGHT_DIFF_RULE_VERSION;
                storedRec.nightDiffWindow = '22:00-06:00';
                storedRec.nightDiffTimeZone = MANILA_TIME_ZONE;
            } else {
                delete storedRec.nightDiffMinutes;
                delete storedRec.nightDiffRuleVersion;
                delete storedRec.nightDiffWindow;
                delete storedRec.nightDiffTimeZone;
                delete storedRec.nightDiffOverrideMinutes;
                delete storedRec.nightDiffOverrideBy;
                delete storedRec.nightDiffOverrideAt;
                if (!ndEnabledForRecord) delete storedRec.nightDiffBreakPolicy;
            }
            const key = recKey(dateStr, name);

            if (isPunchSave && options.field && storedRec[options.field]) {
                const eventId = options.punchEventId || createMutationToken();
                storedRec._syncPunchIds = { ...(storedRec._syncPunchIds || {}), [options.field]: eventId };
                options.punchEventId = eventId;
            } else if (!isPunchSave && storedRec._syncPunchIds) {
                const nextIds = { ...storedRec._syncPunchIds };
                punchFieldsForPermission.forEach(field => {
                    if (String(existing[field] || '') !== String(storedRec[field] || '')) delete nextIds[field];
                });
                if (Object.keys(nextIds).length) storedRec._syncPunchIds = nextIds;
                else delete storedRec._syncPunchIds;
            }

            const preparedVersion = prepareVersionedRecord(key, existing, storedRec, {
                label:`attendance for ${name} on ${dateStr}`
            });
            storedRec = preparedVersion.record;
            const payload = preparedVersion.payload;
            allRecords[recordKey] = storedRec;
            const localAttendanceChange = makeIncrementalChange('records', recordKey, {
                pod:resolvedPod || '',
                source:isPunchSave ? (isOperatorPunch ? 'operator-punch-optimistic' : 'local-punch') : 'local-edit'
            });
            notifyLiveAttendanceState(localAttendanceChange);
            scheduleIncrementalRender(localAttendanceChange);
            pruneSupersededPunchEvents(key, storedRec);

            queueVersionedRecord(key, preparedVersion);
            if (isPunchSave && options.field && storedRec[options.field]) {
                persistPunchSyncEvent({
                    id:options.punchEventId,
                    key,
                    date:dateStr,
                    name,
                    pod:resolvedPod,
                    field:options.field,
                    timestamp:storedRec[options.field],
                    payload
                });
            }
            updatePendingSyncUi();
            if (isPunchSave) {
                publishUpdate();
                renderAgentPunchOptimisticSurfaces(dateStr, name, storedRec);
                schedulePendingSyncRetry(500);
            }

            const isLatestPunchSave = () => isPunchSave && options.saveToken === latestPunchSaveToken;
            const punchLabel = isPunchSave ? punchFieldLabel(options.field) : '';
            const punchTime = isPunchSave && options.field && storedRec[options.field] ? formatManilaTime(storedRec[options.field], true) : '';
            if (isLatestPunchSave()) setPunchSaveState('saving', `${punchLabel} ${punchTime} • Counted now — confirming Firebase…`);

            const syncStartedAt = isPunchSave ? Date.now() : 0;
            let firstResult;
            try {
                firstResult = await commitVersionedRecord(key, payload, preparedVersion.meta, { attendance:true, punch:isPunchSave });
            } catch (error) {
                // commitVersionedRecord normally returns queued/error state; retain this guard for
                // unexpected SDK exceptions so the durable queue still survives.
                firstResult = { localSaved:true, remoteSaved:false, queued:true, error };
            }

            if (isPunchSave) {
                const confirmed = await confirmVersionedPunchWrite({
                    key,
                    payload,
                    meta:preparedVersion.meta,
                    field:options.field,
                    timestamp:storedRec[options.field],
                    eventId:options.punchEventId,
                    label:punchLabel,
                    initialResult:firstResult
                });
                const syncResult = { ...confirmed, punchEventId:options.punchEventId, latencyMs:Math.max(0, Date.now() - syncStartedAt) };
                options.syncResult = syncResult;

                if (syncResult.serverConfirmed && syncResult.remoteRecord) {
                    allRecords[recordKey] = syncResult.remoteRecord;
                    const confirmedChange = makeIncrementalChange('records', recordKey, {
                        pod:syncResult.remoteRecord.pod || resolvedPod || '',
                        source:'server-confirmed-punch'
                    });
                    notifyLiveAttendanceState(confirmedChange);
                    scheduleIncrementalRender(confirmedChange);
                    publishUpdate();
                    renderAgentPunchOptimisticSurfaces(dateStr, name, syncResult.remoteRecord);
                }

                if (syncResult.conflict) {
                    if (isLatestPunchSave()) setPunchSaveState('error', `${punchLabel} was not applied because a newer server version exists.`);
                    throw new Error('This attendance record changed on another device before the punch could commit. The newer server version was kept; reopen the Agent before recording another punch.');
                }
                if (syncResult.definitiveFailure || (syncResult.error && isDefinitivePunchWriteError(syncResult.error))) {
                    if (isLatestPunchSave()) setPunchSaveState('error', `${punchLabel} was rejected by the live server.`);
                    throw syncResult.error || new Error(`The live server rejected ${punchLabel}.`);
                }

                if (syncResult.serverConfirmed) {
                    if (isLatestPunchSave()) setPunchSaveState('saved', `${punchLabel} ${punchTime} • Firebase confirmed ✓`);
                } else {
                    if (isLatestPunchSave()) setPunchSaveState('pending', `${punchLabel} ${punchTime} • Connection interrupted — retry active`);
                    schedulePendingSyncRetry(500);
                }
                updatePendingSyncUi();
                setConnBanner(fbConnected === true, { immediate:getPendingSyncSummary().punchWrites > 0 });
                return allRecords[recordKey] || storedRec;
            }

            if (firstResult && firstResult.conflict) {
                throw new Error('This attendance record changed on another device. The newer server version was kept; reopen the record before editing again.');
            }
            if (!firstResult || !firstResult.remoteSaved) schedulePendingSyncRetry();
            return storedRec;
        }

