        function tlPunchFieldsChanged(existing, next) {
            return ['timeIn','startBreak','endBreak','logOut'].some(field => String((existing && existing[field]) || '') !== String((next && next[field]) || ''));
        }

        function validateTeamLeaderSelfPunchTransition(existing, field) {
            const rec = existing || {};
            if (!['timeIn','startBreak','endBreak','logOut'].includes(field)) return 'Unsupported attendance punch.';
            if ((rec.startBreak && !rec.timeIn) || (rec.endBreak && !rec.startBreak) || (rec.logOut && !rec.timeIn)) {
                return 'This attendance record has an invalid punch sequence and needs Admin review before another punch can be recorded.';
            }
            if (rec.logOut) return 'This shift is already complete. Attendance actions are locked until your next scheduled shift.';
            if (field === 'timeIn') {
                if (rec.timeIn || rec.startBreak || rec.endBreak) return 'Time In is not available for this attendance record.';
                return '';
            }
            if (!rec.timeIn) return 'Time In must be recorded first.';
            if (field === 'startBreak') {
                if (rec.startBreak || rec.endBreak) return 'Start Break is not available right now.';
                return '';
            }
            if (field === 'endBreak') {
                if (!rec.startBreak) return 'Start Break must be recorded first.';
                if (rec.endBreak) return 'End Break is already recorded.';
                return '';
            }
            if (field === 'logOut') {
                if (rec.startBreak && !rec.endBreak) return 'End Break before logging out.';
                return '';
            }
            return 'Unsupported attendance punch.';
        }

        async function saveTeamLeaderAttendanceRecord(dateStr, name, rec, options = {}) {
            const currentAssignedPod = String((TEAM_LEADER_POD_BY_NAME && TEAM_LEADER_POD_BY_NAME[name]) || '').trim();
            const mapKey = tlAttendanceMapKey(dateStr, name);
            const key = tlAttendanceRecordKey(dateStr, name);
            const isTlPunch = options.source === 'tl-self-punch' || options.source === 'tl-admin-punch';
            let existing = allTeamLeaderRecords[mapKey] || {};
            let existingPod = String(existing.pod || '').trim();
            const restoredPod = options.preserveRecordPod === true ? String((rec && rec.pod) || '').trim() : '';
            let recordPod = existingPod || restoredPod || currentAssignedPod;
            if (!recordPod) throw new Error('Unknown Team Leader account or attendance POD.');

            if (isTlPunch) {
                const field = options.field;
                const adminOverride = options.source === 'tl-admin-punch';
                if (adminOverride) {
                    TrinoPermissions.require('attendance.tl.override', { name, pod:recordPod }, 'An authenticated system Admin is required to record Team Leader override punches.');
                } else {
                    TrinoPermissions.require('attendance.tl.self.punch', { name, pod:recordPod }, 'Team Leaders may record only their own attendance.');
                }
                if (!timeSyncEstablished) throw new Error('Verified server time is required before Team Leader attendance can be recorded.');
                if (!(await ensureRealtimePunchConnectionReady({ userInitiated:adminOverride }))) {
                    throw new Error('A live verified Firebase connection is required before a new Team Leader punch can be accepted. Reconnect and try again.');
                }

                // Serialize this TL attendance record against any earlier punch that is still
                // waiting for its Firebase receipt. This prevents Start/End Break or Time Out
                // from being calculated on top of an unconfirmed predecessor.
                if (hasPendingWrite(key)) {
                    await retryPendingSyncQueue({ userInitiated:adminOverride });
                    if (hasPendingWrite(key)) throw new Error('The previous Team Leader attendance punch is still waiting for Firebase confirmation. Finish syncing it before recording the next step.');
                    existing = allTeamLeaderRecords[mapKey] || existing;
                    existingPod = String(existing.pod || '').trim();
                    recordPod = existingPod || restoredPod || currentAssignedPod;
                }

                const transitionError = validateTeamLeaderSelfPunchTransition(existing, field);
                if (transitionError) throw new Error(transitionError);

                let stored = { ...existing, attendanceRole:'teamLeader', name, pod:recordPod, team:teamIdForPod(recordPod) };
                const stamp = nowIso();
                const lastPunch = tlAttendanceLastPunch(existing);
                if (lastPunch && new Date(stamp).getTime() <= lastPunch.ms) throw new Error('Verified punch time must be later than the previous attendance event. Please try again.');
                if (field === 'timeIn') {
                    const shift = getTeamLeaderStandardShiftWindow(recordPod);
                    stored.timeIn = stamp;
                    stored.shiftStart = shift.start;
                    stored.shiftEnd = shift.end;
                    stored.shiftLabel = shift.label;
                    stored.breakPolicyMinutes = TEAM_LEADER_STANDARD_BREAK_MINUTES;
                    stored.regularShiftCreditHours = TEAM_LEADER_STANDARD_PAID_HOURS;
                    stored.standardShiftWindowMinutes = TEAM_LEADER_STANDARD_WINDOW_MINUTES;
                    stored.timekeepingPolicy = 'agent-standard-v1';
                } else if (field === 'startBreak') stored.startBreak = stamp;
                else if (field === 'endBreak') stored.endBreak = stamp;
                else if (field === 'logOut') stored.logOut = stamp;
                else throw new Error('Unsupported Team Leader attendance punch.');

                const eventId = options.punchEventId || createMutationToken();
                options.punchEventId = eventId;
                stored._syncPunchIds = { ...(stored._syncPunchIds || {}), [field]:eventId };
                if (adminOverride) {
                    const adminId = options.modifiedBy || requireAuthenticatedAdminId();
                    stored.modified_by = adminId;
                    stored.modified_at = stamp;
                    stored.modified_action = 'admin_override_punch';
                    stored.modified_field = field;
                }

                const prepared = prepareVersionedRecord(key, existing, stored, { label:`Team Leader attendance for ${name} on ${dateStr}` });
                stored = prepared.record;
                const payload = prepared.payload;
                const beforeRecord = JSON.parse(JSON.stringify(existing || {}));
                const startedAt = typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();

                // Durability is established before the network call, then all TL surfaces paint
                // the new punch immediately. The exact event id makes retry/read-back idempotent.
                allTeamLeaderRecords[mapKey] = stored;
                queueVersionedRecord(key, prepared);
                setLocalMirrorForKey(key, payload, { pendingCloudSync:true });
                persistPunchSyncEvent({ id:eventId, key, date:dateStr, name, pod:recordPod, field, timestamp:stored[field], payload });
                markPendingMutation();
                publishUpdate();
                updatePendingSyncUi();
                if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
                renderTeamLeaderHomeStatus();
                renderTlAdminOverview();
                if (isOverlayOpen($('tlStatusDetailOverlay'))) renderTlStatusDetail();

                const initialResult = await commitVersionedRecord(key, payload, prepared.meta, { teamLeaderAttendance:true, punch:true });
                const sync = await confirmVersionedPunchWrite({
                    key,
                    payload,
                    meta:prepared.meta,
                    field,
                    timestamp:stored[field],
                    eventId,
                    label:`Team Leader ${punchFieldLabel(field)}`,
                    initialResult
                });
                const endedAt = typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now();
                sync.latencyMs = Math.max(0, Math.round(endedAt - startedAt));
                options.syncResult = sync;

                if (sync.serverConfirmed) {
                    const confirmed = sync.remoteRecord || parseAttendanceRecordRaw(payload) || stored;
                    allTeamLeaderRecords[mapKey] = confirmed;
                    setLocalMirrorForKey(key, JSON.stringify(confirmed), { pendingCloudSync:false });
                    clearVersionedPendingIfCurrent(key, payload, prepared.meta.mutationId);
                    stored = confirmed;
                    appendSyncAudit('server_confirmed', `Team Leader ${punchFieldLabel(field)} confirmed by Firebase for ${name}.`, {
                        key, field, eventId, timestamp:confirmed[field], receiptSource:sync.receiptSource || '', latencyMs:sync.latencyMs
                    });
                } else if (sync.conflict || sync.definitiveFailure) {
                    rollbackUnconfirmedTeamLeaderPunch(dateStr, name, field, beforeRecord, eventId);
                    const error = sync.error || new Error(sync.conflict
                        ? 'This Team Leader attendance record changed on another device. The newer Firebase version was kept.'
                        : `Firebase rejected Team Leader ${punchFieldLabel(field)}.`);
                    options.syncResult = { ...sync, error };
                    throw error;
                } else {
                    // A connection can disappear after submission and before the ACK reaches
                    // this browser. Keep the already-counted event durable and retry the exact
                    // mutation rather than rolling it back or creating a duplicate punch.
                    setLocalMirrorForKey(key, payload, { pendingCloudSync:true });
                    schedulePendingSyncRetry(500);
                    appendSyncAudit('tl_punch_pending', `Team Leader ${punchFieldLabel(field)} for ${name} is counted and awaiting Firebase confirmation.`, {
                        key, field, eventId, error:sync.error ? getErrorMessage(sync.error) : ''
                    });
                }

                updatePendingSyncUi();
                if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
                renderTeamLeaderHomeStatus();
                renderTlAdminOverview();
                if (isOverlayOpen($('tlStatusDetailOverlay'))) renderTlStatusDetail();
                return allTeamLeaderRecords[mapKey] || stored;
            }

            // Administrative timestamp correction path remains versioned but is not treated as
            // a realtime punch; preserve its existing permission and conflict behavior.
            let stored = { ...existing, ...rec, attendanceRole:'teamLeader', name, pod:recordPod, team:teamIdForPod(recordPod) };
            TrinoPermissions.require('attendance.tl.edit', { name, pod:recordPod }, 'An authenticated system Admin is required to edit Team Leader attendance timestamps.');
            if (!tlPunchFieldsChanged(existing, stored) && options.requireTimestampChange) throw new Error('No timestamp change detected.');
            const adminId = options.modifiedBy || requireAuthenticatedAdminId();
            stored.modified_by = adminId;
            stored.modified_at = options.modifiedAt || nowIso();
            stored.modified_action = options.modificationAction || 'admin_timestamp_edit';
            if (options.modificationReason) stored.modified_reason = String(options.modificationReason).slice(0, 240);

            const prepared = prepareVersionedRecord(key, existing, stored, { label:`Team Leader attendance for ${name} on ${dateStr}` });
            stored = prepared.record;
            allTeamLeaderRecords[mapKey] = stored;
            queueVersionedRecord(key, prepared);
            markPendingMutation();
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { teamLeaderAttendance:true });
            if (result && result.conflict) throw new Error('This Team Leader attendance record changed on another device. The newer server version was kept.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
            renderTeamLeaderHomeStatus();
            renderTlAdminOverview();
            if (isOverlayOpen($('tlStatusDetailOverlay'))) renderTlStatusDetail();
            return allTeamLeaderRecords[mapKey] || stored;
        }

        async function deleteTeamLeaderAttendanceRecord(dateStr, name) {
            const mapKey = tlAttendanceMapKey(dateStr, name);
            const key = tlAttendanceRecordKey(dateStr, name);
            const existing = allTeamLeaderRecords[mapKey] || {};
            const recordPod = teamLeaderAttendanceRecordPod(name, existing);
            TrinoPermissions.require('attendance.tl.delete', { name, pod:recordPod }, 'An authenticated system Admin is required to delete Team Leader attendance records.');
            const deleteMeta = prepareVersionedDelete(key, existing, { label:`Team Leader attendance for ${name} on ${dateStr}` });
            delete allTeamLeaderRecords[mapKey];
            queueVersionedDelete(key, deleteMeta);
            const result = await commitVersionedDelete(key, deleteMeta);
            if (result && result.conflict) throw new Error('This Team Leader attendance record changed on another device. The newer server version was kept instead of deleting it.');
            if (!result || !result.remoteDeleted) schedulePendingSyncRetry();
            if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
            renderTeamLeaderHomeStatus();
            renderTlAdminOverview();
            if (isOverlayOpen($('tlStatusDetailOverlay'))) renderTlStatusDetail();
        }





        async function saveOTRecord(dateStr, name, rec) {
            ensureOvertimePeriodUnlocked(dateStr);
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || {};
            const overtimePod = (rec && rec.pod) || existing.pod || overtimePodForName(name);
            if (isTeamLeaderOTRecord(name, rec || existing)) TrinoPermissions.require('admin.authenticated', { name, pod:overtimePod }, 'Only an authenticated Admin can approve or correct Team Leader overtime.');
            else TrinoPermissions.require('overtime.manage', { name, pod:overtimePod }, 'Only an authorized Team Leader or Admin can manage overtime.');
            const key = otRecKey(dateStr, name);
            const prepared = prepareVersionedRecord(key, existing, rec, { label:`overtime for ${name} on ${dateStr}` });
            allOT[mapKey] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { overtime:true });
            if (result && result.conflict) throw new Error('This overtime record changed on another device. Reopen it before editing again.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            return prepared.record;
        }

        async function saveTLOvertimeRequest(dateStr, name, request) {
            const requestedCalendarDate = String(dateStr || '').trim();
            const shiftResolution = resolveTLOvertimeShiftDate(requestedCalendarDate, name);
            dateStr = shiftResolution.date || requestedCalendarDate;
            ensureOvertimePeriodUnlocked(dateStr);
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || {};
            const attendance = overtimeAttendanceRecordFor(dateStr, name) || {};
            const requestPod = (request && request.pod) || attendance.pod || existing.pod || overtimePodForName(name);
            TrinoPermissions.require('overtime.tl.submit', { name, pod:requestPod }, 'Only the signed-in Team Leader can submit their own overtime request.');
            if (!dateStr || !name) throw new Error('Team Leader overtime requires a date and Team Leader.');
            const requestedHours = getStoredOTHoursFromRecord(request || {});
            if (!Number.isFinite(requestedHours) || requestedHours <= 0 || requestedHours > 12) throw new Error('Team Leader overtime must be greater than 0 and no more than 12 hours.');
            const requestNote = String(request && request.note || '').trim();
            if (!requestNote) throw new Error('A manager request / reason is required for Team Leader overtime.');
            if (existing && existing.status === 'approved') throw new Error('This shift date already has approved overtime. Ask an Admin to correct or revoke the approved record.');
            if (existing && existing.status === 'pending' && existing.name && existing.name !== name) throw new Error('A pending overtime request already exists for this Team Leader and shift date.');
            const now = nowIso();
            const rec = {
                ...existing,
                ...request,
                note:requestNote.slice(0, 300),
                pod:requestPod,
                targetRole:'Team Leader',
                requestType:'tl_submission',
                status:'pending',
                shiftDate:dateStr,
                requestedCalendarDate:requestedCalendarDate || dateStr,
                shiftDateAdjusted:!!shiftResolution.adjusted,
                shiftDateAdjustmentReason:shiftResolution.reason || '',
                requestSeriesId:existing.requestSeriesId || ('tlot-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8)),
                submissionCount:Math.max(1, Number(existing.submissionCount || 0) + 1),
                submittedBy:name,
                submittedByRole:'team_leader',
                submittedAt:(existing.status === 'pending' && existing.submittedAt) ? existing.submittedAt : now,
                updatedAt:now
            };
            ['approvedBy','approvedById','approvedAt','rejectedBy','rejectedById','rejectedAt','reviewedBy','reviewedById','reviewedAt','reviewNote','withdrawnBy','withdrawnAt','revokedBy','revokedById','revokedAt','revocationReason','correctedBy','correctedById','correctedAt','correctionReason'].forEach(field => { delete rec[field]; });
            const key = otRecKey(dateStr, name);
            const prepared = prepareVersionedRecord(key, existing, rec, { label:`Team Leader overtime request for ${name} on ${dateStr}` });
            allOT[mapKey] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { overtime:true, tlOvertimeRequest:true });
            if (result && result.conflict) throw new Error('This overtime request changed on another device. Reopen Overtime before submitting again.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            return prepared.record;
        }

        async function withdrawTLOvertimeRequest(dateStr, name) {
            ensureOvertimePeriodUnlocked(dateStr);
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || null;
            if (!existing || existing.status !== 'pending') throw new Error('Only a pending overtime request can be withdrawn.');
            const pod = existing.pod || overtimePodForName(name);
            TrinoPermissions.require('overtime.tl.submit', { name, pod }, 'Only the signed-in Team Leader can withdraw their own overtime request.');
            const rec = { ...existing, status:'withdrawn', withdrawnBy:name, withdrawnAt:nowIso(), updatedAt:nowIso() };
            const key = otRecKey(dateStr, name);
            const prepared = prepareVersionedRecord(key, existing, rec, { label:`Team Leader overtime request for ${name} on ${dateStr}` });
            allOT[mapKey] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { overtime:true, tlOvertimeRequest:true });
            if (result && result.conflict) throw new Error('This overtime request changed on another device. The newer server version was kept.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            return prepared.record;
        }

        async function reviewTLOvertimeRequest(dateStr, name, decision, reviewNote = '') {
            ensureOvertimePeriodUnlocked(dateStr);
            TrinoPermissions.require('overtime.tl.review', { name }, 'An authenticated Admin session is required to review Team Leader overtime.');
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || null;
            if (!existing || existing.status !== 'pending' || !isTeamLeaderOTRecord(name, existing)) throw new Error('This Team Leader overtime request is no longer pending. Refresh the queue and try again.');
            const normalizedDecision = String(decision || '').toLowerCase();
            if (normalizedDecision !== 'approved' && normalizedDecision !== 'rejected') throw new Error('Choose Approve or Reject.');
            const requestedHours = getStoredOTHoursFromRecord(existing);
            if (!Number.isFinite(requestedHours) || requestedHours <= 0 || requestedHours > 12) throw new Error('This overtime request has an invalid duration and cannot be reviewed.');
            if (!String(existing.note || '').trim()) throw new Error('This overtime request is missing the required manager reason and cannot be reviewed.');
            if (normalizedDecision === 'rejected' && !String(reviewNote || '').trim()) throw new Error('Enter a review note before rejecting this overtime request.');
            if (normalizedDecision === 'approved') {
                const blockedReason = otBlockedReason(dateStr, name);
                if (blockedReason) throw new Error(blockedReason);
            }
            const now = nowIso();
            const adminId = requireAuthenticatedAdminId();
            const rec = {
                ...existing,
                status:normalizedDecision,
                reviewedBy:'Admin',
                reviewedById:adminId,
                reviewedAt:now,
                reviewNote:String(reviewNote || '').trim().slice(0, 300),
                targetRole:'Team Leader',
                requestType:existing.requestType || 'tl_submission'
            };
            ['withdrawnBy','withdrawnAt','revokedBy','revokedById','revokedAt','revocationReason'].forEach(field => { delete rec[field]; });
            if (normalizedDecision === 'approved') {
                rec.approvedBy = 'Admin';
                rec.approvedById = adminId;
                rec.approvedAt = now;
                rec.approvalHistory = appendTLOvertimeApprovalHistory(existing, 'approved', reviewNote || 'Approved by Admin', { toHours:requestedHours });
                ['rejectedBy','rejectedById','rejectedAt'].forEach(field => { delete rec[field]; });
            } else {
                rec.rejectedBy = 'Admin';
                rec.rejectedById = adminId;
                rec.rejectedAt = now;
                rec.approvalHistory = appendTLOvertimeApprovalHistory(existing, 'rejected', reviewNote, { requestedHours });
                ['approvedBy','approvedById','approvedAt'].forEach(field => { delete rec[field]; });
            }
            return saveOTRecord(dateStr, name, rec);
        }

        async function correctApprovedTLOvertime(dateStr, name, nextHours, reason) {
            ensureOvertimePeriodUnlocked(dateStr);
            TrinoPermissions.require('admin.authenticated', { name, pod:overtimePodForName(name) }, 'An authenticated Admin session is required to correct approved Team Leader overtime.');
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || null;
            if (!existing || existing.status !== 'approved' || !isTeamLeaderOTRecord(name, existing)) throw new Error('Only an approved Team Leader overtime record can be corrected.');
            const hours = Math.round(Number(nextHours) * 60) / 60;
            if (!Number.isFinite(hours) || hours <= 0 || hours > 12) throw new Error('Corrected overtime must be greater than 0 and no more than 12 hours.');
            const correctionReason = String(reason || '').trim();
            if (!correctionReason) throw new Error('Enter a reason for correcting approved Team Leader overtime.');
            const beforeHours = getStoredOTHoursFromRecord(existing);
            const adminId = requireAuthenticatedAdminId();
            const rec = {
                ...existing,
                hours:Math.round(hours * 100) / 100,
                minutes:Math.round(hours * 60),
                status:'approved',
                correctedBy:'Admin',
                correctedById:adminId,
                correctedAt:nowIso(),
                correctionReason:correctionReason.slice(0, 300),
                updatedAt:nowIso(),
                approvalHistory:appendTLOvertimeApprovalHistory(existing, 'corrected', correctionReason, { fromHours:beforeHours, toHours:hours })
            };
            return saveOTRecord(dateStr, name, rec);
        }

        async function revokeApprovedTLOvertime(dateStr, name, reason) {
            ensureOvertimePeriodUnlocked(dateStr);
            TrinoPermissions.require('admin.authenticated', { name, pod:overtimePodForName(name) }, 'An authenticated Admin session is required to revoke approved Team Leader overtime.');
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || null;
            if (!existing || existing.status !== 'approved' || !isTeamLeaderOTRecord(name, existing)) throw new Error('Only an approved Team Leader overtime record can be revoked.');
            const revocationReason = String(reason || '').trim();
            if (!revocationReason) throw new Error('Enter a reason for revoking approved Team Leader overtime.');
            const previousHours = getStoredOTHoursFromRecord(existing);
            const adminId = requireAuthenticatedAdminId();
            const rec = {
                ...existing,
                status:'revoked',
                revokedBy:'Admin',
                revokedById:adminId,
                revokedAt:nowIso(),
                revocationReason:revocationReason.slice(0, 300),
                updatedAt:nowIso(),
                approvalHistory:appendTLOvertimeApprovalHistory(existing, 'revoked', revocationReason, { fromHours:previousHours, toHours:0 })
            };
            return saveOTRecord(dateStr, name, rec);
        }

        async function deleteOTRecord(dateStr, name) {
            ensureOvertimePeriodUnlocked(dateStr);
            const mapKey = dateStr + '|' + name;
            const existing = allOT[mapKey] || {};
            const overtimePod = existing.pod || overtimePodForName(name);
            if (isTeamLeaderOTRecord(name, existing)) TrinoPermissions.require('admin.authenticated', { name, pod:overtimePod }, 'Only an authenticated Admin can remove Team Leader overtime.');
            else TrinoPermissions.require('overtime.manage', { name, pod:overtimePod }, 'Only an authorized Team Leader or Admin can manage overtime.');
            const key = otRecKey(dateStr, name);
            const deleteMeta = prepareVersionedDelete(key, existing, { label:`overtime for ${name} on ${dateStr}` });
            delete allOT[mapKey];
            queueVersionedDelete(key, deleteMeta);
            const result = await commitVersionedDelete(key, deleteMeta);
            if (result && result.conflict) throw new Error('This overtime record changed on another device. The newer server version was kept instead of deleting it.');
            if (!result || !result.remoteDeleted) schedulePendingSyncRetry();
            return result;
        }

        async function saveOvertimePeriodLock(dateStr, nextStatus, reason = '') {
            TrinoPermissions.require('admin.authenticated', {}, 'An authenticated Admin session is required to finalize or unlock overtime pay periods.');
            const period = overtimePayPeriodForDate(dateStr);
            const normalizedStatus = String(nextStatus || '').toLowerCase();
            if (normalizedStatus !== 'locked' && normalizedStatus !== 'unlocked') throw new Error('Choose a valid overtime pay-period status.');
            const cleanReason = String(reason || '').trim();
            if (normalizedStatus === 'unlocked' && !cleanReason) throw new Error('Enter a reason before unlocking a finalized overtime pay period.');
            if (normalizedStatus === 'locked') {
                const pending = pendingTLOvertimeForPeriod(period);
                if (pending.length) throw new Error(`Review the ${pending.length} pending Team Leader overtime request${pending.length === 1 ? '' : 's'} in ${period.label} before finalizing the pay period.`);
            }
            const existing = getOvertimePeriodLockByStart(period.start) || {};
            const now = nowIso();
            const adminId = requireAuthenticatedAdminId();
            const history = Array.isArray(existing.history) ? existing.history.slice(-49) : [];
            history.push({ action:normalizedStatus === 'locked' ? 'locked' : 'unlocked', at:now, by:'Admin', byId:adminId, reason:(cleanReason || 'Payroll reviewed / exported').slice(0, 300) });
            const rec = {
                ...existing,
                periodStart:period.start,
                periodEnd:period.end,
                status:normalizedStatus,
                updatedAt:now,
                history
            };
            if (normalizedStatus === 'locked') {
                rec.lockedAt = now;
                rec.lockedBy = 'Admin';
                rec.lockedById = adminId;
                rec.lockReason = (cleanReason || 'Payroll reviewed / exported').slice(0, 300);
                ['unlockedAt','unlockedBy','unlockedById','unlockReason'].forEach(field => { delete rec[field]; });
            } else {
                rec.unlockedAt = now;
                rec.unlockedBy = 'Admin';
                rec.unlockedById = adminId;
                rec.unlockReason = cleanReason.slice(0, 300);
            }
            const key = overtimePeriodLockStorageKey(period.start);
            const prepared = prepareVersionedRecord(key, existing, rec, { label:`overtime payroll period ${period.label}` });
            allOvertimePeriodLocks[period.start] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { overtimePayrollLock:true });
            if (result && result.conflict) throw new Error('This overtime pay-period lock changed on another device. Reopen Overtime before trying again.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            return prepared.record;
        }

        async function loadAllOT() {
            try {
                const keys = await appStorage.list('ot:');
                allOT = {};
                for (const k of keys) {
                    try {
                        const raw = await appStorage.get(k);
                        if (raw) allOT[k.slice(3)] = JSON.parse(raw);
                    } catch (e) {}
                }
            } catch (e) { allOT = {}; }
        }


        async function loadAllOvertimePeriodLocks() {
            try {
                const keys = await appStorage.list(OVERTIME_PAYROLL_LOCK_PREFIX);
                allOvertimePeriodLocks = {};
                for (const k of keys) {
                    try {
                        const raw = await appStorage.get(k);
                        if (raw) allOvertimePeriodLocks[k.slice(OVERTIME_PAYROLL_LOCK_PREFIX.length)] = JSON.parse(raw);
                    } catch (e) {}
                }
            } catch (e) { allOvertimePeriodLocks = {}; }
        }

        async function saveDayOffSwap(swap) {
            if (!swap || !swap.id) throw new Error('Invalid day-off swap.');
            TrinoPermissions.require('schedule.dayoff.manage', { pod:swap.pod || '' }, 'You do not have permission to manage day-off swaps for this POD.');
            const existing = allDayOffSwaps[swap.id] || {};
            const key = dayOffSwapStorageKey(swap.id);
            const prepared = prepareVersionedRecord(key, existing, swap, { label:`day-off swap ${swap.id}` });
            allDayOffSwaps[swap.id] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { dayOffSwap:true });
            if (result && result.conflict) throw new Error('This day-off swap changed on another device. The newer server version was kept.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            return prepared.record;
        }

        async function deleteDayOffSwap(id) {
            if (!id) return;
            const existing = allDayOffSwaps[id];
            if (existing) TrinoPermissions.require('schedule.dayoff.manage', { pod:existing.pod || '' }, 'You do not have permission to manage day-off swaps for this POD.');
            const key = dayOffSwapStorageKey(id);
            const deleteMeta = prepareVersionedDelete(key, existing || {}, { label:`day-off swap ${id}` });
            delete allDayOffSwaps[id];
            queueVersionedDelete(key, deleteMeta);
            const result = await commitVersionedDelete(key, deleteMeta);
            if (result && result.conflict) throw new Error('This day-off swap changed on another device. The newer server version was kept instead of deleting it.');
            if (!result || !result.remoteDeleted) schedulePendingSyncRetry();
            return result;
        }

        async function loadAllDayOffSwaps() {
            try {
                const keys = await appStorage.list('dayswap:');
                allDayOffSwaps = {};
                for (const k of keys) {
                    try {
                        const raw = await appStorage.get(k);
                        if (!raw) continue;
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.id) allDayOffSwaps[parsed.id] = parsed;
                    } catch (e) {}
                }
            } catch (e) { allDayOffSwaps = {}; }
        }

        async function saveShiftOverride(item, options = {}) {
            if (!item || !item.id) throw new Error('Invalid shift override.');
            const permission = item.overrideKind === 'tl_work_authorization' ? 'schedule.tl_work_authorization.manage' : item.overrideKind === 'tl_dayoff_date' ? 'schedule.tl_dayoff_override.manage' : 'schedule.shift_override.manage';
            TrinoPermissions.require(permission, { name:item.name || '', pod:item.pod || '' }, 'You do not have permission to manage this schedule override.');
            const existing = allShiftOverrides[item.id] || {};
            const key = shiftOverrideStorageKey(item.id);
            const prepared = prepareVersionedRecord(key, existing, item, { label:`shift override ${item.id}` });
            allShiftOverrides[item.id] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { shiftOverride:true, forceAttempt:options.forceAttempt === true });
            if (result && result.conflict) throw new Error('This shift override changed on another device. The newer server version was kept.');
            let receipt = null;
            if (options.requireRemoteReceipt === true) {
                if (result && result.remoteSaved && String(result.remoteRaw || '') === String(prepared.payload)) {
                    receipt = { ok:true, remoteRaw:String(result.remoteRaw || prepared.payload) };
                } else {
                    receipt = await verifyVersionedPayloadOnServer(key, prepared.payload, 'shift assignment');
                }
                if (!receipt.ok) {
                    schedulePendingSyncRetry(500);
                    const reason = receipt.reason || (result && result.error ? getErrorMessage(result.error) : 'Firebase confirmation is still pending.');
                    throw new Error(`The shift selection was saved locally but was not confirmed across devices yet. ${reason}`);
                }
            } else if (!result || !result.remoteSaved) {
                schedulePendingSyncRetry();
            }
            if (options.returnSync === true) return { record:prepared.record, result, receipt, key, payload:prepared.payload };
            return prepared.record;
        }

        async function saveTodayShiftAssignment(name, dateStr, pod, choice) {
            const selected = choice === 'early' ? 'early' : 'pod';
            const current = getTodayShiftAssignment(name, dateStr, pod);
            const win = selected === 'early' ? getAlternateShiftWindow() : getShiftWindowForPod(pod);
            if (!isValidShiftWindow(win)) throw new Error('The selected shift window is invalid.');
            const ready = await ensureRealtimePunchConnectionReady({ userInitiated:true });
            if (!ready) throw new Error("A verified live Firebase connection is required before assigning Today's Shift to another user.");
            const actor = attendanceManagementActorLabel();
            const actorId = recordMutationActorId();
            const stamp = nowIso();
            const item = {
                ...(current || {}),
                id:todayShiftAssignmentId(dateStr, name, pod),
                overrideKind:TODAY_SHIFT_ASSIGNMENT_KIND,
                name,
                pod,
                date:dateStr,
                shiftPreset:selected,
                shiftLabel:selected === 'early' ? (win.label || 'Early 6h shift') : 'Pod schedule',
                shiftStart:win.start,
                shiftEnd:win.end,
                reason:"Today's Shift assignment",
                createdBy:current && current.createdBy ? current.createdBy : actor,
                createdById:current && current.createdById ? current.createdById : actorId,
                createdAt:current && current.createdAt ? current.createdAt : stamp,
                updatedBy:actor,
                updatedById:actorId,
                updatedAt:stamp,
                synchronizedAssignment:true
            };
            const saved = await saveShiftOverride(item, { requireRemoteReceipt:true, returnSync:true, forceAttempt:true });
            clearPendingTodayShiftChoice(dateStr, name);
            try {
                await logAudit(current ? 'today_shift_assignment_updated' : 'today_shift_assignment_created', {
                    auditCategory:'schedule_assignment', name, pod, date:dateStr,
                    shiftPreset:selected, shiftStart:win.start, shiftEnd:win.end,
                    assignmentId:item.id, modified_by:actorId, modified_by_role:isAdmin ? 'admin' : 'team_leader'
                });
            } catch (e) {}
            return saved;
        }

        async function deleteShiftOverride(id) {
            if (!id) return;
            const existing = allShiftOverrides[id];
            if (existing) {
                const permission = existing.overrideKind === 'tl_work_authorization' ? 'schedule.tl_work_authorization.manage' : existing.overrideKind === 'tl_dayoff_date' ? 'schedule.tl_dayoff_override.manage' : 'schedule.shift_override.manage';
                TrinoPermissions.require(permission, { name:existing.name || '', pod:existing.pod || '' }, 'You do not have permission to manage this schedule override.');
            }
            const key = shiftOverrideStorageKey(id);
            const deleteMeta = prepareVersionedDelete(key, existing || {}, { label:`shift override ${id}` });
            delete allShiftOverrides[id];
            queueVersionedDelete(key, deleteMeta);
            const result = await commitVersionedDelete(key, deleteMeta);
            if (result && result.conflict) throw new Error('This shift override changed on another device. The newer server version was kept instead of deleting it.');
            if (!result || !result.remoteDeleted) schedulePendingSyncRetry();
            return result;
        }

        async function loadAllShiftOverrides() {
            try {
                const keys = await appStorage.list('shiftoverride:');
                allShiftOverrides = {};
                for (const k of keys) {
                    try {
                        const raw = await appStorage.get(k);
                        if (!raw) continue;
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.id) allShiftOverrides[parsed.id] = parsed;
                    } catch (e) {}
                }
            } catch (e) { allShiftOverrides = {}; }
        }


        const LEAVE_API_ENDPOINT = window.TRINOTIME_LEAVE_API_ENDPOINT || 'https://asia-southeast1-cwh-timeclock.cloudfunctions.net/leaveApi/leave-requests';
        const LEAVE_MAX_FILE_BYTES = 8 * 1024 * 1024;
        const LEAVE_MAX_RANGE_DAYS = 90;

        function normalizeLeaveStatus(value) {
            const status = String(value || '').trim().toUpperCase();
            return ['PENDING', 'APPROVED', 'REJECTED'].includes(status) ? status : 'PENDING';
        }

        function leaveRequesterIdentity() {
            if (!isAdmin && !isTeamLeader && agentSessionAuthenticated && agentSessionName) {
                return { name: agentSessionName, pod: agentSessionPod || podOf(agentSessionName) || activePod, role: 'agent' };
            }
            if (!isAdmin && isTeamLeader && teamLeaderName) {
                return { name: teamLeaderName, pod: TEAM_LEADER_POD_BY_NAME[teamLeaderName] || lockedPod || activePod, role: 'teamleader' };
            }
            return null;
        }

        function leaveDecisionActor() {
            if (isAdmin) return { name: 'Admin', role: 'admin' };
            if (isTeamLeader && teamLeaderName) return { name: teamLeaderName, role: 'teamleader' };
            return { name: agentSessionName || currentEmployee || 'Agent', role: 'agent' };
        }

        function leaveRequestSubjectRole(request) {
            if (!request) return 'labeler';
            const raw = String(request.requesterRole || request.employeeRole || request.role || '').trim().toLowerCase().replace(/[ _-]+/g, '');
            const name = String(request.agentName || request.name || '').trim();
            if (raw === 'teamleader' || raw === 'tl' || (name && TEAM_LEADER_POD_BY_NAME && TEAM_LEADER_POD_BY_NAME[name])) return 'teamleader';
            return 'labeler';
        }

        function leaveRequestRoleLabel(request) {
            return leaveRequestSubjectRole(request) === 'teamleader' ? 'Team Leader' : 'Labeler';
        }

        function leaveRequestEffectivePod(request) {
            if (!request) return '';
            const explicit = String(request.pod || '').trim();
            if (explicit) return explicit;
            const name = String(request.agentName || request.name || '').trim();
            if (!name) return '';
            return (TEAM_LEADER_POD_BY_NAME && TEAM_LEADER_POD_BY_NAME[name]) || podOf(name) || '';
        }

        function unifiedLeaveRosterMembers(pod = '') {
            const wantedPod = String(pod || '').trim();
            const seen = new Set();
            const out = [];
            const add = (name, memberPod, role) => {
                const cleanName = String(name || '').trim();
                const cleanPod = String(memberPod || '').trim();
                if (!cleanName || (wantedPod && cleanPod !== wantedPod)) return;
                const key = cleanName.toLowerCase();
                if (seen.has(key)) return;
                seen.add(key);
                out.push({ name:cleanName, pod:cleanPod, leaveRole:role, roleLabel:role === 'teamleader' ? 'Team Leader' : 'Labeler' });
            };
            labelerRosterEmployees().forEach(emp => add(emp && emp.name, emp && emp.pod, 'labeler'));
            (Array.isArray(TEAM_LEADER_ROSTER) ? TEAM_LEADER_ROSTER : []).forEach(tl => add(tl && tl.name, tl && tl.pod, 'teamleader'));
            if ((!Array.isArray(TEAM_LEADER_ROSTER) || !TEAM_LEADER_ROSTER.length) && TEAM_LEADER_POD_BY_NAME) {
                Object.entries(TEAM_LEADER_POD_BY_NAME).forEach(([name, memberPod]) => add(name, memberPod, 'teamleader'));
            }
            return out;
        }

        function unifiedLeaveAvailabilitySnapshot(pod, dateStr) {
            return unifiedLeaveRosterMembers(pod).map(member => {
                const availability = resolveEffectiveAvailability(member.name, dateStr, member.pod || pod, { includeAttendance:false });
                return {
                    ...member,
                    availability,
                    leaveRequest:availability.leaveRequest,
                    onLeave:!!availability.leaveRequest,
                    fullDayLeave:availability.fullDayLeave,
                    scheduledDayOff:availability.scheduledDayOff,
                    available:availability.available,
                    availabilityCode:availability.code,
                    availabilityReason:availability.reason
                };
            });
        }

        function normalizeLeaveRequestForRoster(request, fallbackId = '') {
            if (!request || typeof request !== 'object') return null;
            const normalized = { ...request };
            if (!normalized.id && fallbackId) normalized.id = fallbackId;
            normalized.status = normalizeLeaveStatus(normalized.status);
            const inferredPod = leaveRequestEffectivePod(normalized);
            if (!normalized.pod && inferredPod) normalized.pod = inferredPod;
            if (!normalized.requesterRole) normalized.requesterRole = leaveRequestSubjectRole(normalized);
            return normalized;
        }

        function leaveIsoDateParts(iso) {
            const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso || ''));
            if (!match) return null;
            const y = Number(match[1]), m = Number(match[2]), d = Number(match[3]);
            const dt = new Date(Date.UTC(y, m - 1, d));
            if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
            return { y, m, d };
        }

        function leaveDateRangeDays(startIso, endIso) {
            const start = leaveIsoDateParts(startIso);
            const end = leaveIsoDateParts(endIso);
            if (!start || !end) return [];
            let cursor = Date.UTC(start.y, start.m - 1, start.d);
            const stop = Date.UTC(end.y, end.m - 1, end.d);
            if (stop < cursor) return [];
            const days = [];
            while (cursor <= stop && days.length <= LEAVE_MAX_RANGE_DAYS) {
                const dt = new Date(cursor);
                days.push(`${dt.getUTCMonth() + 1}/${dt.getUTCDate()}/${dt.getUTCFullYear()}`);
                cursor += 86400000;
            }
            return days;
        }

        function leaveRequestRangeContainsDate(request, dateStr) {
            if (!request) return false;
            const comp = dateStrToComparable(dateStr);
            const start = isoToComparable(request.startDate);
            const end = isoToComparable(request.endDate);
            return start !== null && end !== null && comp >= start && comp <= end;
        }

        function leaveRequestDateContains(request, dateStr) {
            return !!(request && normalizeLeaveStatus(request.status) === 'APPROVED' && leaveRequestRangeContainsDate(request, dateStr));
        }

        function getActiveLeaveForEmployeeOnDate(name, dateStr, pod) {
            const exactName = String(name || '').trim().toLowerCase();
            if (!exactName) return null;
            const matches = Object.values(allLeaveRequests).filter(request => {
                if (!request || !['PENDING','APPROVED'].includes(normalizeLeaveStatus(request.status))) return false;
                if (String(request.agentName || '').trim().toLowerCase() !== exactName) return false;
                const requestPod = leaveRequestEffectivePod(request);
                if (pod && requestPod && requestPod !== pod) return false;
                return leaveRequestRangeContainsDate(request, dateStr);
            });
            matches.sort((a,b) => String(b.updatedAt || b.createdAt || '').localeCompare(String(a.updatedAt || a.createdAt || '')));
            return matches[0] || null;
        }

        function getApprovedLeaveForEmployee(name, dateStr, pod) {
            const exactName = String(name || '').trim().toLowerCase();
            if (!exactName) return null;
            const matches = Object.values(allLeaveRequests).filter(request => {
                if (!request || normalizeLeaveStatus(request.status) !== 'APPROVED') return false;
                if (String(request.agentName || '').trim().toLowerCase() !== exactName) return false;
                const requestPod = leaveRequestEffectivePod(request);
                if (pod && requestPod && requestPod !== pod) return false;
                return leaveRequestDateContains(request, dateStr);
            });
            matches.sort((a, b) => String(b.decisionAt || b.updatedAt || '').localeCompare(String(a.decisionAt || a.updatedAt || '')));
            return matches[0] || null;
        }

        function leaveRangesOverlap(aStart, aEnd, bStart, bEnd) {
            const a1 = isoToComparable(aStart), a2 = isoToComparable(aEnd);
            const b1 = isoToComparable(bStart), b2 = isoToComparable(bEnd);
            if ([a1, a2, b1, b2].some(v => v === null)) return false;
            return a1 <= b2 && b1 <= a2;
        }

        function leaveRequestHasAttendanceConflict(request) {
            return leaveDateRangeDays(request.startDate, request.endDate).some(dateStr => effectiveLeaveChargeableResolver(request, dateStr) && hasAttendanceActivity(request.agentName, dateStr));
        }

        function canReviewLeaveRequest(request) {
            if (!request || normalizeLeaveStatus(request.status) !== 'PENDING') return false;
            if (isAdmin) return true;
            if (!isTeamLeader || !teamLeaderName || !lockedPod) return false;
            if (leaveRequestEffectivePod(request) !== lockedPod) return false;
            if (leaveRequestSubjectRole(request) === 'teamleader') return false;
            return String(request.agentName || '').trim().toLowerCase() !== String(teamLeaderName).trim().toLowerCase();
        }

        function leaveRequestVisibleToViewer(request) {
            if (!request) return false;
            const requestPod = leaveRequestEffectivePod(request);
            if (isAdmin) return !requestPod || teamIdForPod(requestPod) === activeTeam;
            if (isTeamLeader) return requestPod === lockedPod;
            return !!(agentSessionAuthenticated && agentSessionName && String(request.agentName || '').toLowerCase() === String(agentSessionName).toLowerCase());
        }

        function leaveRequestSortNewest(a, b) {
            return String(b.createdAt || b.updatedAt || '').localeCompare(String(a.createdAt || a.updatedAt || ''));
        }

        function formatLeaveDate(iso) {
            const p = leaveIsoDateParts(iso);
            if (!p) return String(iso || '—');
            return new Date(Date.UTC(p.y, p.m - 1, p.d)).toLocaleDateString('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric', year: 'numeric' });
        }

        function formatLeaveRange(request) {
            if (!request) return '—';
            const start = formatLeaveDate(request.startDate);
            const end = formatLeaveDate(request.endDate);
            return request.startDate === request.endDate ? start : `${start} – ${end}`;
        }

        function leaveSafeAttachmentUrl(value) {
            const raw = String(value || '').trim();
            if (!raw) return '';
            try {
                const url = new URL(raw);
                return url.protocol === 'https:' ? url.toString() : '';
            } catch (_) { return ''; }
        }

        function leaveAttachmentMarkup(request) {
            if (!request) return '';
            if (request.attachmentUrl) {
                const allowedUrl = leaveSafeAttachmentUrl(request.attachmentUrl);
                if (allowedUrl) {
                    const safeUrl = escapeHtml(allowedUrl);
                    return `<div class="leave-request-attachment">Attachment: <a href="${safeUrl}" target="_blank" rel="noopener noreferrer">Open supporting document</a></div>`;
                }
                return '<div class="leave-request-attachment">Attachment URL blocked because it is not a valid HTTPS link.</div>';
            }
            if (request.attachmentName) {
                return `<div class="leave-request-attachment">Attachment file: ${escapeHtml(request.attachmentName)}${request.attachmentUploadPending ? ' · upload awaiting API endpoint' : ''}</div>`;
            }
            return '';
        }

        function leaveRequestCardMarkup(request, options = {}) {
            const status = normalizeLeaveStatus(request.status);
            const statusClass = status.toLowerCase();
            const effectivePod = leaveRequestEffectivePod(request);
            const podLabel = effectivePod ? podContextLabel(effectivePod) : 'Unassigned POD';
            const roleLabel = leaveRequestRoleLabel(request);
            const roleClass = leaveRequestSubjectRole(request) === 'teamleader' ? 'team-leader' : 'labeler';
            const decision = request.decisionAt ? `<div class="leave-request-meta">Decision: ${escapeHtml(request.decisionBy || 'Reviewer')} · ${escapeHtml(formatLeaveDate(String(request.decisionAt).slice(0,10)))}${request.decisionNote ? ` · ${escapeHtml(request.decisionNote)}` : ''}</div>` : '';
            const actions = options.review && status === 'PENDING' ? (canReviewLeaveRequest(request) ?
                `<div class="leave-review-actions"><button class="leave-approve-btn" type="button" data-leave-action="approve" data-leave-id="${escapeHtml(request.id)}">Approve</button><button class="leave-reject-btn" type="button" data-leave-action="reject" data-leave-id="${escapeHtml(request.id)}">Reject</button></div>` :
                `<div class="leave-request-meta">${isTeamLeader && String(request.agentName || '').toLowerCase() === String(teamLeaderName || '').toLowerCase() ? 'Your own request requires Admin approval.' : 'Read-only in this account scope.'}</div>`) : '';
            return `<article class="leave-request-card ${statusClass}">
                <div class="leave-request-card-head">
                    <div class="leave-request-card-title"><strong>${escapeHtml(agentDisplayName(request.agentName) || 'Team member')} · ${escapeHtml(request.leaveType || 'Leave')}</strong><span class="leave-role-pill ${roleClass}">${escapeHtml(roleLabel)}</span><span>${escapeHtml(formatLeaveRange(request))} · ${escapeHtml(podLabel)}</span></div>
                    <span class="leave-status-pill ${statusClass}">${escapeHtml(status)}</span>
                </div>
                ${request.reason ? `<div class="leave-request-reason">${escapeHtml(request.reason)}</div>` : ''}
                <div class="leave-request-meta">Submitted ${escapeHtml(formatLeaveDate(String(request.createdAt || '').slice(0,10)))} · ID ${escapeHtml(request.id || '')}</div>
                ${leaveAttachmentMarkup(request)}${decision}${actions}
            </article>`;
        }

        function pendingLeaveApprovalRequests() {
            return Object.values(allLeaveRequests).filter(request => normalizeLeaveStatus(request.status) === 'PENDING' && leaveRequestVisibleToViewer(request)).sort(leaveRequestSortNewest);
        }

        function updateLeaveRequestBadge() {
            const badge = $('leaveRequestFloaterBadge');
            if (!badge) return;
            let count = 0;
            if (isAdmin || isTeamLeader) count = pendingLeaveApprovalRequests().filter(canReviewLeaveRequest).length;
            else if (agentSessionAuthenticated && agentSessionName) {
                count = Object.values(allLeaveRequests).filter(request => normalizeLeaveStatus(request.status) === 'PENDING' && String(request.agentName || '').toLowerCase() === String(agentSessionName).toLowerCase()).length;
            }
            badge.textContent = count > 99 ? '99+' : String(count);
            badge.classList.toggle('show', count > 0);
        }

        function resetLeaveRequestForm(options = {}) {
            const identity = leaveRequesterIdentity();
            const form = $('leaveRequestForm');
            if (!form) return;
            if (options.full !== false) form.reset();
            const identityInput = $('leaveAgentIdentity');
            if (identityInput) identityInput.value = identity ? `${agentDisplayName(identity.name)} · ${agentAuthId(identity.name)}` : '';
            const todayIso = mdyToIsoDateInput(todayKeyPart());
            const start = $('leaveStartDate');
            const end = $('leaveEndDate');
            if (start && !start.value) start.value = todayIso;
            if (end && !end.value) end.value = start && start.value ? start.value : todayIso;
            const err = $('leaveRequestError');
            if (err) { err.textContent = ''; err.classList.remove('show'); }
        }

        function renderLeaveRequestModal() {
            const identity = leaveRequesterIdentity();
            const form = $('leaveRequestForm');
            const unavailable = $('leaveRequestFormUnavailable');
            if (form) form.style.display = identity ? 'block' : 'none';
            if (unavailable) unavailable.style.display = identity ? 'none' : 'block';
            resetLeaveRequestForm({ full:false });

            const recentTitle = $('leaveRecentTitle');
            const recentScope = $('leaveRecentScope');
            let recent = Object.values(allLeaveRequests).filter(leaveRequestVisibleToViewer).sort(leaveRequestSortNewest);
            if (identity) {
                recent = recent.filter(request => String(request.agentName || '').toLowerCase() === identity.name.toLowerCase());
                if (recentTitle) recentTitle.textContent = 'My Requests';
                if (recentScope) recentScope.textContent = `${agentDisplayName(identity.name)} · ${podContextLabel(identity.pod)}`;
            } else {
                if (recentTitle) recentTitle.textContent = 'Recent Requests';
                if (recentScope) recentScope.textContent = isAdmin ? `${teamGroupById(activeTeam).fullName} approval scope` : 'Current approval scope';
            }
            const recentList = $('leaveRecentList');
            if (recentList) recentList.innerHTML = recent.length ? recent.slice(0, 30).map(request => leaveRequestCardMarkup(request)).join('') : '<div class="leave-empty">No leave requests in this view yet.</div>';

            const pendingPanel = $('leavePendingPanel');
            const pendingList = $('leavePendingList');
            const pendingCount = $('leavePendingCount');
            const pendingScope = $('leavePendingScope');
            if (pendingPanel) pendingPanel.style.display = (isAdmin || isTeamLeader) ? 'block' : 'none';
            if (isAdmin || isTeamLeader) {
                const pending = pendingLeaveApprovalRequests();
                const actionable = pending.filter(canReviewLeaveRequest).length;
                if (pendingCount) pendingCount.textContent = String(actionable);
                if (pendingScope) pendingScope.textContent = isAdmin ? `${teamGroupById(activeTeam).fullName} · ${actionable} awaiting action` : `${podContextLabel(lockedPod)} · ${actionable} awaiting your action`;
                if (pendingList) pendingList.innerHTML = pending.length ? pending.map(request => leaveRequestCardMarkup(request, { review:true })).join('') : '<div class="leave-empty">No pending approvals in this scope.</div>';
            }
            updateLeaveRequestBadge();
        }

        function syncLeaveRequestUi(options = {}) {
            const floater = $('leaveRequestFloater');
            const hasSession = !!(isAdmin || (isTeamLeader && teamLeaderName) || (agentSessionAuthenticated && agentSessionName));
            if (floater) floater.hidden = !hasSession;
            updateLeaveRequestBadge();
            const overlay = $('leaveRequestOverlay');
            if (hasSession && overlay && (options.renderOpen || overlay.classList.contains('open'))) renderLeaveRequestModal();
            if (!hasSession && overlay) overlay.classList.remove('open');
        }

        function openLeaveRequestModal() {
            if (typeof closeProfileDirectorySearchDrawer === 'function') closeProfileDirectorySearchDrawer({ returnFocus:false });
            if (!(isAdmin || isTeamLeader || agentSessionAuthenticated)) {
                showToast('Sign in before opening Leave Request.');
                return;
            }
            renderLeaveRequestModal();
            $('leaveRequestOverlay').classList.add('open');
            requestAnimationFrame(() => {
                const target = leaveRequesterIdentity() ? $('leaveType') : $('leavePendingList');
                if (target && typeof target.focus === 'function') { try { target.focus({ preventScroll:true }); } catch (e) {} }
            });
        }

        function closeLeaveRequestModal() {
            const overlay = $('leaveRequestOverlay');
            if (overlay) overlay.classList.remove('open');
        }

        function showLeaveRequestError(message) {
            const err = $('leaveRequestError');
            if (!err) return;
            err.textContent = String(message || 'Please check the request details.');
            err.classList.add('show');
        }

        async function postLeaveRequestToApi(request, file) {
            if (typeof fetch !== 'function') return { ok:false, reason:'fetch unavailable' };
            const controller = typeof AbortController === 'function' ? new AbortController() : null;
            const timer = controller ? setTimeout(() => controller.abort(), 9000) : null;
            try {
                let response;
                if (file) {
                    const formData = new FormData();
                    formData.append('payload', JSON.stringify(request));
                    formData.append('attachment', file, file.name);
                    response = await fetch(LEAVE_API_ENDPOINT, { method:'POST', body:formData, signal:controller ? controller.signal : undefined, credentials:'same-origin' });
                } else {
                    response = await fetch(LEAVE_API_ENDPOINT, { method:'POST', headers:{ 'Content-Type':'application/json' }, body:JSON.stringify(request), signal:controller ? controller.signal : undefined, credentials:'same-origin' });
                }
                if (!response.ok) return { ok:false, status:response.status };
                let data = null;
                try { data = await response.json(); } catch (e) {}
                return { ok:true, data };
            } catch (error) {
                return { ok:false, error };
            } finally {
                if (timer) clearTimeout(timer);
            }
        }

        async function patchLeaveRequestApi(request) {
            if (typeof fetch !== 'function') return { ok:false, reason:'fetch unavailable' };
            const controller = typeof AbortController === 'function' ? new AbortController() : null;
            const timer = controller ? setTimeout(() => controller.abort(), 9000) : null;
            try {
                const response = await fetch(`${LEAVE_API_ENDPOINT}/${encodeURIComponent(request.id)}`, {
                    method:'PATCH',
                    headers:{ 'Content-Type':'application/json' },
                    body:JSON.stringify({ status:request.status, decisionAt:request.decisionAt, decisionBy:request.decisionBy, decisionRole:request.decisionRole, decisionNote:request.decisionNote || '', scheduleSyncedAt:request.scheduleSyncedAt || null }),
                    signal:controller ? controller.signal : undefined,
                    credentials:'same-origin'
                });
                if (!response.ok) return { ok:false, status:response.status };
                let data = null;
                try { data = await response.json(); } catch (e) {}
                return { ok:true, data };
            } catch (error) {
                return { ok:false, error };
            } finally {
                if (timer) clearTimeout(timer);
            }
        }

        async function saveLeaveRequest(request) {
            if (!request || !request.id) throw new Error('Invalid leave request.');
            request = { ...request, status:normalizeLeaveStatus(request.status), updatedAt:request.updatedAt || nowIso() };
            const existing = allLeaveRequests[request.id] || {};
            const key = leaveRequestStorageKey(request.id);
            const prepared = prepareVersionedRecord(key, existing, request, { label:`leave request ${request.id}` });
            allLeaveRequests[request.id] = prepared.record;
            queueVersionedRecord(key, prepared);
            publishUpdate();
            syncLeaveRequestUi({ renderOpen:true });
            const result = await commitVersionedRecord(key, prepared.payload, prepared.meta, { leaveRequest:true });
            if (result && result.conflict) throw new Error('This leave request changed on another device. The newer server version was kept.');
            if (!result || !result.remoteSaved) schedulePendingSyncRetry();
            return prepared.record;
        }

        async function loadAllLeaveRequests() {
            try {
                const keys = await appStorage.list('leave:');
                const next = {};
                for (const key of keys) {
                    try {
                        const raw = await appStorage.get(key);
                        if (!raw) continue;
                        const parsed = normalizeLeaveRequestForRoster(JSON.parse(raw));
                        if (parsed && parsed.id) next[parsed.id] = parsed;
                    } catch (e) {}
                }
                allLeaveRequests = next;
            } catch (e) { allLeaveRequests = {}; }
            syncLeaveRequestUi({ renderOpen:true });
        }

        function refreshLeaveAffectedViews(request) {
            syncLeaveRequestUi({ renderOpen:true });
            withScrollPreserved(() => {
                if (isPanelVisible($('desktopTableContainer')) || isPanelVisible($('mobileCards'))) renderTable();
                if (isOverlayOpen($('todayStatusOverlay'))) renderTodayStatus();
                if (isOverlayOpen($('historyOverlay'))) renderHistoryCalendar();
                if (isOverlayOpen($('dayOffOverlay'))) renderDayOffSwapList($('dayOffPodSelect') ? $('dayOffPodSelect').value : activePod);
                if (isOverlayOpen($('scheduleExceptionsOverlay'))) refreshScheduleExceptionsView();
                if (request && (currentEmployee === request.agentName || agentSessionName === request.agentName || teamLeaderName === request.agentName)) refreshPunchCard();
            });
        }

        async function submitLeaveRequestFromModal() {
            const identity = leaveRequesterIdentity();
            if (!identity) throw new Error('Leave requests must be submitted from an Agent or Team Leader session.');
            const leaveType = String($('leaveType').value || '').trim();
            const startDate = String($('leaveStartDate').value || '').trim();
            const endDate = String($('leaveEndDate').value || '').trim();
            const reason = String($('leaveReason').value || '').trim();
            const attachmentUrl = String($('leaveAttachmentUrl').value || '').trim();
            const file = $('leaveAttachmentFile').files && $('leaveAttachmentFile').files[0] ? $('leaveAttachmentFile').files[0] : null;
            if (!leaveType) throw new Error('Choose a leave type.');
            if (!leaveIsoDateParts(startDate) || !leaveIsoDateParts(endDate)) throw new Error('Choose a valid start and end date.');
            if (isoToComparable(endDate) < isoToComparable(startDate)) throw new Error('End Date cannot be earlier than Start Date.');
            const days = leaveDateRangeDays(startDate, endDate);
            if (!days.length) throw new Error('Choose a valid leave date range.');
            if (days.length > LEAVE_MAX_RANGE_DAYS) throw new Error(`Leave requests are limited to ${LEAVE_MAX_RANGE_DAYS} calendar days per submission.`);
            if (reason.length < 3) throw new Error('Add a brief reason or details for the request.');
            if (attachmentUrl && !/^https:\/\//i.test(attachmentUrl)) throw new Error('Attachment URL must begin with https://.');
            if (file && file.size > LEAVE_MAX_FILE_BYTES) throw new Error('Supporting files must be 8 MB or smaller.');
            const duplicate = Object.values(allLeaveRequests).find(request => request && String(request.agentName || '').toLowerCase() === identity.name.toLowerCase() && ['PENDING','APPROVED'].includes(normalizeLeaveStatus(request.status)) && leaveRangesOverlap(startDate, endDate, request.startDate, request.endDate));
            if (duplicate) throw new Error(`This date range overlaps an existing ${normalizeLeaveStatus(duplicate.status).toLowerCase()} leave request.`);

            const createdAt = nowIso();
            const request = {
                id: 'lv-' + createMutationToken(),
                agentName: identity.name,
                agentId: agentAuthId(identity.name),
                pod: identity.pod,
                team: teamIdForPod(identity.pod),
                requesterRole: identity.role,
                leaveType,
                startDate,
                endDate,
                reason,
                attachmentUrl: attachmentUrl || '',
                attachmentName: file ? file.name : '',
                attachmentType: file ? file.type : '',
                attachmentSize: file ? file.size : 0,
                attachmentUploadPending: !!file,
                status: 'PENDING',
                createdAt,
                updatedAt: createdAt,
                apiSync: 'pending'
            };

            await saveLeaveRequest(request);
            refreshLeaveAffectedViews(request);
            resetLeaveRequestForm();
            showToast('Leave request sent for approval.');
            void logAudit('leave_request_submit', { requestId:request.id, name:request.agentName, pod:request.pod, leaveType:request.leaveType, startDate, endDate, status:'PENDING' });

            void postLeaveRequestToApi(request, file).then(async result => {
                const latest = allLeaveRequests[request.id];
                if (!latest) return;
                const next = { ...latest, apiSync: result.ok ? 'api' : 'firebase-fallback', apiSyncedAt: result.ok ? nowIso() : null };
                if (result.ok && result.data && typeof result.data === 'object') {
                    if (result.data.attachmentUrl) next.attachmentUrl = String(result.data.attachmentUrl);
                    if (result.data.requestId || result.data.id) next.serverRequestId = String(result.data.requestId || result.data.id);
                    next.attachmentUploadPending = false;
                }
                await saveLeaveRequest(next);
                syncLeaveRequestUi({ renderOpen:true });
            }).catch(() => {});
        }

        async function updateLeaveRequestStatus(id, nextStatus, decisionNote = '') {
            const request = allLeaveRequests[id];
            if (!request) throw new Error('Leave request was not found.');
            if (!canReviewLeaveRequest(request) || !TrinoPermissions.can('leave.request.review', { name:request.agentName || '', pod:request.pod || '' })) throw new Error('You do not have permission to review this leave request.');
            const status = normalizeLeaveStatus(nextStatus);
            if (!['APPROVED','REJECTED'].includes(status)) throw new Error('Unsupported leave decision.');
            if (status === 'APPROVED' && leaveRequestHasAttendanceConflict(request)) {
                throw new Error('This request overlaps attendance punches. Correct or review attendance before approving leave for those dates.');
            }
            const actor = leaveDecisionActor();
            const decisionAt = nowIso();
            const next = {
                ...request,
                status,
                decisionAt,
                decisionBy: actor.name,
                decisionRole: actor.role,
                decisionNote: String(decisionNote || '').trim(),
                updatedAt: decisionAt,
                scheduleSyncedAt: status === 'APPROVED' ? decisionAt : null
            };
            await saveLeaveRequest(next);
            refreshLeaveAffectedViews(next);
            await logAudit(status === 'APPROVED' ? 'leave_request_approved' : 'leave_request_rejected', {
                requestId:next.id, name:next.agentName, pod:next.pod, leaveType:next.leaveType,
                startDate:next.startDate, endDate:next.endDate, status, decisionBy:actor.name, decisionRole:actor.role, decisionNote:next.decisionNote
            });
            showToast(status === 'APPROVED' ? 'Leave approved and synced to the schedule.' : 'Leave request rejected.');
            void patchLeaveRequestApi(next).then(async result => {
                const latest = allLeaveRequests[id];
                if (!latest) return;
                if (result.ok && latest.apiSync !== 'api') await saveLeaveRequest({ ...latest, apiSync:'api', apiSyncedAt:nowIso() });
            }).catch(() => {});
            return next;
        }

        function applyKvSnapshot(val) {
            val = val || {};
            fbKvCache = {};
            agentSecurityStateCache.clear();
            const newRecords = {};
            const newTeamLeaderRecords = {};
            const newOT = {};
            const newOvertimePeriodLocks = {};
            const newSpeedTests = {};
            const newAgentProfiles = {};
            let newNetworkQualitySettings = null;
            const newDayOffSwaps = {};
            const newShiftOverrides = {};
            const newLeaveRequests = {};
            let newEmployees = null;
            let newPodDirectoryRaw = null;
            let podDirectorySeen = false;
            let newTeamLeaderDirectoryRaw = null;
            let teamLeaderDirectorySeen = false;
            let newDayOff = null;
            let newShiftSettings = null;
            let newAnnouncements = null;
            let newPremiumAccessPolicy = defaultPremiumAccessPolicy();
            let premiumPolicyServerConfirmed = false;
            let legacyBeblessPremiumAccessSeen = false;
            const ingestedKeys = new Set();

            const ingest = (key, raw, fromPending = false) => {
                if (typeof raw !== 'string' || hasPendingDelete(key)) return;
                if (!fromPending && hasPendingWrite(key)) return;
                ingestedKeys.add(key);
                fbKvCache[key] = raw;
                if (key.startsWith(AGENT_AUTH_KEY_PREFIX)) cacheAgentSecurityStateFromRaw(key, raw);
                if (!fromPending) setLocalMirrorForKey(key, raw, { pendingCloudSync:false });

                if (key.indexOf('att:') === 0) {
                    try { newRecords[key.slice(4)] = JSON.parse(raw); } catch (e) {}
                } else if (key.indexOf(TL_ATTENDANCE_KEY_PREFIX) === 0) {
                    try { newTeamLeaderRecords[key.slice(TL_ATTENDANCE_KEY_PREFIX.length)] = JSON.parse(raw); } catch (e) {}
                } else if (key.indexOf('ot:') === 0) {
                    try { newOT[key.slice(3)] = JSON.parse(raw); } catch (e) {}
                } else if (key.indexOf(OVERTIME_PAYROLL_LOCK_PREFIX) === 0) {
                    try { newOvertimePeriodLocks[key.slice(OVERTIME_PAYROLL_LOCK_PREFIX.length)] = JSON.parse(raw); } catch (e) {}
                } else if (key.indexOf('speedtest:') === 0) {
                    try {
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.id) newSpeedTests[parsed.id] = parsed;
                    } catch (e) {}
                } else if (key.indexOf('profile:') === 0) {
                    try {
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.agentName) newAgentProfiles[key.slice('profile:'.length)] = parsed;
                    } catch (e) {}
                } else if (key === NETWORK_SETTINGS_KEY) {
                    try { newNetworkQualitySettings = JSON.parse(raw); } catch (e) {}
                } else if (key.indexOf('dayswap:') === 0) {
                    try {
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.id) newDayOffSwaps[parsed.id] = parsed;
                    } catch (e) {}
                } else if (key.indexOf('shiftoverride:') === 0) {
                    try {
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.id) newShiftOverrides[parsed.id] = parsed;
                    } catch (e) {}
                } else if (key.indexOf('leave:') === 0) {
                    try {
                        const parsed = normalizeLeaveRequestForRoster(JSON.parse(raw));
                        if (parsed && parsed.id) newLeaveRequests[parsed.id] = parsed;
                    } catch (e) {}
                } else if (key === POD_DIRECTORY_KEY) {
                    newPodDirectoryRaw = raw;
                    podDirectorySeen = true;
                } else if (key === TEAM_LEADER_DIRECTORY_KEY) {
                    newTeamLeaderDirectoryRaw = raw;
                    teamLeaderDirectorySeen = true;
                } else if (key === 'employees') {
                    try {
                        const parsed = JSON.parse(raw);
                        if (Array.isArray(parsed)) newEmployees = parsed;
                    } catch (e) {}
                } else if (key === 'dayoff_schedule') {
                    try { newDayOff = JSON.parse(raw); } catch (e) {}
                } else if (key === 'shift_settings') {
                    try { newShiftSettings = JSON.parse(raw); } catch (e) {}
                } else if (key === 'announcements') {
                    try {
                        const parsed = JSON.parse(raw);
                        if (Array.isArray(parsed)) newAnnouncements = parsed;
                    } catch (e) {}
                } else if (key === PREMIUM_ACCESS_POLICY_KEY) {
                    newPremiumAccessPolicy = parsePremiumAccessPolicyRaw(raw);
                    if (!fromPending) premiumPolicyServerConfirmed = true;
                } else if (key === PREMIUM_BEBLESS_LEGACY_ACCESS_KEY) {
                    legacyBeblessPremiumAccessSeen = true;
                } else if (key === 'employees_v') {
                    employeesVersion = raw;
                } else if (key === 'dayoff_schedule_v') {
                    dayOffVersion = raw;
                } else if (key === 'shift_settings_v') {
                    shiftSettingsVersion = raw;
                } else if (key === 'announcements_v') {
                    announcementsVersion = raw;
                }
            };

            for (const encodedKey of Object.keys(val)) {
                let key;
                try { key = fbDecodeKey(encodedKey); } catch (e) { continue; }
                const raw = val[encodedKey];
                ingest(key, raw, false);
            }

            getLocalKeysWithPrefix(PENDING_PREFIX).forEach(storageKey => {
                const key = storageKey.slice(PENDING_PREFIX.length);
                if (!key || hasPendingDelete(key)) return;
                const raw = pendingWritePayload(key);
                if (raw !== null) ingest(key, raw, true);
            });

            const managedSingletons = new Set([
                'employees', POD_DIRECTORY_KEY, TEAM_LEADER_DIRECTORY_KEY, 'dayoff_schedule', 'shift_settings', 'announcements', 'audit_log', NETWORK_SETTINGS_KEY, PREMIUM_ACCESS_POLICY_KEY, PREMIUM_BEBLESS_LEGACY_ACCESS_KEY,
                'employees_v', 'dayoff_schedule_v', 'shift_settings_v', 'announcements_v'
            ]);
            try {
                const localKeys = [];
                for (let i = 0; i < localStorage.length; i++) {
                    const key = localStorage.key(i);
                    if (key) localKeys.push(key);
                }
                localKeys.forEach(key => {
                    const managed = key.startsWith('att:') || key.startsWith(TL_ATTENDANCE_KEY_PREFIX) || key.startsWith('ot:') || key.startsWith(OVERTIME_PAYROLL_LOCK_PREFIX) || key.startsWith('speedtest:') || key.startsWith('profile:') || key.startsWith('dayswap:') || key.startsWith('shiftoverride:') || key.startsWith('leave:') || key.startsWith('leaveledger:') || key.startsWith('leaveprofile:') || key.startsWith('leavepolicyv3:') || key === 'leave_policy_v3' || key.startsWith(AGENT_AUTH_KEY_PREFIX) || key.startsWith(TEAM_LEADER_AUTH_KEY_PREFIX) || managedSingletons.has(key);
                    if (!managed || ingestedKeys.has(key) || hasPendingWrite(key) || hasPendingDelete(key)) return;
                    safeLocalRemove(key);
                });
            } catch (e) {}

            cachedAnnouncements = newAnnouncements || [];
            allRecords = newRecords;
            allTeamLeaderRecords = newTeamLeaderRecords;
            allOT = newOT;
            allOvertimePeriodLocks = newOvertimePeriodLocks;
            allSpeedTests = newSpeedTests;
            profileServerSnapshotIds.clear();
            Object.keys(newAgentProfiles).forEach(id => profileServerSnapshotIds.add(id));
            profileServerSnapshotLoaded = true;
            allAgentProfiles = newAgentProfiles;
            networkQualitySettings = mergeNetworkQualitySettings(newNetworkQualitySettings || DEFAULT_NETWORK_QUALITY_SETTINGS);
            allDayOffSwaps = newDayOffSwaps;
            allShiftOverrides = newShiftOverrides;
            allLeaveRequests = newLeaveRequests;
            premiumPodAccessPolicy = normalizePremiumAccessPolicy(newPremiumAccessPolicy);
            markPremiumPodPolicyTrust(premiumPolicyServerConfirmed ? 'server-confirmed' : 'missing', 'firebase-snapshot', premiumPolicyServerConfirmed ? 'Premium policy confirmed by Firebase snapshot.' : 'Premium policy is absent or pending; Standard is enforced for Premium-gated access.');
            premiumBeblessLegacyEntitlementDetected = premiumBeblessLegacyEntitlementDetected || legacyBeblessPremiumAccessSeen;
            applyPremiumModeForCurrentSession('firebase-snapshot');
            renderPremiumAccessManager();
            let usedDefaultEmployees = false;
            let usedDefaultDayOff = false;
            if (podDirectorySeen && newPodDirectoryRaw) {
                applyPodDirectoryState(newPodDirectoryRaw, { serverConfirmed:true, source:'firebase-snapshot' });
            } else if (!podDirectorySeen) {
                podDirectoryServerConfirmed = true;
                applyPodDirectoryState({ revision:0, entries:DEFAULT_POD_DIRECTORY.map(entry => ({ ...entry })) }, { serverConfirmed:true, source:'firebase-snapshot-default' });
            }
            if (teamLeaderDirectorySeen && newTeamLeaderDirectoryRaw) {
                applyTeamLeaderDirectoryState(newTeamLeaderDirectoryRaw, { serverConfirmed:true, source:'firebase-snapshot' });
            } else if (!teamLeaderDirectorySeen) {
                teamLeaderDirectoryServerConfirmed = true;
            }
            if (newEmployees !== null) {
                employees = sanitizeEmployeeRoster(newEmployees);
            } else if (!employees.length) {
                employees = [];
            }
            if (newDayOff) {
                const merged = JSON.parse(JSON.stringify(DEFAULT_SCHEDULE));
                for (const [pod, data] of Object.entries(newDayOff)) merged[pod] = data;
                dayOffSchedule = merged;
            } else if (!Object.keys(dayOffSchedule).length) {
                dayOffSchedule = JSON.parse(JSON.stringify(DEFAULT_SCHEDULE));
                usedDefaultDayOff = true;
            }
            ensureCustomPodRuntimeScheduleData();
            if (newShiftSettings) {
                shiftSettings = mergeShiftSettings(newShiftSettings);
            }
            return { usedDefaultEmployees, usedDefaultDayOff };
        }

        async function loadAllFromFirebaseOnce(timeoutMs = FIREBASE_READ_TIMEOUT_MS) {
            if (!fbDb) throw new Error('Live database is unavailable.');
            try {
                const snap = await withTimeout(
                    fbDb.ref('kv').once('value'),
                    Math.max(1500, Number(timeoutMs) || FIREBASE_READ_TIMEOUT_MS),
                    'Timed out loading live data.'
                );
                const result = applyKvSnapshot(snap.val());
                if (fbConnected !== true) setLiveConnectionState(true, 'full-snapshot');
                return result;
            } catch (error) {
                handleStorageError(error, 'snapshot-failed');
                throw error;
            }
        }

        async function loadDayOffSchedule() {
            try {
                const raw = await appStorage.get('dayoff_schedule');
                if (raw) {
                    const parsed = JSON.parse(raw);
                    dayOffSchedule = JSON.parse(JSON.stringify(DEFAULT_SCHEDULE));
                    for (const [pod, data] of Object.entries(parsed)) {
                        if (dayOffSchedule[pod]) {
                            dayOffSchedule[pod] = data;
                        } else {
                            dayOffSchedule[pod] = data;
                        }
                    }
                    ensureCustomPodRuntimeScheduleData();
                    return;
                }
            } catch (e) {}
            dayOffSchedule = JSON.parse(JSON.stringify(DEFAULT_SCHEDULE));
            ensureCustomPodRuntimeScheduleData();
        }

        async function saveDayOffSchedule() {
            await saveBlobWithBackup('dayoff_schedule', JSON.stringify(dayOffSchedule));
        }

        async function saveShiftSettings() {
            await saveBlobWithBackup('shift_settings', JSON.stringify(shiftSettings));
        }

        function cutoffDateFor(dateStr, hhmm) {
            return new Date(manilaScheduleBoundaryMs(dateStr, hhmm));
        }
        function isLateTimeIn(rec, dateStr, pod) {
            return getLateArrivalMs(rec, dateStr, pod) > 0;
        }
        function isEarlyLogout(rec, dateStr, pod) {
            return getEarlyLogoutMs(rec, dateStr, pod) > 0;
        }
        function breakDurationMs(rec, nowMs) {
            if (!rec || !rec.startBreak) return 0;
            const start = new Date(rec.startBreak).getTime();
            const end = getEffectiveBreakEndMs(rec, nowMs);
            if (!Number.isFinite(start) || !Number.isFinite(end)) return 0;
            return Math.max(0, end - start);
        }

        function getExcessBreakMinutes(rec, nowMs) {
            if (!rec || !rec.startBreak) return 0;
            const excessMs = Math.max(0, breakDurationMs(rec, nowMs) - BREAK_ALLOWANCE_MINUTES * 60000);
            return excessMs > 0 ? Math.ceil(excessMs / 60000) : 0;
        }

        function getExcessBreakHours(rec, nowMs) {
            return getExcessBreakMinutes(rec, nowMs) / 60;
        }

        function formatBreakDurationExact(rec, nowMs) {
            if (!rec || !rec.startBreak) return '—';
            const totalSeconds = Math.max(0, Math.round(breakDurationMs(rec, nowMs) / 1000));
            const hours = Math.floor(totalSeconds / 3600);
            const minutes = Math.floor((totalSeconds % 3600) / 60);
            const seconds = totalSeconds % 60;
            const parts = [];
            if (hours) parts.push(`${hours}h`);
            parts.push(`${minutes}m`);
            parts.push(`${String(seconds).padStart(2, '0')}s`);
            return parts.join(' ');
        }

        function formatBreakDeductionMinutes(minutes) {
            const value = Math.max(0, Math.round(Number(minutes) || 0));
            if (!value) return '0m';
            return value >= 60 ? `${Math.floor(value / 60)}h ${value % 60}m` : `${value}m`;
        }

        function isLongBreak(rec) {
            if (!rec || !rec.startBreak) return false;
            if (!rec.endBreak && !rec.logOut) return false;
            return getExcessBreakMinutes(rec) > 0;
        }

        function getRecordFor(dateStr, name) {
            return allRecords[dateStr + '|' + name] || null;
        }

        function overtimePodForName(name) {
            return (TEAM_LEADER_POD_BY_NAME && TEAM_LEADER_POD_BY_NAME[name]) || podOf(name) || '';
        }

        function overtimeAttendanceRecordFor(dateStr, name) {
            return isKnownTeamLeader(name) ? (allTeamLeaderRecords[tlAttendanceMapKey(dateStr, name)] || null) : getRecordFor(dateStr, name);
        }

        function canManageOvertimeForName(name) {
            const pod = overtimePodForName(name);
            if (isKnownTeamLeader(name)) return TrinoPermissions.can('admin.authenticated', { name, pod });
            return TrinoPermissions.can('overtime.manage', { name, pod });
        }

        function otBlockedReason(dateStr, name) {
            if (!dateStr || !name) return null;
            const rec = overtimeAttendanceRecordFor(dateStr, name);
            if (!rec) return null;
            if (!isKnownTeamLeader(name) && isVoidedAttendanceRecord(rec)) {
                return `${name}'s attendance record for ${dateStr} is voided — restore the attendance record before managing overtime.`;
            }
            const calcRec = isKnownTeamLeader(name) ? teamLeaderCalculationRecord(name, rec) : rec;
            const pod = isKnownTeamLeader(name) ? (calcRec.pod || overtimePodForName(name)) : (rec.pod || overtimePodForName(name));
            if (isEarlyLogout(calcRec, dateStr, pod)) {
                return `${name} recorded an early Time Out on ${dateStr} — overtime isn't available after an early Time Out.`;
            }
            return null;
        }

        let broadcastChannel = null;
        let broadcastSyncStarted = false;
        let firebaseSyncDb = null;
        let localPollingTimer = null;
        let refreshDebounceTimer = null;
        let refreshInFlight = false;
        const pendingIncrementalChanges = new Map();

        function makeIncrementalChange(type, key, extra = {}) {
            if (type !== 'records' && type !== 'ot') return { type, ...extra };
            const splitAt = key.indexOf('|');
            return {
                type,
                key,
                date: splitAt >= 0 ? key.slice(0, splitAt) : '',
                name: splitAt >= 0 ? key.slice(splitAt + 1) : '',
                ...extra
            };
        }

        function notifyLiveAttendanceState(change) {
            if (!change || change.type !== 'records') return;
            try {
                window.dispatchEvent(new CustomEvent('trinotime:attendance-live-change', {
                    detail: {
                        key: change.key || '',
                        date: change.date || '',
                        name: change.name || '',
                        pod: change.pod || '',
                        source: change.source || 'firebase'
                    }
                }));
            } catch (e) {}
        }

        function applyKvChildUpsert(encodedKey, raw) {
            if (typeof raw !== 'string') return null;
            let key;
            try { key = fbDecodeKey(encodedKey); } catch (e) { return null; }

            if (hasPendingDelete(key) || hasPendingWrite(key)) return null;
            if (isCredentialStorageKey(key)) {
                if (!fbKvCache) fbKvCache = {};
                fbKvCache[key] = raw;
                if (key.startsWith(AGENT_AUTH_KEY_PREFIX)) cacheAgentSecurityStateFromRaw(key, raw);
                safeLocalRemove(key);
                scheduleAgentSecurityPanelRender();
                scheduleLiveCredentialSessionValidation(key, 'firebase-credential-upsert');
                return null;
            }
            if (!fbKvCache) fbKvCache = {};
            if (key === POD_DIRECTORY_KEY) {
                fbKvCache[key] = raw;
                setLocalMirrorForKey(key, raw, { pendingCloudSync:false });
                if (applyPodDirectoryState(raw, { serverConfirmed:true, source:'firebase-live' })) return { type:'pod-directory' };
                return null;
            }
            if (key === TEAM_LEADER_DIRECTORY_KEY) {
                fbKvCache[key] = raw;
                setLocalMirrorForKey(key, raw, { pendingCloudSync:false });
                if (applyTeamLeaderDirectoryState(raw, { serverConfirmed:true, source:'firebase-live' })) return { type:'teamleader-directory' };
                return null;
            }
            if (key === PREMIUM_ACCESS_POLICY_KEY) markPremiumPodPolicyTrust('server-confirmed', 'firebase-live', 'Premium policy confirmed by Firebase live update.');
            if (fbKvCache[key] === raw) {
                if (key === PREMIUM_ACCESS_POLICY_KEY) applyPremiumModeForCurrentSession('live-policy-reconfirmed');
                return null;
            }
            fbKvCache[key] = raw;
            setLocalMirrorForKey(key, raw, { pendingCloudSync:false });
            if (key.indexOf('att:') === 0) {
                const recordKey = key.slice(4);
                try {
                    const parsedRecord = JSON.parse(raw);
                    allRecords[recordKey] = parsedRecord;
                    const change = makeIncrementalChange('records', recordKey, {
                        pod: parsedRecord && parsedRecord.pod ? parsedRecord.pod : '',
                        source: 'firebase'
                    });
                    notifyLiveAttendanceState(change);
                    return change;
                } catch (e) { return null; }
            }
            if (key.indexOf(TL_ATTENDANCE_KEY_PREFIX) === 0) {
                const recordKey = key.slice(TL_ATTENDANCE_KEY_PREFIX.length);
                try {
                    allTeamLeaderRecords[recordKey] = JSON.parse(raw);
                    if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
                    renderTeamLeaderHomeStatus();
                    if (isTeamLeader && !isAdmin) setTimeout(() => refreshTeamLeaderDelegationAccess('tl-attendance-live'), 0);
                } catch (e) {}
                return null;
            }
            if (key.indexOf('ot:') === 0) {
                const recordKey = key.slice(3);
                try {
                    const parsedOT = JSON.parse(raw);
                    allOT[recordKey] = parsedOT;
                    const splitAt = recordKey.indexOf('|');
                    const otName = splitAt >= 0 ? recordKey.slice(splitAt + 1) : '';
                    return makeIncrementalChange('ot', recordKey, { pod:(parsedOT && parsedOT.pod) || overtimePodForName(otName), source:'firebase' });
                } catch (e) { return null; }
            }
            if (key.indexOf(OVERTIME_PAYROLL_LOCK_PREFIX) === 0) {
                const periodStart = key.slice(OVERTIME_PAYROLL_LOCK_PREFIX.length);
                try {
                    allOvertimePeriodLocks[periodStart] = JSON.parse(raw);
                    return { type:'otlock', periodStart, source:'firebase' };
                } catch (e) { return null; }
            }
            if (key.indexOf('speedtest:') === 0) {
                try {
                    const parsed = JSON.parse(raw);
                    if (!parsed || !parsed.id) return null;
                    allSpeedTests[parsed.id] = parsed;
                    return { type: 'speedtests', id: parsed.id, name: parsed.name, pod: parsed.pod, date: parsed.date };
                } catch (e) { return null; }
            }
            if (key.indexOf('profile:') === 0) {
                handleAgentProfileRemoteUpsert(key, raw);
                return null;
            }
            if (key === NETWORK_SETTINGS_KEY) {
                try {
                    networkQualitySettings = mergeNetworkQualitySettings(JSON.parse(raw));
                    speedTestRetentionCleanupStarted = false;
                    return { type: 'networksettings' };
                } catch (e) { return null; }
            }
            if (key.indexOf('dayswap:') === 0) {
                try {
                    const parsed = JSON.parse(raw);
                    if (!parsed || !parsed.id) return null;
                    allDayOffSwaps[parsed.id] = parsed;
                    return { type: 'dayswap', swapId: parsed.id, date: parsed.date, pod: parsed.pod };
                } catch (e) { return null; }
            }
            if (key.indexOf('shiftoverride:') === 0) {
                try {
                    const parsed = JSON.parse(raw);
                    if (!parsed || !parsed.id) return null;
                    allShiftOverrides[parsed.id] = parsed;
                    return { type: 'shiftoverride', overrideId: parsed.id, date: parsed.date, pod: parsed.pod, name: parsed.name };
                } catch (e) { return null; }
            }
            if (key.indexOf('leave:') === 0) {
                try {
                    const parsed = normalizeLeaveRequestForRoster(JSON.parse(raw));
                    if (!parsed || !parsed.id) return null;
                    allLeaveRequests[parsed.id] = parsed;
                    updateLeaveRequestBadge();
                    return { type: 'leave', leaveId: parsed.id, date: isoDateInputToMdy(parsed.startDate), pod: leaveRequestEffectivePod(parsed), name: parsed.agentName };
                } catch (e) { return null; }
            }
            if (key === 'employees') {
                try {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed)) {
                        employees = sanitizeEmployeeRoster(parsed);
                        return { type: 'employees' };
                    }
                } catch (e) {}
                return null;
            }
            if (key === 'dayoff_schedule') {
                try {
                    const parsed = JSON.parse(raw);
                    const merged = JSON.parse(JSON.stringify(DEFAULT_SCHEDULE));
                    for (const [pod, data] of Object.entries(parsed)) merged[pod] = data;
                    dayOffSchedule = merged;
                    ensureCustomPodRuntimeScheduleData();
                    return { type: 'dayoff' };
                } catch (e) { return null; }
            }
            if (key === 'shift_settings') {
                try {
                    shiftSettings = mergeShiftSettings(JSON.parse(raw));
                    return { type: 'shiftsettings' };
                } catch (e) { return null; }
            }
            if (key === 'announcements') {
                try {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed)) {
                        cachedAnnouncements = parsed;
                        updateNotifBadge();
                        if ($('announceOverlay') && $('announceOverlay').classList.contains('open')) {
                            renderAnnouncementList();
                        }
                    }
                } catch (e) {}
                return null;
            }
            if (key === PREMIUM_ACCESS_POLICY_KEY) {
                premiumPodAccessPolicy = parsePremiumAccessPolicyRaw(raw);
                markPremiumPodPolicyTrust('server-confirmed', 'firebase-live', 'Premium policy confirmed by Firebase live update.');
                applyPremiumModeForCurrentSession('live-policy-update');
                renderPremiumAccessManager();
                return null;
            }
            if (key === PREMIUM_BEBLESS_LEGACY_ACCESS_KEY) {
                premiumBeblessLegacyEntitlementDetected = true;
                renderPremiumAccessManager();
                return null;
            }
            if (key === 'employees_v') { employeesVersion = raw; return null; }
            if (key === 'dayoff_schedule_v') { dayOffVersion = raw; return null; }
            if (key === 'shift_settings_v') { shiftSettingsVersion = raw; return null; }
            if (key === 'announcements_v') { announcementsVersion = raw; return null; }
            return null;
        }

        function applyKvChildRemove(encodedKey) {
            let key;
            try { key = fbDecodeKey(encodedKey); } catch (e) { return null; }
            if (hasPendingWrite(key)) return null;

            safeLocalRemove(key);
            safeLocalRemove(PENDING_DELETE_PREFIX + key);
            if (fbKvCache) delete fbKvCache[key];
            if (key.indexOf(AGENT_AUTH_KEY_PREFIX) === 0) agentSecurityStateCache.delete(key);
            if (key.indexOf(AGENT_AUTH_KEY_PREFIX) === 0 || key.indexOf(TEAM_LEADER_AUTH_KEY_PREFIX) === 0) {
                scheduleAgentSecurityPanelRender();
                scheduleLiveCredentialSessionValidation(key, 'firebase-credential-remove');
                return null;
            }
            if (key === POD_DIRECTORY_KEY) {
                applyPodDirectoryState({ revision:0, entries:DEFAULT_POD_DIRECTORY.map(entry => ({ ...entry })) }, { serverConfirmed:true, source:'firebase-remove' });
                return { type:'pod-directory' };
            }
            if (key === TEAM_LEADER_DIRECTORY_KEY) {
                applyTeamLeaderDirectoryState({ revision:0, entries:DEFAULT_TEAM_LEADER_DIRECTORY.map(entry => ({ ...entry })) }, { serverConfirmed:true, source:'firebase-remove' });
                return { type:'teamleader-directory' };
            }
            if (key.indexOf('att:') === 0) {
                const recordKey = key.slice(4);
                const priorRecord = allRecords[recordKey] || null;
                delete allRecords[recordKey];
                const change = makeIncrementalChange('records', recordKey, {
                    pod: priorRecord && priorRecord.pod ? priorRecord.pod : '',
                    source: 'firebase-remove'
                });
                notifyLiveAttendanceState(change);
                return change;
            }
            if (key.indexOf(TL_ATTENDANCE_KEY_PREFIX) === 0) {
                const recordKey = key.slice(TL_ATTENDANCE_KEY_PREFIX.length);
                delete allTeamLeaderRecords[recordKey];
                if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
                renderTeamLeaderHomeStatus();
                if (isTeamLeader && !isAdmin) setTimeout(() => refreshTeamLeaderDelegationAccess('tl-attendance-live-remove'), 0);
                return null;
            }
            if (key.indexOf('ot:') === 0) {
                const recordKey = key.slice(3);
                const priorOT = allOT[recordKey] || null;
                delete allOT[recordKey];
                const splitAt = recordKey.indexOf('|');
                const otName = splitAt >= 0 ? recordKey.slice(splitAt + 1) : '';
                return makeIncrementalChange('ot', recordKey, { pod:(priorOT && priorOT.pod) || overtimePodForName(otName), source:'firebase-remove' });
            }
            if (key.indexOf(OVERTIME_PAYROLL_LOCK_PREFIX) === 0) {
                const periodStart = key.slice(OVERTIME_PAYROLL_LOCK_PREFIX.length);
                delete allOvertimePeriodLocks[periodStart];
                return { type:'otlock', periodStart, source:'firebase-remove' };
            }
            if (key.indexOf('speedtest:') === 0) {
                const id = key.slice('speedtest:'.length);
                const prior = allSpeedTests[id] || null;
                delete allSpeedTests[id];
                return { type: 'speedtests', id, name: prior && prior.name, pod: prior && prior.pod, date: prior && prior.date };
            }
            if (key.indexOf('profile:') === 0) {
                void deleteProfileOfflineRecord(key);
                handleAgentProfileRemoteRemove(key);
                return null;
            }
            if (key === NETWORK_SETTINGS_KEY) {
                networkQualitySettings = { ...DEFAULT_NETWORK_QUALITY_SETTINGS };
                speedTestRetentionCleanupStarted = false;
                return { type: 'networksettings' };
            }
            if (key.indexOf('dayswap:') === 0) {
                const swapId = key.slice('dayswap:'.length);
                const prior = allDayOffSwaps[swapId] || null;
                delete allDayOffSwaps[swapId];
                return { type: 'dayswap', swapId, date: prior && prior.date, pod: prior && prior.pod };
            }
            if (key.indexOf('shiftoverride:') === 0) {
                const overrideId = key.slice('shiftoverride:'.length);
                const prior = allShiftOverrides[overrideId] || null;
                delete allShiftOverrides[overrideId];
                return { type: 'shiftoverride', overrideId, date: prior && prior.date, pod: prior && prior.pod, name: prior && prior.name };
            }
            if (key.indexOf('leave:') === 0) {
                const leaveId = key.slice('leave:'.length);
                const prior = allLeaveRequests[leaveId] || null;
                delete allLeaveRequests[leaveId];
                updateLeaveRequestBadge();
                return { type: 'leave', leaveId, date: prior && prior.startDate ? isoDateInputToMdy(prior.startDate) : null, pod: prior && prior.pod, name: prior && prior.agentName };
            }
            if (key === 'employees') {
                employees = [];
                return { type: 'employees' };
            }
            if (key === 'dayoff_schedule') {
                dayOffSchedule = JSON.parse(JSON.stringify(DEFAULT_SCHEDULE));
                return { type: 'dayoff' };
            }
            if (key === 'shift_settings') {
                shiftSettings = mergeShiftSettings(DEFAULT_SHIFT_SETTINGS);
                return { type: 'shiftsettings' };
            }
            if (key === 'announcements') {
                cachedAnnouncements = [];
                updateNotifBadge();
                if ($('announceOverlay') && $('announceOverlay').classList.contains('open')) {
                    renderAnnouncementList();
                }
                return null;
            }
            if (key === PREMIUM_ACCESS_POLICY_KEY) {
                premiumPodAccessPolicy = defaultPremiumAccessPolicy();
                markPremiumPodPolicyTrust('missing', 'firebase-remove', 'Premium policy was removed from the live server; Standard is enforced.');
                applyPremiumModeForCurrentSession('policy-reset');
                renderPremiumAccessManager();
                return null;
            }
            if (key === PREMIUM_BEBLESS_LEGACY_ACCESS_KEY) {
                premiumBeblessLegacyEntitlementDetected = false;
                renderPremiumAccessManager();
                return null;
            }
            if (key === 'employees_v') employeesVersion = null;
            else if (key === 'dayoff_schedule_v') dayOffVersion = null;
            else if (key === 'shift_settings_v') shiftSettingsVersion = null;
            else if (key === 'announcements_v') announcementsVersion = null;
            return null;
        }

        let lastUserGestureAt = 0;
        const markUserGesture = () => { lastUserGestureAt = Date.now(); };
        window.addEventListener('wheel', markUserGesture, { passive: true });
        window.addEventListener('touchmove', markUserGesture, { passive: true });
        window.addEventListener('keydown', (e) => {
            if (['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' '].includes(e.key)) markUserGesture();
        });
        let programmaticScrollUntil = 0;
        window.addEventListener('scroll', () => {
            if (Date.now() > programmaticScrollUntil) markUserGesture();
        }, { passive: true, capture: true });

        function withScrollPreserved(fn) {
            const scroller = document.scrollingElement || document.documentElement;
            const y = scroller ? scroller.scrollTop : (window.scrollY || 0);
            const gestureAtStart = lastUserGestureAt;
            const punchCard = $('punchCard');
            const stickyPunchWasVisible = !!(punchCard && punchCard.classList.contains('sticky'));
            const punchHeightBefore = stickyPunchWasVisible ? punchCard.getBoundingClientRect().height : 0;

            fn();

            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    if (!scroller || lastUserGestureAt !== gestureAtStart) return;

                    let targetY = y;
                    if (stickyPunchWasVisible && punchCard && punchCard.classList.contains('sticky')) {
                        const punchHeightAfter = punchCard.getBoundingClientRect().height;
                        if (Number.isFinite(punchHeightAfter)) targetY += punchHeightAfter - punchHeightBefore;
                    }
                    targetY = Math.max(0, targetY);

                    if (Math.abs(scroller.scrollTop - targetY) > 0.5) {
                        programmaticScrollUntil = Date.now() + 80;
                        window.__ttInstantScroll(scroller, targetY);
                    }
                });
            });
        }

        function isPanelVisible(el) {
            return !!el && el.style.display !== 'none';
        }

        function isOverlayOpen(el) {
            return !!el && el.classList.contains('open');
        }

        function changeTouchesActivePod(change) {
            if (!change || !change.name) return true;
            const currentPod = change.pod || podOf(change.name);
            if (activePod === ALL_PODS_LABEL) return teamIdForPod(currentPod) === activeTeam;
            return currentPod === activePod;
        }

        function changeMatchesCurrentLogFilters(change) {
            if (!change || !change.name || !change.date) return true;
            if (!changeTouchesActivePod(change)) return false;
            const empFilter = $('filterEmp') ? $('filterEmp').value : '';
            if (empFilter && empFilter !== change.name) return false;
            const fromComp = $('filterDate') ? isoToComparable($('filterDate').value) : null;
            const toComp = $('filterDateTo') ? isoToComparable($('filterDateTo').value) : null;
            const changedComp = dateStrToComparable(change.date);
            if (fromComp !== null && changedComp < fromComp) return false;
            if (toComp !== null && changedComp > toComp) return false;
            return true;
        }

        function scheduleIncrementalRender(change = { type: 'unknown' }) {
            const changeKey = `${change.type || 'unknown'}|${change.key || change.name || ''}`;
            pendingIncrementalChanges.set(changeKey, change);
            clearTimeout(refreshDebounceTimer);
            const renderDelayMs = change.type === 'records' ? 40 : 150;
            refreshDebounceTimer = setTimeout(() => {
                if (pendingIncrementalChanges.size === 0) return;
                const changes = Array.from(pendingIncrementalChanges.values());
                pendingIncrementalChanges.clear();

                const structuralChanged = changes.some(c =>
                    c.type === 'employees' || c.type === 'dayoff' || c.type === 'dayswap' || c.type === 'shiftoverride' || c.type === 'leave' || c.type === 'shiftsettings' || c.type === 'unknown');
                const rosterChanged = changes.some(c => c.type === 'employees' || c.type === 'unknown');
                const recordChanges = changes.filter(c => c.type === 'records' || c.type === 'ot');
                const attendanceChanges = changes.filter(c => c.type === 'records');
                const overtimeChanges = changes.filter(c => c.type === 'ot');
                const overtimeLockChanged = changes.some(c => c.type === 'otlock');
                const speedChanges = changes.filter(c => c.type === 'speedtests');
                const networkSettingsChanged = changes.some(c => c.type === 'networksettings');
                const leaveChanged = changes.some(c => c.type === 'leave');
                const delegationInputsChanged = !!(isTeamLeader && !isAdmin && changes.some(c => c.type === 'dayoff' || c.type === 'shiftoverride' || c.type === 'leave'));
                if (leaveChanged) syncLeaveRequestUi({ renderOpen:true });
                const scopedRecordChanges = recordChanges.filter(changeTouchesActivePod);
                const scopedAttendanceChanges = scopedRecordChanges.filter(c => c.type === 'records');
                const today = todayKeyPart();
                const previousDay = addDaysToDateStr(today, -1);

                const visibleLogChanged = structuralChanged || scopedRecordChanges.some(changeMatchesCurrentLogFilters);
                const todayStatusChanged = structuralChanged || scopedAttendanceChanges.some(c =>
                    c.date === today || c.date === previousDay);
                const privilegedAttendanceChanged = (isAdmin || isTeamLeader) && scopedAttendanceChanges.length > 0;
                const privilegedTableSync = privilegedAttendanceChanged && visibleLogChanged &&
                    (typeof document === 'undefined' || document.visibilityState !== 'hidden');
                const selectedEmployeeChanged = structuralChanged || (!!currentEmployee && recordChanges.some(c =>
                    c.name === currentEmployee && (c.date === today || c.date === previousDay)));
                const managementViewsChanged = structuralChanged || scopedRecordChanges.length > 0 || overtimeLockChanged;

                const logVisible = isPanelVisible($('desktopTableContainer')) || isPanelVisible($('mobileCards'));
                const statusOpen = isOverlayOpen($('todayStatusOverlay'));
                const historyOpen = isOverlayOpen($('historyOverlay'));
                const rosterOpen = isOverlayOpen($('rosterOverlay'));
                const moveAgentsOpen = isOverlayOpen($('moveAgentsOverlay'));
                const backupTlOpen = isOverlayOpen($('backupTlOverlay'));
                const noteHistoryOpen = isOverlayOpen($('noteHistoryOverlay'));
                const otOpen = isOverlayOpen($('otTabOverlay'));
                const totalsOpen = isOverlayOpen($('totalsOverlay'));
                const networkOpen = isOverlayOpen($('networkOverlay'));
                const dayOffOpen = isOverlayOpen($('dayOffOverlay'));
                const scheduleExceptionsOpen = isOverlayOpen($('scheduleExceptionsOverlay'));
                const needsDomWork = rosterChanged || delegationInputsChanged || (logVisible && visibleLogChanged) || privilegedTableSync ||
                    (statusOpen && todayStatusChanged) || selectedEmployeeChanged || privilegedAttendanceChanged ||
                    (historyOpen && structuralChanged) ||
                    (rosterOpen && rosterChanged) ||
                    (moveAgentsOpen && rosterChanged) ||
                    (backupTlOpen && (structuralChanged || delegationInputsChanged)) ||
                    (dayOffOpen && structuralChanged) ||
                    (scheduleExceptionsOpen && structuralChanged) ||
                    (noteHistoryOpen && managementViewsChanged) ||
                    ((otOpen || totalsOpen) && managementViewsChanged) ||
                    (networkOpen && (speedChanges.length > 0 || networkSettingsChanged)) ||
                    (isOverlayOpen($('speedtestOverlay')) && networkSettingsChanged) ||
                    (!!currentEmployee && speedChanges.some(c => c.name === currentEmployee));
                if (!needsDomWork) return;

                withScrollPreserved(() => {
                    if (rosterChanged || delegationInputsChanged) {
                        renderTeamTabs();
                        renderPodTabs();
                        populateEmployeeSelects();
                        if (typeof scheduleAgentSecurityPanelRender === 'function') scheduleAgentSecurityPanelRender();
                    }
                    if ((logVisible && visibleLogChanged) || privilegedTableSync) renderTable();
                    if (statusOpen && todayStatusChanged) renderTodayStatus();
                    if (selectedEmployeeChanged) refreshPunchCard();
                    if (privilegedAttendanceChanged) {
                        if (typeof updateExecutiveStatusStrip === 'function' && isPremiumFeatureEnabled()) {
                            updateExecutiveStatusStrip(true);
                        }
                        if (window.trinoAttendanceDashboard && typeof window.trinoAttendanceDashboard.refresh === 'function') {
                            window.trinoAttendanceDashboard.refresh();
                        }
                    }
                    if (historyOpen && structuralChanged) renderHistoryCalendar();
                    if (rosterOpen && rosterChanged) renderRosterTab();
                    if (moveAgentsOpen && rosterChanged) renderMoveAgentsTab();
                    if (backupTlOpen && (structuralChanged || delegationInputsChanged)) renderBackupTlAccessTab();
                    if (isTeamLeader && !isAdmin && (structuralChanged || delegationInputsChanged)) syncBackupTlTabVisibility();
                    if (dayOffOpen && structuralChanged) renderDayOffSwapList($('dayOffPodSelect') ? $('dayOffPodSelect').value : activePod);
                    if (scheduleExceptionsOpen && structuralChanged) refreshScheduleExceptionsView();
                    if (noteHistoryOpen && managementViewsChanged) renderNoteHistory();
                    if (otOpen && managementViewsChanged) renderOTTab();
                    if (totalsOpen && managementViewsChanged) renderTotalsTab();
                    if (overtimeChanges.length) {
                        if (isOverlayOpen($('tlAttendanceOverlay'))) renderTeamLeaderAttendance();
                        renderTeamLeaderHomeStatus();
                        renderTlAdminOverview();
                        if (isAdmin && typeof renderAdminOpsCenter === 'function') renderAdminOpsCenter({ force:true });
                    }
                    if (networkOpen && (speedChanges.length > 0 || networkSettingsChanged)) renderNetworkTab();
                    if (!speedTestRunning && ((currentEmployee && speedChanges.some(c => c.name === currentEmployee)) || networkSettingsChanged)) refreshSpeedTestPanel();
                    refreshSpeedTestReminder();
                });
            }, 150);
        }

        function startLocalPollingFallback() {
            if (localPollingTimer) return;
            let lastHash = getStorageHash();
            localPollingTimer = setInterval(() => {
                if (document.visibilityState === 'hidden') return;
                const currentHash = getStorageHash();
                if (currentHash !== lastHash) {
                    lastHash = currentHash;
                    refreshAllUI();
                }
            }, 3000);
        }

        function initSync() {
            if (!broadcastSyncStarted) {
                broadcastSyncStarted = true;
                try {
                    broadcastChannel = new BroadcastChannel('cwh-timeclock-sync');
                    broadcastChannel.onmessage = (event) => {
                        if (event.data && event.data.type === 'update') refreshAllUI();
                    };
                } catch (e) {                                    }
            }

            if (!fbDb) {
                startLocalPollingFallback();
                return;
            }
            if (firebaseSyncDb === fbDb) return;
            firebaseSyncDb = fbDb;
            if (localPollingTimer) {
                clearInterval(localPollingTimer);
                localPollingTimer = null;
            }

            let sawFirstError = false;
            const onChildErr = (error) => {
                if (sawFirstError) return;
                sawFirstError = true;
                lastConnectionError = error;
                if (isFirebaseAuthApiBlockedError(error)) {
                    markFirebaseAuthApiBlocked(error, 'listener-auth-blocked');
                    reportAppError('Firebase live sync', error, {
                        notify: true,
                        userMessage: firebaseAuthBlockedUserMessage()
                    });
                    return;
                }
                setLiveConnectionState(false, 'listener-error');
                reportAppError('Firebase live sync', error, {
                    notify: true,
                    userMessage: 'Live sync error. Your changes are still saved locally.'
                });
            };
            const liveKvRef = fbDb.ref('kv');
            liveKvRef.on('child_added', (snap) => {
                const change = applyKvChildUpsert(snap.key, snap.val());
                if (change) scheduleIncrementalRender(change);
            }, onChildErr);
            liveKvRef.on('child_changed', (snap) => {
                const change = applyKvChildUpsert(snap.key, snap.val());
                if (change) scheduleIncrementalRender(change);
            }, onChildErr);
            liveKvRef.on('child_removed', (snap) => {
                const change = applyKvChildRemove(snap.key);
                if (change) scheduleIncrementalRender(change);
            }, onChildErr);
            fbDb.ref('.info/connected').on('value', (snap) => {
                const connected = !!snap.val();
                socketReportedConnected = connected;
                if (connected) {
                    clearSocketDisconnectGrace();
                    lastLiveServerPingAt = Date.now();
                    setLiveConnectionState(true, 'firebase-socket');
                } else if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                    clearSocketDisconnectGrace();
                    setLiveConnectionState(false, 'browser-offline');
                } else {
                    scheduleSocketDisconnectConfirmation();
                }
            });
            void flushPendingRecords();
        }

        function clearSocketDisconnectGrace() {
            if (!socketDisconnectGraceTimer) return;
            clearTimeout(socketDisconnectGraceTimer);
            socketDisconnectGraceTimer = null;
        }

        function scheduleSocketDisconnectConfirmation() {
            if (socketDisconnectGraceTimer) return;
            socketDisconnectGraceTimer = setTimeout(async () => {
                socketDisconnectGraceTimer = null;
                if (socketReportedConnected === true) return;
                if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                    setLiveConnectionState(false, 'browser-offline');
                    return;
                }
                try {
                    await pingLiveServer();
                } catch (error) {
                    lastConnectionError = error;
                    if (isFirebaseAppCheckError(error)) {
                        markFirebaseAppCheckBlocked(error, 'socket-grace-app-check-blocked');
                    } else if (isFirebaseAuthApiBlockedError(error)) {
                        markFirebaseAuthApiBlocked(error, 'socket-grace-auth-blocked');
                    } else {
                        setLiveConnectionState(false, 'firebase-socket-grace-expired');
                    }
                    if (getPendingSyncSummary().total) schedulePendingSyncRetry(1000);
                }
            }, SOCKET_DISCONNECT_GRACE_MS);
        }

        function startLiveHeartbeat() {
            if (liveHeartbeatTimer) return;
            liveHeartbeatTimer = setInterval(() => {
                if (document.visibilityState === 'hidden') return;
                if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
                if ((firebaseAppCheckBlocked && Date.now() < firebaseAppCheckBlockedRetryAt) || (firebaseAuthApiBlocked && Date.now() < firebaseAuthApiBlockedRetryAt)) return;
                if (reconnectPromise) return;
                const stale = !lastLiveServerPingAt || Date.now() - lastLiveServerPingAt >= LIVE_HEARTBEAT_STALE_MS;
                if (fbConnected === true && !stale) return;
                void pingLiveServer().then(() => {
                    if (getPendingSyncSummary().total) schedulePendingSyncRetry(250);
                }).catch((error) => {
                    lastConnectionError = error;
                    if (isFirebaseAppCheckError(error)) {
                        markFirebaseAppCheckBlocked(error, 'heartbeat-app-check-blocked');
                        return;
                    }
                    if (isFirebaseAuthApiBlockedError(error)) {
                        markFirebaseAuthApiBlocked(error, 'heartbeat-auth-blocked');
                        return;
                    }
                    if (socketReportedConnected === false || fbConnected !== true) {
                        setLiveConnectionState(false, 'heartbeat-failed');
                    }
                });
            }, LIVE_HEARTBEAT_INTERVAL_MS);
        }

        function setLiveConnectionState(connected, source) {
            const nextConnected = connected === true;
            const changed = fbConnected !== nextConnected;
            fbConnected = nextConnected;
            lastConnectionStateSource = source || 'unknown';
            if (changed) appendSyncAudit(nextConnected ? 'connection_restored' : 'connection_lost', nextConnected ? 'Live server connection restored.' : 'Live server connection interrupted; local backup remains active.', { source:lastConnectionStateSource });
            if (fbConnected) {
                clearSocketDisconnectGrace();
                lastLiveServerPingAt = Date.now();
                lastConnectionError = null;
                reconnectFailureCount = 0;
                nextReconnectAttemptAt = 0;
                setOnlineIndicatorGlobal(true);
                setConnBanner(true);
                if (changed || getPendingSyncSummary().total) void flushPendingRecords();
                void flushPendingImmutableAuditEvents();
            } else {
                setOnlineIndicatorGlobal(false);
                setConnBanner(false, { source, immediate: getPendingSyncSummary().punchWrites > 0 });
                if (changed && getPendingSyncSummary().total && typeof navigator !== 'undefined' && navigator.onLine !== false) {
                    schedulePendingSyncRetry(1000);
                }
            }
            if (typeof renderTeamLeaderHomeStatus === 'function') renderTeamLeaderHomeStatus();
        }

        function setOnlineIndicatorGlobal(connected) {
            const clock = $('liveClock');
            if (clock) clock.title = connected ? 'Live sync connected' : 'Live sync is reconnecting';
            updateHeaderConnectionStatus();
        }

        let connBannerTimer = null;
        function setReconnectBusy(busy) {
            const button = $('reconnectBtn');
            if (!button) return;
            const pending = getPendingSyncSummary();
            button.disabled = !!busy;
            button.textContent = busy ?
                (pending.punchWrites > 0 ? 'Retrying...' : 'Checking...') :
                ((firebaseAppCheckBlocked || firebaseAuthApiBlocked) ? 'Retry Sync' : (pending.punchWrites > 0 ? 'Retry Sync Now' : 'Reconnect'));
            button.setAttribute('aria-label', firebaseAppCheckBlocked ?
                'Retry Firebase App Check verification and sync locally saved attendance data' : (firebaseAuthApiBlocked ?
                'Retry Firebase authentication and sync locally saved attendance data' :
                (pending.punchWrites > 0 ?
                    'Retry syncing locally saved attendance punches now' :
                    'Reconnect to the live attendance server')));
        }
        function setReconnectUi(checking, message) {
            const banner = $('connBanner');
            const textEl = $('connBannerText');
            if (!banner) return;
            const pending = getPendingSyncSummary();
            banner.classList.toggle('is-checking', !!checking);
            banner.classList.toggle('has-pending-punch', pending.punchWrites > 0);
            if (textEl && message) textEl.textContent = message;
            setReconnectBusy(checking);
            banner.style.display = 'flex';
        }
        function formatSyncAge(ms) {
            const value = Number(ms);
            if (!Number.isFinite(value) || value < 0) return 'unknown age';
            const seconds = Math.floor(value / 1000);
            if (seconds < 60) return `${seconds}s`;
            const minutes = Math.floor(seconds / 60);
            const rem = seconds % 60;
            return rem ? `${minutes}m ${rem}s` : `${minutes}m`;
        }

        function updatePunchReceiptBadges(name = currentEmployee, rec = null) {
            const record = rec || (name ? getTodayRecord(name) : null) || {};
            const ids = record._syncPunchIds && typeof record._syncPunchIds === 'object' ? record._syncPunchIds : {};
            const pendingEvents = new Map(getPendingPunchEvents().map(event => [event.id, event]));
            const map = [
                ['timeIn','btnTimeIn'], ['startBreak','btnStartBreak'], ['endBreak','btnEndBreak'], ['logOut','btnLogOut']
            ];
            map.forEach(([field, buttonId]) => {
                const button = $(buttonId);
                if (!button) return;
                let badge = button.querySelector('.punch-sync-badge');
                const eventId = ids[field];
                if (!record[field] || !eventId) {
                    if (badge) badge.remove();
                    return;
                }
                if (!badge) {
                    badge = document.createElement('span');
                    badge.className = 'punch-sync-badge';
                    button.appendChild(badge);
                }
                const event = pendingEvents.get(eventId);
                if (!event) {
                    badge.className = 'punch-sync-badge is-confirmed';
                    badge.textContent = 'Server ✓';
                    badge.title = 'This punch has a server-confirmed receipt.';
                    return;
                }
                const nowMs = typeof getTrueNowMs === 'function' ? getTrueNowMs() : Date.now();
                const age = Math.max(0, nowMs - Number(event.createdAtMs || new Date(event.timestamp).getTime() || nowMs));
                const severity = pendingSeverity(age);
                badge.className = 'punch-sync-badge is-' + severity;
                badge.textContent = severity === 'critical' ? 'Retry sync' : (severity === 'warning' ? 'Still syncing' : 'Syncing…');
                badge.title = `${punchFieldLabel(field)} is safely stored locally and awaiting server confirmation (${formatSyncAge(age)}).`;
            });
        }

        function updatePendingSyncUi() {
            const summary = getPendingSyncSummary();
            const counter = $('pendingSyncCounter');
            const headerCounter = $('pendingSyncHeaderCount');
            const pendingCount = summary.punchEvents || summary.punchWrites || 0;
            if (headerCounter) {
                const headerValue = pendingCount || summary.total;
                headerCounter.textContent = String(headerValue);
                headerCounter.style.display = summary.total ? 'inline-flex' : 'none';
                headerCounter.title = summary.total ? `${headerValue} local change${headerValue === 1 ? '' : 's'} waiting for server confirmation` : '';
            }
            if (counter) {
                counter.className = 'pending-sync-counter';
                if (summary.total) {
                    counter.classList.add('show');
                    if (summary.severity === 'warning') counter.classList.add('is-warning');
                    if (summary.severity === 'critical') counter.classList.add('is-critical');
                    const noun = pendingCount ? (pendingCount === 1 ? 'punch' : 'punches') : (summary.total === 1 ? 'change' : 'changes');
                    const count = pendingCount || summary.total;
                    const age = summary.oldestPunchAgeMs !== null ? ` · ${formatSyncAge(summary.oldestPunchAgeMs)}` : '';
                    counter.textContent = `${count} ${noun} pending${age}`;
                    counter.title = 'Tap to retry all locally saved changes now.';
                }
            }

            const latestEvent = summary.punchEventList && summary.punchEventList.length ? summary.punchEventList[summary.punchEventList.length - 1] : null;
            const saveEl = $('punchSaveState');
            if (latestEvent && saveEl && (saveEl.classList.contains('is-pending') || saveEl.classList.contains('is-saving') || saveEl.classList.contains('is-error'))) {
                const label = punchFieldLabel(latestEvent.field);
                const time = formatManilaTime(latestEvent.timestamp, true);
                if (summary.severity === 'critical') setPunchSaveState('error', `${label} ${time} • Sync failed — Retry Sync Now`);
                else if (summary.severity === 'warning') setPunchSaveState('pending', `${label} ${time} • Still syncing — ${formatSyncAge(summary.oldestPunchAgeMs)}`);
            }
            updatePunchReceiptBadges();
            renderSyncDiagnostics();
        }

        function connectionQualityLabel() {
            const browserOffline = typeof navigator !== 'undefined' && navigator.onLine === false;
            const pending = getPendingSyncSummary();
            const heartbeatStale = !lastLiveServerPingAt || Date.now() - lastLiveServerPingAt >= LIVE_HEARTBEAT_STALE_MS;
            if (browserOffline) return timeSyncEstablished ? 'Offline — local backup active' : 'Offline — punches disabled';
            if (firebaseAppCheckBlocked) return timeSyncEstablished ? 'App Check blocked — local backup active' : 'App Check blocked — punches disabled';
            if (firebaseAuthApiBlocked) return timeSyncEstablished ? 'Live sync blocked — local backup active' : 'Live auth blocked — punches disabled';
            if (!firebaseAppCheckLastVerifiedAt) return 'App Check verifying — cloud sync paused';
            if (fbConnected === true && socketReportedConnected === true && !heartbeatStale && !pending.total) return 'Online — synced';
            if (fbConnected === true && (socketReportedConnected === false || heartbeatStale || pending.total)) return 'Online — connection unstable';
            if (reconnectPromise) return 'Reconnecting — checking live server';
            if (timeSyncEstablished) return 'Reconnecting — local backup active';
            return 'Connecting to live server';
        }

        function renderGateReadiness() {
            const root = $('gateReadiness');
            if (!root) return;
            const stateEl = $('gateReadinessState');
            const titleEl = $('gateReadinessTitle');
            const summaryEl = $('gateReadinessSummary');
            const browserOnline = typeof navigator === 'undefined' ? true : navigator.onLine !== false;
            const appVerified = firebaseAppCheckSatisfied();
            const firebaseVerified = fbConnected === true && !firebaseAuthApiBlocked && !firebaseAppCheckBlocked;
            const timeVerified = !!timeSyncEstablished;
            let state = 'checking';
            let badge = 'Checking';
            let title = 'Preparing secure access';
            let summary = 'Verifying this secure session before access.';
            if (!browserOnline) {
                state = timeVerified ? 'warn' : 'bad';
                badge = 'Offline';
                title = timeVerified ? 'Offline safety is active' : 'Connection required';
                summary = timeVerified ? 'Your established session can continue safely; live synchronization will resume after reconnection.' : 'Reconnect to verify a new secure session.';
            } else if (firebaseAppCheckBlocked || firebaseAuthApiBlocked) {
                state = 'bad';
                badge = 'Unavailable';
                title = firebaseAppCheckBlocked ? 'Secure deployment could not be verified' : 'Secure sign-in service unavailable';
                summary = firebaseAppCheckBlocked ? 'Retry verification or reopen the official TrinoTime deployment.' : 'Retry in a moment or contact support if the issue continues.';
            } else if (appVerified && firebaseVerified && timeVerified) {
                state = 'good';
                badge = 'Ready';
                title = 'Secure connection verified';
                summary = 'This device is ready for protected sign-in and trusted attendance time.';
            } else if (appVerified || firebaseVerified || timeVerified) {
                state = 'warn';
                badge = 'Verifying';
                title = 'Finishing secure verification';
                summary = 'TrinoTime is completing the remaining connection checks.';
            }
            root.dataset.state = state;
            if (stateEl) { stateEl.dataset.state = state; stateEl.textContent = badge; }
            if (titleEl) titleEl.textContent = title;
            if (summaryEl) summaryEl.textContent = summary;
            const setMetric = (itemId, valueId, value, metricState, loading = false) => {
                const item = $(itemId), valueEl = $(valueId);
                if (item) { item.dataset.state = metricState; item.dataset.loading = loading ? 'true' : 'false'; }
                if (valueEl) valueEl.textContent = value;
            };
            const appState = firebaseAppCheckBlocked ? 'bad' : (appVerified ? 'good' : (firebaseAppCheckLastError ? 'bad' : 'warn'));
            const appValue = !FIREBASE_APP_CHECK_REQUIRED ? 'Unenforced' : (firebaseAppCheckBlocked ? 'Blocked' : (appVerified ? 'Verified' : (firebaseAppCheckLastError ? 'Unverified' : 'Verifying')));
            const firebaseState = firebaseAppCheckBlocked || firebaseAuthApiBlocked || fbConnected === false ? 'bad' : (firebaseVerified ? 'good' : 'warn');
            const firebaseValue = firebaseAppCheckBlocked ? 'Blocked' : (firebaseAuthApiBlocked ? 'Auth blocked' : (fbConnected === true ? 'Connected' : (fbConnected === false ? 'Offline' : 'Connecting')));
            setMetric('gateReadinessAppCheck', 'gateReadinessAppCheckValue', appValue, appState, !appVerified && !firebaseAppCheckBlocked && !firebaseAppCheckLastError);
            setMetric('gateReadinessFirebase', 'gateReadinessFirebaseValue', firebaseValue, firebaseState, !firebaseVerified && !firebaseAppCheckBlocked && !firebaseAuthApiBlocked && fbConnected !== false);
            setMetric('gateReadinessTime', 'gateReadinessTimeValue', timeVerified ? 'Verified' : 'Waiting', timeVerified ? 'good' : 'warn', !timeVerified && browserOnline);
            const versionMeta = document.querySelector('meta[name="trinotime-version"]');
            setMetric('gateReadinessBuild', 'gateReadinessBuildValue', 'v' + (versionMeta ? String(versionMeta.content || '1.0.36') : '1.0.36'), 'neutral', false);
            try { syncGateSecureAccessUi(); } catch (e) {}
        }

        function formatDiagnosticTimestamp(ms) {
            const n = Number(ms);
            if (!Number.isFinite(n) || n <= 0) return '—';
            try { return new Date(n).toLocaleString('en-US', { hour12:true }); } catch (e) { return '—'; }
        }

        function renderSyncDiagnostics() {
            try { renderGateReadiness(); } catch (e) {}
            const panel = $('settingsPanelSync');
            if (!panel) return;
            const summary = getPendingSyncSummary();
            const set = (id, value) => { const el = $(id); if (el) el.textContent = value; };
            set('syncDiagConnection', `${connectionQualityLabel()} · ${lastConnectionStateSource || 'unknown source'}`);
            set('syncDiagSocket', socketReportedConnected === true ? 'Connected' : (socketReportedConnected === false ? 'Disconnected' : 'Unknown'));
            const appCheckCode = firebaseErrorCode(firebaseAppCheckLastError);
            set('syncDiagAppCheck', !FIREBASE_APP_CHECK_REQUIRED ? 'Temporarily unenforced · emergency no-cost recovery' : (firebaseAppCheckBlocked ? `Blocked${appCheckCode ? ' · ' + appCheckCode : ''}` : (firebaseAppCheckLastVerifiedAt ? `Verified · ${formatDiagnosticTimestamp(firebaseAppCheckLastVerifiedAt)}` : (firebaseAppCheckLastError ? `Unverified${appCheckCode ? ' · ' + appCheckCode : ''} · cloud sync paused` : (firebaseAppCheckActivatedApps.size ? `Active · SDK ${FIREBASE_WEB_SDK_VERSION} · waiting for token` : 'Not started')))));
            set('syncDiagAppCheckAttempt', formatDiagnosticTimestamp(firebaseAppCheckLastAttemptAt));
            set('syncDiagLastConfirm', formatDiagnosticTimestamp(lastServerConfirmedWriteAt));
            set('syncDiagHeartbeat', formatDiagnosticTimestamp(lastLiveServerPingAt));
            set('syncDiagPending', `${summary.total} total · ${summary.punchEvents || summary.punchWrites || 0} punch${(summary.punchEvents || summary.punchWrites || 0) === 1 ? '' : 'es'}`);
            set('syncDiagOldest', summary.oldestPunchAgeMs === null ? '—' : formatSyncAge(summary.oldestPunchAgeMs));
            try {
                const workspace = customizedWorkspaceDiagnosticsSnapshot();
                const expiry = workspace.premium && workspace.premium.expiresAt ? ` · ${premiumExpiryDisplay(workspace.premium.expiresAt)}` : '';
                const trust = workspace.premiumPolicyTrust && workspace.premiumPolicyTrust.status ? ` · policy ${workspace.premiumPolicyTrust.status}` : '';
                set('syncDiagWorkspaceAccess', `${workspace.enabled ? 'Enabled' : 'Standard'} · ${workspace.label}${expiry}${trust}`);
            } catch (e) { set('syncDiagWorkspaceAccess', 'Standard · access decision unavailable'); }
            set('syncDiagError', firebaseAppCheckBlocked ?
                firebaseAppCheckQuotaExhausted ? `${firebaseAppCheckDiagnosticMessage(firebaseAppCheckLastError)} · Free App Check assessment quota reached. Automatic retries are throttled; keep billing disabled and use a longer App Check TTL to stay within the free allowance after quota resets.` : `${firebaseAppCheckDiagnosticMessage(firebaseAppCheckLastError)} · Firebase SDK ${FIREBASE_WEB_SDK_VERSION}. Retry Sync once; if it remains blocked, confirm the reCAPTCHA Enterprise key/domain and Firebase App Check API restriction.` : (firebaseAuthApiBlocked ?
                'Firebase API-key restriction blocks Authentication token refresh (securetoken.googleapis.com). Allow Identity Toolkit API + Token Service API, then Retry Sync.' :
                (lastConnectionError ? getErrorMessage(lastConnectionError) : (firebaseAppCheckLastError ? `App Check required: ${firebaseAppCheckDiagnosticMessage(firebaseAppCheckLastError)} · Live cloud sync is paused until verification succeeds.` : 'None'))));
            const log = $('syncDiagnosticsLog');
            if (log) {
                const events = readSyncAuditTrail().slice().reverse();
                log.innerHTML = events.length ? events.map(event => {
                    const when = formatDiagnosticTimestamp(event.at);
                    return `<div class="sync-audit-item"><time>${escapeHtml(when)}</time>${escapeHtml(event.message || event.kind || 'Sync event')}</div>`;
                }).join('') : '<div class="sync-audit-empty">No sync events recorded on this device yet.</div>';
            }
        }

        function setConnBanner(connected, options = {}) {
            if (connBannerTimer) {
                clearTimeout(connBannerTimer);
                connBannerTimer = null;
            }
            const banner = $('connBanner');
            const textEl = $('connBannerText');
            if (!banner) return;
            const pending = getPendingSyncSummary();
            const pendingCount = pending.punchEvents || pending.punchWrites || 0;
            const hasPendingPunch = pendingCount > 0 || pending.punchWrites > 0;
            banner.classList.toggle('has-pending-punch', hasPendingPunch);
            banner.classList.toggle('is-pending-warning', hasPendingPunch && pending.severity === 'warning');
            banner.classList.toggle('is-pending-critical', hasPendingPunch && pending.severity === 'critical');

            if (firebaseAppCheckBlocked) {
                if (textEl && !banner.classList.contains('is-checking')) textEl.textContent = appCheckUserMessage();
                setReconnectBusy(banner.classList.contains('is-checking'));
                banner.style.display = 'flex';
                return;
            }

            if (firebaseAuthApiBlocked) {
                if (textEl && !banner.classList.contains('is-checking')) {
                    if (hasPendingPunch) {
                        const countText = pendingCount === 1 ? '1 attendance punch is' : `${pendingCount} attendance punches are`;
                        textEl.textContent = `Live sync authentication is blocked by Firebase API-key settings. ${countText} safely stored on this device. Admin: allow Token Service API (securetoken.googleapis.com), then tap Retry Sync.`;
                    } else {
                        textEl.textContent = firebaseAuthBlockedUserMessage();
                    }
                }
                setReconnectBusy(banner.classList.contains('is-checking'));
                banner.style.display = 'flex';
                return;
            }

            if (hasPendingPunch) {
                if (textEl && !banner.classList.contains('is-checking')) {
                    const countText = pendingCount === 1 ? '1 attendance punch' : `${pendingCount} attendance punches`;
                    const ageText = pending.oldestPunchAgeMs === null ? '' : ` (${formatSyncAge(pending.oldestPunchAgeMs)})`;
                    textEl.textContent = pending.severity === 'critical' ?
                        `Critical: ${countText} ${pendingCount === 1 ? 'has' : 'have'} not yet been received by the live server${ageText}. Tap Retry Sync Now.` :
                        pending.severity === 'warning' ?
                            `${countText} ${pendingCount === 1 ? 'is' : 'are'} still waiting for server confirmation${ageText}. Tap Retry Sync Now if needed.` :
                            `${countText} ${pendingCount === 1 ? 'is' : 'are'} safely stored locally and syncing${ageText}.`;
                }
                setReconnectBusy(banner.classList.contains('is-checking'));
                banner.style.display = 'flex';
                return;
            }

            if (connected) {
                banner.classList.remove('is-checking', 'is-pending-warning', 'is-pending-critical');
                banner.style.display = 'none';
                setReconnectBusy(false);
                return;
            }
            if (textEl && !banner.classList.contains('is-checking')) {
                textEl.textContent = typeof navigator !== 'undefined' && navigator.onLine === false ?
                    'This device is offline. Your changes are saved locally and will sync after reconnection.' :
                    'Reconnecting to the live server. Your changes remain saved on this device.';
            }
            setReconnectBusy(banner.classList.contains('is-checking'));
            const show = () => { banner.style.display = 'flex'; };
            if (options.immediate) show();
            else connBannerTimer = setTimeout(show, 600);
        }

        function startReconnectMonitor() {
            if (reconnectMonitorTimer) return;
            reconnectMonitorTimer = setInterval(() => {
                if (document.visibilityState === 'hidden') return;
                if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
                if ((firebaseAppCheckBlocked && Date.now() < firebaseAppCheckBlockedRetryAt) || (firebaseAuthApiBlocked && Date.now() < firebaseAuthApiBlockedRetryAt)) return;
                if (fbConnected === true || reconnectPromise) return;
                if (Date.now() < nextReconnectAttemptAt) return;
                void reconnectToLiveServer({ userInitiated: false });
            }, 5000);
        }

        function clearPendingSyncRetryTimer() {
            if (!pendingSyncRetryTimer) return;
            clearTimeout(pendingSyncRetryTimer);
            pendingSyncRetryTimer = null;
        }

        function schedulePendingSyncRetry(delayMs) {
            const pending = getPendingSyncSummary();
            if (!pending.total) {
                pendingSyncRetryCount = 0;
                clearPendingSyncRetryTimer();
                setConnBanner(fbConnected === true, { immediate: true });
                return;
            }
            setConnBanner(fbConnected === true, { immediate: pending.punchWrites > 0 });
            if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
            if (pendingSyncRetryTimer) return;
            const requested = Number(delayMs);
            const appCheckBlockedDelay = firebaseAppCheckBlocked && Date.now() < firebaseAppCheckBlockedRetryAt ?
                Math.max(1000, firebaseAppCheckBlockedRetryAt - Date.now()) : null;
            const authBlockedDelay = firebaseAuthApiBlocked && Date.now() < firebaseAuthApiBlockedRetryAt ?
                Math.max(1000, firebaseAuthApiBlockedRetryAt - Date.now()) : null;
            const blockedDelay = appCheckBlockedDelay !== null ? appCheckBlockedDelay : authBlockedDelay;
            const delay = Number.isFinite(requested) ? Math.max(250, requested) :
                (blockedDelay !== null ? blockedDelay :
                    Math.min(PENDING_SYNC_RETRY_MAX_MS,
                        PENDING_SYNC_RETRY_BASE_MS * Math.pow(2, Math.min(pendingSyncRetryCount, 3))));
            pendingSyncRetryTimer = setTimeout(() => {
                pendingSyncRetryTimer = null;
                void retryPendingSyncQueue({ userInitiated: false });
            }, delay);
        }

        function markPunchQueueSyncedInUi() {
            if (getPendingSyncSummary().punchWrites > 0) return;
            const el = $('punchSaveState');
            if (!el || (!el.classList.contains('is-pending') && !el.classList.contains('is-saving'))) return;
            const current = String(el.textContent || '');
            const prefix = current.includes('•') ? current.split('•')[0].trim() : '';
            setPunchSaveState('saved', prefix ? `${prefix} • Saved to server ✓` : 'Pending attendance punch synced to server ✓');
        }

        async function retryPendingSyncQueue(options = {}) {
            if (pendingSyncRetryInFlight) return pendingSyncRetryInFlight;
            const userInitiated = !!options.userInitiated;
            if (firebaseAppCheckBlocked && !userInitiated && Date.now() < firebaseAppCheckBlockedRetryAt) {
                setConnBanner(false, { immediate: true });
                schedulePendingSyncRetry(firebaseAppCheckBlockedRetryAt - Date.now());
                return false;
            }
            if (firebaseAuthApiBlocked && !userInitiated && Date.now() < firebaseAuthApiBlockedRetryAt) {
                setConnBanner(false, { immediate: true });
                schedulePendingSyncRetry(firebaseAuthApiBlockedRetryAt - Date.now());
                return false;
            }
            if (userInitiated && firebaseAppCheckBlocked) {
                firebaseAppCheckBlockedRetryAt = 0;
                nextReconnectAttemptAt = 0;
            }
            if (userInitiated && firebaseAuthApiBlocked) {
                firebaseAuthApiBlockedRetryAt = 0;
                nextReconnectAttemptAt = 0;
            }
            pendingSyncRetryInFlight = (async () => {
                const before = getPendingSyncSummary();
                if (!before.total) return true;
                if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                    setConnBanner(false, { immediate: true });
                    if (userInitiated) showToast('This device is offline. The punch remains safely stored locally.');
                    return false;
                }

                appendSyncAudit('retry_started', userInitiated ? 'Manual sync retry started.' : 'Automatic sync retry started.', { pending:before.total, punchEvents:before.punchEvents });
                setReconnectUi(true, before.punchWrites > 0 || before.punchEvents > 0 ?
                    'Retrying locally saved attendance punches with the live server...' :
                    'Retrying locally saved changes with the live server...');

                let connected = fbConnected === true;
                if (!connected) connected = await reconnectToLiveServer({ userInitiated: false });
                if (!connected && fbConnected !== true) {
                    if (userInitiated && firebaseAppCheckBlocked) showToast(appCheckUserMessage(), 7000);
                    else if (userInitiated && firebaseAuthApiBlocked) showToast(firebaseAuthBlockedUserMessage(), 7000);
                    return false;
                }

                const flushed = await flushPendingRecords();
                const after = getPendingSyncSummary();
                if (!after.total) {
                    pendingSyncRetryCount = 0;
                    markPunchQueueSyncedInUi();
                    setConnBanner(true, { immediate: true });
                    appendSyncAudit('retry_complete', 'All pending local changes were confirmed by the live server.', {});
                    updatePendingSyncUi();
                    if (userInitiated) showToast('Saved attendance data synced to the live server.');
                    return true;
                }

                pendingSyncRetryCount += 1;
                if (userInitiated) showToast('The live server did not confirm every saved punch yet. Automatic retry will continue.');
                return !!flushed && !after.total;
            })().catch((error) => {
                lastConnectionError = error;
                pendingSyncRetryCount += 1;
                setLiveConnectionState(false, 'pending-retry-failed');
                if (userInitiated) showToast(getUserFacingSyncError(error), 7000);
                return false;
            }).finally(() => {
                pendingSyncRetryInFlight = null;
                const banner = $('connBanner');
                if (banner) banner.classList.remove('is-checking');
                setReconnectBusy(false);
                const remaining = getPendingSyncSummary();
                updatePendingSyncUi();
                setConnBanner(fbConnected === true, { immediate: remaining.punchWrites > 0 || remaining.punchEvents > 0 });
                if (remaining.total && typeof navigator !== 'undefined' && navigator.onLine !== false) {
                    schedulePendingSyncRetry();
                }
            });
            return pendingSyncRetryInFlight;
        }

        startReconnectMonitor();
        startLiveHeartbeat();
        updatePendingSyncUi();

        function flushPendingRecords() {
            if (!fbDb || fbConnected === false) {
                if (getPendingSyncSummary().total) schedulePendingSyncRetry();
                return Promise.resolve(false);
            }
            if (pendingFlushPromise) return pendingFlushPromise;
            const flushGeneration = pendingMutationVersion;

            pendingFlushPromise = (async () => {
                let allSucceeded = true;

                const deleteKeys = getLocalKeysWithPrefix(PENDING_DELETE_PREFIX);
                for (const storageKey of deleteKeys) {
                    const realKey = storageKey.slice(PENDING_DELETE_PREFIX.length);
                    const deleteToken = safeLocalGet(storageKey);
                    if (!realKey || deleteToken === null) {
                        safeLocalRemove(storageKey);
                        continue;
                    }
                    try {
                        if (readRecordDeleteMeta(realKey)) {
                            const resolved = await flushPendingVersionedDelete(storageKey, realKey);
                            if (!resolved) allSucceeded = false;
                        } else {
                            await withTimeout(
                                fbDb.ref('kv/' + fbEncodeKey(realKey)).remove(),
                                FIREBASE_WRITE_TIMEOUT_MS,
                                'Timed out replaying a queued delete.'
                            );
                            if (safeLocalGet(storageKey) === deleteToken) {
                                safeLocalRemove(storageKey);
                                safeLocalRemove(realKey);
                                safeLocalRemove(PENDING_PREFIX + realKey);
                                if (fbKvCache) delete fbKvCache[realKey];
                            }
                        }
                    } catch (error) {
                        allSucceeded = false;
                        handleStorageError(error, 'delete-retry-failed');
                        if (fbConnected === false) break;
                    }
                }

                if (fbConnected === false) return false;

                const writeKeys = getLocalKeysWithPrefix(PENDING_PREFIX);
                for (const storageKey of writeKeys) {
                    const realKey = storageKey.slice(PENDING_PREFIX.length);
                    const stored = safeLocalGet(storageKey);
                    if (!realKey || stored === null) continue;
                    if (hasPendingDelete(realKey)) {
                        safeLocalRemove(storageKey);
                        continue;
                    }
                    try {
                        if (readRecordVersionMeta(realKey)) {
                            const resolved = await flushPendingVersionedRecord(storageKey, realKey, stored);
                            if (!resolved) allSucceeded = false;
                        } else if (BLOB_VERSION_KEYS[realKey]) {
                            await flushPendingBlob(storageKey, realKey, stored);
                        } else {
                            getPendingPunchEvents().filter(event => event.key === realKey).forEach(updatePunchEventAttempt);
                            await withTimeout(
                                fbDb.ref('kv/' + fbEncodeKey(realKey)).set(stored),
                                FIREBASE_WRITE_TIMEOUT_MS,
                                'Timed out replaying queued live data.'
                            );
                            lastLiveServerPingAt = Date.now();
                            if (fbConnected !== true) setLiveConnectionState(true, 'pending-write');

                            let receiptOk = true;
                            let remoteRecord = null;
                            if (realKey.startsWith('att:') || realKey.startsWith('tlatt:')) {
                                const events = getPendingPunchEvents().filter(event => event.key === realKey);
                                if (events.length) {
                                    receiptOk = false;
                                    for (const event of events) {
                                        const receipt = await verifyPunchReceiptOnServer(realKey, event.field, event.timestamp, event.id);
                                        if (receipt.ok) {
                                            remoteRecord = receipt.remote || remoteRecord;
                                            acknowledgePunchEventsForRecord(realKey, receipt.remote);
                                            receiptOk = true;
                                        }
                                    }
                                    // If more than one event shares the same queued record, require
                                    // every receipt represented by the stored payload to be resolved.
                                    receiptOk = getPendingPunchEvents().filter(event => event.key === realKey).length === 0;
                                    if (!receiptOk) appendSyncAudit('verify_pending', 'Queued attendance write is still awaiting exact punch receipt confirmation.', { key:realKey });
                                } else {
                                    const receipt = await verifyAttendancePayloadOnServer(realKey, stored);
                                    receiptOk = receipt.ok;
                                    remoteRecord = receipt.remote || null;
                                }
                            }
                            if (!receiptOk) {
                                allSucceeded = false;
                                continue;
                            }
                            if (safeLocalGet(storageKey) === stored) {
                                setLocalMirrorForKey(realKey, stored, { pendingCloudSync:false });
                                if (isProfileStorageKey(realKey)) void markProfileOfflineRecordSynced(realKey, stored);
                                safeLocalRemove(storageKey);
                                lastServerConfirmedWriteAt = typeof getTrueNowMs === 'function' ? getTrueNowMs() : Date.now();
                            }
                        }
                    } catch (error) {
                        allSucceeded = false;
                        handleStorageError(error, 'write-retry-failed');
                        if (fbConnected === false) break;
                    }
                }
                return allSucceeded;
            })().catch((error) => {
                handleStorageError(error, 'pending-flush-failed');
                return false;
            }).finally(() => {
                pendingFlushPromise = null;
                const remaining = getPendingSyncSummary();
                if (!remaining.total) {
                    pendingSyncRetryCount = 0;
                    clearPendingSyncRetryTimer();
                    markPunchQueueSyncedInUi();
                } else if (typeof navigator !== 'undefined' && navigator.onLine !== false) {
                    schedulePendingSyncRetry();
                }
                updatePendingSyncUi();
                setConnBanner(fbConnected === true, { immediate: remaining.punchWrites > 0 || remaining.punchEvents > 0 });
                if (pendingMutationVersion !== flushGeneration && fbDb && fbConnected === true) {
                    setTimeout(() => { void flushPendingRecords(); }, 0);
                }
            });

            return pendingFlushPromise;
        }

        async function flushPendingBlob(storageKey, realKey, storedRaw) {
            let parsed;
            try {
                parsed = JSON.parse(storedRaw);
            } catch (e) {
                safeLocalRemove(storageKey);
                return false;
            }
            const { payload, baseVersion } = parsed || {};
            const targetVersion = parsed && parsed.targetVersion ? parsed.targetVersion : createBlobVersion();
            const acceptedBaseVersions = new Set([
                baseVersion,
                ...(parsed && Array.isArray(parsed.acceptedBaseVersions) ? parsed.acceptedBaseVersions : [])
            ].filter(value => value !== null && value !== undefined));
            if (typeof payload !== 'string') {
                safeLocalRemove(storageKey);
                return false;
            }

            const vKey = BLOB_VERSION_KEYS[realKey];
            const versionSnap = await withTimeout(
                fbDb.ref('kv/' + fbEncodeKey(vKey)).once('value'),
                FIREBASE_READ_TIMEOUT_MS,
                'Timed out checking the shared-data version.'
            );
            const remoteVersion = versionSnap.exists() ? versionSnap.val() : null;

            if (remoteVersion === targetVersion) {
                const remoteSnap = await withTimeout(
                    fbDb.ref('kv/' + fbEncodeKey(realKey)).once('value'),
                    FIREBASE_READ_TIMEOUT_MS,
                    'Timed out confirming shared live data.'
                );
                if (remoteSnap.exists() && remoteSnap.val() === payload) {
                    if (safeLocalGet(storageKey) === storedRaw) {
                        safeLocalSet(realKey, payload);
                        safeLocalSet(vKey, targetVersion);
                        safeLocalRemove(storageKey);
                        blobVersionVarSet(realKey, targetVersion);
                    }
                    return true;
                }
            }

            if (remoteVersion !== null && !acceptedBaseVersions.has(remoteVersion)) {
                if (safeLocalGet(storageKey) !== storedRaw) return false;
                safeLocalRemove(storageKey);
                void logAudit('pending_write_conflict', {
                    key: realKey,
                    reason: 'A newer shared version was saved while this device was offline.'
                });
                showToast('A newer shared update was kept; the older offline edit was not replayed.');

                const remoteSnap = await withTimeout(
                    fbDb.ref('kv/' + fbEncodeKey(realKey)).once('value'),
                    FIREBASE_READ_TIMEOUT_MS,
                    'Timed out restoring the newer shared data.'
                );
                let change = null;
                if (remoteSnap.exists() && typeof remoteSnap.val() === 'string') {
                    change = applyKvChildUpsert(fbEncodeKey(realKey), remoteSnap.val());
                } else {
                    change = applyKvChildRemove(fbEncodeKey(realKey));
                }
                if (change) scheduleIncrementalRender(change);
                return false;
            }

            await writeSharedBlobRemote(realKey, payload, targetVersion);
            if (safeLocalGet(storageKey) === storedRaw) {
                safeLocalSet(realKey, payload);
                safeLocalSet(vKey, targetVersion);
                safeLocalRemove(storageKey);
                blobVersionVarSet(realKey, targetVersion);
            }
            return true;
        }

        function getStorageHash() {
            let s = '';
            try {
                const keys = Object.keys(localStorage).filter(k => k.startsWith('att:') || k.startsWith('ot:') || k.startsWith('speedtest:') || k.startsWith('dayswap:') || k.startsWith('shiftoverride:') || k.startsWith('leave:') || k.startsWith('leaveledger:') || k.startsWith('leaveprofile:') || k.startsWith('leavepolicyv3:') || k === 'leave_policy_v3' ||
                    k === 'employees' || k === 'dayoff_schedule' || k === 'shift_settings' || k === 'announcements' || k === NETWORK_SETTINGS_KEY || k === PREMIUM_ACCESS_POLICY_KEY || k === PREMIUM_BEBLESS_LEGACY_ACCESS_KEY);
                for (const k of keys) {
                    s += k + ':' + (localStorage.getItem(k) || '') + '|';
                }
            } catch (e) {}
            return s;
        }

