            podSel.innerHTML = pods.map(pod => `<option value="${escapeHtml(pod)}">${escapeHtml(podDisplayName(pod))}</option>`).join('');
            podSel.disabled = !!fixedTeam;
            if (preferredPod && pods.includes(preferredPod)) podSel.value = preferredPod;
            else if (activePod !== ALL_PODS_LABEL && pods.includes(activePod)) podSel.value = activePod;
