            const scoped = employeeScopePod === ALL_PODS_LABEL ? teamScoped : teamScoped.filter(e => e.pod === employeeScopePod);
            const sorted = [...scoped].sort((a, b) => a.name.localeCompare(b.name));
            const html = sorted.map(e => `<option value="${escapeHtml(e.name)}">${escapeHtml(agentDisplayName(e.name))} (${escapeHtml(podDisplayName(e.pod))})</option>`).join('');
            sel.innerHTML = '<option value="">— Select Agent —</option>' + html;
