        function renderPodTabs() {
            const container = $('podTabs');
            if (!container) return;
            let pods;
            let scopeWasRevoked = false;
            let revokedBackupContext = null;
            const homePod = isTeamLeader && !isAdmin && teamLeaderName ? teamLeaderHomePod(teamLeaderName) : '';
            if (isAdmin) {
                pods = [ALL_PODS_LABEL, ...podsForTeam(activeTeam)];
            } else if (isTeamLeader && teamLeaderName) {
                pods = teamLeaderAuthorizedPods(teamLeaderName);
                if (!pods.length && homePod) pods = [homePod];
                if (!pods.includes(lockedPod)) {
                    const previousScope = lockedPod;
                    scopeWasRevoked = !!(previousScope && homePod && previousScope !== homePod);
                    if (scopeWasRevoked) {
                        const assignment = teamLeaderBackupAssignments(teamLeaderName).find(item => item.targetPod === previousScope) || null;
                        const verification = teamLeaderDelegationForPod(previousScope, teamLeaderName);
                        revokedBackupContext = { previousScope, assignment, reason:(verification && verification.reason) || 'coverage-ended' };
                    }
                    lockedPod = homePod || pods[0] || lockedPod;
                    activePod = lockedPod;
                }
            } else {
                pods = [lockedPod || activePod];
            }
            if (isTeamLeader && !isAdmin && teamLeaderName) teamLeaderDelegationScopeSignature = teamLeaderDelegationSignature();
            const solo = pods.length === 1;
            container.classList.toggle('solo', solo);
            container.innerHTML = pods.map(p => {
                const active = p === activePod ? 'active' : '';
                const cls = solo ? 'pod-tab-solo' : `pod-tab ${active}`;
                const delegated = !!(isTeamLeader && !isAdmin && teamLeaderName && homePod && p !== homePod && teamLeaderDelegationForPod(p, teamLeaderName).active);
                const baseLabel = p === ALL_PODS_LABEL ? p : podDisplayName(p);
                const label = delegated ? `${baseLabel} · Backup` : baseLabel;
                const title = delegated ? `Temporary Backup TL access while ${agentDisplayName(teamLeaderDelegationForPod(p, teamLeaderName).primaryName)} is on Day Off` : '';
                return `<button class="${cls}" data-pod="${escapeHtml(p)}" data-delegated="${delegated ? 'true' : 'false'}" type="button" ${title ? `title="${escapeHtml(title)}"` : ''}>${escapeHtml(label)}</button>`;
            }).join('');
            container.querySelectorAll('.pod-tab, .pod-tab-solo').forEach(btn => {
                btn.addEventListener('click', () => {
                    const pod = btn.dataset.pod;
                    if (pod === activePod) return;
                    if (isTeamLeader && !isAdmin && teamLeaderName) {
                        const allowed = teamLeaderAuthorizedPods(teamLeaderName);
                        if (!allowed.includes(pod)) {
                            showToast('Temporary Backup access is not active for that POD.');
                            renderPodTabs();
                            return;
                        }
                        lockedPod = pod;
                    } else if (lockedPod && !isAdmin && pod !== lockedPod) {
                        showToast('You are locked to ' + podContextLabel(lockedPod));
                        return;
                    }
                    activePod = pod;
                    if (pod !== ALL_PODS_LABEL) rememberTeamPod(activeTeam, pod);
                    applyPremiumModeForCurrentSession('pod-scope-change');
                    renderPodTabs();
                    populateEmployeeSelects();
                    renderTable();
                    renderTodayStatus();
                    if (isOverlayOpen($('historyOverlay'))) renderHistoryCalendar();
                    if (isOverlayOpen($('noteHistoryOverlay'))) renderNoteHistory();
                    if (isOverlayOpen($('otTabOverlay'))) renderOTTab();
                    if (isOverlayOpen($('totalsOverlay'))) renderTotalsTab();
                    if (isOverlayOpen($('networkOverlay'))) renderNetworkTab();
                    if (currentEmployee) {
                        const teamScope = currentTeamEmployees();
                        const scope = activePod === ALL_PODS_LABEL ? teamScope : teamScope.filter(e => e.pod === activePod);
                        if (!scope.some(e => e.name === currentEmployee)) {
                            currentEmployee = null;
                            if ($('empSelect')) $('empSelect').value = '';
                            if ($('empSearch')) $('empSearch').value = '';
                            refreshPunchCard();
                        }
                    }
                    const delegation = currentTeamLeaderDelegation();
                    if (delegation) {
                        void logAudit('tl_backup_delegate_scope_opened', {
                            backupTeamLeader:teamLeaderName,
                            backupHomePod:delegation.homePod,
                            primaryTeamLeader:delegation.primaryName,
                            delegatedPod:delegation.pod,
                            date:delegation.date,
                            source:'automatic_day_off_delegate'
                        });
                        showToast(`Backup TL access active for ${podDisplayName(delegation.pod)} while ${agentDisplayName(delegation.primaryName)} is on Day Off.`);
                    }
                    updateAdminUI();
                });
            });
            syncBackupTlCoverageBanner();
            if (scopeWasRevoked) {
                const revoked = revokedBackupContext;
                setTimeout(() => {
                    const assignment = revoked && revoked.assignment;
                    const reason = revoked && revoked.reason || 'coverage-ended';
                    showToast(backupTlRevocationCopy(reason, assignment));
                    void logAudit('tl_backup_coverage_ended', {
                        backupTeamLeader:teamLeaderName,
                        primaryTeamLeader:assignment && assignment.primaryName || '',
                        delegatedPod:revoked && revoked.previousScope || '',
                        backupHomePod:homePod,
                        date:assignment && assignment.date || todayKeyPart(),
                        reason,
                        source:'automatic_scope_revocation'
                    });
                    populateEmployeeSelects();
                    renderTable();
                    renderTodayStatus();
                    refreshPunchCard();
                    updateAdminUI();
                }, 0);
            }
        }

