            agentSel.innerHTML = roster.length ? roster.map(emp => `<option value="${escapeHtml(emp.name)}">${escapeHtml(agentDisplayName(emp.name))}</option>`).join('') : '<option value="">No scheduled-working agents</option>';
            if (roster.some(emp => emp.name === prior)) agentSel.value = prior;
