        const tlAttendanceEditCancelBtn = $('tlAttendanceEditCancelBtn');
        if (tlAttendanceEditCancelBtn) tlAttendanceEditCancelBtn.addEventListener('click', closeTlAttendanceAdminEdit);
        const tlAttendanceEditOverlay = $('tlAttendanceEditOverlay');
        if (tlAttendanceEditOverlay) tlAttendanceEditOverlay.addEventListener('click', event => { if (event.target === tlAttendanceEditOverlay) closeTlAttendanceAdminEdit(); });
        const tlAttendanceEditSaveBtn = $('tlAttendanceEditSaveBtn');
        if (tlAttendanceEditSaveBtn) tlAttendanceEditSaveBtn.addEventListener('click', () => {
            void runAsyncAction(async () => {
                if (!editingTlAttendanceKey) { showToast('Select a Team Leader attendance record first.'); return; }
                const { date, name } = editingTlAttendanceKey;
                const oldRec = allTeamLeaderRecords[tlAttendanceMapKey(date, name)] || {};
                const historicalPod = teamLeaderAttendanceRecordPod(name, oldRec);
                if (!TrinoPermissions.can('attendance.tl.edit', { name, pod:historicalPod })) { showToast('An authenticated system Admin is required to edit Team Leader timestamps.'); return; }
                const reason = String($('tlEditReason').value || '').trim();
                if (!reason) { showToast('Enter a reason for the timestamp correction.'); $('tlEditReason').focus(); return; }
                const edited = readTlAdminEditedPunches(date);
                if (edited.error) { showToast(edited.error); return; }
                const next = { ...oldRec };
                ['timeIn','startBreak','endBreak','logOut'].forEach(field => {
                    if (edited.values[field]) next[field] = edited.values[field];
                    else delete next[field];
                });
                if (!tlPunchFieldsChanged(oldRec, next)) { showToast('No timestamp changes detected.'); return; }
                const adminId = requireAuthenticatedAdminId();
                const correctionAt = nowIso();
                next.lastTimestampCorrectionAt = correctionAt;
                next.lastTimestampCorrectionBy = adminId;
                next.lastTimestampCorrectionRole = 'Admin';
                next.lastTimestampCorrectionReason = reason;
                next.modified_by = adminId;
                next.modified_at = correctionAt;
                next.modified_action = 'admin_timestamp_edit';
                next.modified_reason = reason;
                const stored = await saveTeamLeaderAttendanceRecord(date, name, next, {
                    requireTimestampChange:true,
                    modifiedBy:adminId,
                    modifiedAt:correctionAt,
                    modificationAction:'admin_timestamp_edit',
                    modificationReason:reason
                });
                await logAudit('tl_attendance_edit', {
                    date,
                    name,
                    pod:historicalPod,
                    old:oldRec,
                    new:stored,
                    editedBy:'Admin',
                    modified_by:adminId,
                    admin_id:adminId,
                    reason
                });
                if (recoveryCanManage() && !adminRecoveryRestoring) {
                    registerAdminRecovery('tl_attendance_edit', `${name} · Team Leader attendance correction`, {
                        date, name, record:recoveryClone(oldRec)
                    }, reason);
                }
                closeTlAttendanceAdminEdit();
                renderTeamLeaderAttendance();
                showToast('Team Leader attendance timestamps corrected.');
            }, 'Edit Team Leader attendance');
        });
        const tlAttendanceDeleteBtn = $('tlAttendanceDeleteBtn');
        if (tlAttendanceDeleteBtn) tlAttendanceDeleteBtn.addEventListener('click', () => {
            void runAsyncAction(async () => {
                if (!editingTlAttendanceKey) { showToast('Select a Team Leader attendance record first.'); return; }
                const { date, name } = editingTlAttendanceKey;
                const oldRec = allTeamLeaderRecords[tlAttendanceMapKey(date, name)] || {};
                const historicalPod = teamLeaderAttendanceRecordPod(name, oldRec);
                if (!TrinoPermissions.can('attendance.tl.delete', { name, pod:historicalPod })) { showToast('An authenticated system Admin is required to delete Team Leader attendance records.'); return; }
                const reason = String($('tlEditReason').value || '').trim();
                if (!reason) { showToast('Enter a reason before deleting this attendance record.'); $('tlEditReason').focus(); return; }
                if (!(await showConfirmAsync(
                    'Delete Team Leader Attendance Record?',
                    `Delete the attendance record for <strong>${escapeHtml(name)}</strong> on <strong>${escapeHtml(date)}</strong>?<br><br>This Admin-only action is destructive and will be written to the immutable audit log.`,
                    { confirmLabel:'Delete Record', cancelLabel:'Cancel', tone:'danger', kind:'tl-attendance-delete' }
                ))) return;
                const adminId = requireAuthenticatedAdminId();
                await deleteTeamLeaderAttendanceRecord(date, name);
                await logAudit('tl_attendance_delete', { date, name, pod:historicalPod, deletedBy:'Admin', modified_by:adminId, admin_id:adminId, reason, original:oldRec });
                closeTlAttendanceAdminEdit();
                renderTeamLeaderAttendance();
                showToast('Team Leader attendance record deleted.');
            }, 'Delete Team Leader attendance');
        });







        function mdyToIsoDateInput(mdy) {
            const { y, m, d } = parseDateStr(mdy);
            return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
        }
        function isoDateInputToMdy(iso) {
            if (!iso) return todayKeyPart();
            const [y, m, d] = iso.split('-').map(n => parseInt(n, 10));
            return `${m}/${d}/${y}`;
        }


        function otEmployeeScope() {
            if (isAdmin) {
                const combined = [...currentTeamEmployees(), ...teamLeadersForAttendanceTeam(activeTeam).map(tl => ({ name:tl.name, pod:tl.pod, overtimeRole:'Team Leader' }))];
                const seen = new Set();
                return combined.filter(item => item && item.name && !seen.has(item.name) && (seen.add(item.name), true));
            }
            if (isTeamLeader && lockedPod) return labelerRosterEmployees().filter(e => e.pod === lockedPod);
            return [];
        }

        function populateOTEmpSelect(preselect) {
            const sel = $('otEmpSelect');
            if (!sel) return;
            // v1.1.69: TL overtime must go through the submission/review workflow.
            // The generic Add / Approve dialog is intentionally Agent-only so Admin
            // cannot accidentally bypass the TL approval queue or its audit history.
            const scope = [...otEmployeeScope()].filter(e => !isKnownTeamLeader(e.name) && e.overtimeRole !== 'Team Leader').sort((a, b) => a.name.localeCompare(b.name));
            sel.innerHTML = scope.map(e => `<option value="${escapeHtml(e.name)}">${escapeHtml(agentDisplayName(e.name))} — ${escapeHtml(e.pod)}</option>`).join('');
            if (preselect && scope.some(e => e.name === preselect)) sel.value = preselect;
        }

        let editingOTKey = null;

        function refreshOTModalForSelection() {
            const name = $('otEmpSelect').value;
            const dateStr = isoDateInputToMdy($('otDate').value);
            editingOTKey = { date: dateStr, name };
            const existing = name ? getOTRecord(dateStr, name) : null;
            setOvertimeDuration('otHours', 'otMinutes', existing ? getStoredOTHoursFromRecord(existing) : null);
            $('otNote').value = existing ? (existing.note || '') : '';
            $('otDeleteBtn').style.display = existing ? '' : 'none';

            const blockedReason = overtimePayPeriodLockMessage(dateStr) || otBlockedReason(dateStr, name);
            const note = $('otEligibilityNote');
            const controls = [$('otHours'), $('otMinutes'), $('otNote'), $('otSaveBtn')];
            if (blockedReason) {
                note.textContent = blockedReason;
                note.style.display = '';
                controls.forEach(el => { if (el) el.disabled = true; });
                if ($('otDeleteBtn')) $('otDeleteBtn').disabled = true;
            } else {
                note.style.display = 'none';
                controls.forEach(el => { if (el) el.disabled = false; });
                if ($('otDeleteBtn')) $('otDeleteBtn').disabled = false;
            }
        }

        function openOTModal(dateStr, name) {
            if (!isAdmin && !isTeamLeader) {
                showToast('Only Team Leaders and Admins can manage overtime.');
                return;
            }
            if (name && isKnownTeamLeader(name)) {
                if (isAdmin) openTLOvertimeCorrectionModal(dateStr || todayKeyPart(), name);
                else showToast('Team Leader overtime uses the TL submission and Admin review workflow.');
                return;
            }
            populateOTEmpSelect(name);
            if (!$('otEmpSelect').options.length) { showToast('No Agents are available in your overtime scope.'); return; }
            const d = dateStr || todayKeyPart();
            $('otDate').value = mdyToIsoDateInput(d);
            refreshOTModalForSelection();
            const overlay = ensureOvertimeChildModalPortal('otOverlay') || $('otOverlay');
            if (overlay) overlay.classList.add('open');
        }

        function closeOTModal() {
            $('otOverlay').classList.remove('open');
            editingOTKey = null;
        }

        function overtimeEntryFromMap(key, rec) {
            const idx = key.indexOf('|');
            const date = idx >= 0 ? key.slice(0, idx) : '';
            const name = idx >= 0 ? key.slice(idx + 1) : '';
            const attendance = name && date ? overtimeAttendanceRecordFor(date, name) : null;
            const pod = (rec && rec.pod) || (attendance && attendance.pod) || overtimePodForName(name) || 'Unassigned';
            return { date, name, pod, ...(rec || {}) };
        }

        function allOvertimeEntries() {
            return Object.entries(allOT).map(([key, rec]) => overtimeEntryFromMap(key, rec));
        }

        function pendingTLOvertimeRequests() {
            return allOvertimeEntries().filter(entry => entry.status === 'pending' && isTeamLeaderOTRecord(entry.name, entry));
        }

        function overtimeStatusChip(rec) {
            const status = String(rec && rec.status || 'saved').toLowerCase();
            return `<span class="ot-status-chip" data-status="${escapeHtml(status)}">${escapeHtml(overtimeStatusLabel(status))}</span>`;
        }

        function formatOTSubmissionTime(value) {
            if (!value) return '—';
            try { return formatPremiumEntitlementTimestamp(value) || formatManilaTime(value, true); } catch (_) { return String(value); }
        }

        function overtimeBreakdownHtml(breakdown, labels = { regular:'Regular', overtime:'Approved OT', total:'Total' }) {
            return `<div class="ot-hours-breakdown">
                <span><small>${escapeHtml(labels.regular || 'Regular')}</small><strong>${escapeHtml(formatOTHoursValue(breakdown.regular))}</strong></span>
                <span><small>${escapeHtml(labels.overtime || 'Approved OT')}</small><strong>${escapeHtml(formatOTHoursValue(breakdown.approved))}</strong></span>
                <span><small>${escapeHtml(labels.total || 'Total')}</small><strong>${escapeHtml(formatOTHoursValue(breakdown.total))}</strong></span>
            </div>`;
        }

        function updateOvertimeTabBadge() {
            const tab = $('otTabBtn');
            if (!tab) return;
            let count = 0;
            if (isAdmin) count = pendingTLOvertimeRequests().length;
            else if (isTeamLeader && teamLeaderName) count = allOvertimeEntries().filter(e => e.name === teamLeaderName && e.status === 'pending').length;
            tab.textContent = count > 0 ? `Overtime (${count})` : 'Overtime';
        }

        function renderMyTLOvertimeRequests() {
            const section = $('tlOtMyRequestsSection');
            const wrap = $('tlOtMyRequestsWrap');
            if (!section || !wrap) return;
            const visible = Boolean(isTeamLeader && !isAdmin && teamLeaderName);
            section.hidden = !visible;
            if (!visible) { wrap.innerHTML = ''; return; }
            const rows = allOvertimeEntries().filter(e => e.name === teamLeaderName && isTeamLeaderOTRecord(e.name, e));
            rows.sort((a,b) => dateStrToComparable(b.date) - dateStrToComparable(a.date));
            if (!rows.length) {
                wrap.innerHTML = '<div class="ot-empty-state"><strong>No TL overtime requests yet.</strong><span>Submit overtime here when a manager asks you to work extra time. Your daily total will not change until Admin approval.</span></div>';
                return;
            }
            wrap.innerHTML = `<div class="ot-request-list">${rows.map(row => {
                const hours = getStoredOTHoursFromRecord(row);
                const status = String(row.status || '').toLowerCase();
                const breakdown = overtimeHoursBreakdown(row.date, row.name, hours);
                const lockMessage = overtimePayPeriodLockMessage(row.date);
                const adminNote = status === 'rejected' && row.reviewNote ? row.reviewNote : (status === 'revoked' ? row.revocationReason : '');
                const reviewText = adminNote ? `<span class="ot-request-review-note">Admin note: ${escapeHtml(adminNote)}</span>` : '';
                let action = '';
                if (!lockMessage && status === 'pending') {
                    action = `<div class="ot-request-actions"><button type="button" class="row-edit-btn tl-ot-request-edit" data-date="${escapeHtml(row.date)}">Edit</button><button type="button" class="row-edit-btn danger tl-ot-request-withdraw" data-date="${escapeHtml(row.date)}">Withdraw</button></div>`;
                } else if (!lockMessage && (status === 'rejected' || status === 'withdrawn' || status === 'revoked')) {
                    action = `<div class="ot-request-actions"><button type="button" class="row-edit-btn tl-ot-request-edit" data-date="${escapeHtml(row.date)}">Resubmit</button></div>`;
                }
                const shiftNote = row.shiftDateAdjusted ? `<span class="ot-request-info">Overnight shift date applied${row.requestedCalendarDate ? ` · originally selected ${escapeHtml(row.requestedCalendarDate)}` : ''}</span>` : '';
                const lockNote = lockMessage ? `<span class="ot-request-review-note">Payroll finalized — this request is read-only until Admin unlocks the period.</span>` : '';
                return `<article class="ot-request-row">
                    <div class="ot-request-main"><strong>${escapeHtml(row.date)} · ${escapeHtml(formatOvertimeDuration(hours))}</strong>${overtimeStatusChip(row)}<span>${escapeHtml(row.note || 'No reason recorded')}</span>${shiftNote}${reviewText}${lockNote}</div>
                    <div class="ot-request-meta">${overtimeBreakdownHtml(breakdown)}<span>${escapeHtml(podDisplayName(row.pod))} · Submitted ${escapeHtml(formatOTSubmissionTime(row.submittedAt))}</span></div>
                    ${action}
                </article>`;
            }).join('')}</div>`;
            wrap.querySelectorAll('.tl-ot-request-edit').forEach(btn => btn.addEventListener('click', () => openTLOvertimeRequestModal(btn.dataset.date)));
            wrap.querySelectorAll('.tl-ot-request-withdraw').forEach(btn => btn.addEventListener('click', () => {
                void runAsyncAction(async () => {
                    const date = btn.dataset.date;
                    if (!(await showConfirmAsync('Withdraw Overtime Request?', `Withdraw your pending overtime request for <strong>${escapeHtml(date)}</strong>? It will remain in history as Withdrawn and will not affect credited hours.`, { confirmLabel:'Withdraw Request', cancelLabel:'Keep Request', tone:'danger', kind:'tl-overtime-withdraw' }))) return;
                    await withdrawTLOvertimeRequest(date, teamLeaderName);
                    await logAudit('tl_overtime_request_withdraw', { date, name:teamLeaderName, pod:overtimePodForName(teamLeaderName), withdrawnBy:teamLeaderName });
                    renderOTTab();
                    showToast('Overtime request withdrawn.');
                }, 'Withdraw overtime request');
            }));
        }

        function renderTLOvertimeAdminQueue() {
            const section = $('tlOtAdminQueueSection');
            const wrap = $('tlOtAdminQueueWrap');
            const badge = $('tlOtPendingCount');
            if (!section || !wrap) return;
            section.hidden = !isAdmin;
            if (!isAdmin) { wrap.innerHTML = ''; if (badge) badge.textContent = '0 pending'; return; }
            const rows = pendingTLOvertimeRequests().sort((a,b) => {
                const at = new Date(a.submittedAt || 0).getTime();
                const bt = new Date(b.submittedAt || 0).getTime();
                return at - bt || dateStrToComparable(a.date) - dateStrToComparable(b.date);
            });
            if (badge) badge.textContent = `${rows.length} pending`;
            if (!rows.length) {
                wrap.innerHTML = '<div class="ot-empty-state"><strong>No pending TL overtime requests.</strong><span>New Team Leader submissions will appear here automatically.</span></div>';
                return;
            }
            wrap.innerHTML = `<div class="ot-review-list">${rows.map(row => {
                const requested = getStoredOTHoursFromRecord(row);
                const breakdown = overtimeHoursBreakdown(row.date, row.name, requested);
                const locked = isOvertimePeriodLocked(row.date);
                return `<article class="ot-review-row">
                    <div class="ot-review-person">${profilePhotoMarkup(row.name, 'avatar')}<div><strong>${escapeHtml(agentDisplayName(row.name))}</strong><span>${escapeHtml(podDisplayName(row.pod))} · ${escapeHtml(row.date)}</span>${row.shiftDateAdjusted ? '<small class="ot-request-info">Overnight shift date protected</small>' : ''}</div></div>
                    <div class="ot-review-breakdown"><span><small>Regular</small><strong>${escapeHtml(formatOTHoursValue(breakdown.regular))}</strong></span><span><small>Requested OT</small><strong>${escapeHtml(formatOvertimeDuration(requested))}</strong></span><span><small>Proposed Total</small><strong>${escapeHtml(formatOTHoursValue(breakdown.proposedTotal))}</strong></span></div>
                    <div class="ot-review-reason"><span>Reason</span><strong>${escapeHtml(row.note || 'No reason recorded')}</strong><small>Submitted ${escapeHtml(formatOTSubmissionTime(row.submittedAt))}${locked ? ' · PAYROLL FINALIZED' : ''}</small></div>
                    <div class="ot-request-actions"><button type="button" class="modal-btn save tl-ot-review-open" data-date="${escapeHtml(row.date)}" data-name="${escapeHtml(row.name)}">Review</button></div>
                </article>`;
            }).join('')}</div>`;
            wrap.querySelectorAll('.tl-ot-review-open').forEach(btn => btn.addEventListener('click', () => openTLOvertimeReviewModal(btn.dataset.date, btn.dataset.name)));
        }

        function renderOTPayrollLockPanel() {
            const section = $('otPayrollLockSection');
            if (!section) return;
            section.hidden = !isAdmin;
            if (!isAdmin) return;
            const dateInput = $('otPayrollLockDate');
            if (dateInput && !dateInput.value) dateInput.value = mdyToIsoDateInput(todayKeyPart());
            const dateStr = dateInput && dateInput.value ? isoDateInputToMdy(dateInput.value) : todayKeyPart();
            const period = overtimePayPeriodForDate(dateStr);
            const record = getOvertimePeriodLockByStart(period.start);
            const locked = !!(record && String(record.status || '').toLowerCase() === 'locked');
            const pending = pendingTLOvertimeForPeriod(period);
            const status = $('otPayrollLockStatus');
            const periodEl = $('otPayrollLockPeriod');
            const meta = $('otPayrollLockMeta');
            const pendingEl = $('otPayrollLockPending');
            const action = $('otPayrollLockActionBtn');
            if (periodEl) periodEl.textContent = period.label;
            if (status) { status.textContent = locked ? 'Finalized / Locked' : 'Open for OT changes'; status.dataset.status = locked ? 'locked' : 'open'; }
            if (pendingEl) pendingEl.textContent = `${pending.length} pending TL request${pending.length === 1 ? '' : 's'}`;
            if (meta) {
                if (locked) meta.textContent = `Finalized ${formatOTSubmissionTime(record.lockedAt)}${record.lockReason ? ` · ${record.lockReason}` : ''}`;
                else if (record && record.unlockedAt) meta.textContent = `Unlocked ${formatOTSubmissionTime(record.unlockedAt)} · ${record.unlockReason || 'Correction window reopened'}`;
                else meta.textContent = 'Not finalized. Overtime can still be submitted, approved, corrected, or removed.';
            }
            if (action) {
                action.textContent = locked ? 'Unlock for Correction' : 'Finalize OT Period';
                action.dataset.periodStart = period.start;
                action.dataset.locked = locked ? 'true' : 'false';
                action.disabled = !locked && pending.length > 0;
                action.title = !locked && pending.length ? 'Review all pending TL overtime requests before finalizing this pay period.' : '';
            }
        }

        function renderOTTab() {
            const wrap = $('otListWrap');
            if (!wrap) return;
            const submitBtn = $('tlOtSubmitBtn');
            const addBtn = $('otAddBtn');
            const intro = $('otTabIntro');
            const recordsHeading = $('otRecordsHeading');
            if (submitBtn) submitBtn.style.display = (isTeamLeader && !isAdmin) ? '' : 'none';
            if (addBtn) {
                addBtn.style.display = (isAdmin || isTeamLeader) ? '' : 'none';
                addBtn.textContent = isTeamLeader && !isAdmin ? '+ Add / Approve Agent Overtime' : '+ Add / Approve Agent Overtime';
            }
            if (intro) intro.textContent = isTeamLeader && !isAdmin
                ? 'Submit your own manager-requested overtime for Admin approval. Your TL totals stay unchanged while a request is Pending. Approved payroll periods become read-only until Admin unlocks them.'
                : 'Team Leader OT must pass Admin review. Finalized weekly OT pay periods are locked against later changes until an Admin explicitly unlocks them for correction.';
            if (recordsHeading) recordsHeading.textContent = isTeamLeader && !isAdmin ? 'Agent Overtime' : 'Overtime History';
            renderOTPayrollLockPanel();
            renderMyTLOvertimeRequests();
            renderTLOvertimeAdminQueue();
            updateOvertimeTabBadge();

            const scopeNames = new Set(otEmployeeScope().map(e => e.name));
            let entries = allOvertimeEntries().filter(e => scopeNames.has(e.name));
            if (isTeamLeader && !isAdmin) entries = entries.filter(e => !isTeamLeaderOTRecord(e.name, e));
            if (isAdmin) entries = entries.filter(e => !(isTeamLeaderOTRecord(e.name, e) && e.status === 'pending'));
            entries.sort((a, b) => dateStrToComparable(b.date) - dateStrToComparable(a.date) || a.name.localeCompare(b.name));
            if (!entries.length) {
                wrap.innerHTML = `<div class="loading-note">${isTeamLeader && !isAdmin ? 'No Agent overtime recorded in your POD yet.' : 'No finalized overtime records yet.'}</div>`;
                return;
            }
            wrap.innerHTML = `<div class="table-card"><table class="desktop-table ot-management-table" style="width:100%; border-collapse:collapse;">
                <thead><tr><th>Date</th><th>POD</th><th>Name</th><th>Role</th><th>Status</th><th>Requested / Saved OT</th><th>Regular</th><th>Approved OT</th><th>Total</th><th>Approved By</th><th>Reason / Note</th><th></th></tr></thead>
                <tbody>${entries.map(e => {
                    const isTl = isTeamLeaderOTRecord(e.name, e);
                    const stored = getStoredOTHoursFromRecord(e);
                    const breakdown = overtimeHoursBreakdown(e.date, e.name, stored);
                    const approvedForRow = e.status === 'approved' ? stored : 0;
                    const totalForRow = breakdown.regular === null ? null : breakdown.regular + approvedForRow;
                    const canEdit = e.status === 'approved' && canManageOvertimeForName(e.name);
                    const adminHistoryNote = e.status === 'revoked' && e.revocationReason ? `Revoked: ${e.revocationReason}` : (e.correctionReason ? `Correction: ${e.correctionReason}` : '');
                    return `<tr>
                        <td>${escapeHtml(e.date)}${isOvertimePeriodLocked(e.date) ? '<small class="ot-table-review-note">Payroll locked</small>' : ''}</td>
                        <td class="pod-cell">${escapeHtml(podDisplayName(e.pod))}</td>
                        <td class="name-cell">${profilePhotoMarkup(e.name, 'avatar')}${escapeHtml(agentDisplayName(e.name))}</td>
                        <td>${isTl ? 'Team Leader' : 'Agent'}</td>
                        <td>${overtimeStatusChip(e)}</td>
                        <td class="hours-cell">${escapeHtml(formatOvertimeDuration(stored))}</td>
                        <td class="hours-cell">${escapeHtml(formatOTHoursValue(breakdown.regular))}</td>
                        <td class="hours-cell">${escapeHtml(formatOTHoursValue(approvedForRow))}</td>
                        <td class="hours-cell">${escapeHtml(formatOTHoursValue(totalForRow))}</td>
                        <td>${escapeHtml(e.approvedBy || '—')}</td>
                        <td>${escapeHtml(e.note || '')}${e.reviewNote ? `<small class="ot-table-review-note">Review: ${escapeHtml(e.reviewNote)}</small>` : ''}${adminHistoryNote ? `<small class="ot-table-review-note">${escapeHtml(adminHistoryNote)}</small>` : ''}</td>
                        <td>${canEdit ? `<button class="row-edit-btn ${isTl ? 'tl-ot-correct-btn' : 'ot-edit-btn'}" type="button" data-date="${escapeHtml(e.date)}" data-name="${escapeHtml(e.name)}">${isTl ? 'Correct' : 'Edit'}</button>` : ''}</td>
                    </tr>`;
                }).join('')}</tbody>
            </table></div>`;
            wrap.querySelectorAll('.ot-edit-btn').forEach(btn => btn.addEventListener('click', () => openOTModal(btn.dataset.date, btn.dataset.name)));
            wrap.querySelectorAll('.tl-ot-correct-btn').forEach(btn => btn.addEventListener('click', () => openTLOvertimeCorrectionModal(btn.dataset.date, btn.dataset.name)));
        }

        let editingTLOvertimeRequestDate = '';
        let reviewingTLOvertimeKey = null;
        let correctingTLOvertimeKey = null;

        function refreshTLOvertimeRequestModalForDate() {
            if (!isTeamLeader || isAdmin || !teamLeaderName) return;
            const selectedDate = isoDateInputToMdy($('tlOtRequestDate').value);
            const shiftResolution = resolveTLOvertimeShiftDate(selectedDate, teamLeaderName);
            const dateStr = shiftResolution.date || selectedDate;
            editingTLOvertimeRequestDate = dateStr;
            const existing = getOTRecord(dateStr, teamLeaderName);
            const status = existing ? String(existing.status || '').toLowerCase() : '';
            setOvertimeDuration('tlOtRequestHours', 'tlOtRequestMinutes', existing ? getStoredOTHoursFromRecord(existing) : null);
            $('tlOtRequestNote').value = existing ? (existing.note || '') : '';
            const identity = $('tlOtRequestIdentity');
            if (identity) identity.textContent = `${agentDisplayName(teamLeaderName)} · ${podDisplayName((existing && existing.pod) || overtimePodForName(teamLeaderName))}`;
            const hint = $('tlOtShiftDateHint');
            const hintMessages = [];
            if (shiftResolution.adjusted) hintMessages.push(shiftResolution.reason);
            if (status === 'pending') hintMessages.push(`An existing pending request for ${dateStr} was found. Saving will update that request instead of creating a duplicate.`);
            if (hint) { hint.textContent = hintMessages.join(' '); hint.style.display = hintMessages.length ? '' : 'none'; }
            const breakdownEl = $('tlOtRequestBreakdown');
            if (breakdownEl) breakdownEl.innerHTML = overtimeBreakdownHtml(overtimeHoursBreakdown(dateStr, teamLeaderName, existing ? getStoredOTHoursFromRecord(existing) : 0));
            const eligibility = $('tlOtRequestEligibility');
            const save = $('tlOtRequestSaveBtn');
            const controls = [$('tlOtRequestHours'), $('tlOtRequestMinutes'), $('tlOtRequestNote'), save];
            let blocked = overtimePayPeriodLockMessage(dateStr) || otBlockedReason(dateStr, teamLeaderName);
            if (status === 'approved') blocked = `Approved overtime already exists for ${dateStr}. Only an Admin can correct or revoke an approved TL overtime record.`;
            if (blocked) {
                eligibility.textContent = blocked;
                eligibility.style.display = '';
                controls.forEach(el => { if (el) el.disabled = true; });
            } else {
                eligibility.style.display = 'none';
                controls.forEach(el => { if (el) el.disabled = false; });
            }
            if (save) save.textContent = status === 'pending' ? 'Update Pending Request' : 'Submit for Admin Review';
        }

        function openTLOvertimeRequestModal(dateStr = todayKeyPart()) {
            if (!isTeamLeader || isAdmin || !teamLeaderName) { showToast('Sign in as a Team Leader to submit your own overtime request.'); return; }
            if (!TrinoPermissions.can('overtime.tl.submit', { name:teamLeaderName, pod:overtimePodForName(teamLeaderName) })) { showToast('Your Team Leader session is not authorized to submit overtime.'); return; }
            $('tlOtRequestDate').value = mdyToIsoDateInput(dateStr || todayKeyPart());
            refreshTLOvertimeRequestModalForDate();
            const overlay = ensureOvertimeChildModalPortal('tlOtRequestOverlay') || $('tlOtRequestOverlay');
            if (overlay) overlay.classList.add('open');
        }

        function closeTLOvertimeRequestModal() {
            $('tlOtRequestOverlay').classList.remove('open');
            editingTLOvertimeRequestDate = '';
        }

        function openTLOvertimeReviewModal(dateStr, name) {
            if (!isAdmin || !TrinoPermissions.can('overtime.tl.review', { name })) { showToast('An authenticated Admin session is required to review TL overtime.'); return; }
            const rec = getOTRecord(dateStr, name);
            if (!rec || rec.status !== 'pending' || !isTeamLeaderOTRecord(name, rec)) { showToast('This request is no longer pending. Refresh Overtime and try again.'); renderOTTab(); return; }
            reviewingTLOvertimeKey = { date:dateStr, name };
            const requested = getStoredOTHoursFromRecord(rec);
            const breakdown = overtimeHoursBreakdown(dateStr, name, requested);
            $('tlOtReviewLeader').textContent = agentDisplayName(name);
            $('tlOtReviewPod').textContent = podDisplayName(rec.pod || overtimePodForName(name));
            $('tlOtReviewDate').textContent = dateStr;
            $('tlOtReviewDuration').textContent = formatOvertimeDuration(requested);
            $('tlOtReviewRegular').textContent = formatOTHoursValue(breakdown.regular);
            $('tlOtReviewProposedTotal').textContent = formatOTHoursValue(breakdown.proposedTotal);
            $('tlOtReviewReason').textContent = rec.note || 'No reason recorded';
            $('tlOtReviewSubmitted').textContent = formatOTSubmissionTime(rec.submittedAt);
            $('tlOtReviewDecisionNote').value = '';
            const blocked = overtimePayPeriodLockMessage(dateStr) || otBlockedReason(dateStr, name);
            const note = $('tlOtReviewEligibility');
            const approve = $('tlOtReviewApproveBtn');
            const reject = $('tlOtReviewRejectBtn');
            if (blocked) {
                note.textContent = blocked;
                note.style.display = '';
                approve.disabled = true;
                reject.disabled = true;
            } else {
                note.style.display = 'none';
                approve.disabled = false;
                reject.disabled = false;
            }
            const overlay = ensureOvertimeChildModalPortal('tlOtReviewOverlay') || $('tlOtReviewOverlay');
            if (overlay) overlay.classList.add('open');
        }

        function closeTLOvertimeReviewModal() {
            $('tlOtReviewOverlay').classList.remove('open');
            reviewingTLOvertimeKey = null;
        }

        function openTLOvertimeCorrectionModal(dateStr, name) {
            if (!isAdmin || !TrinoPermissions.can('admin.authenticated', { name, pod:overtimePodForName(name) })) { showToast('An authenticated Admin session is required to correct approved TL overtime.'); return; }
            const rec = getOTRecord(dateStr, name);
            if (!rec || rec.status !== 'approved' || !isTeamLeaderOTRecord(name, rec)) { showToast('Only an approved Team Leader overtime record can be corrected.'); return; }
            correctingTLOvertimeKey = { date:dateStr, name };
            const current = getStoredOTHoursFromRecord(rec);
            const breakdown = overtimeHoursBreakdown(dateStr, name, current);
            $('tlOtCorrectionLeader').textContent = agentDisplayName(name);
            $('tlOtCorrectionPod').textContent = podDisplayName(rec.pod || overtimePodForName(name));
            $('tlOtCorrectionDate').textContent = dateStr;
            $('tlOtCorrectionRegular').textContent = formatOTHoursValue(breakdown.regular);
            $('tlOtCorrectionCurrent').textContent = formatOvertimeDuration(current);
            $('tlOtCorrectionTotal').textContent = formatOTHoursValue(breakdown.total);
            setOvertimeDuration('tlOtCorrectionHours', 'tlOtCorrectionMinutes', current);
            $('tlOtCorrectionReason').value = '';
            const locked = overtimePayPeriodLockMessage(dateStr);
            const eligibility = $('tlOtCorrectionEligibility');
            const controls = [$('tlOtCorrectionHours'), $('tlOtCorrectionMinutes'), $('tlOtCorrectionReason'), $('tlOtCorrectionSaveBtn'), $('tlOtCorrectionRevokeBtn')];
            if (locked) {
                eligibility.textContent = locked;
                eligibility.style.display = '';
                controls.forEach(el => { if (el) el.disabled = true; });
            } else {
                eligibility.style.display = 'none';
                controls.forEach(el => { if (el) el.disabled = false; });
            }
            const overlay = ensureOvertimeChildModalPortal('tlOtCorrectionOverlay') || $('tlOtCorrectionOverlay');
            if (overlay) overlay.classList.add('open');
        }

        function closeTLOvertimeCorrectionModal() {
            $('tlOtCorrectionOverlay').classList.remove('open');
            correctingTLOvertimeKey = null;
        }

        function totalsEmployeeScope() {
            if (isAdmin) return currentTeamEmployees();
            if (isTeamLeader && lockedPod) return labelerRosterEmployees().filter(e => e.pod === lockedPod);
            if (agentSessionAuthenticated && agentSessionName && currentEmployee === agentSessionName) {
                const employee = employees.find(e => e.name === agentSessionName);
                return employee && canAccessPodForCurrentSession(employee.pod) ? [employee] : [];
            }
            return [];
        }

        const DEFAULT_AGENT_HOURLY_RATE_PHP = 119;

        function getEmployeeHourlyRate(name) {



            if (!canViewFinancialDetailsFor(name)) return null;
            const employee = employees.find(e => e.name === name);
            if (!employee || employee.hourlyRate === '' || employee.hourlyRate == null) return null;
            const rate = Number(employee.hourlyRate);
            return Number.isFinite(rate) && rate >= 0 ? rate : null;
        }

        function formatPayAmount(value) {
            const amount = Number(value);
            if (!Number.isFinite(amount)) return '—';
            return '₱' + amount.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }

        function formatTotalsHours(value) {
            const hours = Number(value);
            return `${(Number.isFinite(hours) ? hours : 0).toFixed(2)}h`;
        }

        async function saveEmployeeHourlyRate(name, nextRate) {



            TrinoPermissions.require('finance.hourly_rate.edit', { name, pod:podOf(name) || '' }, 'An authenticated Admin session is required to edit hourly rates.');
            const employee = employees.find(e => e.name === name);
            if (!employee) throw new Error('Agent not found.');
            const oldRate = getEmployeeHourlyRate(name);
            if (nextRate == null) {
                delete employee.hourlyRate;
                delete employee.hourlyRateCurrency;
            } else {
                const parsed = Number(nextRate);
                if (!Number.isFinite(parsed) || parsed < 0) throw new Error('Hourly rate must be zero or greater.');
                employee.hourlyRate = Math.round(parsed * 100) / 100;
                employee.hourlyRateCurrency = 'PHP';
            }
            const saveResult = await saveEmployees({ awaitRemote:true });
            await logAudit('hourly_rate_update', {
                name,
                pod: employee.pod || podOf(name),
                oldRate,
                newRate: getEmployeeHourlyRate(name),
                editedBy: 'Admin',
                currency: 'PHP'
            });
            publishUpdate();
            return saveResult;
        }





        function renderTotalsTab(options = {}) {
            const wrap = $('totalsListWrap');
            const podFilter = $('totalsPodFilter');
            if (!wrap) return;
            // Attendance refreshes must not destroy an Admin's unsaved rate draft.
            if (options.force !== true && isAdmin &&
                wrap.querySelector('.hourly-rate-input[data-editing="1"], .hourly-rate-input[data-saving="1"]')) return;

            const baseScope = totalsEmployeeScope();
            if (!baseScope.length) {
                if (podFilter) {
                    podFilter.innerHTML = '<option value="">No POD available</option>';
                    podFilter.disabled = true;
                }
                wrap.innerHTML = '<div class="loading-note">Select and verify your Agent name to view your weekly and monthly credited hours.</div>';
                return;
            }

            const podRank = pod => {
                const index = POD_LIST.indexOf(pod);
                return index >= 0 ? index : POD_LIST.length + 100;
            };
            const availablePods = [...new Set(baseScope.map(employee => employee.pod || podOf(employee.name) || 'Unassigned'))]
                .sort((a, b) => (podRank(a) - podRank(b)) || a.localeCompare(b));

            let selectedPod = '';
            if (podFilter) {
                const previous = podFilter.value;
                const canViewAllPods = isAdmin && availablePods.length > 1;
                podFilter.innerHTML = (canViewAllPods ? '<option value="">All PODs</option>' : '') +
                    availablePods.map(pod => `<option value="${escapeHtml(pod)}">${escapeHtml(podDisplayName(pod))}</option>`).join('');
                if (canViewAllPods && (previous === '' || availablePods.includes(previous))) {
                    podFilter.value = previous;
                } else if (availablePods.includes(previous)) {
                    podFilter.value = previous;
                } else {
                    podFilter.value = canViewAllPods ? '' : availablePods[0];
                }
                podFilter.disabled = !isAdmin || availablePods.length <= 1;
                selectedPod = podFilter.value;
            }

            const scope = selectedPod
                ? baseScope.filter(employee => (employee.pod || podOf(employee.name) || 'Unassigned') === selectedPod)
                : baseScope;
            if (!scope.length) {
                wrap.innerHTML = '<div class="loading-note">No labelers match this POD filter.</div>';
                return;
            }



            const showNightDiff = scope.some(employee => nightDiffEnabledForPod(employee.pod || podOf(employee.name)));
            const todayParts = parseDateStr(todayKeyPart());
            const todayDate = new Date(todayParts.y, todayParts.m - 1, todayParts.d);
            const weekStart = getWeekStartDate(todayDate);
            const monthStart = new Date(todayParts.y, todayParts.m - 1, 1);
            const weekTotals = computeAggregatedHours(scope, weekStart);
            const monthTotals = computeAggregatedHours(scope, monthStart);
            const weekNightTotals = showNightDiff ? computeAggregatedNightDiffHours(scope, weekStart) : {};
            const monthNightTotals = showNightDiff ? computeAggregatedNightDiffHours(scope, monthStart) : {};
            const weekNightSources = showNightDiff ? computeAggregatedNightDiffSourceCounts(scope, weekStart) : {};
            const monthNightSources = showNightDiff ? computeAggregatedNightDiffSourceCounts(scope, monthStart) : {};
            const selfView = !isAdmin && !isTeamLeader;

            const grouped = new Map();
            scope.forEach(employee => {
                const pod = employee.pod || podOf(employee.name) || 'Unassigned';
                if (!grouped.has(pod)) grouped.set(pod, []);
                grouped.get(pod).push(employee);
            });

            const orderedGroups = [...grouped.entries()].sort((a, b) =>
                (podRank(a[0]) - podRank(b[0])) || a[0].localeCompare(b[0])
            );

            const renderWeekList = employeesInPod => {
                let entries = employeesInPod.map(employee => [
                    employee.name,
                    Number(weekTotals[employee.name] || 0),
                    showNightDiff ? Number(weekNightTotals[employee.name] || 0) : 0
                ]);
                if (!selfView) entries = entries.filter(([, hours]) => hours > 0);
                entries.sort((a, b) => (b[1] - a[1]) || a[0].localeCompare(b[0]));
                if (!entries.length) return '<li style="color:var(--muted); list-style:none;">— none yet —</li>';
                return entries.map(([name, hrs, ndHrs]) => {
                    const ndSuffix = showNightDiff
                        ? ` · ND ${formatTotalsHours(ndHrs)}${ndHrs > 0 ? ' · ' + escapeHtml(formatNightDiffSourceCounts(weekNightSources[name])) : ''}`
                        : '';
                    return `<li class="status-entry"><div class="status-entry-row"><span class="status-entry-name" title="${escapeHtml(name)}">${escapeHtml(name)}</span><span class="status-entry-time">${formatTotalsHours(hrs)}${ndSuffix}</span></div></li>`;
                }).join('');
            };

            const renderPodGroup = ([pod, podEmployees]) => {
                const sortedEmployees = [...podEmployees].sort((a, b) => {
                    const hoursA = Number(monthTotals[a.name] || 0);
                    const hoursB = Number(monthTotals[b.name] || 0);
                    return (hoursB - hoursA) || a.name.localeCompare(b.name);
                });
                const podWeekHours = sortedEmployees.reduce((sum, employee) => sum + Number(weekTotals[employee.name] || 0), 0);
                const podMonthHours = sortedEmployees.reduce((sum, employee) => sum + Number(monthTotals[employee.name] || 0), 0);
                const podWeekNdHours = showNightDiff ? sortedEmployees.reduce((sum, employee) => sum + Number(weekNightTotals[employee.name] || 0), 0) : 0;
                const podMonthNdHours = showNightDiff ? sortedEmployees.reduce((sum, employee) => sum + Number(monthNightTotals[employee.name] || 0), 0) : 0;
                let podKnownPay = 0;
                let unsetRates = 0;

                const monthlyRows = sortedEmployees.map(employee => {
                    const hours = Number(monthTotals[employee.name] || 0);
                    const ndHours = showNightDiff ? Number(monthNightTotals[employee.name] || 0) : 0;
                    const ndSources = showNightDiff ? formatNightDiffSourceCounts(monthNightSources[employee.name]) : '';
                    const rate = getEmployeeHourlyRate(employee.name);
                    if (rate == null) unsetRates += 1;
                    else podKnownPay += hours * rate;
                    const rateDisplay = rate == null ? '<span class="totals-pay-unset">Not set</span>' : formatPayAmount(rate);
                    const payDisplay = rate == null ? '<span class="totals-pay-unset">—</span>' : formatPayAmount(hours * rate);
                    const rateCell = isAdmin
                        ? `<span class="hourly-rate-field"><span class="hourly-rate-prefix" aria-hidden="true">₱</span><input class="hourly-rate-input" type="text" inputmode="decimal" maxlength="14" autocomplete="off" spellcheck="false" data-name="${escapeHtml(employee.name)}" data-hours="${hours}" value="${rate == null ? '' : rate.toFixed(2)}" placeholder="0.00" aria-label="Hourly rate in Philippine Peso for ${escapeHtml(agentDisplayName(employee.name))}"></span><span class="hourly-rate-actions" hidden><button class="hourly-rate-save" type="button">Save</button><button class="hourly-rate-cancel" type="button">Cancel</button></span><span class="hourly-rate-feedback" role="status" aria-live="polite"></span>`
                        : rateDisplay;
                    const ndCells = showNightDiff
                        ? `<td class="num">${formatTotalsHours(ndHours)}</td><td>${escapeHtml(ndSources)}</td>`
                        : '';
                    return `<tr>
                        <td class="totals-pay-name">${escapeHtml(agentDisplayName(employee.name))}</td>
                        <td class="num">${formatTotalsHours(hours)}</td>
                        ${ndCells}
                        <td class="num">${rateCell}</td>
                        <td class="num totals-pay-value">${payDisplay}</td>
                    </tr>`;
                }).join('');

                const paySummary = unsetRates
                    ? `${formatPayAmount(podKnownPay)} estimated from set rates · ${unsetRates} rate${unsetRates === 1 ? '' : 's'} not set`
                    : `${formatPayAmount(podKnownPay)} estimated pay`;
                const podMonthNd = showNightDiff ? ` · ND ${formatTotalsHours(podMonthNdHours)}` : '';
                const podWeekNd = showNightDiff ? ` · ND ${formatTotalsHours(podWeekNdHours)}` : '';
                const ndHeaders = showNightDiff ? '<th class="num">Night Diff Hours</th><th>ND Sources</th>' : '';
                const ndNote = showNightDiff
                    ? ' Night Diff Hours are tracked separately for the 10:00 PM–6:00 AM PHT window and are not double-counted in Total Hours. ND Sources show how many ND-contributing records came from Actual punches, stamped Schedule fallback, or a Manual override. Total Pay currently remains Total Hours × Hourly Rate; no ND premium percentage is assumed.'
                    : '';

                return `<section class="status-card online totals-pod-group" data-pod="${escapeHtml(pod)}">
                    <div class="totals-pod-head">
                        <span class="totals-pod-title">${escapeHtml(podDisplayName(pod))}</span>
                        <span class="totals-pod-summary">This month ${formatTotalsHours(podMonthHours)}${podMonthNd}</span>
                    </div>
                    <div class="totals-period-grid">
                        <div class="totals-period-block">
                            <h4 class="totals-period-title">📅 THIS WEEK · ${formatTotalsHours(podWeekHours)}${podWeekNd}</h4>
                            <ul>${renderWeekList(sortedEmployees)}</ul>
                        </div>
                        <div class="totals-period-block">
                            <h4 class="totals-period-title">🗓️ THIS MONTH · ${formatTotalsHours(podMonthHours)}</h4>
                            <div class="totals-pay-table-wrap"><table class="totals-pay-table">
                                <thead><tr><th>Labeler</th><th class="num">Total Hours</th>${ndHeaders}<th class="num">Hourly Rate (PHP)</th><th class="num">Total Pay (PHP)</th></tr></thead>
                                <tbody>${monthlyRows}</tbody>
                            </table></div>
                            <p class="totals-pay-note">${paySummary}.${ndNote}${isAdmin ? ' Edit a ₱ hourly rate and press Enter or leave the field to save.' : ''}</p>
                        </div>
                    </div>
                </section>`;
            };

            const totalWeekHours = Object.values(weekTotals).reduce((a, b) => a + b, 0);
            const totalMonthHours = Object.values(monthTotals).reduce((a, b) => a + b, 0);
            const totalWeekNdHours = showNightDiff ? Object.values(weekNightTotals).reduce((a, b) => a + b, 0) : 0;
            const totalMonthNdHours = showNightDiff ? Object.values(monthNightTotals).reduce((a, b) => a + b, 0) : 0;
            const overallNd = showNightDiff
                ? ` · ND ${formatTotalsHours(totalWeekNdHours)} · This month ${formatTotalsHours(totalMonthHours)} · ND ${formatTotalsHours(totalMonthNdHours)}`
                : ` · This month ${formatTotalsHours(totalMonthHours)}`;
            wrap.innerHTML =
                `<div class="totals-overall-summary">${selectedPod ? escapeHtml(podDisplayName(selectedPod)) : 'All PODs'} · This week ${formatTotalsHours(totalWeekHours)}${overallNd} · PHP (₱)</div>` +
                orderedGroups.map(renderPodGroup).join('');



            if (isAdmin) {
                wrap.querySelectorAll('.hourly-rate-input').forEach(input => {
                    const row = input.closest('tr');
                    const payCell = row && row.querySelector('.totals-pay-value');
                    const actions = row && row.querySelector('.hourly-rate-actions');
                    const saveButton = row && row.querySelector('.hourly-rate-save');
                    const cancelButton = row && row.querySelector('.hourly-rate-cancel');
                    const feedback = row && row.querySelector('.hourly-rate-feedback');
                    const employeeName = input.dataset.name;
                    const hours = Number(input.dataset.hours || 0);
                    const savedValue = () => {
                        const rate = getEmployeeHourlyRate(employeeName);
                        return rate == null ? '' : rate.toFixed(2);
                    };
                    const showActions = open => {
                        if (actions) actions.hidden = !open;
                        input.dataset.editing = open ? '1' : '';
                        if (row) row.classList.toggle('rate-is-editing', open);
                    };
                    const preview = () => {
                        if (!payCell) return;
                        const raw = input.value.trim();
                        const rate = Number(raw);
                        const valid = raw === '' || (/^\d+(?:\.\d{0,2})?$/.test(raw) && Number.isFinite(rate));
                        input.setAttribute('aria-invalid', valid ? 'false' : 'true');
                        if (feedback) feedback.textContent = valid ? '' : 'Enter a valid peso amount (up to 2 decimals).';
                        payCell.textContent = valid ? formatPayAmount(hours * (raw === '' ? DEFAULT_AGENT_HOURLY_RATE_PHP : rate)) : '—';
                        return valid;
                    };
                    const cancel = () => {
                        if (input.dataset.saving === '1') return;
                        input.value = savedValue();
                        showActions(false);
                        preview();
                        if (feedback) feedback.textContent = '';
                    };
                    const commit = async () => {
                        if (input.dataset.saving === '1') return;
                        const raw = input.value.trim();
                        if (!preview()) { showToast('Enter a valid hourly rate (e.g. 120.00).'); input.focus(); return; }
                        const nextRate = raw === '' ? null : Number(raw);
                        const currentRate = getEmployeeHourlyRate(employeeName);
                        const effectiveRate = nextRate == null ? DEFAULT_AGENT_HOURLY_RATE_PHP : nextRate;
                        if (currentRate != null && Math.abs(currentRate - effectiveRate) < 0.005 &&
                            !(nextRate == null && employees.some(e => e.name === employeeName && e.hourlyRate != null))) {
                            cancel();
                            return;
                        }
                        input.dataset.saving = '1';
                        input.disabled = true;
                        if (saveButton) { saveButton.disabled = true; saveButton.textContent = 'Saving…'; }
                        if (cancelButton) cancelButton.disabled = true;
                        if (feedback) feedback.textContent = 'Saving hourly rate…';
                        try {
                            const result = await saveEmployeeHourlyRate(employeeName, nextRate);
                            // A queued/local save is NOT a confirmed Firebase write.
                            const confirmed = Boolean(result && result.remoteSaved);
                            const message = nextRate == null
                                ? `Hourly rate reset to ₱${DEFAULT_AGENT_HOURLY_RATE_PHP} default for ${agentDisplayName(employeeName)}.`
                                : `Hourly rate for ${agentDisplayName(employeeName)}: ${formatPayAmount(nextRate)}/hr.`;
                            showToast(confirmed ? `${message} Saved to server.` : `${message} Queued for sync; server confirmation pending.`, 5200);
                            // Recompute POD pay summaries only after an explicit save.
                            const scrollTop = wrap.scrollTop;
                            const tableWraps = Array.from(wrap.querySelectorAll('.totals-pay-table-wrap')).map(el => ({pod:el.closest('.totals-pod-group')?.dataset.pod, left:el.scrollLeft}));
                            showActions(false);
                            renderTotalsTab({force:true});
                            wrap.scrollTop = scrollTop;
                            tableWraps.forEach(item => {
                                const box = Array.from(wrap.querySelectorAll('.totals-pod-group')).find(el => el.dataset.pod === item.pod)?.querySelector('.totals-pay-table-wrap');
                                if (box) box.scrollLeft = item.left;
                            });
                        } catch (error) {
                            reportAppError('Save hourly rate', error);
                            if (feedback) feedback.textContent = 'Could not save. Check Admin access and try again.';
                            showToast('Hourly rate could not be saved: ' + getErrorMessage(error), 6000);
                        } finally {
                            if (input.isConnected) {
                                input.dataset.saving = '';
                                input.disabled = false;
                                if (saveButton) { saveButton.disabled = false; saveButton.textContent = 'Save'; }
                                if (cancelButton) cancelButton.disabled = false;
                            }
                        }
                    };
                    input.addEventListener('focus', () => {
                        showActions(true);
                        // Select the full amount so typing 120 replaces 119.00.
                        input.select();
                    });
                    input.addEventListener('input', () => { showActions(true); preview(); });
                    input.addEventListener('keydown', event => {
                        if (event.key === 'Enter') { event.preventDefault(); void commit(); }
                        if (event.key === 'Escape') { event.preventDefault(); cancel(); input.blur(); }
                    });
                    // No change/blur autosave: a partial edit must never overwrite a pay rate.
                    if (saveButton) saveButton.addEventListener('click', () => { void commit(); });
                    if (cancelButton) cancelButton.addEventListener('click', cancel);
                });
            }
        }








        let previewingNoteKey = null;
        let editingNoteKey = null;

        function normalizeDailyNoteText(value) {
            return String(value == null ? '' : value).replace(/\r\n?/g, '\n').trim().slice(0, 2000);
        }

        function dailyNoteActorLabel() {
            if (isAdmin) return 'Admin';
            if (isTeamLeader) return teamLeaderName || 'Team Leader';
            return currentEmployee || 'Agent';
        }

        function dailyNotePod(name, dateStr, rec) {
            return (rec && rec.pod) || podOf(name) ||
                (activePod !== ALL_PODS_LABEL ? activePod : null) || 'Unassigned';
        }

        function canEditDailyNote(name, pod) {
            if (!name) return false;
            const resolvedPod = pod || currentRosterPodForName(name) || podOf(name) || '';
            return TrinoPermissions.can('attendance.note.edit', { name, pod:resolvedPod });
        }

        function noteHistoryRowVisible(row) {
            const recordPod = row.pod || currentRosterPodForName(row.name) || podOf(row.name) || '';
            if (isAdmin) return teamIdForPod(recordPod) === activeTeam && (activePod === ALL_PODS_LABEL || recordPod === activePod);
            if (isTeamLeader) return teamLeaderCanAccessPod(recordPod);
            const currentPod = currentRosterPodForName(row.name) || recordPod;
            return Boolean(agentSessionAuthenticated && agentSessionName === row.name && currentEmployee === row.name && canAccessPodForCurrentSession(currentPod));
        }

        function dailyNoteRecordHasOtherData(rec) {
            const ignored = new Set(['pod', 'note', 'noteCreatedAt', 'noteUpdatedAt', 'noteUpdatedBy']);
            return Object.entries(rec || {}).some(([key, value]) =>
                !ignored.has(key) && value !== undefined && value !== null && value !== '');
        }

        function dailyNoteOnlyRecord(rec, name, dateStr) {
            const note = normalizeDailyNoteText(rec && rec.note);
            if (!note) return null;
            const result = { note };
            const pod = dailyNotePod(name, dateStr, rec || {});
            if (pod && pod !== 'Unassigned') result.pod = pod;
            if (rec && rec.noteCreatedAt) result.noteCreatedAt = rec.noteCreatedAt;
            if (rec && rec.noteUpdatedAt) result.noteUpdatedAt = rec.noteUpdatedAt;
            if (rec && rec.noteUpdatedBy) result.noteUpdatedBy = rec.noteUpdatedBy;
            return result;
        }

        function formatDailyNoteDateHeading(dateStr) {
            try {
                const { y, m, d } = parseDateStr(dateStr);
                return new Date(y, m - 1, d, 12).toLocaleDateString('en-US', {
                    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
                });
            } catch (e) {
                return dateStr;
            }
        }

        function formatDailyNoteUpdatedAt(value) {
            if (!value) return '';
            try {
                return new Date(value).toLocaleString('en-US', {
                    timeZone: 'Asia/Manila', month: 'short', day: 'numeric', year: 'numeric',
                    hour: 'numeric', minute: '2-digit'
                });
            } catch (e) {
                return '';
            }
        }

        function getAllDailyNoteRows() {
            const rows = [];
            Object.entries(allRecords).forEach(([key, rec]) => {
                const idx = key.indexOf('|');
                if (idx <= 0 || !rec) return;
                const date = key.slice(0, idx);
                const name = key.slice(idx + 1);
                const note = normalizeDailyNoteText(rec.note);
                if (!note) return;
                const row = {
                    date,
                    name,
                    pod: dailyNotePod(name, date, rec),
                    note,
                    noteCreatedAt: rec.noteCreatedAt || '',
                    noteUpdatedAt: rec.noteUpdatedAt || '',
                    noteUpdatedBy: rec.noteUpdatedBy || ''
                };
                if (noteHistoryRowVisible(row)) rows.push(row);
            });
            rows.sort((a, b) => {
                const dateDiff = dateStrToComparable(b.date) - dateStrToComparable(a.date);
                return dateDiff || a.name.localeCompare(b.name);
            });
            return rows;
        }

        function populateNoteHistoryEmployeeFilter(rows) {
            const sel = $('noteHistoryEmpFilter');
            if (!sel) return;
            const previous = sel.value;
            if (!isAdmin && !isTeamLeader) {
                if (currentEmployee) {
                    sel.innerHTML = `<option value="${escapeHtml(currentEmployee)}">${escapeHtml(agentDisplayName(currentEmployee))}</option>`;
                    sel.value = currentEmployee;
                } else {
                    sel.innerHTML = '<option value="">Select your name first</option>';
                }
                sel.disabled = true;
                return;
            }

            sel.disabled = false;
            const names = Array.from(new Set(rows.map(row => row.name))).sort((a, b) => a.localeCompare(b));
            sel.innerHTML = '<option value="">All Agents</option>' + names.map(name =>
                `<option value="${escapeHtml(name)}">${escapeHtml(agentDisplayName(name))}</option>`).join('');
            sel.value = names.includes(previous) ? previous : '';
        }

        function updateNoteHistoryScopeHint() {
            const hint = $('noteHistoryScopeHint');
            if (!hint) return;
            if (isAdmin) {
                hint.textContent = activePod === ALL_PODS_LABEL ?
                    `Daily notes across all ${teamGroupById(activeTeam).fullName} pods, newest first.` :
                    `Daily notes for ${podContextLabel(activePod)}, newest first.`;
            } else if (isTeamLeader) {
                hint.textContent = `Daily notes for ${lockedPod || activePod}, newest first.`;
            } else if (currentEmployee) {
                hint.textContent = `${agentDisplayName(currentEmployee)}'s daily notes, newest first.`;
            } else {
                hint.textContent = 'Select your name above to view and manage your daily notes.';
            }
        }

        function renderNoteHistory() {
            const list = $('noteHistoryList');
            const summary = $('noteHistorySummary');
            const search = $('noteHistorySearch');
            const filter = $('noteHistoryEmpFilter');
            if (!list || !summary || !search || !filter) return;

            updateNoteHistoryScopeHint();
            const allRows = getAllDailyNoteRows();
            populateNoteHistoryEmployeeFilter(allRows);

            if (!isAdmin && !isTeamLeader && !currentEmployee) {
                summary.textContent = 'No Agent selected.';
                list.innerHTML = '<div class="note-history-empty">Select your name in the Agent search above, then reopen Note History.</div>';
                return;
            }

            const selectedEmployee = filter.value;
            const query = search.value.trim().toLowerCase();
            const rows = allRows.filter(row => {
                if (selectedEmployee && row.name !== selectedEmployee) return false;
                if (!query) return true;
                const searchable = [
                    row.note, row.name, row.pod, row.date, formatDailyNoteDateHeading(row.date),
                    row.noteUpdatedBy, formatDailyNoteUpdatedAt(row.noteUpdatedAt)
                ].join(' ').toLowerCase();
                return searchable.includes(query);
            });

            const dayCount = new Set(rows.map(row => row.date)).size;
            summary.textContent = `${rows.length} ${rows.length === 1 ? 'note' : 'notes'} across ${dayCount} ${dayCount === 1 ? 'day' : 'days'}.`;

            if (!rows.length) {
                list.innerHTML = query || selectedEmployee ?
                    '<div class="note-history-empty">No notes match the current search or Agent filter.</div>' :
                    '<div class="note-history-empty">No saved notes yet. Use <b>+ New Note</b> to add the first dated note.</div>';
                return;
            }

            const grouped = [];
            rows.forEach(row => {
                let group = grouped[grouped.length - 1];
                if (!group || group.date !== row.date) {
                    group = { date: row.date, rows: [] };
                    grouped.push(group);
                }
                group.rows.push(row);
            });

            list.innerHTML = grouped.map(group => {
                const cards = group.rows.map(row => {
                    const updatedAt = formatDailyNoteUpdatedAt(row.noteUpdatedAt);
                    const updateBits = [];
                    if (updatedAt) updateBits.push(`Updated ${updatedAt}`);
                    if (row.noteUpdatedBy) updateBits.push(`by ${row.noteUpdatedBy}`);
                    const meta = [row.pod, ...updateBits].filter(Boolean).join(' \u00b7 ');
                    const viewButton = `<button class="note-history-view" type="button" data-date="${escapeHtml(row.date)}" data-name="${escapeHtml(row.name)}">View</button>`;
                    const editButton = canEditDailyNote(row.name, row.pod) ?
                        `<button class="note-history-edit" type="button" data-date="${escapeHtml(row.date)}" data-name="${escapeHtml(row.name)}">Edit</button>` : '';
                    return `<article class="note-history-card">
                        <div class="note-history-card-head">
                            <div class="note-history-person">
                                <span class="note-history-name">${escapeHtml(agentDisplayName(row.name))}</span>
                                <span class="note-history-meta">${escapeHtml(meta || row.pod)}</span>
                            </div>
                            <div class="note-history-actions">${viewButton}${editButton}</div>
                        </div>
                        <div class="note-history-body">${escapeHtml(row.note)}</div>
                    </article>`;
                }).join('');
                return `<section class="note-date-group">
                    <div class="note-date-heading">
                        <span>${escapeHtml(formatDailyNoteDateHeading(group.date))}</span>
                        <span class="note-date-count">${group.rows.length} ${group.rows.length === 1 ? 'note' : 'notes'} \u00b7 ${escapeHtml(group.date)}</span>
                    </div>
                    ${cards}
                </section>`;
            }).join('');

            list.querySelectorAll('.note-history-view').forEach(btn => {
                btn.addEventListener('click', () => openNotePreview(btn.dataset.name, btn.dataset.date));
            });
            list.querySelectorAll('.note-history-edit').forEach(btn => {
                btn.addEventListener('click', () => openDailyNoteEditor(btn.dataset.date, btn.dataset.name));
            });
        }

        function noteEditorScopedEmployees(preselect, dateStr) {
            let scope;
            if (isAdmin) {
                const teamScope = currentTeamEmployees();
                scope = activePod === ALL_PODS_LABEL ? teamScope : teamScope.filter(e => e.pod === activePod);
            } else if (isTeamLeader) {
                scope = lockedPod ? labelerRosterEmployees().filter(e => e.pod === lockedPod) : [];
            } else {
                scope = currentEmployee ? employees.filter(e => e.name === currentEmployee) : [];
            }
            scope = scope.map(e => ({ name: e.name, pod: e.pod }));

            if (preselect && !scope.some(e => e.name === preselect)) {
                const rec = allRecords[dateStr + '|' + preselect] || {};
                const pod = dailyNotePod(preselect, dateStr, rec);
                if (canEditDailyNote(preselect, pod)) scope.push({ name: preselect, pod });
            }

            const seen = new Set();
            return scope.filter(e => {
                const key = e.name.toLowerCase();
                if (seen.has(key)) return false;
                seen.add(key);
                return true;
            }).sort((a, b) => a.name.localeCompare(b.name));
        }

        function populateDailyNoteEmployeeSelect(preselect, dateStr) {
            const sel = $('noteEditorEmpSelect');
            if (!sel) return false;
            const scope = noteEditorScopedEmployees(preselect, dateStr);
            if (!scope.length) {
                sel.innerHTML = '<option value="">No Agent available</option>';
                sel.disabled = true;
                return false;
            }
            sel.innerHTML = scope.map(e =>
                `<option value="${escapeHtml(e.name)}">${escapeHtml(agentDisplayName(e.name))} (${escapeHtml(e.pod)})</option>`).join('');
            if (preselect && scope.some(e => e.name === preselect)) sel.value = preselect;
            sel.disabled = !isAdmin && !isTeamLeader;
            return true;
        }

        function updateDailyNoteCounter() {
            const input = $('noteEditorText');
            const counter = $('noteEditorCounter');
            if (input && counter) counter.textContent = `${input.value.length} / 2000`;
        }

        function refreshDailyNoteEditorSelection() {
            const sel = $('noteEditorEmpSelect');
            const dateInput = $('noteEditorDate');
            editingNoteKey = null;
            if (!sel || !dateInput || !sel.value || !dateInput.value) {
                if ($('noteEditorSaveBtn')) $('noteEditorSaveBtn').disabled = true;
                if ($('noteEditorDeleteBtn')) $('noteEditorDeleteBtn').style.display = 'none';
                return;
            }
            const dateStr = isoDateInputToMdy(dateInput.value);
            const name = sel.value;
            const rec = allRecords[dateStr + '|' + name] || {};
            const pod = dailyNotePod(name, dateStr, rec);
            if (!canEditDailyNote(name, pod)) {
                $('noteEditorError').textContent = 'You do not have permission to edit this note.';
                $('noteEditorError').style.display = 'block';
                $('noteEditorSaveBtn').disabled = true;
                $('noteEditorDeleteBtn').style.display = 'none';
                return;
            }

            editingNoteKey = { date: dateStr, name };
            $('noteEditorText').value = rec.note || '';
            $('noteEditorDeleteBtn').style.display = normalizeDailyNoteText(rec.note) ? '' : 'none';
            $('noteEditorSub').textContent = `${name} \u00b7 ${formatDailyNoteDateHeading(dateStr)} \u2014 one note for this day.`;
            $('noteEditorError').style.display = 'none';
            $('noteEditorSaveBtn').disabled = false;
            updateDailyNoteCounter();
        }

        function openDailyNoteEditor(dateStr, name) {
            const resolvedDate = dateStr || todayKeyPart();
            let resolvedName = name || ($('noteHistoryEmpFilter') && $('noteHistoryEmpFilter').value) || currentEmployee;
            if (!resolvedName && (isAdmin || isTeamLeader)) {
                const scope = noteEditorScopedEmployees(null, resolvedDate);
                resolvedName = scope[0] ? scope[0].name : null;
            }
            if (!resolvedName) {
                showToast('Select your name before adding a note.');
                return;
            }

            const rec = allRecords[resolvedDate + '|' + resolvedName] || {};
            const pod = dailyNotePod(resolvedName, resolvedDate, rec);
            if (!canEditDailyNote(resolvedName, pod)) {
                showToast('You can only edit your own notes.');
                return;
            }

            const dateInput = $('noteEditorDate');
            dateInput.max = mdyToIsoDateInput(todayKeyPart());
            dateInput.value = mdyToIsoDateInput(resolvedDate);
            if (!populateDailyNoteEmployeeSelect(resolvedName, resolvedDate)) {
                showToast('No Agent is available for this note.');
                return;
            }
            refreshDailyNoteEditorSelection();
            $('noteEditorOverlay').classList.add('open');
            setTimeout(() => $('noteEditorText').focus(), 0);
        }

        function closeDailyNoteEditor() {
            $('noteEditorOverlay').classList.remove('open');
            editingNoteKey = null;
            $('noteEditorError').style.display = 'none';
        }

        async function saveDailyNote(dateStr, name, value) {
            const note = normalizeDailyNoteText(value);
            if (!note) throw new Error('Write a note before saving.');
            if (dateStrToComparable(dateStr) > dateStrToComparable(todayKeyPart())) {
                throw new Error('Notes cannot be saved for a future date.');
            }
            const key = dateStr + '|' + name;
            const existing = allRecords[key] || {};
            const pod = dailyNotePod(name, dateStr, existing);
            if (!canEditDailyNote(name, pod)) throw new Error('You do not have permission to edit this note.');

            const previous = normalizeDailyNoteText(existing.note);
            const timestamp = nowIso();
            const next = {
                ...existing,
                note,
                noteCreatedAt: existing.noteCreatedAt || existing.noteUpdatedAt || timestamp,
                noteUpdatedAt: timestamp,
                noteUpdatedBy: dailyNoteActorLabel()
            };
            if (pod && pod !== 'Unassigned') next.pod = pod;
            await saveRecord(dateStr, name, next);
            await logAudit(previous ? 'note_edit' : 'note_add', {
                date: dateStr,
                name,
                pod,
                old: { note: previous },
                new: { note }
            });
        }

        async function deleteDailyNote(dateStr, name) {
            const key = dateStr + '|' + name;
            const existing = allRecords[key] || null;
            if (!existing || !normalizeDailyNoteText(existing.note)) return false;
            const pod = dailyNotePod(name, dateStr, existing);
            if (!canEditDailyNote(name, pod)) throw new Error('You do not have permission to delete this note.');

            const previous = normalizeDailyNoteText(existing.note);
            const next = { ...existing };
            delete next.note;
            delete next.noteCreatedAt;
            delete next.noteUpdatedAt;
            delete next.noteUpdatedBy;

            if (dailyNoteRecordHasOtherData(next)) {
                await saveRecord(dateStr, name, next);
            } else {
                const storageKey = recKey(dateStr, name);
                const deleteMeta = prepareVersionedDelete(storageKey, existing, { label:`daily note for ${name} on ${dateStr}` });
                delete allRecords[key];
                queueVersionedDelete(storageKey, deleteMeta);
                const result = await commitVersionedDelete(storageKey, deleteMeta);
                if (result && result.conflict) throw new Error('This note changed on another device. The newer server version was kept instead of deleting it.');
                if (!result || !result.remoteDeleted) schedulePendingSyncRetry();
            }
            await logAudit('note_delete', { date: dateStr, name, pod, old: { note: previous }, new: { note: '' } });
            return true;
        }

        function refreshDailyNoteViews() {
            renderTable();
            if (isOverlayOpen($('todayStatusOverlay'))) renderTodayStatus();
            if (isOverlayOpen($('historyOverlay'))) renderHistoryCalendar();
            if (isOverlayOpen($('noteHistoryOverlay'))) renderNoteHistory();
        }

        function openNotePreview(name, dateStr) {
            const rec = allRecords[dateStr + '|' + name] || {};
            const note = normalizeDailyNoteText(rec.note);
            if (!note) {
                showToast('This note is no longer available.');
                return;
            }
            const pod = dailyNotePod(name, dateStr, rec);
            previewingNoteKey = { date: dateStr, name };
            $('notePreviewSub').textContent = `${name} \u00b7 ${formatDailyNoteDateHeading(dateStr)}`;
            $('notePreviewText').textContent = note;
            $('notePreviewEditBtn').style.display = canEditDailyNote(name, pod) ? '' : 'none';
            $('notePreviewOverlay').classList.add('open');
        }

        function closeNotePreview() {
            $('notePreviewOverlay').classList.remove('open');
            previewingNoteKey = null;
        }




        let editingNameFor = null;

        function openEditNameModal(name) {


            if (!TrinoPermissions.can('agent.rename', { name, pod:podOf(name) || '' })) {
                showToast(isTeamLeader ? 'Team Leaders can only manage agents in their assigned POD.' : 'You can only edit your own name.');
                return;
            }
            editingNameFor = name;
            $('editNameSub').textContent = `Currently: ${name}`;
            $('editNameInput').value = name;
            $('editNameError').style.display = 'none';
            $('editNameDeleteBtn').style.display = (isAdmin || isTeamLeader) ? '' : 'none';
            $('editNameOverlay').classList.add('open');
            $('editNameInput').focus();
        }

        function closeEditNameModal() {
            $('editNameOverlay').classList.remove('open');
            editingNameFor = null;
        }

        async function performRename(oldName, newName) {
            oldName = String(oldName || '').trim();
            newName = String(newName || '').trim();
            if (!oldName) throw new Error('The Agent being renamed is missing.');
            if (!newName) throw new Error('Name cannot be empty.');
            if (newName.length > 60) throw new Error('Names are limited to 60 characters.');
            const target = employees.find(e => e.name === oldName);
            const targetPod = target ? target.pod : podOf(oldName);
            if (!target) throw new Error('The Agent being renamed is no longer in the active roster.');
            TrinoPermissions.require('agent.rename', { name:oldName, pod:targetPod || '' },
                isTeamLeader ? 'Team Leaders can only rename agents in their assigned POD.' : 'You can only rename your own profile.');
            const oldNameLower = oldName.toLowerCase();
            const newNameLower = newName.toLowerCase();
            const duplicate = employees.find(e => e.name !== oldName && e.name.toLowerCase() === newNameLower);
            if (duplicate) throw new Error(`${duplicate.name} already exists in ${duplicate.pod}.`);
            const keyName = key => {
                const idx = String(key).indexOf('|');
                return idx >= 0 ? String(key).slice(idx + 1) : '';
            };
            const historicalConflict = [...Object.keys(allRecords), ...Object.keys(allOT)].some(key => {
                const storedName = keyName(key).toLowerCase();
                return storedName === newNameLower && storedName !== oldNameLower;
            });
            if (historicalConflict) {
                throw new Error(`Historical records already use the name ${newName}. Choose a distinct display name to avoid merging two people.`);
            }


            const affectedKeys = Object.keys(allRecords).filter(k => keyName(k).toLowerCase() === oldNameLower);
            for (const key of affectedKeys) {
                const idx = key.indexOf('|');
                const dateStr = key.slice(0, idx);
                const rec = allRecords[key];
                await appStorage.set(recKey(dateStr, newName), JSON.stringify(rec));
                await appStorage.delete(recKey(dateStr, oldName));
                delete allRecords[key];
                allRecords[dateStr + '|' + newName] = rec;
            }



            const affectedOTKeys = Object.keys(allOT).filter(k => keyName(k).toLowerCase() === oldNameLower);
            for (const key of affectedOTKeys) {
                const idx = key.indexOf('|');
                const dateStr = key.slice(0, idx);
                const ot = allOT[key];
                await appStorage.set(otRecKey(dateStr, newName), JSON.stringify(ot));
                await appStorage.delete(otRecKey(dateStr, oldName));
                delete allOT[key];
                allOT[dateStr + '|' + newName] = ot;
            }


            for (const swap of Object.values(allDayOffSwaps)) {
                if (!swap) continue;
                let changed = false;
                if (swap.offAgent === oldName) { swap.offAgent = newName; changed = true; }
                if (swap.workAgent === oldName) { swap.workAgent = newName; changed = true; }
                if (changed) await saveDayOffSwap(swap);
            }
            for (const item of Object.values(allShiftOverrides)) {
                if (!item || item.name !== oldName) continue;
                item.name = newName;
                await saveShiftOverride(item);
            }
            for (const request of Object.values(allLeaveRequests)) {
                if (!request || request.agentName !== oldName) continue;
                request.agentName = newName;
                request.agentId = agentAuthId(newName);
                request.pod = targetPod;
                request.team = teamIdForPod(targetPod);
                request.updatedAt = nowIso();
                await saveLeaveRequest(request);
            }



            const oldLast = getEmployeeLastName(oldName);
            const newLast = getEmployeeLastName(newName);
            let scheduleChanged = false;
            const oldLastLower = oldLast.toLowerCase();
            const sameSurnamePeer = employees.some(e => e.name !== oldName && e.pod === targetPod &&
                getEmployeeLastName(e.name).toLowerCase() === oldLastLower);
            if (oldLast && newLast && oldLastLower !== newLast.toLowerCase() && !sameSurnamePeer) {
                const data = dayOffSchedule[targetPod];
                if (data) {
                    const rowSets = [data.rows, data.extraRows].filter(Array.isArray);
                    rowSets.forEach(rows => rows.forEach(row => {
                        if (!Array.isArray(row)) return;
                        row.forEach((cell, index) => {
                            if (String(cell || '').trim().toLowerCase() === oldLastLower) {
                                row[index] = newLast;
                                scheduleChanged = true;
                            }
                        });
                    }));
                }
                if (scheduleChanged) await saveDayOffSchedule();
            }



            const announcements = await getAnnouncements();
            let announcementsChanged = false;
            const mentionPattern = new RegExp('@' + escapeRegExp(oldName) + '(?![A-Za-z0-9_])', 'gi');
            const oldTlSenderKey = 'tl:' + oldName.trim().toLowerCase();
            const newTlSenderKey = 'tl:' + newName.trim().toLowerCase();
            announcements.forEach(a => {
                if (!a) return;
                if (Array.isArray(a.mentions)) {
                    const nextMentions = a.mentions.map(name => String(name).toLowerCase() === oldName.toLowerCase() ? newName : name);
                    if (nextMentions.some((name, i) => name !== a.mentions[i])) {
                        a.mentions = Array.from(new Set(nextMentions));
                        if (isPrivateAnnouncement(a)) a.recipientCount = a.mentions.length;
                        announcementsChanged = true;
                    }
                }
                if (mentionPattern.test(String(a.message || ''))) {
                    mentionPattern.lastIndex = 0;
                    a.message = String(a.message || '').replace(mentionPattern, '@' + newName);
                    announcementsChanged = true;
                }
                mentionPattern.lastIndex = 0;
                if (String(a.author || '').toLowerCase() === oldName.toLowerCase()) {
                    a.author = newName;
                    announcementsChanged = true;
                }
                if (String(a.senderKey || '').toLowerCase() === oldTlSenderKey) {
                    a.senderKey = newTlSenderKey;
                    announcementsChanged = true;
                }
            });
            if (announcementsChanged) {
                cachedAnnouncements = announcements;
                await saveBlobWithBackup('announcements', JSON.stringify(announcements));
            }




            try {
                const oldAuthKey = agentAuthStorageKey(oldName);
                const newAuthKey = agentAuthStorageKey(newName);
                const rawAuth = await appStorage.get(oldAuthKey);
                if (rawAuth) {
                    let authPayload = String(rawAuth);
                    try {
                        const parsedAuth = JSON.parse(authPayload);
                        if (parsedAuth && typeof parsedAuth === 'object') {
                            parsedAuth.agentName = newName;
                            authPayload = JSON.stringify(parsedAuth);
                        }
                    } catch (e) {}
                    await saveBlobWithBackup(newAuthKey, authPayload);
                    if (oldAuthKey !== newAuthKey) await appStorage.delete(oldAuthKey);
                }
            } catch (e) { reportAppError('Migrate agent password on rename', e); }

            try {
                const oldProfileKey = profileStorageKey(oldName);
                const newProfileKey = profileStorageKey(newName);
                const rawProfile = await appStorage.get(oldProfileKey);
                if (rawProfile) {
                    const parsedProfile = JSON.parse(String(rawProfile));
                    if (parsedProfile && typeof parsedProfile === 'object') {
                        parsedProfile.agentName = newName;
                        parsedProfile.pod = targetPod || parsedProfile.pod || '';
                        parsedProfile.updatedAt = typeof nowIso === 'function' ? nowIso() : new Date().toISOString();
                        const nextProfileRaw = JSON.stringify(parsedProfile);
                        await saveBlobWithBackup(newProfileKey, nextProfileRaw);
                        if (oldProfileKey !== newProfileKey) await appStorage.delete(oldProfileKey);
                        delete allAgentProfiles[profileIdForAgent(oldName)];
                        allAgentProfiles[profileIdForAgent(newName)] = parsedProfile;
                    }
                }
            } catch (e) { reportAppError('Migrate public profile on rename', e); }


            target.name = newName;
            const rosterSaveResult = await saveEmployees({ awaitRemote:true });


            if (currentEmployee === oldName) currentEmployee = newName;
            if (agentSessionName === oldName) {
                agentSessionName = newName;
                agentSessionPod = targetPod || agentSessionPod;
                syncAgentSessionLockUi();
            }
            if (typeof profileSelectedAgent !== 'undefined' && profileSelectedAgent === oldName) profileSelectedAgent = newName;
            if (teamLeaderName === oldName) teamLeaderName = newName;
            if (historyEmpName === oldName) historyEmpName = newName;
            try {
                if (localStorage.getItem('lastEmployee') === oldName) localStorage.setItem('lastEmployee', newName);
                const oldSeenKey = ANNOUNCE_SEEN_KEY + ':agent:' + oldName.trim().toLowerCase();
                const newSeenKey = ANNOUNCE_SEEN_KEY + ':agent:' + newName.trim().toLowerCase();
                const seenTs = localStorage.getItem(oldSeenKey);
                if (seenTs && !localStorage.getItem(newSeenKey)) localStorage.setItem(newSeenKey, seenTs);
                if (oldSeenKey !== newSeenKey) localStorage.removeItem(oldSeenKey);
                const oldTlSeenKey = ANNOUNCE_SEEN_KEY + ':' + oldTlSenderKey;
                const newTlSeenKey = ANNOUNCE_SEEN_KEY + ':' + newTlSenderKey;
                const tlSeenTs = localStorage.getItem(oldTlSeenKey);
                if (tlSeenTs && !localStorage.getItem(newTlSeenKey)) localStorage.setItem(newTlSeenKey, tlSeenTs);
                if (oldTlSeenKey !== newTlSeenKey) localStorage.removeItem(oldTlSeenKey);
            } catch (e) {}

            await logAudit('rename', {
                name: newName,
                pod: targetPod,
                old: { name: oldName },
                new: { name: newName },
                rosterSync: rosterSaveResult && rosterSaveResult.remoteSaved ? 'server_confirmed' : 'queued_offline'
            });
            publishUpdate();
            refreshRosterDependentViews();
            return { syncPending: !(rosterSaveResult && rosterSaveResult.remoteSaved) };
        }

        function refreshRosterDependentViews() {
            renderTeamTabs();
            renderPodTabs();
            populateEmployeeSelects();
            refreshPunchCard();
            if (isPanelVisible($('desktopTableContainer')) || isPanelVisible($('mobileCards'))) renderTable();
            renderTodayStatus();
            if (typeof updateNotifBadge === 'function') updateNotifBadge();
            if (typeof refreshSpeedTestReminder === 'function') refreshSpeedTestReminder();
            if (typeof scheduleAgentSecurityPanelRender === 'function') scheduleAgentSecurityPanelRender();
            if (isOverlayOpen($('rosterOverlay'))) renderRosterTab();
            if (isOverlayOpen($('moveAgentsOverlay'))) renderMoveAgentsTab();
            if (isOverlayOpen($('historyOverlay'))) renderHistoryCalendar();
            if (isOverlayOpen($('noteHistoryOverlay'))) renderNoteHistory();
            if (isOverlayOpen($('otTabOverlay'))) renderOTTab();
            if (isOverlayOpen($('totalsOverlay'))) renderTotalsTab();
            if (isOverlayOpen($('networkOverlay'))) renderNetworkTab();
            if (typeof renderAgentProfileFeature === 'function') renderAgentProfileFeature();
        }




        function agentCascadeNormalizedName(value) {
            return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
        }

        function agentCascadeCoachingSlug(value) {
            return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'unknown';
        }

        function agentCascadeJson(raw) {
            if (typeof raw !== 'string' || !raw) return null;
            try {
                const parsed = JSON.parse(raw);
                return parsed && typeof parsed === 'object' ? parsed : null;
            } catch (e) { return null; }
        }

        function agentCascadeFieldEquals(value, identity) {
            return agentCascadeNormalizedName(value) === identity.normalizedName;
        }

        function agentCascadeObjectReferencesIdentity(value, identity, depth = 0) {
            if (depth > 8 || value === null || value === undefined) return false;
            if (typeof value === 'string') {
                const text = value.trim();
                if (agentCascadeFieldEquals(text, identity)) return true;
                if (identity.agentId && text === identity.agentId) return true;
                if (identity.employeeId && text === identity.employeeId) return true;
                return false;
            }
            if (Array.isArray(value)) return value.some(item => agentCascadeObjectReferencesIdentity(item, identity, depth + 1));
            if (typeof value !== 'object') return false;
            return Object.values(value).some(item => agentCascadeObjectReferencesIdentity(item, identity, depth + 1));
        }

        function agentCascadeRecordMatches(key, raw, identity) {
            const value = String(key || '');
            if (!value) return false;
            if (value === identity.authKey || value === identity.profileKey || value === identity.leaveProfileKey) return true;
            if (value === `coachlock:agent:${identity.coachingSlug}`) return true;
            if ((value.startsWith('att:') || value.startsWith('ot:')) && agentCascadeFieldEquals(value.slice(value.indexOf('|') + 1), identity)) return true;

            const parsed = agentCascadeJson(raw);
            if (!parsed) return false;
            if (value.startsWith('speedtest:')) return agentCascadeFieldEquals(parsed.name || parsed.agentName, identity);
            if (value.startsWith('dayswap:')) return agentCascadeFieldEquals(parsed.offAgent, identity) || agentCascadeFieldEquals(parsed.workAgent, identity);
            if (value.startsWith('shiftoverride:')) return agentCascadeFieldEquals(parsed.name || parsed.agentName, identity);
            if (value.startsWith('leave:')) return agentCascadeFieldEquals(parsed.agentName || parsed.name, identity) || String(parsed.agentId || '') === identity.agentId;
            if (value.startsWith('leaveledger:')) return agentCascadeFieldEquals(parsed.agentName || parsed.name, identity) || String(parsed.agentId || '') === identity.agentId;
            if (value.startsWith('leaveprofile:')) return agentCascadeFieldEquals(parsed.agentName || parsed.name, identity) || String(parsed.agentId || '') === identity.agentId;
            if (value.startsWith('coaching:')) return agentCascadeFieldEquals(parsed.agentName, identity);
            if (value.startsWith('agentaccess:') || value.startsWith('agentsecurity:') || value.startsWith('agentsecuritylog:') || value.startsWith('accesslog:')) return agentCascadeFieldEquals(parsed.agentName || parsed.name || parsed.targetAgent, identity) || String(parsed.agentId || '') === identity.agentId;
            if (value.startsWith(FORCE_LOGOUT_COMMAND_PREFIX)) return agentCascadeFieldEquals(parsed.name || parsed.agentName, identity);
            return false;
        }

        function agentCascadeBuildIdentity(removed) {
            const name = String(removed && removed.name || '').trim();
            const agentId = agentAuthId(name);
            return {
                name,
                normalizedName:agentCascadeNormalizedName(name),
                employeeId:String(removed && removed.employeeId || ''),
                pod:String(removed && removed.pod || ''),
                agentId,
                authKey:agentAuthStorageKey(name),
                profileKey:profileStorageKey(name),
                leaveProfileKey:LEAVE_V3_PROFILE_PREFIX + agentId,
                coachingSlug:agentCascadeCoachingSlug(name)
            };
        }

        function agentCascadeProtectedIdentity(identity) {
            return Boolean(identity && identity.employeeId && identity.employeeId === PREMIUM_ACCESS_MANAGER_EMPLOYEE_ID);
        }

        function agentCascadeRemoteKvEntries(snapshotValue) {
            const rows = [];
            const val = snapshotValue && typeof snapshotValue === 'object' ? snapshotValue : {};
            Object.entries(val).forEach(([encodedKey, raw]) => {
                let key = '';
                try { key = fbDecodeKey(encodedKey); } catch (e) { return; }
                rows.push({ encodedKey, key, raw:typeof raw === 'string' ? raw : String(raw == null ? '' : raw) });
            });
            return rows;
        }

        function agentCascadeLocalPendingKeys(identity) {
            const keys = new Set();
            getLocalKeysWithPrefix(PENDING_PREFIX).forEach(storageKey => {
                const key = storageKey.slice(PENDING_PREFIX.length);
                let raw = pendingWritePayload(key);
                if (raw === null || raw === undefined) raw = safeLocalGet(storageKey);
                if (agentCascadeRecordMatches(key, raw, identity)) keys.add(key);
            });
            getLocalKeysWithPrefix(PENDING_DELETE_PREFIX).forEach(storageKey => {
                const key = storageKey.slice(PENDING_DELETE_PREFIX.length);
                if (agentCascadeRecordMatches(key, safeLocalGet(key), identity)) keys.add(key);
            });
            return keys;
        }

        function agentCascadeCleanLocalAudit(identity) {
            try {
                const events = JSON.parse(safeLocalGet(SYNC_AUDIT_KEY) || '[]');
                if (Array.isArray(events)) {
                    const next = events.filter(event => !agentCascadeObjectReferencesIdentity(event, identity));
                    safeLocalSet(SYNC_AUDIT_KEY, JSON.stringify(next.slice(-SYNC_AUDIT_MAX)));
                }
            } catch (e) {}
            try {
                const mirror = readLocalAuditMirror();
                const next = mirror.filter(event => !agentCascadeObjectReferencesIdentity(event, identity));
                safeLocalSet(LOCAL_AUDIT_MIRROR_KEY, JSON.stringify(next.slice(0, LOCAL_AUDIT_MIRROR_MAX)));
            } catch (e) {}
            try {
                getLocalKeysWithPrefix(PENDING_IMMUTABLE_AUDIT_PREFIX).forEach(storageKey => {
                    try {
                        const entry = JSON.parse(safeLocalGet(storageKey) || 'null');
                        if (entry && agentCascadeObjectReferencesIdentity(entry, identity)) safeLocalRemove(storageKey);
                    } catch (e) {}
                });
            } catch (e) {}
        }

        function agentCascadeClearLocalKey(key) {
            safeLocalRemove(key);
            safeLocalRemove(PENDING_PREFIX + key);
            safeLocalRemove(PENDING_DELETE_PREFIX + key);
            safeLocalRemove(RECORD_VERSION_META_PREFIX + key);
            safeLocalRemove(RECORD_DELETE_META_PREFIX + key);
            safeLocalRemove(RECORD_CONFLICT_PREFIX + key);
            if (fbKvCache) delete fbKvCache[key];
            try { applyKvChildRemove(fbEncodeKey(key)); } catch (e) {}
        }

        async function agentCascadeClearLocalState(identity, purgeKeys) {
            for (const key of purgeKeys) agentCascadeClearLocalKey(key);
            getPendingPunchEvents().filter(event => event && (event.name === identity.name || purgeKeys.has(event.key))).forEach(event => removePunchSyncEvent(event));
            getLocalKeysWithPrefix(TODAY_SHIFT_CHOICE_PREFIX).forEach(key => {
                if (key.endsWith('|' + identity.name)) safeLocalRemove(key);
            });
            safeLocalRemove(profileDraftStorageKey(identity.name));
            safeLocalRemove(profileSyncMetaStorageKey(identity.name));
            try { await deleteProfileOfflineRecord(identity.profileKey); } catch (e) {}
            try { safeLocalRemove(ANNOUNCE_SEEN_KEY + ':agent:' + identity.normalizedName); } catch (e) {}
            agentCascadeCleanLocalAudit(identity);
            try { if (profilePresence && typeof profilePresence === 'object') delete profilePresence[profileIdForAgent(identity.name)]; } catch (e) {}
            if (profileSelectedAgent === identity.name) profileSelectedAgent = null;
            if (currentEmployee === identity.name) {
                currentEmployee = null;
                safeLocalRemove('lastEmployee');
                if ($('empSelect')) $('empSelect').value = '';
                if ($('empSearch')) $('empSearch').value = '';
            }
        }

        function agentCascadeCountKinds(keys) {
            const counts = { security:0, attendance:0, overtime:0, network:0, coaching:0, profile:0, schedule:0, leave:0, command:0, other:0 };
            keys.forEach(key => {
                if (key.startsWith(AGENT_AUTH_KEY_PREFIX) || key.startsWith('agentaccess:') || key.startsWith('agentsecurity:') || key.startsWith('agentsecuritylog:') || key.startsWith('accesslog:')) counts.security += 1;
                else if (key.startsWith('att:')) counts.attendance += 1;
                else if (key.startsWith('ot:')) counts.overtime += 1;
                else if (key.startsWith('speedtest:')) counts.network += 1;
                else if (key.startsWith('coaching:') || key.startsWith('coachlock:')) counts.coaching += 1;
                else if (key.startsWith('profile:')) counts.profile += 1;
                else if (key.startsWith('dayswap:') || key.startsWith('shiftoverride:')) counts.schedule += 1;
                else if (key.startsWith('leave:') || key.startsWith('leaveledger:') || key.startsWith('leaveprofile:')) counts.leave += 1;
                else if (key.startsWith(FORCE_LOGOUT_COMMAND_PREFIX)) counts.command += 1;
                else counts.other += 1;
            });
            return counts;
        }

        async function permanentlyDeleteAgentData(removed) {
            const identity = agentCascadeBuildIdentity(removed);
            if (!identity.name) throw new Error('Agent identity is unavailable.');
            if (agentCascadeProtectedIdentity(identity)) {
                throw new Error('This protected Premium Manager workforce identity cannot be deleted from the standard Agent removal flow.');
            }
            let db = fbDb;
            if (!db) db = await ensureFirebaseReady({ silent:true });
            if (!db || fbConnected !== true) {
                throw new Error('Permanent Agent deletion requires a live verified Firebase connection. Reconnect and wait for Server Sync to show verified, then try again.');
            }
            if (hasPendingWrite('employees')) {
                throw new Error('A roster update is still syncing. Wait for roster sync to finish before permanently deleting an Agent.');
            }
            if (typeof leaveV3ServerCapable !== 'undefined' && leaveV3ServerCapable && window.TRINOTIME_LEAVE_FREE_PILOT !== true) {
                throw new Error('Permanent Agent deletion is blocked while the authoritative HR leave backend is active because this client has no verified HR cascade-delete endpoint.');
            }

            const kvSnapshot = await withTimeout(
                db.ref('kv').once('value'),
                FIREBASE_READ_TIMEOUT_MS,
                'Timed out loading live Agent data before permanent deletion.'
            );
            const remoteRows = agentCascadeRemoteKvEntries(kvSnapshot.val() || {});
            const employeesRow = remoteRows.find(row => row.key === 'employees');
            let remoteRoster = [];
            try { remoteRoster = employeesRow && employeesRow.raw ? JSON.parse(employeesRow.raw) : employees.slice(); } catch (e) { remoteRoster = employees.slice(); }
            remoteRoster = sanitizeEmployeeRoster(Array.isArray(remoteRoster) ? remoteRoster : []);
            const remoteTarget = remoteRoster.find(emp => agentCascadeNormalizedName(emp && emp.name) === identity.normalizedName) || removed;
            if (!TrinoPermissions.can('agent.roster.remove', { agent:remoteTarget, name:remoteTarget.name, pod:remoteTarget.pod })) {
                throw new Error('You can permanently delete agents only within your authorized POD scope.');
            }

            const purgeKeys = new Set();
            const coachingSessionIds = new Set();
            remoteRows.forEach(row => {
                if (agentCascadeRecordMatches(row.key, row.raw, identity)) {
                    purgeKeys.add(row.key);
                    if (row.key.startsWith('coaching:')) {
                        const parsed = agentCascadeJson(row.raw);
                        if (parsed && parsed.id) coachingSessionIds.add(String(parsed.id));
                    }
                }
            });
            remoteRows.forEach(row => {
                if (!row.key.startsWith('coachlock:')) return;
                const parsed = agentCascadeJson(row.raw);
                if (parsed && parsed.sessionId && coachingSessionIds.has(String(parsed.sessionId))) purgeKeys.add(row.key);
            });
            agentCascadeLocalPendingKeys(identity).forEach(key => purgeKeys.add(key));
            purgeKeys.add(identity.authKey);
            purgeKeys.add(identity.profileKey);
            purgeKeys.add(identity.leaveProfileKey);
            purgeKeys.add(`coachlock:agent:${identity.coachingSlug}`);

            const nextRoster = remoteRoster.filter(emp => agentCascadeNormalizedName(emp && emp.name) !== identity.normalizedName);
            const nextRosterVersion = createBlobVersion();
            const legacyAuditRow = remoteRows.find(row => row.key === 'audit_log');
            let nextLegacyAudit = null;
            if (legacyAuditRow && legacyAuditRow.raw) {
                try {
                    const parsedLegacyAudit = JSON.parse(legacyAuditRow.raw);
                    if (Array.isArray(parsedLegacyAudit)) {
                        const filtered = parsedLegacyAudit.filter(entry => !agentCascadeObjectReferencesIdentity(entry, identity));
                        if (filtered.length !== parsedLegacyAudit.length) nextLegacyAudit = filtered;
                    }
                } catch (e) {}
            }
            const updates = {};
            purgeKeys.forEach(key => { updates['kv/' + fbEncodeKey(key)] = null; });
            updates['kv/' + fbEncodeKey('employees')] = JSON.stringify(nextRoster);
            updates['kv/' + fbEncodeKey('employees_v')] = nextRosterVersion;
            if (nextLegacyAudit) updates['kv/' + fbEncodeKey('audit_log')] = JSON.stringify(nextLegacyAudit);
            updates[PROFILE_PRESENCE_ROOT + '/' + profileIdForAgent(identity.name)] = null;

            await withTimeout(
                db.ref().update(updates),
                Math.max(FIREBASE_WRITE_TIMEOUT_MS, 25000),
                'Timed out permanently deleting the Agent data set.'
            );

            employees = nextRoster;
            employeesVersion = nextRosterVersion;
            safeLocalSet('employees', JSON.stringify(nextRoster));
            safeLocalSet('employees_v', nextRosterVersion);
            safeLocalRemove(PENDING_PREFIX + 'employees');
            if (nextLegacyAudit) {
                safeLocalSet('audit_log', JSON.stringify(nextLegacyAudit));
                safeLocalRemove(PENDING_PREFIX + 'audit_log');
                if (fbKvCache) fbKvCache.audit_log = JSON.stringify(nextLegacyAudit);
            }
            await agentCascadeClearLocalState(identity, purgeKeys);

            const counts = agentCascadeCountKinds(purgeKeys);
            const totalPurged = purgeKeys.size + 1;
            await logAudit('agent_cascade_delete_completed', {
                auditCategory:'security',
                pod:identity.pod,
                deletionScope:'agent_full_cascade',
                purgeCounts:counts,
                recordsPurged:totalPurged,
                targetIdentityRetained:false
            });
            publishUpdate();
            refreshRosterDependentViews();
            if (typeof updateLeaveRequestBadge === 'function') updateLeaveRequestBadge();
            if (typeof refreshCoachingSurfaces === 'function') refreshCoachingSurfaces();
            return { removed, counts, recordsPurged:totalPurged, syncPending:false };
        }

        async function deleteEmployee(name) {
            const idx = employees.findIndex(e => e.name === name);
            if (idx === -1) return;
            const removed = employees[idx];
            if (!TrinoPermissions.can('agent.roster.remove', { agent:removed, name:removed.name, pod:removed.pod })) {
                throw new Error('You can remove agents only within your authorized POD scope.');
            }
            return permanentlyDeleteAgentData(removed);
        }










        const moveAgentsSelectedNames = new Set();

        function rosterEmployeeByName(name) {
            const target = String(name || '').trim().toLowerCase();
            return employees.find(emp => String(emp && emp.name || '').trim().toLowerCase() === target) || null;
        }

        function currentRosterPodForName(name) {
            const emp = rosterEmployeeByName(name);
            return emp && emp.pod ? emp.pod : null;
        }

        function canTransferAgentPod(name) {
            const emp = rosterEmployeeByName(name);
            if (!emp || !emp.pod) return false;
            return TrinoPermissions.can('agent.pod.transfer', { agent: emp, name: emp.name, pod: emp.pod });
        }

        function podTransferActorLabel() {
            if (isAdmin) return 'Admin';
            if (isTeamLeader) return teamLeaderName || 'Team Leader';
            return currentEmployee || 'Unknown';
        }

        function openAttendanceShiftForTransfer(name) {
            try {
                const rec = getTodayRecord(name) || {};
                if (rec.timeIn && !rec.logOut && !isVoidedAttendanceRecord(rec)) {
                    return { rec, date: attendanceRecordDate(rec, todayKeyPart()), pod: rec.pod || currentRosterPodForName(name) || '' };
                }
            } catch (e) {}
            return null;
        }

        function podTransferOptionsHtml(name) {
            const current = currentRosterPodForName(name);
            return podsForTeam(teamIdForPod(current)).filter(pod => pod !== current)
                .map(pod => `<option value="${escapeHtml(pod)}">${escapeHtml(podDisplayName(pod))}</option>`).join('');
        }

        function podTransferSelectMarkup(name, origin = 'inline') {
            if (!canTransferAgentPod(name)) return '';
            const options = podTransferOptionsHtml(name);
            if (!options) return '';




            if (origin === 'roster') {
                return `<select class="pod-transfer-inline-select" data-pod-transfer-agent="${escapeHtml(name)}" data-transfer-origin="roster" data-pod-options-lazy="1" aria-label="Move ${escapeHtml(name)} to another POD" title="Change current roster POD. Historical attendance keeps its original POD stamp."><option value="">Move POD…</option></select>`;
            }
            return `<select class="pod-transfer-inline-select" data-pod-transfer-agent="${escapeHtml(name)}" data-transfer-origin="${escapeHtml(origin)}" aria-label="Move ${escapeHtml(name)} to another POD" title="Change current roster POD. Historical attendance keeps its original POD stamp."><option value="">Move POD…</option>${options}</select>`;
        }

        function hydrateRosterPodTransferOptions(select) {
            if (!select || select.dataset.podOptionsLazy !== '1' || select.dataset.podOptionsReady === '1') return;
            const name = select.dataset.podTransferAgent || '';
            const options = podTransferOptionsHtml(name);
            if (options) select.insertAdjacentHTML('beforeend', options);
            select.dataset.podOptionsReady = '1';
        }

        function podAssignmentDisplayMarkup(recordPod, currentPod) {
            const recorded = recordPod || 'Unassigned';
            const current = currentPod || recorded;
            const recordedLabel = recorded === 'Unassigned' ? recorded : podDisplayName(recorded);
            const currentLabel = current === 'Unassigned' ? current : podDisplayName(current);
            if (current === recorded) return `<span class="pod-assignment-display"><span class="pod-assignment-current">${escapeHtml(currentLabel)}</span></span>`;
            return `<span class="pod-assignment-display" title="Current roster assignment: ${escapeHtml(currentLabel)}. This attendance record was originally stamped to ${escapeHtml(recordedLabel)}."><span class="pod-assignment-current">${escapeHtml(currentLabel)}</span><span class="pod-assignment-history">record: ${escapeHtml(recordedLabel)}</span></span>`;
        }

        function profilePodTransferMarkup(name) {
            if (!canTransferAgentPod(name)) return '';
            const current = currentRosterPodForName(name) || 'Unassigned';
            return `<div class="profile-pod-management"><div class="profile-pod-management-copy"><strong>Assigned POD · ${escapeHtml(podContextLabel(current))}</strong><span>Leadership can transfer this agent here. Profile data stays with the same agent and historical shifts keep their original POD stamp.</span></div>${podTransferSelectMarkup(name, 'profile')}</div>`;
        }

        async function persistProfilePodAfterTransfer(name, newPod) {
            try {
                if (typeof profileIdForAgent !== 'function' || typeof allAgentProfiles !== 'object' || !allAgentProfiles) return;
                const id = profileIdForAgent(name);
                const existing = allAgentProfiles[id];
                if (!existing || !existing.agentName) return;
                const next = { ...existing, pod: newPod, podAssignmentUpdatedAt: nowIso() };
                allAgentProfiles[id] = next;
                if (typeof saveAgentProfile === 'function') await saveAgentProfile(next);
            } catch (error) {
                reportAppError('Profile POD continuity', error);
            }
        }

        function transferScopeEmployees() {
            if (isAdmin) return currentTeamEmployees().slice();
            if (isTeamLeader && lockedPod) return labelerRosterEmployees().filter(emp => emp.pod === lockedPod);
            return [];
        }

        function refreshAfterPodTransfer() {
            populateEmployeeSelects();
            renderPodTabs();
            refreshPunchCard();
            renderTable();
            renderTodayStatus();
            if (typeof updateExecutiveStatusStrip === 'function') updateExecutiveStatusStrip(true);
            if (typeof updateNotifBadge === 'function') updateNotifBadge();
            if (typeof refreshSpeedTestReminder === 'function') refreshSpeedTestReminder();
            if (typeof scheduleAgentSecurityPanelRender === 'function') scheduleAgentSecurityPanelRender();
            if (isOverlayOpen($('rosterOverlay'))) renderRosterTab();
            if (isOverlayOpen($('moveAgentsOverlay'))) renderMoveAgentsTab();
            if (isOverlayOpen($('historyOverlay'))) renderHistoryCalendar();
            if (isOverlayOpen($('noteHistoryOverlay'))) renderNoteHistory();
            if (isOverlayOpen($('totalsOverlay'))) renderTotalsTab();
            if (typeof renderAgentProfileFeature === 'function') renderAgentProfileFeature();
        }

        async function transferAgentsToPod(names, targetPod, options = {}) {
            if (!POD_LIST.includes(targetPod)) throw new Error('Choose a valid destination POD.');
            TrinoPermissions.require('agent.pod.transfer.destination', { pod:targetPod }, 'You cannot move agents outside your authorized team scope.');
            const uniqueNames = [...new Set((Array.isArray(names) ? names : [names]).map(v => String(v || '').trim()).filter(Boolean))];
            const moves = [];
            for (const name of uniqueNames) {
                const emp = rosterEmployeeByName(name);
                if (!emp) throw new Error(`${name} is no longer in the active roster.`);
                if (!canTransferAgentPod(emp.name)) {
                    throw new Error(isTeamLeader && !isAdmin
                        ? `You can only move agents who are currently assigned to ${lockedPod}.`
                        : `You do not have permission to move ${emp.name}.`);
                }
                if (emp.pod === targetPod) continue;
                moves.push({ emp, name: emp.name, fromPod: emp.pod, toPod: targetPod, openShift: openAttendanceShiftForTransfer(emp.name) });
            }
            if (!moves.length) return { moved: [], skipped: uniqueNames.length };

            if (options.confirmMove !== false) {
                const openCount = moves.filter(move => move.openShift).length;
                const namePreview = moves.slice(0, 6).map(move => move.name).join(', ') + (moves.length > 6 ? ` +${moves.length - 6} more` : '');
                let message = `Move ${moves.length === 1 ? namePreview : moves.length + ' agents'} to ${podContextLabel(targetPod)}?\n\nTheir complete attendance/profile history will follow their current roster assignment, while historical records keep the original POD/shift stamp for payroll.`;
                if (openCount) message += `\n\n${openCount} selected ${openCount === 1 ? 'agent has' : 'agents have'} an open shift. That open shift will remain stamped to its original POD until Time Out; the new POD applies to the next new shift.`;
                if (!(await showConfirmAsync(
                    'Move Agent POD Assignment?',
                    escapeHtml(message).replace(/\n/g, '<br>'),
                    { confirmLabel: moves.length === 1 ? 'Move Agent' : `Move ${moves.length} Agents`, cancelLabel:'Cancel', kind:'pod-transfer' }
                ))) return { moved: [], cancelled: true };
            }

            const actor = podTransferActorLabel();
            const movedAt = nowIso();
            moves.forEach(move => {
                const history = Array.isArray(move.emp.podTransferHistory) ? move.emp.podTransferHistory.slice() : [];
                history.push({ fromPod: move.fromPod, toPod: move.toPod, at: movedAt, by: actor });
                move.emp.podTransferHistory = history.slice(-20);
                move.emp.pod = move.toPod;
            });

            await saveEmployees();
            await Promise.allSettled(moves.map(move => persistProfilePodAfterTransfer(move.name, move.toPod)));
            for (const move of moves) {
                await logAudit('pod_transfer', {
                    name: move.name,
                    pod: move.toPod,
                    fromPod: move.fromPod,
                    toPod: move.toPod,
                    transferredBy: actor,
                    openShiftPod: move.openShift ? move.openShift.pod : null,
                    openShiftDate: move.openShift ? move.openShift.date : null,
                    continuity: 'Historical attendance/shift stamps preserved; current roster scope follows destination POD.'
                });
                moveAgentsSelectedNames.delete(move.name);
            }
            publishUpdate();
            refreshAfterPodTransfer();
            return { moved: moves };
        }

        // v1.1.60 Admin Custom POD / Team Management
        let podTeamManagementSubmitting = false;
        const podTeamManagerSelectedAgents = new Set();

        function setPodTeamManagementStatus(message, state = '') {
            const status = $('podTeamManagementStatus');
            if (!status) return;
            status.textContent = message || '';
            status.dataset.state = state || '';
        }
        function activePodDirectoryEntriesForTeam(team) {
            return podDirectory.filter(entry => entry && entry.active !== false && entry.team === team);
        }
        function podTeamManagerPodOptions(selected = '', includePlaceholder = true) {
            const groups = TEAM_GROUPS.map(group => {
                const options = podsForTeam(group.id).map(pod => `<option value="${escapeHtml(pod)}"${pod === selected ? ' selected' : ''}>${escapeHtml(podDisplayName(pod))}</option>`).join('');
                return `<optgroup label="${escapeHtml(group.fullName)}">${options}</optgroup>`;
            }).join('');
            return (includePlaceholder ? '<option value="">Choose a POD...</option>' : '') + groups;
        }
        function renderPodTeamManagementCard() {
            const card = $('podTeamManagementCard');
            if (!card) return;
            card.hidden = !isAdmin;
            if (!isAdmin) return;
            const customCount = customPodDirectoryEntries().length;
            const tlCount = TEAM_LEADER_ROSTER.filter(tl => tl && POD_LIST.includes(tl.pod)).length;
            const agentCount = labelerRosterEmployees().filter(emp => emp && POD_LIST.includes(emp.pod)).length;
            if ($('podTeamStatPods')) $('podTeamStatPods').textContent = String(POD_LIST.length);
            if ($('podTeamStatCustom')) $('podTeamStatCustom').textContent = String(customCount);
            if ($('podTeamStatTl')) $('podTeamStatTl').textContent = String(tlCount);
            if ($('podTeamStatAgents')) $('podTeamStatAgents').textContent = String(agentCount);
            const trust = $('podTeamDirectoryTrust');
            if (trust) {
                trust.textContent = podDirectoryServerConfirmed ? `Server-confirmed · rev ${podDirectoryRevision}` : 'Waiting for Firebase confirmation';
                trust.dataset.state = podDirectoryServerConfirmed ? 'ok' : 'pending';
            }
        }
        function podTeamManagerShiftSourceOptions(team, selected = '') {
            return podsForTeam(team).map(pod => {
                const gid = getShiftGroupIdForPod(pod);
                const suffix = gid ? ` · ${gid}` : '';
                return `<option value="${escapeHtml(pod)}"${pod === selected ? ' selected' : ''}>${escapeHtml(podDisplayName(pod) + suffix)}</option>`;
            }).join('');
        }
        function refreshPodTeamManagerCreateShiftOptions() {
            const teamEl = $('podManagerCreateTeam');
            const sourceEl = $('podManagerCreateShiftSource');
            if (!teamEl || !sourceEl) return;
            const team = teamEl.value === TEAM_ALBERTSONS ? TEAM_ALBERTSONS : TEAM_CWH;
            const previous = sourceEl.value;
            sourceEl.innerHTML = podTeamManagerShiftSourceOptions(team, previous);
            if (previous && Array.from(sourceEl.options).some(option => option.value === previous)) sourceEl.value = previous;
        }
        function podTeamManagerDirectoryRows() {
            const agents = labelerRosterEmployees();
            return podDirectory.filter(entry => entry && entry.active !== false).map(entry => {
                const leader = assignedActiveTeamLeaderForPod(entry.id);
                const primary = leader ? leader.name : '';
                const backup = primary ? teamLeaderBackupForPrimary(entry.id, primary) : '';
                const agentCount = agents.filter(emp => emp && emp.pod === entry.id).length;
                return `<div class="pod-manager-directory-row" role="listitem">
                    <div class="pod-manager-directory-name"><strong>${escapeHtml(entry.name)}</strong><span>${escapeHtml(teamGroupById(entry.team).label)} · ${entry.system ? 'System POD' : 'Custom POD'}</span></div>
                    <div><small>Team Leader</small><strong>${primary ? escapeHtml(agentDisplayName(primary)) : 'Unassigned'}</strong></div>
                    <div><small>Backup TL</small><strong>${backup ? escapeHtml(agentDisplayName(backup)) : 'None'}</strong></div>
                    <div><small>Agents</small><strong>${agentCount}</strong></div>
                </div>`;
            }).join('');
        }
        function renderPodTeamManagerAgentList() {
            const list = $('podManagerAgentList');
            const target = $('podManagerAssignmentPod') ? $('podManagerAssignmentPod').value : '';
            if (!list) return;
            const count = $('podManagerAgentSelectionCount');
            const assign = $('podManagerAssignAgentsBtn');
            if (!target) {
                list.innerHTML = '<div class="pod-manager-agent-empty">Choose a target POD to manage Agents.</div>';
                if (count) count.textContent = `${podTeamManagerSelectedAgents.size} selected`;
                if (assign) assign.disabled = true;
                return;
            }
            const query = String(($('podManagerAgentSearch') && $('podManagerAgentSearch').value) || '').trim().toLowerCase();
            const rows = labelerRosterEmployees()
                .filter(emp => emp && emp.name)
                .filter(emp => !query || `${agentDisplayName(emp.name)} ${emp.name} ${teamGroupById(teamIdForPod(emp.pod)).label} ${podDisplayName(emp.pod)}`.toLowerCase().includes(query))
                .sort((a,b) => String(teamGroupById(teamIdForPod(a.pod)).label).localeCompare(String(teamGroupById(teamIdForPod(b.pod)).label)) || String(podDisplayName(a.pod)).localeCompare(String(podDisplayName(b.pod))) || String(a.name).localeCompare(String(b.name)));
            list.innerHTML = rows.length ? rows.map(emp => {
                const selected = podTeamManagerSelectedAgents.has(emp.name);
                const already = emp.pod === target;
                return `<label class="pod-manager-agent-row${already ? ' is-current' : ''}"><input type="checkbox" class="pod-manager-agent-check" value="${escapeHtml(emp.name)}" ${selected ? 'checked' : ''} ${already ? 'disabled' : ''}><span><strong>${escapeHtml(agentDisplayName(emp.name))}</strong><small>${escapeHtml(teamGroupById(teamIdForPod(emp.pod)).label)} · ${escapeHtml(podDisplayName(emp.pod))}${already ? ' · already assigned' : ''}</small></span></label>`;
            }).join('') : '<div class="pod-manager-agent-empty">No matching Agents.</div>';
            if (count) count.textContent = `${podTeamManagerSelectedAgents.size} selected`;
            const movable = [...podTeamManagerSelectedAgents].filter(name => currentRosterPodForName(name) !== target);
            if (assign) assign.disabled = !target || movable.length === 0 || podTeamManagementSubmitting;
        }
        function syncPodTeamManagerLeadershipFields(options = {}) {
            const target = $('podManagerAssignmentPod') ? $('podManagerAssignmentPod').value : '';
            const tlSelect = $('podManagerTeamLeader');
            const backupSelect = $('podManagerBackupTl');
            if (!tlSelect || !backupSelect) return;
            if (!target) {
                tlSelect.innerHTML = '<option value="">Choose a target POD first</option>';
                backupSelect.innerHTML = '<option value="">No Backup TL</option>';
                const summary = $('podManagerLeadershipSummary');
                if (summary) summary.textContent = 'Choose a target POD.';
                const save = $('podManagerLeadershipSave');
                if (save) save.disabled = true;
                return;
            }
            const targetTeam = teamIdForPod(target);
            const current = assignedActiveTeamLeaderForPod(target);
            const previous = tlSelect.value;
            const activeTls = TEAM_LEADER_ROSTER.filter(tl => tl && tl.name && tl.pod).slice().sort((a,b) => {
                const ar = teamIdForPod(a.pod) === targetTeam ? 0 : 1;
                const br = teamIdForPod(b.pod) === targetTeam ? 0 : 1;
                return ar - br || String(teamGroupById(teamIdForPod(a.pod)).label).localeCompare(String(teamGroupById(teamIdForPod(b.pod)).label)) || String(a.name).localeCompare(String(b.name));
            });
            tlSelect.innerHTML = '<option value="">Choose a Team Leader...</option>' + activeTls.map(tl => `<option value="${escapeHtml(tl.name)}">${escapeHtml(agentDisplayName(tl.name))} · ${escapeHtml(teamGroupById(teamIdForPod(tl.pod)).label)} / ${escapeHtml(podDisplayName(tl.pod))}${tl.pod === target ? ' · current' : ''}</option>`).join('');
            const preferCurrent = options.preferCurrent !== false;
            const desired = preferCurrent && current ? current.name : (activeTls.some(tl => tl.name === previous) ? previous : (current ? current.name : ''));
            if (desired && Array.from(tlSelect.options).some(option => option.value === desired)) tlSelect.value = desired;
            const selectedName = tlSelect.value;
            const selectedEntry = selectedName ? activeTeamLeaderDirectoryEntry(selectedName) : null;
            const selectedOldPod = selectedEntry ? selectedEntry.pod : '';
            const swapName = current && selectedName && current.name !== selectedName ? current.name : '';
            const currentBackup = selectedName ? teamLeaderBackupForPrimary(target, selectedName) : '';
            const candidates = selectedName ? TEAM_LEADER_ROSTER.filter(tl => {
                if (!tl || !tl.name || tl.name === selectedName) return false;
                const projectedPod = swapName && tl.name === swapName ? selectedOldPod : tl.pod;
                return projectedPod && teamIdForPod(projectedPod) === targetTeam;
            }).map(tl => ({ ...tl, projectedPod:swapName && tl.name === swapName ? selectedOldPod : tl.pod })).sort((a,b) => String(a.name).localeCompare(String(b.name))) : [];
            backupSelect.innerHTML = '<option value="">No Backup TL</option>' + candidates.map(tl => `<option value="${escapeHtml(tl.name)}">${escapeHtml(agentDisplayName(tl.name))} · ${escapeHtml(podDisplayName(tl.projectedPod))}${tl.projectedPod !== tl.pod ? ' · after swap' : ''}</option>`).join('');
            if (currentBackup && candidates.some(tl => tl.name === currentBackup)) backupSelect.value = currentBackup;
            const summary = $('podManagerLeadershipSummary');
            if (summary) {
                if (!selectedName) summary.textContent = current ? `${podDisplayName(target)} is currently led by ${agentDisplayName(current.name)}.` : `${podDisplayName(target)} currently has no Team Leader.`;
                else if (current && selectedName === current.name) summary.textContent = `${agentDisplayName(current.name)} remains the Team Leader for ${podDisplayName(target)}.`;
                else if (current && selectedOldPod) summary.textContent = `Proposed swap: ${agentDisplayName(selectedName)} -> ${podDisplayName(target)}; ${agentDisplayName(current.name)} -> ${podDisplayName(selectedOldPod)}.`;
                else if (selectedOldPod) summary.textContent = `Proposed move: ${agentDisplayName(selectedName)} -> ${podDisplayName(target)}; ${podDisplayName(selectedOldPod)} becomes unassigned.`;
                else summary.textContent = `${agentDisplayName(selectedName)} will be assigned to ${podDisplayName(target)}.`;
            }
            const save = $('podManagerLeadershipSave');
            if (save) save.disabled = !selectedName || podTeamManagementSubmitting;
        }
        function renderPodTeamManagement() {
            renderPodTeamManagementCard();
            if (!isAdmin) return;
            const renameSelect = $('podManagerRenamePod');
            const targetSelect = $('podManagerAssignmentPod');
            const oldRename = renameSelect ? renameSelect.value : '';
            const oldTarget = targetSelect ? targetSelect.value : '';
            if (renameSelect) {
                renameSelect.innerHTML = podTeamManagerPodOptions(oldRename, true);
                if (oldRename && POD_LIST.includes(oldRename)) renameSelect.value = oldRename;
            }
            if (targetSelect) {
                targetSelect.innerHTML = podTeamManagerPodOptions(oldTarget, true);
                if (oldTarget && POD_LIST.includes(oldTarget)) targetSelect.value = oldTarget;
            }
            const teamEl = $('podManagerCreateTeam');
            if (teamEl && !teamEl.value) teamEl.value = TEAM_CWH;
            refreshPodTeamManagerCreateShiftOptions();
            const list = $('podManagerDirectoryList');
            if (list) list.innerHTML = podTeamManagerDirectoryRows();
            syncPodTeamManagerLeadershipFields();
            renderPodTeamManagerAgentList();
        }
        function openPodTeamManagement() {
            if (!isAdmin) { showToast('Only Admins can manage PODs and team assignments.'); return; }
            const overlay = $('podTeamManagementOverlay');
            if (!overlay) return;
            podTeamManagerSelectedAgents.clear();
            setPodTeamManagementStatus('Changes require a live, verified Firebase Admin session.', 'info');
            renderPodTeamManagement();
            overlay.classList.add('open');
            overlay.setAttribute('aria-hidden', 'false');
            setTimeout(() => { try { $('podManagerCreateName').focus({ preventScroll:true }); } catch (e) {} }, 0);
        }
        function closePodTeamManagement() {
            if (podTeamManagementSubmitting) {
                showToast('Wait for the current POD/team change to finish before closing this panel.');
                return;
            }
            const overlay = $('podTeamManagementOverlay');
            if (overlay) {
                overlay.classList.remove('open');
                overlay.setAttribute('aria-hidden', 'true');
            }
            podTeamManagerSelectedAgents.clear();
        }
        function clonePodManagerData(value, fallback = {}) {
            try { return JSON.parse(JSON.stringify(value)); } catch (e) { return JSON.parse(JSON.stringify(fallback)); }
        }

        function reconcileDayOffScheduleToPodDirectory(sourceSchedule) {
            const next = sourceSchedule && typeof sourceSchedule === 'object' && !Array.isArray(sourceSchedule) ? clonePodManagerData(sourceSchedule) : {};
            const activeIds = new Set(podDirectory.filter(entry => entry && entry.active !== false && entry.id).map(entry => entry.id));
            podDirectory.forEach(entry => {
                if (!entry || entry.active === false || !entry.id) return;
                if (!next[entry.id] || typeof next[entry.id] !== 'object') next[entry.id] = { effective:'', rows:[['','','','','','','']], teamLeaderBackupByName:{} };
                if (!Array.isArray(next[entry.id].rows)) next[entry.id].rows = [['','','','','','','']];
                if (!next[entry.id].teamLeaderBackupByName || typeof next[entry.id].teamLeaderBackupByName !== 'object' || Array.isArray(next[entry.id].teamLeaderBackupByName)) next[entry.id].teamLeaderBackupByName = {};
            });
            Object.keys(next).forEach(pod => {
                if (String(pod).startsWith('tt-custom-pod:') && !activeIds.has(pod)) delete next[pod];
            });
            return next;
        }

        function reconcileBackupMappingsToCurrentLeadership(sourceSchedule) {
            const next = reconcileDayOffScheduleToPodDirectory(sourceSchedule);
            Object.keys(next).forEach(pod => {
                const data = next[pod];
                if (!data || typeof data !== 'object') return;
                const source = data.teamLeaderBackupByName && typeof data.teamLeaderBackupByName === 'object' && !Array.isArray(data.teamLeaderBackupByName) ? data.teamLeaderBackupByName : {};
                const clean = {};
                Object.entries(source).forEach(([primaryName, backupValue]) => {
                    const primary = activeTeamLeaderDirectoryEntry(String(primaryName || '').trim());
                    const backupName = normalizeTeamLeaderBackupName(backupValue);
                    const backup = activeTeamLeaderDirectoryEntry(backupName);
                    if (!primary || primary.pod !== pod || !backup || !backup.pod || backup.name === primary.name) return;
                    if (teamIdForPod(backup.pod) !== teamIdForPod(pod)) return;
                    clean[primary.name] = backup.name;
                });
                data.teamLeaderBackupByName = clean;
            });
            return next;
        }

        async function reconcilePodScheduleFromLiveServer(reason = '') {
            const live = await readSharedBlobServerReceipt('dayoff_schedule');
            let source = {};
            try { source = live.payload ? JSON.parse(live.payload) : {}; } catch (e) { source = {}; }
            dayOffSchedule = reconcileDayOffScheduleToPodDirectory(source);
            await saveSharedBlobStrict('dayoff_schedule', JSON.stringify(dayOffSchedule), { expectedVersion:live.version });
            try { await logAudit('pod_schedule_reconciled', { auditCategory:'pod_team_management', reason, modified_by:recordMutationActorId() }); } catch (e) {}
            return dayOffSchedule;
        }

        async function reconcileLeadershipScheduleFromLiveServer(reason = '') {
            const live = await readSharedBlobServerReceipt('dayoff_schedule');
            let source = {};
            try { source = live.payload ? JSON.parse(live.payload) : {}; } catch (e) { source = {}; }
            dayOffSchedule = reconcileBackupMappingsToCurrentLeadership(source);
            await saveSharedBlobStrict('dayoff_schedule', JSON.stringify(dayOffSchedule), { expectedVersion:live.version });
            try { await logAudit('pod_leadership_schedule_reconciled', { auditCategory:'pod_team_management', reason, modified_by:recordMutationActorId() }); } catch (e) {}
            return dayOffSchedule;
        }

        async function createCustomPodFromManager() {
            if (podTeamManagementSubmitting) return;
            const team = $('podManagerCreateTeam') && $('podManagerCreateTeam').value === TEAM_ALBERTSONS ? TEAM_ALBERTSONS : TEAM_CWH;
            const name = normalizePodDirectoryName($('podManagerCreateName') && $('podManagerCreateName').value);
            const sourcePod = String(($('podManagerCreateShiftSource') && $('podManagerCreateShiftSource').value) || '');
            if (!name) throw new Error('Enter a name for the new POD.');
            if (!POD_LIST.includes(sourcePod) || teamIdForPod(sourcePod) !== team) throw new Error('Choose a valid shift template from the same operating team.');
            if (activePodDirectoryEntriesForTeam(team).some(entry => entry.name.toLowerCase() === name.toLowerCase())) throw new Error(`${name} already exists in ${teamGroupById(team).label}.`);
            const actor = requireAuthenticatedAdminId();
            const id = buildCustomPodId(team);
            const createdAt = nowIso();
            const entry = { id, team, name, system:false, active:true, shiftGroupId:getShiftGroupIdForPod(sourcePod), createdAt, createdBy:actor, updatedAt:createdAt, updatedBy:actor };
            const beforeDirectory = clonePodManagerData(podDirectory, []);
            const beforeSchedule = clonePodManagerData(dayOffSchedule, {});
            podTeamManagementSubmitting = true;
            setPodTeamManagementStatus(`Creating ${name}…`, 'working');
            try {
                await savePodDirectoryStrict([...podDirectory, entry], {
                    auditAction:'pod_create',
                    auditData:{ pod:id, podName:name, team, shiftTemplatePod:sourcePod, shiftGroupId:entry.shiftGroupId }
                });
                dayOffSchedule = reconcileDayOffScheduleToPodDirectory(dayOffSchedule);
                try {
                    await saveSharedBlobStrict('dayoff_schedule', JSON.stringify(dayOffSchedule), { expectedVersion:dayOffVersion });
                } catch (scheduleError) {
                    setPodTeamManagementStatus('The schedule companion write could not be confirmed. Rolling the POD change back safely…', 'warning');
                    let directoryRolledBack = false;
                    try {
                        await savePodDirectoryStrict(beforeDirectory, {
                            auditAction:'pod_create_rollback',
                            auditData:{ pod:id, podName:name, reason:getErrorMessage(scheduleError) }
                        });
                        directoryRolledBack = true;
                    } catch (rollbackError) {
                        await reloadPodDirectoryFromServerStrict();
                        try { await logAudit('pod_create_rollback_conflict', { auditCategory:'pod_team_management', pod:id, podName:name, reason:getErrorMessage(scheduleError), rollbackError:getErrorMessage(rollbackError) }); } catch (e) {}
                    }
                    try {
                        await reconcilePodScheduleFromLiveServer(directoryRolledBack ? 'POD creation rolled back after companion schedule failure.' : 'POD creation encountered a concurrent directory change; schedule reconciled to live directory.');
                    } catch (reconcileError) {
                        dayOffSchedule = beforeSchedule;
                        throw new Error(`POD creation could not be completed and automatic reconciliation could not be confirmed. Refresh before making more POD changes. ${getErrorMessage(reconcileError)}`);
                    }
                    if (directoryRolledBack) throw new Error(`POD creation was rolled back because its Day Off schedule could not be confirmed. No active POD was left behind. ${getErrorMessage(scheduleError)}`);
                    throw new Error('POD configuration changed concurrently. The live directory and Day Off schedule were reconciled; refresh before retrying the creation.');
                }
                if ($('podManagerCreateName')) $('podManagerCreateName').value = '';
                setPodTeamManagementStatus(`${name} was created with its Day Off schedule shell confirmed by Firebase.`, 'success');
                renderPodTeamManagement();
            } finally {
                podTeamManagementSubmitting = false;
                renderPodTeamManagementCard();
            }
        }
        async function renamePodFromManager() {
            if (podTeamManagementSubmitting) return;
            const pod = String(($('podManagerRenamePod') && $('podManagerRenamePod').value) || '');
            const name = normalizePodDirectoryName($('podManagerRenameName') && $('podManagerRenameName').value);
            const entry = podDirectoryEntry(pod);
            if (!entry) throw new Error('Choose the POD you want to rename.');
            if (!name) throw new Error('Enter the new POD name.');
            if (activePodDirectoryEntriesForTeam(entry.team).some(other => other.id !== pod && other.name.toLowerCase() === name.toLowerCase())) throw new Error(`${name} already exists in ${teamGroupById(entry.team).label}.`);
            if (entry.name === name) throw new Error('The POD already uses that display name.');
            const actor = requireAuthenticatedAdminId();
            const oldName = entry.name;
            const next = podDirectory.map(item => item.id === pod ? { ...item, name, updatedAt:nowIso(), updatedBy:actor } : { ...item });
            podTeamManagementSubmitting = true;
            setPodTeamManagementStatus(`Renaming ${oldName}…`, 'working');
            try {
                await savePodDirectoryStrict(next, {
                    auditAction:'pod_rename',
                    auditData:{ pod, oldPodName:oldName, newPodName:name, team:entry.team, stableInternalId:true }
                });
                if ($('podManagerRenameName')) $('podManagerRenameName').value = '';
                setPodTeamManagementStatus(`${oldName} is now displayed as ${name}. Historical records keep the same internal POD ID.`, 'success');
                renderPodTeamManagement();
            } finally {
                podTeamManagementSubmitting = false;
                renderPodTeamManagementCard();
            }
        }
        function clearPrimaryBackupMappings(names) {
            const targets = new Set((Array.isArray(names) ? names : [names]).map(name => String(name || '').trim()).filter(Boolean));
            Object.keys(dayOffSchedule || {}).forEach(pod => {
                const map = ensureTeamLeaderBackupMap(pod);
                let changed = false;
                targets.forEach(name => { if (Object.prototype.hasOwnProperty.call(map, name)) { delete map[name]; changed = true; } });
                if (changed) dayOffSchedule[pod].teamLeaderBackupByName = map;
            });
        }
        async function savePodLeadershipFromManager() {
            if (podTeamManagementSubmitting) return;
            const targetPod = String(($('podManagerAssignmentPod') && $('podManagerAssignmentPod').value) || '');
            const selectedName = String(($('podManagerTeamLeader') && $('podManagerTeamLeader').value) || '').trim();
            const backupName = String(($('podManagerBackupTl') && $('podManagerBackupTl').value) || '').trim();
            if (!POD_LIST.includes(targetPod)) throw new Error('Choose a target POD.');
            const selected = activeTeamLeaderDirectoryEntry(selectedName);
            if (!selected) throw new Error('Choose an active Team Leader.');
            if (backupName && backupName === selectedName) throw new Error('The primary Team Leader cannot also be their own Backup TL.');
            const currentTarget = assignedActiveTeamLeaderForPod(targetPod);
            const selectedOldPod = selected.pod;
            const swapName = currentTarget && currentTarget.name !== selectedName ? currentTarget.name : '';
            if (backupName) {
                const backup = activeTeamLeaderDirectoryEntry(backupName);
                const projectedBackupPod = backup && swapName && backup.name === swapName ? selectedOldPod : (backup ? backup.pod : '');
                if (!backup || !projectedBackupPod || teamIdForPod(projectedBackupPod) !== teamIdForPod(targetPod)) throw new Error('Backup TL must resolve to the same operating team as the target POD after the leadership move.');
            }
            const actor = requireAuthenticatedAdminId();
            const updatedAt = nowIso();
            const beforeDirectory = clonePodManagerData(teamLeaderDirectory, []);
            const beforeSchedule = clonePodManagerData(dayOffSchedule, {});
            const next = teamLeaderDirectory.map(entry => {
                if (!entry || entry.active === false) return { ...entry };
                if (entry.name === selectedName) return { ...entry, pod:targetPod, updatedAt, updatedBy:actor };
                if (swapName && entry.name === swapName) return { ...entry, pod:selectedOldPod, updatedAt, updatedBy:actor };
                return { ...entry };
            });
            podTeamManagementSubmitting = true;
            setPodTeamManagementStatus('Saving Team Leader and Backup TL assignments…', 'working');
            try {
                await saveTeamLeaderDirectoryStrict(next, {
                    auditAction:'pod_team_leadership_assignment',
                    auditData:{ targetPod, targetPodName:podDisplayName(targetPod), teamLeader:selectedName, fromPod:selectedOldPod, swappedTeamLeader:swapName || null, swapDestination:swapName ? selectedOldPod : null }
                });
                dayOffSchedule = reconcileDayOffScheduleToPodDirectory(dayOffSchedule);
                clearPrimaryBackupMappings([selectedName, swapName]);
                const map = ensureTeamLeaderBackupMap(targetPod);
                if (backupName) map[selectedName] = backupName;
                else delete map[selectedName];
                dayOffSchedule[targetPod].teamLeaderBackupByName = map;
                try {
                    const recurringConflicts = projectedRecurringBackupCoverageConflicts(targetPod);
                    if (recurringConflicts.length) {
                        throw new Error(`Backup TL double-coverage conflict. ${recurringConflicts.map(describeProjectedBackupCoverageConflict).join(' | ')}.`);
                    }
                    await saveSharedBlobStrict('dayoff_schedule', JSON.stringify(dayOffSchedule), { expectedVersion:dayOffVersion });
                } catch (scheduleError) {
                    setPodTeamManagementStatus('The Backup TL companion write could not be confirmed. Restoring a consistent leadership state…', 'warning');
                    let directoryRolledBack = false;
                    try {
                        await saveTeamLeaderDirectoryStrict(beforeDirectory, {
                            auditAction:'pod_team_leadership_rollback',
                            auditData:{ targetPod, teamLeader:selectedName, backupTeamLeader:backupName || null, reason:getErrorMessage(scheduleError) }
                        });
                        directoryRolledBack = true;
                    } catch (rollbackError) {
                        await reloadTeamLeaderDirectoryFromServerStrict();
                        try { await logAudit('pod_team_leadership_rollback_conflict', { auditCategory:'pod_team_management', targetPod, teamLeader:selectedName, reason:getErrorMessage(scheduleError), rollbackError:getErrorMessage(rollbackError) }); } catch (e) {}
                    }
                    try {
                        await reconcileLeadershipScheduleFromLiveServer(directoryRolledBack ? 'Leadership directory rolled back after Backup TL write failure.' : 'Leadership directory changed concurrently; Backup TL mappings reconciled to live assignments.');
                    } catch (reconcileError) {
                        dayOffSchedule = beforeSchedule;
                        throw new Error(`Leadership update could not be completed and automatic reconciliation could not be confirmed. Refresh before making more leadership changes. ${getErrorMessage(reconcileError)}`);
                    }
                    if (directoryRolledBack) throw new Error(`The leadership update was rolled back because the Backup TL schedule could not be confirmed. The previous leadership state was restored. ${getErrorMessage(scheduleError)}`);
                    throw new Error('Leadership assignments changed concurrently. The live Team Leader directory and Backup TL mappings were reconciled; refresh before retrying.');
                }
                try {
                    await logAudit('pod_backup_tl_assignment', {
                        auditCategory:'pod_team_management', pod:targetPod, podName:podDisplayName(targetPod), primaryTeamLeader:selectedName,
                        backupTeamLeader:backupName || null, modified_by:actor, modified_by_role:'admin'
                    });
                } catch (e) {}
                const swapText = swapName ? ` ${agentDisplayName(swapName)} was safely moved to ${podDisplayName(selectedOldPod)}.` : (selectedOldPod !== targetPod ? ` ${podDisplayName(selectedOldPod)} is now unassigned.` : '');
                const backupText = backupName ? ` Backup TL: ${agentDisplayName(backupName)}.` : ' No Backup TL is assigned.';
                setPodTeamManagementStatus(`${agentDisplayName(selectedName)} now leads ${podDisplayName(targetPod)}.${swapText}${backupText} Firebase confirmed both leadership and Backup TL data.`, 'success');
                renderPodTeamManagement();
            } finally {
                podTeamManagementSubmitting = false;
                renderPodTeamManagementCard();
                if (isOverlayOpen($('podTeamManagementOverlay'))) renderPodTeamManagement();
            }
        }
