        function isoToTimeInputValue(iso) {
            if (!iso) return '';
            try {
                const date = new Date(iso);
                if (!Number.isFinite(date.getTime())) return '';
                const parts = new Intl.DateTimeFormat('en-GB', {
                    timeZone: MANILA_TIME_ZONE,
                    hour: '2-digit',
                    minute: '2-digit',
                    hourCycle: 'h23'
                }).formatToParts(date);
                const hour = parts.find(part => part.type === 'hour');
                const minute = parts.find(part => part.type === 'minute');
                return hour && minute ? hour.value + ':' + minute.value : '';
            } catch (e) { return ''; }
        }

        function timeInputValueToIso(dateStr, timeVal) {
            if (!timeVal) return null;
            const parsed = parseDateStr(dateStr);
            const parts = timeVal.split(':');
            if (parts.length < 2) return null;
            const hour = parseInt(parts[0], 10);
            const minute = parseInt(parts[1], 10);
            if (!Number.isFinite(hour) || !Number.isFinite(minute) || hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
            const epochMs = Date.UTC(
                parsed.y, parsed.m - 1, parsed.d,
                hour - MANILA_UTC_OFFSET_HOURS, minute, 0, 0
            );
            return new Date(epochMs).toISOString();
        }








        function readOrderedEditPunchTimes(dateStr) {
            const specs = [
                ['timeIn', 'editTimeIn'],
                ['startBreak', 'editStartBreak'],
                ['endBreak', 'editEndBreak'],
                ['logOut', 'editLogOut']
            ];
            const values = {};
            let firstMs = null;
            let previousMs = null;
            for (const [field, inputId] of specs) {
                const input = $(inputId);
                const raw = input ? String(input.value || '').trim() : '';
                if (!raw) {
                    values[field] = null;
                    continue;
                }
                const baseIso = timeInputValueToIso(dateStr, raw);
                let ms = baseIso ? new Date(baseIso).getTime() : NaN;
                if (!Number.isFinite(ms)) return { values, error: `Enter a valid ${field === 'timeIn' ? 'Time In' : field === 'startBreak' ? 'Start Break' : field === 'endBreak' ? 'End Break' : 'Time Out'} time.` };
                if (previousMs !== null && ms <= previousMs) ms += MS_PER_DAY;
                if (previousMs !== null && ms <= previousMs) {
                    return { values, error: 'Punch times cannot span more than one overnight date.' };
                }
                if (firstMs === null) firstMs = ms;
                if (firstMs !== null && ms - firstMs > MAX_OVERNIGHT_CARRYOVER_HOURS * MS_PER_HOUR) {
                    return { values, error: `Edited attendance cannot span more than ${MAX_OVERNIGHT_CARRYOVER_HOURS} hours. Check the punch times.` };
                }
                values[field] = new Date(ms).toISOString();
                previousMs = ms;
            }
            return { values, error: null };
        }







        const IMMUTABLE_AUDIT_ROOT = 'auditEvents';
        const LOCAL_AUDIT_MIRROR_KEY = 'trinotime_immutable_audit_mirror_v1';
        const PENDING_IMMUTABLE_AUDIT_PREFIX = 'pending-immutable-audit:';
        const LOCAL_AUDIT_MIRROR_MAX = 300;
        let immutableAuditFlushPromise = null;

        function auditFirebaseUser() {
            try {
                const user = firebase && firebase.auth ? firebase.auth().currentUser : null;
                return user || null;
            } catch (e) { return null; }
        }

        function auditActorContext(entry) {
            const user = auditFirebaseUser();
            let actorRole = 'pod-session';
            let actorName = String((entry && (entry.editedBy || entry.createdBy || entry.cancelledBy || entry.deletedBy || entry.resetBy || entry.actor)) || '');
            if (isAdmin) {
                actorRole = 'admin';
                actorName = actorName || (user && user.email) || 'Admin';
            } else if (isTeamLeader && teamLeaderName) {
                actorRole = 'teamleader';
                actorName = actorName || teamLeaderName;
            } else if (agentSessionAuthenticated && agentSessionName) {
                actorRole = 'agent';
                actorName = actorName || agentSessionName;
            }
            const pod = String((entry && entry.pod) || lockedPod || agentSessionPod || activePod || '');
            const team = validTeamId(activeTeam) ? activeTeam : (pod && pod !== ALL_PODS_LABEL ? teamIdForPod(pod) : '');
            return {
                actorRole,
                actorName,
                team: team || '',
                pod: pod === ALL_PODS_LABEL ? '' : pod,
                firebaseUid: user ? user.uid : '',
                firebaseAuthAnonymous: Boolean(user && user.isAnonymous),
                firebaseEmail: user && !user.isAnonymous && user.email ? user.email : ''
            };
        }

        function firebaseSafeAuditDetails(entry) {
            try {
                const clone = { ...entry };
                delete clone.auditEventId;
                delete clone.ts;
                delete clone.action;
                return JSON.parse(JSON.stringify(clone));
            } catch (e) { return {}; }
        }

        function readLocalAuditMirror() {
            try {
                const raw = safeLocalGet(LOCAL_AUDIT_MIRROR_KEY);
                const parsed = raw ? JSON.parse(raw) : [];
                return Array.isArray(parsed) ? parsed : [];
            } catch (e) { return []; }
        }

        function writeLocalAuditMirror(entry) {
            try {
                const arr = readLocalAuditMirror();
                arr.unshift(entry);
                safeLocalSet(LOCAL_AUDIT_MIRROR_KEY, JSON.stringify(arr.slice(0, LOCAL_AUDIT_MIRROR_MAX)));
            } catch (e) {}
        }

        async function appendImmutableAuditEvent(entry) {
            let db = fbDb;
            if (!db) {
                try { db = await ensureFirebaseReady({ silent:true }); } catch (e) { db = null; }
            }
            const user = auditFirebaseUser();
            if (!db || !user) return { remoteSaved:false, reason:'firebase-unavailable' };
            const context = auditActorContext(entry);
            const cloudEntry = {
                schemaVersion: 2,
                eventId: entry.auditEventId,
                action: String(entry.action || 'unknown'),
                clientTs: String(entry.ts || nowIso()),
                serverTs: firebase.database.ServerValue.TIMESTAMP,
                firebaseUid: context.firebaseUid,
                firebaseAuthAnonymous: context.firebaseAuthAnonymous,
                firebaseEmail: context.firebaseEmail || null,
                actorRole: context.actorRole,
                actorName: context.actorName || null,
                team: context.team || null,
                pod: context.pod || null,
                details: firebaseSafeAuditDetails(entry)
            };
            try {
                await withTimeout(
                    db.ref(IMMUTABLE_AUDIT_ROOT + '/' + entry.auditEventId).set(cloudEntry),
                    FIREBASE_WRITE_TIMEOUT_MS,
                    'Timed out appending the immutable audit event.'
                );
                return { remoteSaved:true };
            } catch (error) {
                return { remoteSaved:false, error };
            }
        }

        async function flushPendingImmutableAuditEvents() {
            if (immutableAuditFlushPromise) return immutableAuditFlushPromise;
            immutableAuditFlushPromise = (async () => {
                if (!fbDb || fbConnected === false) return 0;
                const keys = getLocalKeysWithPrefix(PENDING_IMMUTABLE_AUDIT_PREFIX);
                let flushed = 0;
                for (const storageKey of keys) {
                    let entry = null;
                    try { entry = JSON.parse(safeLocalGet(storageKey) || 'null'); } catch (e) {}
                    if (!entry || !entry.auditEventId || !entry.action) {
                        safeLocalRemove(storageKey);
                        continue;
                    }
                    const result = await appendImmutableAuditEvent(entry);
                    if (result && result.remoteSaved) {
                        safeLocalRemove(storageKey);
                        flushed += 1;
                    }
                }
                return flushed;
            })().finally(() => { immutableAuditFlushPromise = null; });
            return immutableAuditFlushPromise;
        }

        function normalizeCloudAuditEvent(value) {
            if (!value || typeof value !== 'object') return null;
            const details = value.details && typeof value.details === 'object' ? value.details : {};
            let ts = value.clientTs || '';
            if (Number.isFinite(Number(value.serverTs))) ts = new Date(Number(value.serverTs)).toISOString();
            return {
                ...details,
                auditEventId: value.eventId || '',
                ts: ts || new Date().toISOString(),
                action: value.action || 'unknown',
                firebaseUid: value.firebaseUid || '',
                firebaseAuthAnonymous: Boolean(value.firebaseAuthAnonymous),
                auditActorRole: value.actorRole || '',
                auditActorName: value.actorName || '',
                auditTeam: value.team || '',
                auditPod: value.pod || '',
                serverTs: value.serverTs || null
            };
        }

        function canonicalAuditActor(details = {}) {
            const context = auditActorContext(details);
            let permissionActor = null;
            try { permissionActor = TrinoPermissions && typeof TrinoPermissions.actor === 'function' ? TrinoPermissions.actor() : null; } catch (e) {}
            let id = String(details.actor_id || (permissionActor && permissionActor.id) || '');
            if (!id) id = context.firebaseUid || context.firebaseEmail || context.actorName || currentEmployee || 'pod-session';
            return {
                id,
                name: String(details.actor_name || (permissionActor && permissionActor.name) || context.actorName || id),
                role: String(details.actor_role || (permissionActor && permissionActor.role) || context.actorRole || 'pod_session'),
                pod: String(details.actor_pod || (permissionActor && permissionActor.pod) || context.pod || ''),
                firebaseUid: context.firebaseUid || ''
            };
        }

        function inferAuditTarget(details = {}) {
            if (details.target && typeof details.target === 'object') return details.target;
            const name = String(details.targetAgent || details.targetTeamLeader || details.name || '');
            if (!name) return null;
            let type = String(details.targetRole || '');
            if (!type && details.targetAgent) type = 'Agent';
            if (!type && details.targetTeamLeader) type = 'Team Leader';
            if (!type) type = 'Record Subject';
            return { type, name, pod: String(details.pod || '') };
        }

        function inferAuditCategory(action) {
            const value = String(action || '').toLowerCase();
            if (value.includes('password') || value.includes('auth') || value.includes('login')) return 'security';
            if (value.includes('attendance') || value === 'punch' || value === 'edit' || value.includes('logout')) return 'attendance';
            if (value.includes('leave')) return 'leave';
            if (value.includes('overtime') || value.includes('hourly_rate')) return 'payroll';
            if (value.includes('dayoff') || value.includes('shift')) return 'schedule';
            if (value.includes('conflict')) return 'data_conflict';
            if (value.includes('announcement')) return 'communications';
            if (value.includes('network')) return 'network';
            return 'operations';
        }

        function activeBackupTlAuditContext() {
            if (!isTeamLeader || isAdmin || !teamLeaderName) return null;
            try {
                const delegation = currentTeamLeaderDelegation();
                if (!delegation) return null;
                return {
                    active:true,
                    backupTeamLeader:teamLeaderName,
                    primaryTeamLeader:delegation.primaryName,
                    delegatedPod:delegation.pod,
                    backupHomePod:delegation.homePod,
                    date:delegation.date,
                    permissionScope:'team_leader_operations_only'
                };
            } catch (e) { return null; }
        }

        function normalizeAuditDetails(action, details) {
            const raw = details && typeof details === 'object' ? { ...details } : {};
            const actor = canonicalAuditActor(raw);
            const target = inferAuditTarget(raw);
            const appVersion = (document.querySelector('meta[name="trinotime-version"]') || {}).content || '';
            const backupCoverage = raw.backup_coverage && typeof raw.backup_coverage === 'object' ? raw.backup_coverage : activeBackupTlAuditContext();
            return {
                ...raw,
                ...(backupCoverage ? { performed_under_backup_coverage:true, backup_coverage:backupCoverage } : {}),
                audit_schema_version: 3,
                event_type: String(action || 'unknown'),
                audit_category: String(raw.auditCategory || raw.audit_category || inferAuditCategory(action)),
                occurred_at: String(raw.occurred_at || raw.ts || nowIso()),
                actor_id: actor.id,
                actor_name: actor.name,
                actor_role: actor.role,
                actor_pod: actor.pod,
                actor: { id: actor.id, name: actor.name, role: actor.role, pod: actor.pod, firebase_uid:actor.firebaseUid || '' },
                ...(target ? { target } : {}),
                audit_source: { app:'TrinoTime', channel:'web', version:appVersion }
            };
        }

        async function logAudit(action, details) {
            try {
                const eventId = createMutationToken().replace(/[.#$\[\]\/]/g, '_');
                const normalizedDetails = normalizeAuditDetails(action, details);
                const entry = {
                    auditEventId: eventId,
                    event_id: eventId,
                    ts: nowIso(),
                    action,
                    ...normalizedDetails
                };
                if (action === 'punch' || action === 'tl_punch') recordServerStampedPunch(entry);


                writeLocalAuditMirror(entry);
                const remote = await appendImmutableAuditEvent(entry);
                if (remote.remoteSaved) {
                    safeLocalRemove(PENDING_IMMUTABLE_AUDIT_PREFIX + eventId);
                } else {
                    safeLocalSet(PENDING_IMMUTABLE_AUDIT_PREFIX + eventId, JSON.stringify(entry));
                    if (remote.error) {
                        try { appendSyncAudit('immutable_audit_pending', 'Audit event is queued locally because the append-only cloud path was unavailable.', { action, error:getErrorMessage(remote.error) }); } catch (e) {}
                    }
                }
                return { entry, remoteSaved:Boolean(remote.remoteSaved) };
            } catch (e) { return { entry:null, remoteSaved:false, error:e }; }
        }

        window.TrinoTimeCore = window.TrinoTimeCore || {};
        window.TrinoTimeCore.audit = Object.freeze({
            log: logAudit,
            actor: () => canonicalAuditActor({}),
            normalize: normalizeAuditDetails,
            schemaVersion: 3
        });
        window.TrinoTimeCore.conflicts = Object.freeze({
            summary: getRecordConflictSummary,
            revision: recordRevision,
            read(key) {
                try { return JSON.parse(safeLocalGet(RECORD_CONFLICT_PREFIX + String(key || '')) || 'null'); } catch (e) { return null; }
            }
        });

        async function getAuditLog() {
            const merged = [];
            if (isAdmin && fbDb) {
                try {
                    const snap = await withTimeout(
                        fbDb.ref(IMMUTABLE_AUDIT_ROOT).orderByChild('serverTs').limitToLast(250).once('value'),
                        FIREBASE_READ_TIMEOUT_MS,
                        'Timed out loading immutable audit events.'
                    );
                    const val = snap.val() || {};
                    Object.keys(val).forEach(key => {
                        const normalized = normalizeCloudAuditEvent(val[key]);
                        if (normalized) {
                            if (!normalized.auditEventId) normalized.auditEventId = key;
                            merged.push(normalized);
                        }
                    });
                } catch (e) {}
            }
            merged.push(...readLocalAuditMirror());


            try {
                const raw = await appStorage.get('audit_log');
                const legacy = raw ? JSON.parse(raw) : [];
                if (Array.isArray(legacy)) merged.push(...legacy);
            } catch (e) {}

            const seen = new Set();
            return merged.filter(entry => {
                if (!entry || !entry.action) return false;
                const key = entry.auditEventId || [entry.action, entry.ts, entry.name || '', entry.field || ''].join('|');
                if (seen.has(key)) return false;
                seen.add(key);
                return true;
            }).sort((a, b) => new Date(b.ts || 0).getTime() - new Date(a.ts || 0).getTime()).slice(0, 300);
        }






        const SPEEDTEST_MODULE_VERSION = '1.13.1';
        const SPEEDTEST_MODULE_URLS = [
            'https://cdn.jsdelivr.net/npm/@cloudflare/speedtest@1.13.1/dist/speedtest.js',
            'https://esm.sh/@cloudflare/speedtest@1.13.1'
        ];
        const SPEEDTEST_DOWNLOAD_API_URL = 'https://speed.cloudflare.com/__down';
        const SPEEDTEST_UPLOAD_API_URL = 'https://speed.cloudflare.com/__up';
        const SPEEDTEST_QUICK_PROFILE_NAME = 'trinotime-work-readiness-v1';
        const SPEEDTEST_FULL_PROFILE_NAME = 'trinotime-gigabit-ramp-v2';
        const SPEEDTEST_BANDWIDTH_FINISH_MS = 1000;
        const SPEEDTEST_BANDWIDTH_MIN_MS = 10;
        const SPEEDTEST_BANDWIDTH_PERCENTILE = 0.90;





        const SPEEDTEST_QUICK_PROFILE = [
            { type: 'latency', numPackets: 1 },
            { type: 'download', bytes: 1e5, count: 1, bypassMinDuration: true },
            { type: 'latency', numPackets: 10 },
            { type: 'download', bytes: 1e5, count: 2 },
            { type: 'download', bytes: 1e6, count: 2 },
            { type: 'download', bytes: 8e6, count: 1 },
            { type: 'upload', bytes: 1e5, count: 2 },
            { type: 'upload', bytes: 1e6, count: 2 },
            { type: 'upload', bytes: 8e6, count: 1 }
        ];



        const SPEEDTEST_FULL_PROFILE = [
            { type: 'latency', numPackets: 1 },
            { type: 'download', bytes: 1e5, count: 1, bypassMinDuration: true },
            { type: 'latency', numPackets: 20 },
            { type: 'download', bytes: 1e5, count: 9 },
            { type: 'download', bytes: 1e6, count: 8 },
            { type: 'upload', bytes: 1e5, count: 8 },
            { type: 'upload', bytes: 1e6, count: 6 },
            { type: 'download', bytes: 1e7, count: 6 },
            { type: 'upload', bytes: 1e7, count: 4 },
            { type: 'download', bytes: 2.5e7, count: 4 },
            { type: 'upload', bytes: 2.5e7, count: 4 },
            { type: 'download', bytes: 1e8, count: 3 },
            { type: 'upload', bytes: 5e7, count: 3 },
            { type: 'download', bytes: 2.5e8, count: 2 },
            { type: 'upload', bytes: 1e8, count: 2 },
            { type: 'upload', bytes: 2.5e8, count: 1 }
        ];
        const SPEEDTEST_QUICK_RETEST_COOLDOWN_MS = 30 * 1000;
        const SPEEDTEST_FULL_RETEST_COOLDOWN_MS = 90 * 1000;
        const SPEEDTEST_FRESH_MS = 4 * 60 * 60 * 1000;
        const SPEEDTEST_RECENT_MS = 24 * 60 * 60 * 1000;
        let speedTestModulePromise = null;
        let speedTestRunning = false;
        let speedTestRunningMode = null;
        let speedTestLastMode = 'quick';
        let activeSpeedTestEngine = null;
        let speedTestCancelHandler = null;
        let speedTestCancelRequested = false;
        let speedTestCloseAfterCancel = false;
        let speedTestRetentionCleanupStarted = false;

        function speedTestStorageKey(id) {
            return 'speedtest:' + id;
        }

        function clampNetworkSetting(value, min, max, fallback) {
            const n = Number(value);
            if (!Number.isFinite(n)) return fallback;
            return Math.min(max, Math.max(min, n));
        }

        function mergeNetworkQualitySettings(saved) {
            const src = saved && typeof saved === 'object' ? saved : {};
            const savedVersion = Number(src.settingsVersion) || 1;
            const migrateSpeedTargets = savedVersion < NETWORK_QUALITY_SETTINGS_VERSION;
            return {
                settingsVersion: NETWORK_QUALITY_SETTINGS_VERSION,
                pingMaxMs: clampNetworkSetting(src.pingMaxMs, 10, 1000, DEFAULT_NETWORK_QUALITY_SETTINGS.pingMaxMs),
                jitterMaxMs: clampNetworkSetting(src.jitterMaxMs, 1, 500, DEFAULT_NETWORK_QUALITY_SETTINGS.jitterMaxMs),



                downloadMinMbps: migrateSpeedTargets ? DEFAULT_NETWORK_QUALITY_SETTINGS.downloadMinMbps :
                    clampNetworkSetting(src.downloadMinMbps, 1, 10000, DEFAULT_NETWORK_QUALITY_SETTINGS.downloadMinMbps),
                uploadMinMbps: migrateSpeedTargets ? DEFAULT_NETWORK_QUALITY_SETTINGS.uploadMinMbps :
                    clampNetworkSetting(src.uploadMinMbps, 1, 10000, DEFAULT_NETWORK_QUALITY_SETTINGS.uploadMinMbps),
                retentionDays: Math.round(clampNetworkSetting(src.retentionDays, 30, 365, DEFAULT_NETWORK_QUALITY_SETTINGS.retentionDays))
            };
        }

        async function loadNetworkQualitySettings() {
            try {
                const raw = await appStorage.get(NETWORK_SETTINGS_KEY);
                networkQualitySettings = raw ? mergeNetworkQualitySettings(JSON.parse(raw)) : { ...DEFAULT_NETWORK_QUALITY_SETTINGS };
            } catch (e) {
                networkQualitySettings = { ...DEFAULT_NETWORK_QUALITY_SETTINGS };
            }
            return networkQualitySettings;
        }

        function persistNetworkQualitySettings(nextSettings) {
            const merged = mergeNetworkQualitySettings(nextSettings);
            networkQualitySettings = merged;
            const payload = JSON.stringify(merged);
            safeLocalSet(PENDING_PREFIX + NETWORK_SETTINGS_KEY, payload);
            markPendingMutation();
            publishUpdate();
            updatePendingSyncUi();
            scheduleIncrementalRender({ type: 'networksettings' });
            void appStorage.set(NETWORK_SETTINGS_KEY, payload).then((writeResult) => {
                if (writeResult && writeResult.remoteSaved && safeLocalGet(PENDING_PREFIX + NETWORK_SETTINGS_KEY) === payload) {
                    safeLocalRemove(PENDING_PREFIX + NETWORK_SETTINGS_KEY);
                } else {
                    schedulePendingSyncRetry();
                }
                updatePendingSyncUi();
            }).catch((error) => {
                reportAppError('Network quality settings sync', error);
                schedulePendingSyncRetry();
                updatePendingSyncUi();
            });
            speedTestRetentionCleanupStarted = false;
            refreshSpeedTestPanel();
            renderNetworkQualitySettingsControls();
            if (isOverlayOpen($('networkOverlay'))) renderNetworkTab();
            scheduleSpeedTestRetentionCleanup();
        }

        async function loadAllSpeedTests() {
            try {
                const keys = await appStorage.list('speedtest:');
                allSpeedTests = {};
                for (const key of keys) {
                    try {
                        const raw = await appStorage.get(key);
                        if (!raw) continue;
                        const parsed = JSON.parse(raw);
                        if (parsed && parsed.id) allSpeedTests[parsed.id] = parsed;
                    } catch (e) {}
                }
            } catch (e) { allSpeedTests = {}; }
        }

        function saveSpeedTestResult(result) {
            if (!result || !result.id) return;
            allSpeedTests[result.id] = result;
            const key = speedTestStorageKey(result.id);
            const payload = JSON.stringify(result);



            safeLocalSet(PENDING_PREFIX + key, payload);
            markPendingMutation();
            publishUpdate();
            updatePendingSyncUi();
            scheduleIncrementalRender({ type:'speedtests', id:result.id, name:result.name, pod:result.pod, date:result.date });

            void appStorage.set(key, payload).then((writeResult) => {
                if (writeResult && writeResult.remoteSaved && safeLocalGet(PENDING_PREFIX + key) === payload) {
                    safeLocalRemove(PENDING_PREFIX + key);
                } else {
                    schedulePendingSyncRetry();
                }
                updatePendingSyncUi();
            }).catch((error) => {
                reportAppError('Speed test sync', error);
                schedulePendingSyncRetry();
                updatePendingSyncUi();
            });
        }

        function finiteNumber(value) {
            if (value === null || value === undefined || value === '') return null;
            const n = Number(value);
            return Number.isFinite(n) ? n : null;
        }

        function formatSpeedMetric(value, decimals = 1) {
            const n = finiteNumber(value);
            return n === null ? '\u2014' : n.toFixed(decimals);
        }

        function speedTestStatus(item) {
            if (!item) return 'unknown';
            if (item.status === 'failed' || item.status === 'cancelled') return item.status;
            const ping = finiteNumber(item.pingMs);
            const down = finiteNumber(item.downloadMbps);
            const up = finiteNumber(item.uploadMbps);
            return ping !== null && down !== null && up !== null && down > 0 && up > 0 ? 'complete' : (item.status || 'unknown');
        }

        function isCompletedSpeedTest(item) {
            return speedTestStatus(item) === 'complete';
        }

        function getLatestSpeedTestForEmployee(name, options = {}) {
            if (!name) return null;
            const completedOnly = options.completedOnly !== false;
            return Object.values(allSpeedTests)
                .filter(item => item && item.name === name && item.ts && (!completedOnly || isCompletedSpeedTest(item)))
                .sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime())[0] || null;
        }

        function getLatestSpeedTestAttemptForEmployee(name) {
            return getLatestSpeedTestForEmployee(name, { completedOnly: false });
        }

        function speedTestSessionState(name) {
            const rec = name ? getTodayRecord(name) : null;
            if (!rec || !rec.timeIn) return 'Before Time In';
            if (rec.logOut) return 'After Time Out';
            if (rec.startBreak && !rec.endBreak) return 'On Break';
            return 'Clocked In';
        }

        function normalizeSpeedTestMode(value) {
            if (value && typeof value === 'object') {
                if (value.testMode === 'quick' || value.testMode === 'full') return value.testMode;
                return value.highThroughputProfile ? 'full' : 'legacy';
            }
            return value === 'full' ? 'full' : 'quick';
        }

        function speedTestModeLabel(value) {
            const mode = normalizeSpeedTestMode(value);
            if (mode === 'full') return 'Full Diagnostic';
            if (mode === 'legacy') return 'Legacy Test';
            return 'Quick Check';
        }

        function speedTestProfileForMode(mode) {
            const full = normalizeSpeedTestMode(mode) === 'full';
            return {
                mode: full ? 'full' : 'quick',
                label: full ? 'Full Diagnostic' : 'Quick Check',
                profileName: full ? SPEEDTEST_FULL_PROFILE_NAME : SPEEDTEST_QUICK_PROFILE_NAME,
                measurements: full ? SPEEDTEST_FULL_PROFILE : SPEEDTEST_QUICK_PROFILE,
                timeoutMs: full ? 90000 : 35000,
                finishRequestDuration: full ? SPEEDTEST_BANDWIDTH_FINISH_MS : 650,
                highThroughput: full
            };
        }

        function buildSpeedTestBase(name, mode = 'quick') {
            const profile = speedTestProfileForMode(mode);
            const testedPod = podOf(name) || (activePod !== ALL_PODS_LABEL ? activePod : 'Unassigned');
            const attendance = getTodayRecord(name) || {};
            const attendanceDate = attendanceRecordDate(attendance, todayKeyPart());
            return {
                id: createMutationToken(),
                ts: nowIso(),
                date: attendanceDate,
                name,
                pod: testedPod,
                attendanceRecordKey: attendanceDate + '|' + name,
                attendanceState: speedTestSessionState(name),
                timeIn: attendance.timeIn || null,
                provider: 'Cloudflare',
                engine: '@cloudflare/speedtest',
                engineVersion: SPEEDTEST_MODULE_VERSION,
                testMode: profile.mode,
                profile: profile.profileName,
                measurementEndpoint: 'speed.cloudflare.com',
                highThroughputProfile: profile.highThroughput
            };
        }

        function metricQuality(field, value) {
            const n = finiteNumber(value);
            if (n === null) return 'unknown';
            const s = networkQualitySettings;
            let target;
            let lowerIsBetter = false;
            if (field === 'pingMs') { target = s.pingMaxMs; lowerIsBetter = true; }
            else if (field === 'jitterMs') { target = s.jitterMaxMs; lowerIsBetter = true; }
            else if (field === 'downloadMbps') target = s.downloadMinMbps;
            else if (field === 'uploadMbps') target = s.uploadMinMbps;
            else return 'unknown';

            if (lowerIsBetter) {
                if (n <= target * 0.5) return 'excellent';
                if (n <= target) return 'good';
                if (n <= target * 1.5) return 'attention';
                return 'poor';
            }
            if (n >= target * 2) return 'excellent';
            if (n >= target) return 'good';
            if (n >= target * 0.5) return 'attention';
            return 'poor';
        }

        function getNetworkQuality(item) {
            const status = speedTestStatus(item);
            if (status === 'failed') return { key:'failed', label:'Failed' };
            if (status === 'cancelled') return { key:'cancelled', label:'Cancelled' };
            if (status !== 'complete') return { key:'unknown', label:'Unknown' };
            const metrics = [
                metricQuality('pingMs', item.pingMs),
                metricQuality('downloadMbps', item.downloadMbps),
                metricQuality('uploadMbps', item.uploadMbps)
            ];
            if (finiteNumber(item.jitterMs) !== null) metrics.push(metricQuality('jitterMs', item.jitterMs));
            const order = { excellent:0, good:1, attention:2, poor:3, unknown:4 };
            const worst = metrics.reduce((a, b) => (order[b] > order[a] ? b : a), 'excellent');
            const labels = { excellent:'Excellent', good:'Good', attention:'Needs Attention', poor:'Poor', unknown:'Unknown' };
            return { key:worst, label:labels[worst] || 'Unknown' };
        }

        function formatNetworkTargetValue(value) {
            const n = Number(value);
            return Number.isInteger(n) ? String(n) : Number(n || 0).toFixed(1);
        }

        function networkTargetSummaryText() {
            const s = networkQualitySettings || DEFAULT_NETWORK_QUALITY_SETTINGS;
            return `Download ≥ ${formatNetworkTargetValue(s.downloadMinMbps)} Mbps · Upload ≥ ${formatNetworkTargetValue(s.uploadMinMbps)} Mbps · Ping ≤ ${formatNetworkTargetValue(s.pingMaxMs)} ms · Jitter ≤ ${formatNetworkTargetValue(s.jitterMaxMs)} ms`;
        }

        function networkRequirementFailures(item) {
            if (!isCompletedSpeedTest(item)) return [];
            const s = networkQualitySettings;
            const failures = [];
            const ping = finiteNumber(item.pingMs);
            const jitter = finiteNumber(item.jitterMs);
            const down = finiteNumber(item.downloadMbps);
            const up = finiteNumber(item.uploadMbps);
            if (ping === null || ping > s.pingMaxMs) failures.push(`Ping ${ping === null ? 'unavailable' : ping.toFixed(1) + ' ms'} exceeds ${formatNetworkTargetValue(s.pingMaxMs)} ms`);
            if (jitter === null || jitter > s.jitterMaxMs) failures.push(`Jitter ${jitter === null ? 'unavailable' : jitter.toFixed(1) + ' ms'} exceeds ${formatNetworkTargetValue(s.jitterMaxMs)} ms`);
            if (down === null || down < s.downloadMinMbps) failures.push(`Download ${down === null ? 'unavailable' : down.toFixed(1) + ' Mbps'} is below ${formatNetworkTargetValue(s.downloadMinMbps)} Mbps`);
            if (up === null || up < s.uploadMinMbps) failures.push(`Upload ${up === null ? 'unavailable' : up.toFixed(1) + ' Mbps'} is below ${formatNetworkTargetValue(s.uploadMinMbps)} Mbps`);
            return failures;
        }

        function getNetworkReadiness(item) {
            const status = speedTestStatus(item);
            if (status === 'failed') return { key:'issue', label:'CONNECTION ISSUE', detail:'The network check could not complete. Review the connection and try again.' };
            if (status === 'cancelled') return { key:'unknown', label:'NOT TESTED', detail:'The network check was cancelled before a result was recorded.' };
            if (status !== 'complete') return { key:'unknown', label:'NOT TESTED', detail:'Run a Quick Check to verify this connection against the current Admin targets.' };
            const failures = networkRequirementFailures(item);
            if (failures.length) return { key:'issue', label:'CONNECTION ISSUE', detail:failures.slice(0, 2).join(' · ') + (failures.length > 2 ? ` · +${failures.length - 2} more` : '') };
            const s = networkQualitySettings;
            const nearTarget = Number(item.pingMs) > s.pingMaxMs * 0.8 ||
                Number(item.jitterMs) > s.jitterMaxMs * 0.8 ||
                Number(item.downloadMbps) < s.downloadMinMbps * 1.2 ||
                Number(item.uploadMbps) < s.uploadMinMbps * 1.2;
            return nearTarget
                ? { key:'caution', label:'WORK READY — CAUTION', detail:'All current requirements are met, but one or more measurements are close to the configured limit.' }
                : { key:'ready', label:'WORK READY', detail:'This connection meets all current TrinoTime work-readiness requirements.' };
        }

        function updateNetworkTargetCopy() {
            const text = networkTargetSummaryText();
            const speedTarget = $('speedtestTargetSummary');
            const dailyTarget = $('networkDailyTargetText');
            if (speedTarget) speedTarget.textContent = text;
            if (dailyTarget) dailyTarget.textContent = text;
        }

        function updateSpeedTestReadinessDisplay(item) {
            const panel = $('speedtestReadinessPanel');
            const badge = $('speedtestReadinessBadge');
            const detail = $('speedtestReadinessDetail');
            if (!panel || !badge || !detail) return;
            const readiness = item ? getNetworkReadiness(item) : getNetworkReadiness(null);
            panel.className = 'speedtest-readiness readiness-' + readiness.key;
            badge.textContent = readiness.label;
            detail.textContent = readiness.detail;
        }

        function updateSpeedTestModeCopy(mode) {
            const profile = speedTestProfileForMode(mode || speedTestRunningMode || 'quick');
            const badge = $('speedtestModeBadge');
            const note = $('speedtestModeNote');
            if (badge) badge.textContent = profile.label;
            if (note) {
                note.innerHTML = profile.mode === 'full'
                    ? '<strong>Full Diagnostic</strong> uses the high-throughput ramp for deeper troubleshooting. Fast connections may transfer hundreds of MB and individual samples can reach 250 MB.'
                    : '<strong>Quick Check</strong> is optimized for work readiness and low data use. It is designed for about 20 MB of planned test payload and may use less depending on the connection.';
            }
        }

        function relativeSpeedTestAge(ts) {
            const tsMs = new Date(ts || '').getTime();
            if (!Number.isFinite(tsMs)) return { text:'No recent test', key:'stale', ageMs:null };
            const ageMs = Math.max(0, getTrueNowMs() - tsMs);
            let text;
            if (ageMs < 60 * 1000) text = 'Tested just now';
            else if (ageMs < 60 * 60 * 1000) {
                const mins = Math.floor(ageMs / 60000);
                text = `Tested ${mins} min ago`;
            } else if (ageMs < 24 * 60 * 60 * 1000) {
                const hrs = Math.floor(ageMs / 3600000);
                text = `Tested ${hrs} hr${hrs === 1 ? '' : 's'} ago`;
            } else {
                const days = Math.floor(ageMs / 86400000);
                text = `Tested ${days} day${days === 1 ? '' : 's'} ago`;
            }
            return {
                text,
                ageMs,
                key: ageMs <= SPEEDTEST_FRESH_MS ? 'fresh' : (ageMs <= SPEEDTEST_RECENT_MS ? 'recent' : 'stale')
            };
        }

        function formatCooldown(ms) {
            const sec = Math.max(0, Math.ceil(ms / 1000));
            const m = Math.floor(sec / 60);
            const s = sec % 60;
            return m ? `${m}:${String(s).padStart(2, '0')}` : `${s}s`;
        }

        function speedTestCooldownRemaining(name, mode = 'quick') {
            if (!name) return 0;
            const normalizedMode = normalizeSpeedTestMode(mode);
            const cooldownMs = normalizedMode === 'full' ? SPEEDTEST_FULL_RETEST_COOLDOWN_MS : SPEEDTEST_QUICK_RETEST_COOLDOWN_MS;
            const latest = Object.values(allSpeedTests)
                .filter(item => item && item.name === name && item.ts && isCompletedSpeedTest(item) && normalizeSpeedTestMode(item) === normalizedMode)
                .sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime())[0] || null;
            if (!latest) return 0;
            const tsMs = new Date(latest.ts).getTime();
            if (!Number.isFinite(tsMs)) return 0;
            return Math.max(0, cooldownMs - (getTrueNowMs() - tsMs));
        }

        function setSpeedTestMetricDisplays(summary) {
            summary = summary || {};
            const latency = finiteNumber(summary.latency);
            const jitter = finiteNumber(summary.jitter);
            const downBps = finiteNumber(summary.download);
            const upBps = finiteNumber(summary.upload);
            if ($('speedtestPing')) $('speedtestPing').textContent = latency === null ? '\u2014' : latency.toFixed(1);
            if ($('speedtestJitter')) $('speedtestJitter').textContent = jitter === null ? '\u2014' : jitter.toFixed(1);
            if ($('speedtestDownload')) $('speedtestDownload').textContent = downBps === null ? '\u2014' : (downBps / 1e6).toFixed(1);
            if ($('speedtestUpload')) $('speedtestUpload').textContent = upBps === null ? '\u2014' : (upBps / 1e6).toFixed(1);
        }

        function updateSpeedTestQualityDisplay(item) {
            const badge = $('speedtestQualityBadge');
            if (!badge) return;
            const quality = item ? getNetworkQuality(item) : { key:'unknown', label:'Not tested' };
            badge.className = 'network-quality-badge quality-' + quality.key;
            badge.textContent = quality.label;
        }

        function updateSpeedTestFreshnessDisplay() {
            const badge = $('speedtestFreshnessBadge');
            if (!badge) return;
            const latest = getLatestSpeedTestForEmployee(currentEmployee);
            const age = latest ? relativeSpeedTestAge(latest.ts) : { text:'No recent test', key:'stale' };
            badge.className = 'network-freshness-badge freshness-' + age.key;
            badge.textContent = age.text;
        }

        function setSpeedTestFreshnessMessage(text, key = 'recent') {
            const badge = $('speedtestFreshnessBadge');
            if (!badge) return;
            badge.className = 'network-freshness-badge freshness-' + key;
            badge.textContent = text;
        }

        function hasSuccessfulSpeedTestToday(name) {
            if (!name) return false;
            const today = todayKeyPart();
            return Object.values(allSpeedTests).some(item => item && item.name === name && item.date === today && isCompletedSpeedTest(item));
        }

        function refreshSpeedTestReminder() {
            const reminder = $('speedtestReminder');
            if (!reminder) return;
            const shouldShow = !isAdmin && !isTeamLeader && !!currentEmployee &&
                speedTestSessionState(currentEmployee) === 'Before Time In' && !hasSuccessfulSpeedTestToday(currentEmployee);
            reminder.classList.toggle('show', shouldShow);
            reminder.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');
        }

        function refreshSpeedTestPanel(options = {}) {
            const quickBtn = $('speedtestRunBtn');
            const fullBtn = $('speedtestFullRunBtn');
            const cancelBtn = $('speedtestCancelBtn');
            const meta = $('speedtestLastMeta');
            const closeBtn = $('speedtestCloseBtn');
            if (!quickBtn || !meta) return;
            updateNetworkTargetCopy();
            updateSpeedTestModeCopy(speedTestRunningMode || speedTestLastMode || 'quick');

            const quickCooldown = currentEmployee ? speedTestCooldownRemaining(currentEmployee, 'quick') : 0;
            const fullCooldown = currentEmployee ? speedTestCooldownRemaining(currentEmployee, 'full') : 0;
            quickBtn.disabled = speedTestRunning || !currentEmployee || quickCooldown > 0;
            if (fullBtn) fullBtn.disabled = speedTestRunning || !currentEmployee || fullCooldown > 0;
            if (speedTestRunning) {
                quickBtn.textContent = speedTestRunningMode === 'quick' ? 'Quick Check Running…' : 'Run Quick Check';
                if (fullBtn) fullBtn.textContent = speedTestRunningMode === 'full' ? 'Diagnostic Running…' : 'Full Diagnostic';
            } else {
                quickBtn.textContent = quickCooldown > 0 ? 'Quick Check in ' + formatCooldown(quickCooldown) : 'Run Quick Check';
                if (fullBtn) fullBtn.textContent = fullCooldown > 0 ? 'Diagnostic in ' + formatCooldown(fullCooldown) : 'Full Diagnostic';
            }
            quickBtn.setAttribute('aria-busy', speedTestRunning && speedTestRunningMode === 'quick' ? 'true' : 'false');
            if (fullBtn) fullBtn.setAttribute('aria-busy', speedTestRunning && speedTestRunningMode === 'full' ? 'true' : 'false');
            if (cancelBtn) {
                cancelBtn.hidden = !speedTestRunning;
                cancelBtn.disabled = !speedTestRunning || speedTestCancelRequested;
                cancelBtn.textContent = speedTestCancelRequested ? 'Cancelling…' : 'Cancel Test';
            }
            if (closeBtn) {
                closeBtn.textContent = speedTestRunning ? 'Cancel & Close' : 'Close';
                closeBtn.classList.toggle('save', speedTestRunning);
                closeBtn.classList.toggle('cancel', !speedTestRunning);
            }
            if (speedTestRunning) return;
            if (options.preserveDisplay) {
                refreshSpeedTestReminder();
                return;
            }

            const latest = getLatestSpeedTestForEmployee(currentEmployee);
            if (!currentEmployee) {
                setSpeedTestMetricDisplays(null);
                updateSpeedTestQualityDisplay(null);
                updateSpeedTestReadinessDisplay(null);
                updateSpeedTestFreshnessDisplay();
                meta.textContent = 'Select and verify your Agent name to run a test.';
                refreshSpeedTestReminder();
                return;
            }
            if (!latest) {
                setSpeedTestMetricDisplays(null);
                updateSpeedTestQualityDisplay(null);
                updateSpeedTestReadinessDisplay(null);
                updateSpeedTestFreshnessDisplay();
                const attempt = getLatestSpeedTestAttemptForEmployee(currentEmployee);
                if (attempt && speedTestStatus(attempt) === 'failed') {
                    meta.innerHTML = `<strong>${escapeHtml(agentDisplayName(currentEmployee))}</strong>'s latest ${escapeHtml(speedTestModeLabel(attempt))} attempt failed. You can retry when the connection is ready.`;
                } else {
                    meta.innerHTML = `<strong>${escapeHtml(agentDisplayName(currentEmployee))}</strong> has no successful network checks yet.`;
                }
                refreshSpeedTestReminder();
                return;
            }
            if ($('speedtestPing')) $('speedtestPing').textContent = formatSpeedMetric(latest.pingMs, 1);
            if ($('speedtestJitter')) $('speedtestJitter').textContent = formatSpeedMetric(latest.jitterMs, 1);
            if ($('speedtestDownload')) $('speedtestDownload').textContent = formatSpeedMetric(latest.downloadMbps, 1);
            if ($('speedtestUpload')) $('speedtestUpload').textContent = formatSpeedMetric(latest.uploadMbps, 1);
            updateSpeedTestQualityDisplay(latest);
            updateSpeedTestReadinessDisplay(latest);
            updateSpeedTestFreshnessDisplay();
            const when = new Date(latest.ts).toLocaleString('en-US', {
                timeZone: MANILA_TIME_ZONE, month:'short', day:'numeric', hour:'numeric', minute:'2-digit'
            });
            const syncState = hasPendingWrite(speedTestStorageKey(latest.id)) ? 'saved locally · syncing' : 'saved';
            const age = relativeSpeedTestAge(latest.ts);
            meta.innerHTML = `Latest for <strong>${escapeHtml(agentDisplayName(currentEmployee))}</strong>: ${escapeHtml(speedTestModeLabel(latest))} · ${escapeHtml(when)} PHT · ${escapeHtml(age.text)} · ${escapeHtml(syncState)}.`;
            refreshSpeedTestReminder();
        }

        function setSpeedTestProgress(percent, message) {
            const progress = $('speedtestProgress');
            const fill = $('speedtestProgressFill');
            const status = $('speedtestStatusText');
            if (progress) progress.classList.add('is-active');
            if (fill) {
                const normalized = Math.max(0, Math.min(100, Number(percent) || 0));


                fill.style.setProperty('--speedtest-progress-scale', String(normalized / 100));
            }
            if (status) status.textContent = message || 'Testing\u2026';
        }

        async function getSpeedTestConstructor() {
            if (!speedTestModulePromise) {
                speedTestModulePromise = (async () => {
                    let lastError = null;
                    for (const url of SPEEDTEST_MODULE_URLS) {
                        try {
                            const mod = await import(url);
                            const ctor = mod && (mod.default || mod.SpeedTest);
                            if (typeof ctor === 'function') return ctor;
                            throw new Error('The speed-test module did not expose a constructor.');
                        } catch (error) {
                            lastError = error;
                        }
                    }
                    throw lastError || new Error('Could not load the network speed-test engine.');
                })().catch(error => {
                    speedTestModulePromise = null;
                    throw error;
                });
            }
            return speedTestModulePromise;
        }

        function speedSummaryFromEngine(engine) {
            try {
                return engine && engine.results && typeof engine.results.getSummary === 'function' ?
                    engine.results.getSummary() : {};
            } catch (e) { return {}; }
        }

        function classifySpeedTestFailure(error) {
            const msg = String(getErrorMessage(error) || '').toLowerCase();
            if (typeof navigator !== 'undefined' && navigator.onLine === false) return 'offline';
            if (/timed? out|timeout/.test(msg)) return 'timeout';
            if (/module|constructor|load.*engine|import/.test(msg)) return 'engine_unavailable';
            if (/vpn|firewall|blocked|failed to fetch|network|connection/.test(msg)) return 'network_blocked';
            if (/employee selection changed/.test(msg)) return 'identity_changed';
            return 'measurement_failed';
        }

        function saveFailedSpeedTestAttempt(base, error) {
            const message = String(getErrorMessage(error) || 'Speed test failed.').slice(0, 300);
            const failed = {
                ...base,
                status: 'failed',
                pingMs: null,
                jitterMs: null,
                downloadMbps: null,
                uploadMbps: null,
                failureCategory: classifySpeedTestFailure(error),
                failureMessage: message
            };
            saveSpeedTestResult(failed);
            return failed;
        }

        function makeSpeedTestCancelledError() {
            const error = new Error('Speed test cancelled by user.');
            error.code = 'SPEEDTEST_CANCELLED';
            return error;
        }

        function cancelIntegratedSpeedTest(options = {}) {
            if (!speedTestRunning) return false;
            if (options.closeAfter) speedTestCloseAfterCancel = true;
            speedTestCancelRequested = true;
            setSpeedTestProgress(0, 'Cancelling test\u2026');
            refreshSpeedTestPanel({ preserveDisplay: true });
            const cancel = speedTestCancelHandler;
            if (typeof cancel === 'function') {
                cancel();
            } else {
                try {
                    if (activeSpeedTestEngine && typeof activeSpeedTestEngine.pause === 'function') activeSpeedTestEngine.pause();
                } catch (e) {}
            }
            return true;
        }

        async function runIntegratedSpeedTest(mode = 'quick') {
            if (speedTestRunning) return;
            const profile = speedTestProfileForMode(mode);
            if (!currentEmployee) {
                showToast('Select and verify your Agent name before running a network check.');
                return;
            }
            const cooldown = speedTestCooldownRemaining(currentEmployee, profile.mode);
            if (cooldown > 0) {
                showToast('Please wait ' + formatCooldown(cooldown) + ' before running another ' + profile.label + '.');
                refreshSpeedTestPanel();
                return;
            }

            const testedEmployee = currentEmployee;
            const base = buildSpeedTestBase(testedEmployee, profile.mode);
            speedTestLastMode = profile.mode;
            updateSpeedTestModeCopy(profile.mode);
            if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                const error = new Error('This device reported that it is offline.');
                const failed = saveFailedSpeedTestAttempt(base, error);
                setSpeedTestMetricDisplays(null);
                updateSpeedTestQualityDisplay(failed);
                updateSpeedTestReadinessDisplay(failed);
                setSpeedTestFreshnessMessage('Attempt failed just now', 'recent');
                if ($('speedtestLastMeta')) $('speedtestLastMeta').textContent = 'This device is offline. The failed ' + profile.label + ' attempt was logged for Admin / TL review.';
                refreshSpeedTestPanel({ preserveDisplay: true });
                if (isOverlayOpen($('networkOverlay'))) renderNetworkTab();
                showToast('This device is offline. The failed network-check attempt was logged.');
                return;
            }

            speedTestRunning = true;
            speedTestRunningMode = profile.mode;
            speedTestLastMode = profile.mode;
            speedTestCancelRequested = false;
            speedTestCloseAfterCancel = false;
            let preserveOutcomeDisplay = false;
            setSpeedTestMetricDisplays(null);
            updateSpeedTestQualityDisplay(null);
            updateSpeedTestReadinessDisplay(null);
            setSpeedTestProgress(4, 'Preparing ' + profile.label.toLowerCase() + '…');
            refreshSpeedTestPanel();

            try {
                const SpeedTest = await getSpeedTestConstructor();
                if (speedTestCancelRequested) throw makeSpeedTestCancelledError();
                if (currentEmployee !== testedEmployee) throw new Error('Agent selection changed. Run the test again for the newly selected Agent.');

                const summary = await new Promise((resolve, reject) => {
                    let settled = false;
                    const engine = new SpeedTest({
                        autoStart: false,
                        downloadApiUrl: SPEEDTEST_DOWNLOAD_API_URL,
                        uploadApiUrl: SPEEDTEST_UPLOAD_API_URL,
                        measurements: profile.measurements,
                        bandwidthFinishRequestDuration: profile.finishRequestDuration,
                        bandwidthMinRequestDuration: SPEEDTEST_BANDWIDTH_MIN_MS,
                        bandwidthPercentile: SPEEDTEST_BANDWIDTH_PERCENTILE,
                        measureDownloadLoadedLatency: false,
                        measureUploadLoadedLatency: false
                    });
                    activeSpeedTestEngine = engine;
                    const finish = (fn, value) => {
                        if (settled) return;
                        settled = true;
                        clearTimeout(timeoutId);
                        speedTestCancelHandler = null;
                        activeSpeedTestEngine = null;
                        fn(value);
                    };
                    const timeoutId = setTimeout(() => {
                        try { if (engine && typeof engine.pause === 'function') engine.pause(); } catch (e) {}
                        finish(reject, new Error('The network check took too long to complete.'));
                    }, profile.timeoutMs);
                    speedTestCancelHandler = () => {
                        try { if (engine && typeof engine.pause === 'function') engine.pause(); } catch (e) {}
                        finish(reject, makeSpeedTestCancelledError());
                    };

                    engine.onResultsChange = (info) => {
                        const type = info && info.type ? String(info.type) : '';
                        const live = speedSummaryFromEngine(engine);
                        setSpeedTestMetricDisplays(live);
                        if (type === 'latency') setSpeedTestProgress(22, 'Checking latency and connection stability…');
                        else if (type === 'download') setSpeedTestProgress(58, profile.mode === 'full' ? 'Testing download speed · full diagnostic ramp…' : 'Testing download speed…');
                        else if (type === 'upload') setSpeedTestProgress(84, profile.mode === 'full' ? 'Testing upload speed · full diagnostic ramp…' : 'Testing upload speed…');
                    };
                    engine.onFinish = (results) => {
                        setSpeedTestProgress(94, 'Analyzing connection against work requirements…');
                        const finalSummary = results && typeof results.getSummary === 'function' ? results.getSummary() : speedSummaryFromEngine(engine);
                        finish(resolve, finalSummary || {});
                    };
                    engine.onError = (error) => {
                        finish(reject, new Error(typeof error === 'string' ? error : getErrorMessage(error)));
                    };
                    try { engine.play(); } catch (error) { finish(reject, error); }
                });

                if (currentEmployee !== testedEmployee) throw makeSpeedTestCancelledError();

                const latency = finiteNumber(summary.latency);
                const jitter = finiteNumber(summary.jitter);
                const downBps = finiteNumber(summary.download);
                const upBps = finiteNumber(summary.upload);
                if (latency === null || downBps === null || upBps === null || downBps <= 0 || upBps <= 0) {
                    throw new Error('The network-test service returned an incomplete result.');
                }

                const result = {
                    ...base,
                    ts: nowIso(),
                    status: 'complete',
                    pingMs: Math.round(latency * 10) / 10,
                    jitterMs: jitter === null ? null : Math.round(jitter * 10) / 10,
                    downloadMbps: Math.round((downBps / 1e6) * 10) / 10,
                    uploadMbps: Math.round((upBps / 1e6) * 10) / 10
                };

                setSpeedTestProgress(100, 'Complete — saving result…');
                saveSpeedTestResult(result);
                if ($('speedtestPing')) $('speedtestPing').textContent = result.pingMs.toFixed(1);
                if ($('speedtestJitter')) $('speedtestJitter').textContent = formatSpeedMetric(result.jitterMs, 1);
                if ($('speedtestDownload')) $('speedtestDownload').textContent = result.downloadMbps.toFixed(1);
                if ($('speedtestUpload')) $('speedtestUpload').textContent = result.uploadMbps.toFixed(1);
                updateSpeedTestQualityDisplay(result);
                updateSpeedTestReadinessDisplay(result);
                updateSpeedTestFreshnessDisplay();
                const quality = getNetworkQuality(result);
                const readiness = getNetworkReadiness(result);
                if ($('speedtestLastMeta')) $('speedtestLastMeta').innerHTML =
                    `<strong>${escapeHtml(agentDisplayName(testedEmployee))}</strong> · ${escapeHtml(result.pod)} · ${escapeHtml(profile.label)} · ${escapeHtml(quality.label)} · auto-logged to TrinoTime.`;
                showToast(`${readiness.label}: ${result.downloadMbps.toFixed(1)} Mbps down · ${result.uploadMbps.toFixed(1)} Mbps up · ${result.pingMs.toFixed(1)} ms ping.`);
                if (isOverlayOpen($('networkOverlay'))) renderNetworkTab();
            } catch (error) {
                if (error && error.code === 'SPEEDTEST_CANCELLED') {
                    preserveOutcomeDisplay = true;
                    setSpeedTestMetricDisplays(null);
                    updateSpeedTestQualityDisplay({ status:'cancelled' });
                    updateSpeedTestReadinessDisplay({ status:'cancelled' });
                    setSpeedTestFreshnessMessage('Cancelled just now', 'recent');
                    setSpeedTestProgress(0, 'Test cancelled.');
                    if ($('speedtestLastMeta')) $('speedtestLastMeta').textContent = profile.label + ' cancelled. No partial result was saved.';
                    showToast(profile.label + ' cancelled.');
                } else {
                    reportAppError('Integrated speed test', error);
                    preserveOutcomeDisplay = true;
                    const failed = saveFailedSpeedTestAttempt({ ...base, ts: nowIso() }, error);
                    setSpeedTestMetricDisplays(null);
                    setSpeedTestProgress(0, 'Test failed. The failed attempt was logged.');
                    if ($('speedtestLastMeta')) $('speedtestLastMeta').textContent =
                        'Could not complete the ' + profile.label + '. The failed attempt was logged for Admin / TL review.';
                    updateSpeedTestQualityDisplay(failed);
                    updateSpeedTestReadinessDisplay(failed);
                    setSpeedTestFreshnessMessage('Attempt failed just now', 'recent');
                    showToast(profile.label + ' could not complete. The failed attempt was logged.');
                    if (isOverlayOpen($('networkOverlay'))) renderNetworkTab();
                }
            } finally {
                speedTestRunning = false;
                speedTestRunningMode = null;
                activeSpeedTestEngine = null;
                speedTestCancelHandler = null;
                speedTestCancelRequested = false;
                const closeAfter = speedTestCloseAfterCancel;
                speedTestCloseAfterCancel = false;
                refreshSpeedTestPanel({ preserveDisplay: preserveOutcomeDisplay });
                refreshSpeedTestReminder();
                setTimeout(() => {
                    const progress = $('speedtestProgress');
                    if (progress && !speedTestRunning) progress.classList.remove('is-active');
                }, 3500);
                if (closeAfter) {
                    const overlay = $('speedtestOverlay');
                    if (overlay) overlay.classList.remove('open');
                }
            }
        }

        function openSpeedTestModal() {
            refreshSpeedTestPanel();
            const overlay = $('speedtestOverlay');
            if (!overlay) return;
            overlay.classList.add('open');
            scrollAndFocusSection($('speedtestModalTitle'));
        }

        function closeSpeedTestModal(options = {}) {
            if (speedTestRunning) {
                if (options.cancelRunning) {
                    cancelIntegratedSpeedTest({ closeAfter: true });
                } else {
                    showToast('A speed test is running. Use Cancel Test to stop it safely.');
                }
                return;
            }
            const overlay = $('speedtestOverlay');
            if (overlay) overlay.classList.remove('open');
        }

        function visibleSpeedTestsForRole() {
            let rows = Object.values(allSpeedTests).filter(item => item && item.id && item.name);
            if (isAdmin) return rows.filter(item => teamIdForPod(item.pod || currentRosterPodForName(item.name)) === activeTeam);
            if (isTeamLeader) return rows.filter(item => item.pod === lockedPod && canAccessPodForCurrentSession(item.pod));
            if (agentSessionAuthenticated && agentSessionName && currentEmployee === agentSessionName) {
                return rows.filter(item => item.name === agentSessionName && canAccessPodForCurrentSession(item.pod || currentRosterPodForName(item.name)));
            }
            return [];
        }

        function populateNetworkFilters() {
            const podSel = $('networkPodFilter');
            const empSel = $('networkEmpFilter');
            if (!podSel || !empSel) return;
            const oldPod = podSel.value;
            const oldEmp = empSel.value;
            const wasInitialized = podSel.dataset.historyInitialized === 'true';
            const roleRows = visibleSpeedTestsForRole();

            const allowedPods = isAdmin ? podsForTeam(activeTeam) : (lockedPod ? [lockedPod] : []);
            podSel.innerHTML = (isAdmin ? '<option value="">All PODs</option>' : '') +
                allowedPods.map(p => `<option value="${escapeHtml(p)}">${escapeHtml(podDisplayName(p))}</option>`).join('');
            podSel.disabled = !isAdmin;
            if (isAdmin && oldPod && allowedPods.includes(oldPod)) podSel.value = oldPod;
            else if (isAdmin && !wasInitialized && activePod !== ALL_PODS_LABEL && allowedPods.includes(activePod)) podSel.value = activePod;
            else if (!isAdmin && lockedPod) podSel.value = lockedPod;
            podSel.dataset.historyInitialized = 'true';

            const selectedPod = podSel.value;
            const names = Array.from(new Set(roleRows
                .filter(item => !selectedPod || item.pod === selectedPod)
                .map(item => item.name))).sort((a, b) => a.localeCompare(b));
            empSel.innerHTML = '<option value="">All agents</option>' +
                names.map(name => `<option value="${escapeHtml(name)}">${escapeHtml(agentDisplayName(name))}</option>`).join('');
            if (oldEmp && names.includes(oldEmp)) empSel.value = oldEmp;
        }

        function renderNetworkQualitySettingsControls() {
            updateNetworkTargetCopy();
            const panel = $('networkQualitySettingsPanel');
            if (!panel) return;
            panel.style.display = isAdmin ? 'block' : 'none';
            if (!isAdmin) return;
            if (panel.contains(document.activeElement)) return;
            const map = {
                networkQualityPingMax: networkQualitySettings.pingMaxMs,
                networkQualityJitterMax: networkQualitySettings.jitterMaxMs,
                networkQualityDownloadMin: networkQualitySettings.downloadMinMbps,
                networkQualityUploadMin: networkQualitySettings.uploadMinMbps,
                networkRetentionDays: networkQualitySettings.retentionDays
            };
            Object.entries(map).forEach(([id, value]) => { const el = $(id); if (el) el.value = String(value); });
        }

        function readNetworkQualitySettingsControls() {
            return mergeNetworkQualitySettings({
                pingMaxMs: $('networkQualityPingMax') ? $('networkQualityPingMax').value : networkQualitySettings.pingMaxMs,
                jitterMaxMs: $('networkQualityJitterMax') ? $('networkQualityJitterMax').value : networkQualitySettings.jitterMaxMs,
                downloadMinMbps: $('networkQualityDownloadMin') ? $('networkQualityDownloadMin').value : networkQualitySettings.downloadMinMbps,
                uploadMinMbps: $('networkQualityUploadMin') ? $('networkQualityUploadMin').value : networkQualitySettings.uploadMinMbps,
                retentionDays: $('networkRetentionDays') ? $('networkRetentionDays').value : networkQualitySettings.retentionDays
            });
        }

        function networkDashboardRoleRoster() {
            if (isAdmin) return labelerRosterEmployees().slice();
            if (isTeamLeader && lockedPod) return labelerRosterEmployees().filter(employee => employee.pod === lockedPod);
            return [];
        }

        function getNetworkHistoryFilterState() {
            return {
                pod: $('networkPodFilter') ? $('networkPodFilter').value : '',
                selectedName: $('networkEmpFilter') ? $('networkEmpFilter').value : '',
                searchName: $('networkAgentSearch') ? $('networkAgentSearch').value.trim().toLowerCase() : '',
                range: $('networkRangeFilter') ? $('networkRangeFilter').value : '30',
                fromComp: $('networkDateFrom') ? isoToComparable($('networkDateFrom').value) : null,
                toComp: $('networkDateTo') ? isoToComparable($('networkDateTo').value) : null
            };
        }

        function filterNetworkHistoryRows() {
            const filters = getNetworkHistoryFilterState();
            const nowMs = getTrueNowMs();
            const today = todayKeyPart();
            return visibleSpeedTestsForRole().filter(item => {
                if (filters.pod && item.pod !== filters.pod) return false;
                if (filters.selectedName && item.name !== filters.selectedName) return false;
                if (filters.searchName && !String(item.name || '').toLowerCase().includes(filters.searchName)) return false;
                const itemDateComp = item.date ? dateStrToComparable(item.date) : null;
                if (filters.fromComp !== null && (itemDateComp === null || itemDateComp < filters.fromComp)) return false;
                if (filters.toComp !== null && (itemDateComp === null || itemDateComp > filters.toComp)) return false;
                if (filters.fromComp === null && filters.toComp === null) {
                    if (filters.range === 'today') return item.date === today;
                    if (filters.range !== 'all') {
                        const days = Number(filters.range);
                        const tsMs = new Date(item.ts).getTime();
                        if (Number.isFinite(days) && Number.isFinite(tsMs) && tsMs < nowMs - days * 86400000) return false;
                    }
                }
                return true;
            });
        }

        function speedTestMeetsTargets(item) {
            if (!isCompletedSpeedTest(item)) return false;
            const quality = getNetworkQuality(item);
            return quality.key === 'excellent' || quality.key === 'good';
        }

        function isNetworkProblem(item) {
            const status = speedTestStatus(item);
            if (status === 'failed') return true;
            if (status !== 'complete') return false;
            return !speedTestMeetsTargets(item);
        }

        function latestNetworkAttemptByAgent(rows) {
            const latest = new Map();
            rows.forEach(item => {
                const name = item && item.name;
                if (!name) return;
                const prev = latest.get(name);
                if (!prev || new Date(item.ts).getTime() > new Date(prev.ts).getTime()) latest.set(name, item);
            });
            return Array.from(latest.values());
        }

        function networkPodOrder(value) {
            const index = POD_LIST.indexOf(value);
            return index === -1 ? Number.MAX_SAFE_INTEGER : index;
        }

        function networkQualityRank(item) {
            const key = getNetworkQuality(item).key;
            return ({ excellent:5, good:4, attention:3, poor:2, failed:1, cancelled:0, unknown:-1 })[key] ?? -1;
        }

        function networkDefaultSortDirection(key) {
            if (key === 'name') return 'asc';
            if (key === 'pingMs' || key === 'jitterMs') return 'asc';
            return 'desc';
        }

        function compareNetworkRows(a, b, key, dir) {
            let av, bv;
            if (key === 'ts') { av = new Date(a.ts).getTime(); bv = new Date(b.ts).getTime(); }
            else if (key === 'name') { av = String(a.name || '').toLowerCase(); bv = String(b.name || '').toLowerCase(); }
            else if (key === 'quality') { av = networkQualityRank(a); bv = networkQualityRank(b); }
            else { av = finiteNumber(a[key]); bv = finiteNumber(b[key]); }
            const aNull = av === null || av === undefined || (typeof av === 'number' && !Number.isFinite(av));
            const bNull = bv === null || bv === undefined || (typeof bv === 'number' && !Number.isFinite(bv));
            if (aNull && bNull) return 0;
            if (aNull) return 1;
            if (bNull) return -1;
            let result = 0;
            if (typeof av === 'string') result = av.localeCompare(bv);
            else result = av < bv ? -1 : av > bv ? 1 : 0;
            return dir === 'asc' ? result : -result;
        }

        function sortNetworkHistoryRows(rows) {
            return rows.slice().sort((a, b) => {
                const podDiff = networkPodOrder(a.pod) - networkPodOrder(b.pod);
                if (podDiff) return podDiff;
                const podNameDiff = String(a.pod || '').localeCompare(String(b.pod || ''));
                if (podNameDiff) return podNameDiff;
                const main = compareNetworkRows(a, b, networkHistorySortKey, networkHistorySortDir);
                if (main) return main;
                return new Date(b.ts).getTime() - new Date(a.ts).getTime();
            });
        }

        function getNetworkDashboardRows() {
            let rows = filterNetworkHistoryRows();
            if (networkHistoryViewMode === 'latest') rows = latestNetworkAttemptByAgent(rows);
            if (networkHistoryProblemsOnly) rows = rows.filter(isNetworkProblem);
            return sortNetworkHistoryRows(rows);
        }

        function latestSuccessfulNetworkTest(name) {
            return visibleSpeedTestsForRole().filter(item => item.name === name && isCompletedSpeedTest(item))
                .sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime())[0] || null;
        }

        function networkFreshnessForAgent(name) {
            const latest = latestSuccessfulNetworkTest(name);
            if (!latest) return { key:'never', label:'Never tested' };
            const today = todayKeyPart();
            if (latest.date === today) return { key:'today', label:'Today' };
            try {
                const t = parseDateStr(today), d = parseDateStr(latest.date);
                const diff = Math.max(0, Math.round((Date.UTC(t.y, t.m - 1, t.d) - Date.UTC(d.y, d.m - 1, d.d)) / 86400000));
                if (diff <= 1) return { key:'recent', label:'1 day old' };
                return { key:'stale', label:diff + ' days old' };
            } catch (e) {
                return { key:'stale', label:'Older test' };
            }
        }

        function buildNetworkTrendIndex() {
            const byAgent = {};
            visibleSpeedTestsForRole().filter(isCompletedSpeedTest).forEach(item => {
                (byAgent[item.name] = byAgent[item.name] || []).push(item);
            });
            const previousById = new Map();
            Object.values(byAgent).forEach(list => {
                list.sort((a, b) => new Date(a.ts).getTime() - new Date(b.ts).getTime());
                let previous = null;
                list.forEach(item => {
                    previousById.set(item.id, previous);
                    previous = item;
                });
            });
            return previousById;
        }

        function networkTrendHtml(item, field, previousById) {
            if (!isCompletedSpeedTest(item)) return '';
            const previous = previousById.get(item.id);
            if (!previous) return '';
            const currentValue = finiteNumber(item[field]);
            const previousValue = finiteNumber(previous[field]);
            if (currentValue === null || previousValue === null) return '';
            const delta = currentValue - previousValue;
            if (Math.abs(delta) < 0.05) return '<span class="network-trend trend-neutral" title="No meaningful change vs previous completed test">→ 0.0</span>';
            const lowerIsBetter = field === 'pingMs' || field === 'jitterMs';
            const improved = lowerIsBetter ? delta < 0 : delta > 0;
            const arrow = delta > 0 ? '↑' : '↓';
            const unit = (field === 'pingMs' || field === 'jitterMs') ? ' ms' : ' Mbps';
            return `<span class="network-trend ${improved ? 'trend-good' : 'trend-bad'}" title="Compared with previous completed test">${arrow} ${Math.abs(delta).toFixed(1)}${unit}</span>`;
        }

        function networkDashboardRosterScope() {
            const filters = getNetworkHistoryFilterState();
            return networkDashboardRoleRoster().filter(employee => {
                if (filters.pod && employee.pod !== filters.pod) return false;
                if (filters.selectedName && employee.name !== filters.selectedName) return false;
                if (filters.searchName && !String(employee.name || '').toLowerCase().includes(filters.searchName)) return false;
                return true;
            });
        }

        function buildTodayNetworkMaps() {
            const today = todayKeyPart();
            const attempts = visibleSpeedTestsForRole().filter(item => item.date === today);
            const latestAttempt = new Map();
            const latestSuccess = new Map();
            attempts.forEach(item => {
                const oldAttempt = latestAttempt.get(item.name);
                if (!oldAttempt || new Date(item.ts).getTime() > new Date(oldAttempt.ts).getTime()) latestAttempt.set(item.name, item);
                if (isCompletedSpeedTest(item)) {
                    const oldSuccess = latestSuccess.get(item.name);
                    if (!oldSuccess || new Date(item.ts).getTime() > new Date(oldSuccess.ts).getTime()) latestSuccess.set(item.name, item);
                }
            });
            return { latestAttempt, latestSuccess };
        }

        function renderNetworkPodHealthSummary(scheduled, latestSuccess, latestAttempt) {
            const grid = $('networkPodHealthGrid');
            if (!grid) return;
            const byPod = new Map();
            scheduled.forEach(employee => {
                const pod = employee.pod || 'Unassigned POD';
                if (!byPod.has(pod)) byPod.set(pod, []);
                byPod.get(pod).push(employee);
            });
            if (!byPod.size) {
                grid.innerHTML = '<div class="network-pod-health-empty">No scheduled agents are in the current scope today.</div>';
                return;
            }
            const pods = Array.from(byPod.keys()).sort((a, b) => {
                const ai = POD_LIST.indexOf(a), bi = POD_LIST.indexOf(b);
                if (ai !== -1 || bi !== -1) return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
                return a.localeCompare(b);
            });
            grid.innerHTML = pods.map(pod => {
                const roster = byPod.get(pod) || [];
                const tested = roster.filter(employee => latestSuccess.has(employee.name));
                const ready = tested.filter(employee => getNetworkReadiness(latestSuccess.get(employee.name)).key === 'ready').length;
                const caution = tested.filter(employee => getNetworkReadiness(latestSuccess.get(employee.name)).key === 'caution').length;
                const measuredIssue = tested.filter(employee => getNetworkReadiness(latestSuccess.get(employee.name)).key === 'issue').length;
                const failedWithoutSuccess = roster.filter(employee => !latestSuccess.has(employee.name) && latestAttempt.has(employee.name) && speedTestStatus(latestAttempt.get(employee.name)) === 'failed').length;
                const issue = measuredIssue + failedWithoutSuccess;
                const missing = Math.max(0, roster.length - tested.length - failedWithoutSuccess);
                return `<div class="network-pod-health-card">
                    <div class="network-pod-health-title"><strong>${escapeHtml(podDisplayName(pod) || pod)}</strong><span>${tested.length}/${roster.length} tested</span></div>
                    <div class="network-pod-health-stats">
                        <span class="is-ready">${ready} Ready</span>
                        <span class="is-caution">${caution} Caution</span>
                        <span class="is-issue">${issue} Issue</span>
                        <span class="is-missing">${missing} Not tested</span>
                    </div>
                </div>`;
            }).join('');
        }

        function renderNetworkDailyCompliance() {
            const today = todayKeyPart();
            const scheduled = networkDashboardRosterScope()
                .filter(employee => resolveEffectiveAvailability(employee.name, today, employee.pod, { atMs:getTrueNowMs(), includeAttendance:false }).available);
            const { latestAttempt, latestSuccess } = buildTodayNetworkMaps();
            const tested = scheduled.filter(employee => latestSuccess.has(employee.name));
            const meeting = tested.filter(employee => {
                const readiness = getNetworkReadiness(latestSuccess.get(employee.name));
                return readiness.key === 'ready' || readiness.key === 'caution';
            });
            const below = tested.filter(employee => getNetworkReadiness(latestSuccess.get(employee.name)).key === 'issue');
            const failed = scheduled.filter(employee => {
                const attempt = latestAttempt.get(employee.name);
                return attempt && speedTestStatus(attempt) === 'failed';
            });
            const missing = scheduled.filter(employee => !latestSuccess.has(employee.name));
            if ($('networkDailyCount')) $('networkDailyCount').textContent = `${tested.length} / ${scheduled.length} scheduled agents tested successfully`;
            if ($('networkDailyTested')) $('networkDailyTested').textContent = String(tested.length);
            if ($('networkDailyMeeting')) $('networkDailyMeeting').textContent = String(meeting.length);
            if ($('networkDailyBelow')) $('networkDailyBelow').textContent = String(below.length);
            if ($('networkDailyFailed')) $('networkDailyFailed').textContent = String(failed.length);
            updateNetworkTargetCopy();
            renderNetworkPodHealthSummary(scheduled, latestSuccess, latestAttempt);
            const list = $('networkDailyMissingList');
            if (list) {
                if (!scheduled.length) {
                    list.innerHTML = '<span class="network-missing-label">No scheduled agents are in the current POD/agent scope today.</span>';
                } else if (!missing.length) {
                    list.innerHTML = '<span class="network-missing-label">✓ Everyone scheduled in this scope has a successful network check today.</span>';
                } else {
                    list.innerHTML = '<span class="network-missing-label">Missing successful check:</span>' + missing.slice(0, 30).map(employee => {
                        const freshness = networkFreshnessForAgent(employee.name);
                        return `<button class="network-missing-chip" type="button" data-network-agent="${escapeHtml(encodeURIComponent(employee.name))}" title="Open ${escapeHtml(agentDisplayName(employee.name))} network summary">${escapeHtml(agentDisplayName(employee.name))} · ${escapeHtml(freshness.label)}</button>`;
                    }).join('') + (missing.length > 30 ? `<span class="network-missing-label">+${missing.length - 30} more</span>` : '');
                }
            }
        }

        function updateNetworkViewControls() {
            const allBtn = $('networkViewAllBtn');
            const latestBtn = $('networkViewLatestBtn');
            if (allBtn) { allBtn.classList.toggle('active', networkHistoryViewMode === 'all'); allBtn.setAttribute('aria-pressed', networkHistoryViewMode === 'all' ? 'true' : 'false'); }
            if (latestBtn) { latestBtn.classList.toggle('active', networkHistoryViewMode === 'latest'); latestBtn.setAttribute('aria-pressed', networkHistoryViewMode === 'latest' ? 'true' : 'false'); }
            const problems = $('networkProblemsOnlyBtn');
            if (problems) problems.setAttribute('aria-pressed', networkHistoryProblemsOnly ? 'true' : 'false');
            document.querySelectorAll('.network-sort-btn[data-network-sort]').forEach(button => {
                const active = button.dataset.networkSort === networkHistorySortKey;
                button.classList.toggle('is-active', active);
                const indicator = button.querySelector('.network-sort-indicator');
                if (indicator) indicator.textContent = active ? (networkHistorySortDir === 'asc' ? '▲' : '▼') : '↕';
                button.setAttribute('aria-sort', active ? (networkHistorySortDir === 'asc' ? 'ascending' : 'descending') : 'none');
            });
        }

        function networkPodSummary(rows, pod) {
            const group = rows.filter(item => (item.pod || 'Unassigned POD') === pod);
            const completed = group.filter(isCompletedSpeedTest);
            const avg = field => {
                const values = completed.map(item => finiteNumber(item[field])).filter(value => value !== null);
                return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
            };
            const agents = new Set(group.map(item => item.name).filter(Boolean)).size;
            const below = completed.filter(item => !speedTestMeetsTargets(item)).length;
            const failures = group.filter(item => speedTestStatus(item) === 'failed').length;
            const down = avg('downloadMbps'), up = avg('uploadMbps');
            return `${agents} agent${agents === 1 ? '' : 's'} · Avg ↓ ${down === null ? '—' : down.toFixed(1) + ' Mbps'} · Avg ↑ ${up === null ? '—' : up.toFixed(1) + ' Mbps'} · ${below} need attention${failures ? ` · ${failures} failed` : ''}`;
        }

        function openNetworkAgentSummary(name) {
            if (!name || (!isAdmin && !isTeamLeader)) return;
            const employee = networkDashboardRoleRoster().find(item => item.name === name);
            const tests = visibleSpeedTestsForRole().filter(item => item.name === name)
                .sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime());
            const completed = tests.filter(isCompletedSpeedTest);
            const latestAttempt = tests[0] || null;
            const latest = completed[0] || null;
            const previous = completed[1] || null;
            const sevenDayCutoff = getTrueNowMs() - 7 * 86400000;
            const last7 = tests.filter(item => new Date(item.ts).getTime() >= sevenDayCutoff);
            const completed7 = last7.filter(isCompletedSpeedTest);
            const average7 = field => {
                const values = completed7.map(item => finiteNumber(item[field])).filter(value => value !== null);
                return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
            };
            const freshness = networkFreshnessForAgent(name);
            networkAgentModalName = name;
            if ($('networkAgentTitle')) $('networkAgentTitle').textContent = name + ' — Network Summary';
            if ($('networkAgentMeta')) $('networkAgentMeta').textContent = `${employee ? employee.pod : (latestAttempt ? latestAttempt.pod : 'Unassigned POD')} · Latest successful test: ${latest ? new Date(latest.ts).toLocaleString('en-US', { timeZone: MANILA_TIME_ZONE, month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit' }) + ' PHT' : 'None yet'}`;
            const badges = $('networkAgentBadges');
            if (badges) {
                const quality = latest ? getNetworkQuality(latest) : { key:'unknown', label:'Not tested' };
                const readiness = latest ? getNetworkReadiness(latest) : { key:'unknown', label:'NOT TESTED' };
                badges.innerHTML = `<span class="network-quality-badge quality-${escapeHtml(quality.key)}">${escapeHtml(quality.label)}</span> <span class="network-readiness-mini readiness-${escapeHtml(readiness.key)}">${escapeHtml(readiness.label)}</span> <span class="network-mode-mini">${escapeHtml(latest ? speedTestModeLabel(latest) : 'No test')}</span> <span class="network-freshness-mini is-${escapeHtml(freshness.key)}">${escapeHtml(freshness.label)}</span>`;
            }
            const trend = (field, lowerIsBetter = false) => {
                if (!latest || !previous) return '';
                const current = finiteNumber(latest[field]), old = finiteNumber(previous[field]);
                if (current === null || old === null) return '';
                const delta = current - old;
                if (Math.abs(delta) < .05) return '<span class="network-trend trend-neutral">→ 0.0</span>';
                const improved = lowerIsBetter ? delta < 0 : delta > 0;
                const unit = lowerIsBetter ? ' ms' : ' Mbps';
                return `<span class="network-trend ${improved ? 'trend-good' : 'trend-bad'}">${delta > 0 ? '↑' : '↓'} ${Math.abs(delta).toFixed(1)}${unit}</span>`;
            };
            const latestGrid = $('networkAgentLatestGrid');
            if (latestGrid) latestGrid.innerHTML = [
                ['Download', latest ? formatSpeedMetric(latest.downloadMbps, 1) + ' Mbps' : '—', trend('downloadMbps')],
                ['Upload', latest ? formatSpeedMetric(latest.uploadMbps, 1) + ' Mbps' : '—', trend('uploadMbps')],
                ['Ping', latest ? formatSpeedMetric(latest.pingMs, 1) + ' ms' : '—', trend('pingMs', true)],
                ['Jitter', latest ? formatSpeedMetric(latest.jitterMs, 1) + ' ms' : '—', trend('jitterMs', true)]
            ].map(([label, value, delta]) => `<div class="network-summary-card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong>${delta}</div>`).join('');
            const stats = $('networkAgentStatsGrid');
            const failed7 = last7.filter(item => speedTestStatus(item) === 'failed').length;
            const below7 = completed7.filter(item => !speedTestMeetsTargets(item)).length;
            const avgDown = average7('downloadMbps'), avgUp = average7('uploadMbps');
            if (stats) stats.innerHTML = [
                ['Tests · 7 Days', String(last7.length)],
                ['Avg Download · 7D', avgDown === null ? '—' : avgDown.toFixed(1) + ' Mbps'],
                ['Avg Upload · 7D', avgUp === null ? '—' : avgUp.toFixed(1) + ' Mbps'],
                ['Below / Failed · 7D', `${below7} / ${failed7}`]
            ].map(([label, value]) => `<div class="network-summary-card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join('');
            const recent = $('networkAgentRecent');
            if (recent) {
                if (!tests.length) recent.innerHTML = '<div class="network-agent-empty">No Speedtest attempts have been saved for this agent yet.</div>';
                else recent.innerHTML = '<div class="network-agent-recent-row is-head"><span>Time</span><span>Download</span><span>Upload</span><span>Ping</span><span>Quality / Mode / Readiness</span></div>' + tests.slice(0, 8).map(item => {
                    const when = new Date(item.ts).toLocaleString('en-US', { timeZone: MANILA_TIME_ZONE, month:'short', day:'numeric', hour:'numeric', minute:'2-digit' });
                    const status = speedTestStatus(item), quality = getNetworkQuality(item), readiness = getNetworkReadiness(item);
                    return `<div class="network-agent-recent-row"><span>${escapeHtml(when)} PHT</span><span>${escapeHtml(formatSpeedMetric(item.downloadMbps, 1))} Mbps</span><span>${escapeHtml(formatSpeedMetric(item.uploadMbps, 1))} Mbps</span><span>${escapeHtml(formatSpeedMetric(item.pingMs, 1))} ms</span><span><span class="network-quality-badge quality-${escapeHtml(quality.key)}">${escapeHtml(status === 'failed' ? 'Failed' : quality.label)}</span> <span class="network-mode-mini">${escapeHtml(speedTestModeLabel(item))}</span><div class="network-readiness-mini readiness-${escapeHtml(readiness.key)}">${escapeHtml(readiness.label)}</div></span></div>`;
                }).join('');
            }
            const overlay = $('networkAgentOverlay');
            if (overlay) overlay.classList.add('open');
            scrollAndFocusSection($('networkAgentTitle'));
        }

        function closeNetworkAgentSummary() {
            const overlay = $('networkAgentOverlay');
            if (overlay) overlay.classList.remove('open');
            networkAgentModalName = '';
        }

        function metricCellClass(field, value) {
            const quality = metricQuality(field, value);
            if (quality === 'poor') return 'network-metric-cell metric-poor';
            if (quality === 'attention') return 'network-metric-cell metric-attention';
            if (quality === 'good' || quality === 'excellent') return 'network-metric-cell metric-good';
            return 'network-metric-cell';
        }

        function renderNetworkTab() {
            if (!isAdmin && !isTeamLeader) return;
            populateNetworkFilters();
            renderNetworkQualitySettingsControls();
            updateNetworkViewControls();
            renderNetworkDailyCompliance();

            const rows = getNetworkDashboardRows();
            const completed = rows.filter(isCompletedSpeedTest);
            const average = (field) => {
                const vals = completed.map(r => finiteNumber(r[field])).filter(v => v !== null);
                return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
            };
            if ($('networkSummaryTests')) $('networkSummaryTests').textContent = String(rows.length);
            if ($('networkSummaryFailures')) $('networkSummaryFailures').textContent = String(rows.filter(r => speedTestStatus(r) === 'failed').length);
            const avgPing = average('pingMs');
            const avgJitter = average('jitterMs');
            const avgDown = average('downloadMbps');
            const avgUp = average('uploadMbps');
            if ($('networkSummaryPing')) $('networkSummaryPing').textContent = avgPing === null ? '—' : avgPing.toFixed(1) + ' ms';
            if ($('networkSummaryJitter')) $('networkSummaryJitter').textContent = avgJitter === null ? '—' : avgJitter.toFixed(1) + ' ms';
            if ($('networkSummaryDownload')) $('networkSummaryDownload').textContent = avgDown === null ? '—' : avgDown.toFixed(1) + ' Mbps';
            if ($('networkSummaryUpload')) $('networkSummaryUpload').textContent = avgUp === null ? '—' : avgUp.toFixed(1) + ' Mbps';

            const tbody = $('networkTbody');
            if (!tbody) return;
            if (!rows.length) {
                tbody.innerHTML = '<tr><td colspan="10"><div class="network-empty">No Speedtest results match these filters.<br>Try clearing a filter, switching off Problems Only, or widening the date range.</div></td></tr>';
                if ($('networkTableNote')) $('networkTableNote').textContent = 'No matching saved tests.';
                return;
            }

            const shown = rows.slice(0, 500);
            const groupCounts = shown.reduce((acc, item) => {
                const key = item.pod || 'Unassigned POD';
                acc[key] = (acc[key] || 0) + 1;
                return acc;
            }, {});
            const trendIndex = buildNetworkTrendIndex();
            let lastPod = null;
            const output = [];
            shown.forEach(item => {
                const itemPod = item.pod || 'Unassigned POD';
                if (itemPod !== lastPod) {
                    const count = groupCounts[itemPod] || 0;
                    const podSummary = networkPodSummary(shown, itemPod);
                    output.push(`<tr class="network-pod-group"><td colspan="10"><div class="network-pod-group-inner"><span>${escapeHtml(itemPod)} · ${count} result${count === 1 ? '' : 's'}</span><span class="network-pod-summary-text">${escapeHtml(podSummary)}</span></div></td></tr>`);
                    lastPod = itemPod;
                }
                const when = new Date(item.ts).toLocaleString('en-US', {
                    timeZone: MANILA_TIME_ZONE, month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit'
                });
                const session = item.attendanceState || '—';
                const status = speedTestStatus(item);
                const quality = getNetworkQuality(item);
                const freshness = networkFreshnessForAgent(item.name);
                const statusLabel = status === 'complete' ? 'Complete' : status === 'failed' ? 'Failed' : status === 'cancelled' ? 'Cancelled' : 'Unknown';
                const failure = status === 'failed' && item.failureMessage ? `<span class="network-failure-detail" title="${escapeHtml(item.failureMessage)}">${escapeHtml(item.failureCategory || 'failed')}: ${escapeHtml(item.failureMessage)}</span>` : '';
                output.push(`<tr>
                    <td>${escapeHtml(when)} PHT</td>
                    <td>${escapeHtml(itemPod)}</td>
                    <td><button class="network-agent-link" type="button" data-network-agent="${escapeHtml(encodeURIComponent(item.name || ''))}">${escapeHtml(agentDisplayName(item.name) || '—')}</button><div class="network-agent-meta"><span class="network-freshness-mini is-${escapeHtml(freshness.key)}">${escapeHtml(freshness.label)}</span><span class="network-mode-mini">${escapeHtml(speedTestModeLabel(item))}</span></div></td>
                    <td class="${metricCellClass('downloadMbps', item.downloadMbps)}"><span class="network-number">${escapeHtml(formatSpeedMetric(item.downloadMbps, 1))}</span> Mbps${networkTrendHtml(item, 'downloadMbps', trendIndex)}</td>
                    <td class="${metricCellClass('uploadMbps', item.uploadMbps)}"><span class="network-number">${escapeHtml(formatSpeedMetric(item.uploadMbps, 1))}</span> Mbps${networkTrendHtml(item, 'uploadMbps', trendIndex)}</td>
                    <td class="${metricCellClass('pingMs', item.pingMs)}"><span class="network-number">${escapeHtml(formatSpeedMetric(item.pingMs, 1))}</span> ms${networkTrendHtml(item, 'pingMs', trendIndex)}</td>
                    <td class="${metricCellClass('jitterMs', item.jitterMs)}"><span class="network-number">${escapeHtml(formatSpeedMetric(item.jitterMs, 1))}</span> ms${networkTrendHtml(item, 'jitterMs', trendIndex)}</td>
                    <td><span class="network-quality-badge quality-${escapeHtml(quality.key)}">${escapeHtml(quality.label)}</span><div class="network-readiness-mini readiness-${escapeHtml(getNetworkReadiness(item).key)}">${escapeHtml(getNetworkReadiness(item).label)}</div></td>
                    <td><span class="network-session-badge">${escapeHtml(session)}</span></td>
                    <td><span class="network-status-badge status-${escapeHtml(status)}">${escapeHtml(statusLabel)}</span>${failure}</td>
                </tr>`);
            });
            tbody.innerHTML = output.join('');
            const modeText = networkHistoryViewMode === 'latest' ? 'latest attempt per agent' : 'all attempts';
            const problemText = networkHistoryProblemsOnly ? ' · problems only' : '';
            if ($('networkTableNote')) $('networkTableNote').textContent =
                `${rows.length} saved ${modeText} across ${Object.keys(groupCounts).length} POD group${Object.keys(groupCounts).length === 1 ? '' : 's'}${problemText}${rows.length > shown.length ? ` · showing first ${shown.length} in the grouped view` : ''}. Click an agent name for their 7-day summary and recent history.`;
        }

        async function downloadNetworkHistoryExcel() {
            const rows = getNetworkDashboardRows();
            if (!rows.length) { showToast('No Speedtest records match the current dashboard filters.'); return; }
            if (!(await ensureExcelJsReady())) { showToast('Excel export could not be loaded. Check your connection and try again.'); return; }
            showToast(`Exporting ${rows.length} Speedtest record${rows.length === 1 ? '' : 's'} from the current dashboard view.`);
            const wb = new ExcelJS.Workbook();
            wb.creator = 'OOS TrinoTime';
            wb.created = new Date();
            const ws = wb.addWorksheet('Speedtest History', { views:[{ state:'frozen', ySplit:2 }] });
            ws.properties.tabColor = { argb:'FF7C3AED' };
            const headers = ['Test Time (PHT)','Date','Pod','Agent','Mode','Download (Mbps)','Upload (Mbps)','Ping (ms)','Jitter (ms)','Quality','Work Readiness','Attendance State','Status','Failure Category','Failure Detail'];
            ws.columns = [{width:22},{width:12},{width:12},{width:23},{width:18},{width:18},{width:18},{width:12},{width:12},{width:18},{width:24},{width:18},{width:12},{width:18},{width:44}];
            const filters = getNetworkHistoryFilterState();
            const title = `OOS TrinoTime · Speedtest History · ${filters.pod || (isTeamLeader ? lockedPod : 'All PODs')} · ${networkHistoryViewMode === 'latest' ? 'Latest per Agent' : 'All Tests'}${networkHistoryProblemsOnly ? ' · Problems Only' : ''}`;
            const titleRow = ws.addRow([title]);
            ws.mergeCells(titleRow.number, 1, titleRow.number, headers.length);
            titleRow.eachCell({includeEmpty:true}, cell => { cell.font = XLS_STYLE.titleFont; cell.fill = XLS_STYLE.titleFill; cell.alignment = {vertical:'middle',horizontal:'left'}; cell.protection = {locked:false}; });
            const headerRow = ws.addRow(headers);
            styleHeaderRow(headerRow);
            unlockNonFormulaCells(headerRow);
            const first = ws.rowCount + 1;
            rows.forEach((item, index) => {
                const status = speedTestStatus(item), quality = getNetworkQuality(item);
                const when = new Date(item.ts).toLocaleString('en-US', { timeZone:MANILA_TIME_ZONE, month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit' });
                const row = ws.addRow([
                    when, item.date || '', item.pod || '', item.name || '', speedTestModeLabel(item),
                    finiteNumber(item.downloadMbps) === null ? '' : Number(item.downloadMbps),
                    finiteNumber(item.uploadMbps) === null ? '' : Number(item.uploadMbps),
                    finiteNumber(item.pingMs) === null ? '' : Number(item.pingMs),
                    finiteNumber(item.jitterMs) === null ? '' : Number(item.jitterMs),
                    quality.label, getNetworkReadiness(item).label, item.attendanceState || '',
                    status === 'complete' ? 'Complete' : status === 'failed' ? 'Failed' : status === 'cancelled' ? 'Cancelled' : 'Unknown',
                    item.failureCategory || '', item.failureMessage || ''
                ]);
                [6,7,8,9].forEach(column => { row.getCell(column).numFmt = '0.0'; });
                styleDataRow(row, index % 2 === 1 ? XLS_STYLE.zebraFill : null);
                unlockNonFormulaCells(row);
            });
            const last = ws.rowCount;
            ws.autoFilter = { from:{row:headerRow.number,column:1}, to:{row:last,column:headers.length} };
            if (last >= first) {
                ws.addConditionalFormatting({ ref:`J${first}:J${last}`, rules:[
                    { type:'expression', formulae:[`$J${first}="Poor"`], style:{ fill:{type:'pattern',pattern:'solid',fgColor:{argb:'FFFEF2F2'}} } },
                    { type:'expression', formulae:[`$J${first}="Needs Attention"`], style:{ fill:{type:'pattern',pattern:'solid',fgColor:{argb:'FFFFFBEB'}} } }
                ]});
            }
            const buffer = await wb.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type:'application/octet-stream' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `trinotime-speedtest-history-${todayKeyPart().replace(/\//g,'-')}.xlsx`;
            document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
        }

        function getNetworkExportRowsForCurrentView() {
            const emp = $('filterEmp') ? $('filterEmp').value : '';
            const fromComp = $('filterDate') ? isoToComparable($('filterDate').value) : null;
            const toComp = $('filterDateTo') ? isoToComparable($('filterDateTo').value) : null;
            return visibleSpeedTestsForRole().filter(item => {
                if (!item || !item.id || !item.name) return false;
                if (teamIdForPod(item.pod || currentRosterPodForName(item.name)) !== activeTeam) return false;
                if (activePod !== ALL_PODS_LABEL && item.pod !== activePod) return false;
                if (emp && item.name !== emp) return false;
                const comp = dateStrToComparable(item.date || '');
                if (fromComp !== null && comp < fromComp) return false;
                if (toComp !== null && comp > toComp) return false;
                return true;
            }).sort((a, b) => new Date(b.ts).getTime() - new Date(a.ts).getTime());
        }

        async function cleanupExpiredSpeedTests() {
            if (!TrinoPermissions.can('network.history.cleanup') || !timeSyncEstablished) return 0;
            const retentionDays = networkQualitySettings.retentionDays || DEFAULT_NETWORK_QUALITY_SETTINGS.retentionDays;
            const cutoff = getTrueNowMs() - retentionDays * 86400000;
            const expired = Object.values(allSpeedTests).filter(item => {
                if (!item || !item.id || !item.ts) return false;
                const tsMs = new Date(item.ts).getTime();
                return Number.isFinite(tsMs) && tsMs < cutoff;
            });
            if (!expired.length) return 0;
            for (const item of expired) {
                delete allSpeedTests[item.id];
                try { await appStorage.delete(speedTestStorageKey(item.id)); } catch (e) {
                    reportAppError('Speed test retention cleanup', e);
                }
            }
            scheduleIncrementalRender({ type:'speedtests', name:'', pod:'', date:'' });
            return expired.length;
        }

        function scheduleSpeedTestRetentionCleanup() {
            if (!TrinoPermissions.can('network.history.cleanup') || speedTestRetentionCleanupStarted || !timeSyncEstablished) return;
            speedTestRetentionCleanupStarted = true;
            setTimeout(() => {
                void cleanupExpiredSpeedTests().catch(error => reportAppError('Speed test retention cleanup', error));
            }, 1200);
        }










        const ANNOUNCE_SEEN_KEY = 'oosLastSeenAnnouncement';
        const EVERYONE_MENTION = 'everyone';
        const ANNOUNCEMENT_AUTOCOMPLETE_LIMIT = 15;

        function getAnnouncementViewerKey() {
            if (isAdmin) return 'admin:' + (currentAuthenticatedAdminId() || 'admin');
            if (isTeamLeader) return 'tl:' + (teamLeaderName || lockedPod || 'teamleader');
            if (currentEmployee) return 'agent:' + currentEmployee;
            return 'unselected';
        }
        function getAnnouncementSeenStorageKey() {
            return ANNOUNCE_SEEN_KEY + ':' + getAnnouncementViewerKey().trim().toLowerCase();
        }
        function getLastSeenAnnouncementTs() {
            try { return localStorage.getItem(getAnnouncementSeenStorageKey()) || ''; } catch (e) { return ''; }
        }
        function setLastSeenAnnouncementTs(ts) {
            try { localStorage.setItem(getAnnouncementSeenStorageKey(), ts); } catch (e) {}
        }

        const NOTIFICATION_RELEASE_VERSION = '1.0.36';
        const RELEASE_SEEN_KEY = 'oosLastSeenRelease';
        function getReleaseSeenStorageKey() {
            return RELEASE_SEEN_KEY + ':' + getAnnouncementViewerKey().trim().toLowerCase();
        }
        function isCurrentReleaseUnseen() {
            try { return localStorage.getItem(getReleaseSeenStorageKey()) !== NOTIFICATION_RELEASE_VERSION; }
            catch (e) { return true; }
        }
        function markCurrentReleaseSeen() {
            try { localStorage.setItem(getReleaseSeenStorageKey(), NOTIFICATION_RELEASE_VERSION); } catch (e) {}
        }
        function updateReleaseNotificationBadges() {
            const unseen = isCurrentReleaseUnseen();
            const bellBadge = $('notifReleaseBadge');
            const tabBadge = $('notificationReleaseTabBadge');
            if (bellBadge) bellBadge.classList.toggle('show', unseen);
            if (tabBadge) tabBadge.classList.toggle('show', unseen);
            return unseen;
        }
        function canMentionEveryone() {
            return isAdmin || isTeamLeader;
        }
        function announcementScopeTeamId() {
            if (isAdmin) return activeTeam;
            if (isTeamLeader && lockedPod) return teamIdForPod(lockedPod);
            if (agentSessionAuthenticated && agentSessionPod) return teamIdForPod(agentSessionPod);
            if (currentEmployee) return teamIdForPod(podOf(currentEmployee));
            return activeTeam;
        }
        function announcementScopeEmployees() {
            if (isTeamLeader && !isAdmin && lockedPod) return labelerRosterEmployees().filter(employee => employee.pod === lockedPod);
            if (!isAdmin && agentSessionAuthenticated && agentSessionPod) return labelerRosterEmployees().filter(employee => employee.pod === agentSessionPod);
            return employeesForTeam(announcementScopeTeamId());
        }
        function announcementTeamId(announcement) {
            if (!announcement) return null;
            if (announcement.team === TEAM_CWH || announcement.team === TEAM_ALBERTSONS) return announcement.team;
            const pods = Array.isArray(announcement.recipientPods) ? announcement.recipientPods.filter(Boolean) : [];
            const teams = Array.from(new Set(pods.map(teamIdForPod)));
            if (teams.length === 1) return teams[0];
            const authorPod = TEAM_LEADER_POD_BY_NAME[announcement.author] || null;
            return authorPod ? teamIdForPod(authorPod) : null;
        }
        function isAnnouncementWithinViewerTeam(announcement) {
            if (isAdmin) return true;
            const announcementTeam = announcementTeamId(announcement);
            return !!announcementTeam && announcementTeam === announcementScopeTeamId();
        }
        function containsEveryoneMention(text) {
            return /@everyone(?![A-Za-z0-9_])/i.test(String(text || ''));
        }
        function escapeRegExp(str) {
            return String(str).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        }
        function canonicalEmployeeName(name) {
            const lower = String(name || '').trim().toLowerCase();
            if (!lower) return null;
            if (lower === PREMIUM_ACCESS_MANAGER_PUBLIC_LABEL.toLowerCase()) {
                try {
                    const bound = employees.find(employee => employee && employee.employeeId === PREMIUM_ACCESS_MANAGER_EMPLOYEE_ID);
                    if (bound && bound.name) return bound.name;
                } catch (e) {}
                return PREMIUM_ACCESS_MANAGER_NAME;
            }
            const found = employees.find(employee => String(employee.name || '').trim().toLowerCase() === lower);
            return found ? found.name : null;
        }
        function buildMentionRegex() {
            const labels = [];
            employees.forEach(employee => {
                if (!employee || !employee.name) return;
                labels.push(employee.name);
                const publicName = agentDisplayName(employee.name);
                if (publicName && publicName !== employee.name) labels.push(publicName);
            });
            const names = Array.from(new Set(labels)).filter(Boolean)
                .sort((a, b) => b.length - a.length).map(escapeRegExp);
            names.unshift(EVERYONE_MENTION);
            return new RegExp('@(' + names.join('|') + ')(?![A-Za-z0-9_])', 'gi');
        }
        function extractMentions(text, options = {}) {
            const allowEveryone = options.allowEveryone !== false && canMentionEveryone();
            const re = buildMentionRegex();
            const direct = new Set();
            const scopedNames = new Set(announcementScopeEmployees().map(employee => String(employee.name || '').trim().toLowerCase()));
            let mentionAll = false;
            let match;
            while ((match = re.exec(String(text || '')))) {
                if (match[1].toLowerCase() === EVERYONE_MENTION) {
                    mentionAll = true;
                    continue;
                }
                const canonical = canonicalEmployeeName(match[1]);
                if (canonical && scopedNames.has(canonical.toLowerCase())) direct.add(canonical);
            }
            if (mentionAll && allowEveryone) {
                return Array.from(new Set(announcementScopeEmployees().map(employee => employee.name).filter(Boolean)));
            }
            return Array.from(direct);
        }
        function announcementRecipientNames(announcement) {
            if (!announcement || !Array.isArray(announcement.mentions)) return [];
            const unique = new Set();
            announcement.mentions.forEach(name => {
                const canonical = canonicalEmployeeName(name) || String(name || '').trim();
                if (canonical) unique.add(canonical);
            });
            return Array.from(unique);
        }
        function isPrivateAnnouncement(announcement) {
            if (!announcement) return false;
            if (announcement.mentionAll || announcement.notifyAll || announcement.audience === 'all') return false;
            if (announcement.audience === 'private') return true;


            return announcementRecipientNames(announcement).length > 0;
        }
        function getAnnouncementViewerAgentName() {



            if (isAdmin) return null;
            if (isTeamLeader) return canonicalEmployeeName(teamLeaderName);
            if (!agentSessionAuthenticated || !agentSessionName || currentEmployee !== agentSessionName) return null;
            const pod = podOf(agentSessionName);
            return canAccessPodForCurrentSession(pod) ? canonicalEmployeeName(agentSessionName) : null;
        }
        function getAnnouncementPosterKey() {
            if (isAdmin) return 'admin';
            if (isTeamLeader) return 'tl:' + String(teamLeaderName || lockedPod || 'teamleader').trim().toLowerCase();
            return currentEmployee ? 'agent:' + String(currentEmployee).trim().toLowerCase() : 'unselected';
        }
        function isAnnouncementOwnedByViewer(announcement) {
            if (!announcement || (!isAdmin && !isTeamLeader)) return false;
            const currentPosterKey = getAnnouncementPosterKey();
            if (announcement.senderKey) {
                return String(announcement.senderKey).trim().toLowerCase() === currentPosterKey;
            }

            if (isAdmin && announcement.role === 'admin') return true;
            if (isTeamLeader && announcement.role === 'teamleader') {
                return String(announcement.author || '').trim().toLowerCase() ===
                    String(teamLeaderName || 'Team Leader').trim().toLowerCase();
            }
            return false;
        }
        function isAnnouncementVisibleToViewer(announcement) {
            if (!isAnnouncementWithinViewerTeam(announcement)) return false;
            if (!isPrivateAnnouncement(announcement)) return true;
            const viewerAgent = getAnnouncementViewerAgentName();
            if (viewerAgent) {
                const viewerLower = viewerAgent.toLowerCase();
                if (announcementRecipientNames(announcement).some(name => String(name).toLowerCase() === viewerLower)) {
                    return true;
                }
            }

            return isAnnouncementOwnedByViewer(announcement);
        }
        function getVisibleAnnouncements() {
            return cachedAnnouncements.filter(isAnnouncementVisibleToViewer);
        }
        function canDeleteAnnouncement(announcement) {


            return TrinoPermissions.can('announcement.delete', {
                private:isPrivateAnnouncement(announcement),
                owned:isAnnouncementOwnedByViewer(announcement)
            });
        }
        function renderMessageWithMentions(text) {
            const raw = privacySafePublicText(String(text || ''));
            const re = buildMentionRegex();
            const viewerAgent = getAnnouncementViewerAgentName();
            let output = '';
            let lastIndex = 0;
            let match;
            while ((match = re.exec(raw))) {
                output += escapeHtml(raw.slice(lastIndex, match.index));
                const isEveryone = match[1].toLowerCase() === EVERYONE_MENTION;
                const canonical = isEveryone ? EVERYONE_MENTION : (canonicalEmployeeName(match[1]) || match[1]);
                const isSelf = !isEveryone && viewerAgent && canonical.toLowerCase() === viewerAgent.toLowerCase();
                const classes = ['mention-chip'];
                if (isEveryone) classes.push('everyone');
                if (isSelf) classes.push('self');
                const publicMention = isEveryone ? EVERYONE_MENTION : agentDisplayName(canonical);
                output += '<span class="' + classes.join(' ') + '">@' + escapeHtml(publicMention) + '</span>';
                lastIndex = match.index + match[0].length;
            }
            output += escapeHtml(raw.slice(lastIndex));
            return output;
        }
        function updateAnnouncementAudienceHint() {
            const hint = $('announceAudienceHint');
            const composer = $('announceComposerText');
            if (!hint || !composer) return;
            const text = composer.value || '';
            const mentionAll = containsEveryoneMention(text) && canMentionEveryone();
            const directRecipients = extractMentions(text, { allowEveryone: false });
            hint.classList.toggle('all', mentionAll);
            hint.classList.toggle('private', !mentionAll && directRecipients.length > 0);
            if (mentionAll) {
                const scopedEmployees = announcementScopeEmployees();
                const podCount = new Set(scopedEmployees.map(employee => employee.pod).filter(Boolean)).size;
                hint.textContent = '@everyone selected: all ' + scopedEmployees.length + ' agents across ' + podCount + ' scoped pod' + (podCount === 1 ? '' : 's') + ' will receive this announcement.';
                return;
            }
            if (directRecipients.length) {
                hint.textContent = 'Private: only the ' + directRecipients.length + ' tagged agent' +
                    (directRecipients.length === 1 ? '' : 's') + ' will receive and view this announcement.';
                return;
            }
            hint.textContent = 'No agent tags: this announcement will be visible only to agents in your current team scope.';
        }

        function updateNotifBadge() {
            const badge = $('notifBellBadge');
            const tabBadge = $('notificationUnreadTabBadge');
            const bell = $('notifBellBtn');
            const lastSeen = getLastSeenAnnouncementTs();
            const unread = getVisibleAnnouncements().filter(a => a.ts > lastSeen).length;
            const releaseUnseen = updateReleaseNotificationBadges();
            if (badge) {
                if (unread > 0) { badge.textContent = unread > 99 ? '99+' : String(unread); badge.classList.add('show'); }
                else badge.classList.remove('show');
            }
            if (tabBadge) {
                if (unread > 0) { tabBadge.textContent = unread > 99 ? '99+' : String(unread); tabBadge.classList.add('show'); }
                else tabBadge.classList.remove('show');
            }
            if (bell) {
                const unreadText = unread > 0 ? `${unread} unread notification${unread === 1 ? '' : 's'}` : '';
                const releaseText = releaseUnseen ? 'new release notes available' : '';
                const details = [unreadText, releaseText].filter(Boolean).join('; ');
                bell.setAttribute('aria-label', details ? `Open Notification Center; ${details}` : 'Open Notification Center');
                bell.title = details ? `Notification Center · ${details}` : 'Notification Center';
            }
        }

        async function getAnnouncements() {
            try {
                const raw = await appStorage.get('announcements');
                const parsed = raw ? JSON.parse(raw) : [];
                cachedAnnouncements = Array.isArray(parsed) ? parsed : [];
            } catch (e) {}
            return cachedAnnouncements;
        }

        async function addAnnouncement(message) {
            TrinoPermissions.require('announcement.post', {}, 'Only an authenticated Admin or Team Leader can post announcements.');
            const trimmed = (message || '').trim();
            if (!trimmed) return null;
            const mentionAll = containsEveryoneMention(trimmed);
            if (mentionAll && !canMentionEveryone()) throw new Error('You do not have permission to use @everyone.');
            const directRecipients = extractMentions(trimmed, { allowEveryone: false });
            const isPrivate = !mentionAll && directRecipients.length > 0;
            const scopedEmployees = announcementScopeEmployees();
            const recipients = mentionAll ? Array.from(new Set(scopedEmployees.map(employee => employee.name).filter(Boolean))) : directRecipients;
            const recipientPods = mentionAll ? Array.from(new Set(scopedEmployees.map(employee => employee.pod).filter(Boolean))) :
                Array.from(new Set(recipients.map(podOf).filter(Boolean)));
            const publicAnnouncementAuthor = privacySafePublicText(isAdmin ? 'Admin' : (teamLeaderName || 'Team Leader'));
            const publicAnnouncementMessage = privacySafePublicText(trimmed);
            const entry = {
                ts: nowIso(),
                author: publicAnnouncementAuthor,
                role: isAdmin ? 'admin' : 'teamleader',
                senderKey: getAnnouncementPosterKey(),
                team: announcementScopeTeamId(),
                scopePod: isTeamLeader && !isAdmin ? lockedPod : null,
                message: publicAnnouncementMessage,
                audience: isPrivate ? 'private' : 'all',
                mentionAll,
                notifyAll: !isPrivate,
                mentions: recipients,
                recipientCount: isPrivate ? recipients.length : scopedEmployees.length,
                recipientPods
            };
            const arr = await getAnnouncements();
            arr.unshift(entry);
            const next = arr.slice(0, 200);
            cachedAnnouncements = next;
            await saveBlobWithBackup('announcements', JSON.stringify(next));
            return entry;
        }

        async function deleteAnnouncement(ts) {
            const arr = await getAnnouncements();
            const target = arr.find(a => a.ts === ts);
            if (target && !canDeleteAnnouncement(target)) {
                throw new Error('You do not have permission to delete this private announcement.');
            }
            const next = arr.filter(a => a.ts !== ts);
            cachedAnnouncements = next;
            await saveBlobWithBackup('announcements', JSON.stringify(next));
        }

        function renderAnnouncementList() {
            const listEl = $('announceList');
            if (!listEl) return;
            const visibleAnnouncements = getVisibleAnnouncements();
            if (!visibleAnnouncements.length) {
                listEl.innerHTML = '<p class="announce-empty">No announcements for you yet.</p>';
                return;
            }
            listEl.innerHTML = visibleAnnouncements.map(a => {
                const t = new Date(a.ts).toLocaleString('en-US', { timeZone: 'Asia/Manila', month: 'short',
                    day: 'numeric', hour: 'numeric', minute: '2-digit' });
                const privatePost = isPrivateAnnouncement(a);
                const recipients = announcementRecipientNames(a);
                const delBtn = canDeleteAnnouncement(a) ?
                    `<button class="announce-item-del" data-ts="${escapeHtml(a.ts)}" type="button">Delete</button>` : '';
                const audienceBadge = privatePost ?
                    `<span class="announce-item-audience private">Private &middot; ${recipients.length} recipient${recipients.length === 1 ? '' : 's'}</span>` :
                    `<span class="announce-item-audience">All agents${a.recipientCount ? ` &middot; ${a.recipientCount}` : ''}</span>`;
                return `<div class="announce-item">
                    <div class="announce-item-head">
                        <span class="announce-item-author">${escapeHtml(privacySafePublicText(a.author || 'Team'))}</span>
                        <span class="announce-item-time">${escapeHtml(t)} PHT</span>
                    </div>
                    <div class="announce-item-msg">${renderMessageWithMentions(a.message)}</div>
                    ${audienceBadge}
                    ${delBtn}
                </div>`;
            }).join('');
            listEl.querySelectorAll('.announce-item-del').forEach(btn => {
                btn.addEventListener('click', async () => {
                    if (!(await showConfirmAsync(
                        'Delete Announcement?',
                        'Delete this announcement for everyone who can currently see it?',
                        { confirmLabel:'Delete Announcement', cancelLabel:'Cancel', tone:'danger', kind:'announcement-delete' }
                    ))) return;
                    void runAsyncAction(async () => {
                        await deleteAnnouncement(btn.getAttribute('data-ts'));
                        renderAnnouncementList();
                        updateNotifBadge();
                    }, 'Delete announcement');
                });
            });
        }

        function setNotificationCenterTab(tab, options = {}) {
            const nextTab = tab === 'whatsnew' ? 'whatsnew' : 'notifications';
            const markReleaseSeen = options.markReleaseSeen !== false;
            document.querySelectorAll('[data-notification-center-tab]').forEach(btn => {
                const active = btn.getAttribute('data-notification-center-tab') === nextTab;
                btn.classList.toggle('active', active);
                btn.setAttribute('aria-selected', active ? 'true' : 'false');
                btn.tabIndex = active ? 0 : -1;
            });
            const notificationPanel = $('notificationPanelNotifications');
            const releasePanel = $('notificationPanelWhatsNew');
            if (notificationPanel) {
                const active = nextTab === 'notifications';
                notificationPanel.hidden = !active;
                notificationPanel.classList.toggle('active', active);
            }
            if (releasePanel) {
                const active = nextTab === 'whatsnew';
                releasePanel.hidden = !active;
                releasePanel.classList.toggle('active', active);
            }
            if (nextTab === 'whatsnew' && markReleaseSeen) markCurrentReleaseSeen();
            updateNotifBadge();
            return nextTab;
        }

        async function openNotificationCenter(initialTab = 'notifications') {
            await getAnnouncements();
            renderAnnouncementList();
            const overlay = $('announceOverlay');
            if (!overlay) return;
            overlay.classList.add('open');
            const activeTab = setNotificationCenterTab(initialTab, { markReleaseSeen: initialTab === 'whatsnew' });
            if (activeTab === 'notifications') {
                const visibleAnnouncements = getVisibleAnnouncements();
                if (visibleAnnouncements.length) setLastSeenAnnouncementTs(visibleAnnouncements[0].ts);
                updateNotifBadge();
            }
            requestAnimationFrame(() => {
                const tabBtn = $(activeTab === 'whatsnew' ? 'notificationTabWhatsNew' : 'notificationTabNotifications');
                try { tabBtn?.focus({ preventScroll:true }); } catch (e) {}
            });
        }

