        async function copySecureCredentialValue() {
            const input = $('secureCredentialValue');
            const status = $('secureCredentialCopyStatus');
            const value = String(input ? input.value : '');
            if (!value) { if (status) status.textContent = 'No credential is available to copy.'; return; }
            let copied = false;
            try {
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    await navigator.clipboard.writeText(value);
                    copied = true;
                }
            } catch (e) {}
            if (!copied && input) {
                try {
                    input.focus();
                    input.select();
                    input.setSelectionRange(0, value.length);
                    copied = document.execCommand('copy');
                } catch (e) { copied = false; }
            }
            if (status) {
                status.textContent = copied ? 'Copied. Send it privately, then close this dialog.' : 'Copy was blocked by the browser. Select the password and copy it manually.';
                status.classList.toggle('is-copied', copied);
            }
        }




