            const countdown = formatBreakCountdownDuration(remainingMs);
            announcer.textContent = stage === 'one'
                ? `Break ending now. ${countdown} remaining. Please return and prepare to punch End Break.`
                : `Break ending soon. ${countdown} remaining. Please prepare to return on time.`;
