        async function primeBreakWarningAudio() {
            let unlocked = false;
            const ctx = getBreakWarningAudioContext();
            if (ctx) {
                try { if (ctx.state === 'suspended') await ctx.resume(); unlocked = ctx.state === 'running'; } catch (e) {}
            }
            const audio = $('breakWarningAudio');
            if (audio) {
                const oldMuted = audio.muted;
                const oldVolume = audio.volume;
                try {
                    audio.muted = true;
                    audio.volume = 0;
                    audio.currentTime = 0;
                    const playPromise = audio.play();
                    if (playPromise && typeof playPromise.then === 'function') await playPromise;
                    audio.pause();
                    audio.currentTime = 0;
                    unlocked = true;
                } catch (e) {
                } finally {
                    audio.muted = oldMuted;
                    audio.volume = oldVolume || .42;
                }
            }
            if (unlocked) breakWarningAudioBlocked = false;
            syncBreakWarningControls();
            return unlocked;
        }

        function playBreakWarningFallbackChime() {
            const ctx = getBreakWarningAudioContext();
            if (!ctx || ctx.state !== 'running') return false;
            try {
                const start = ctx.currentTime + .01;
                [[659.25,0,.52,.085],[880,.30,.58,.06]].forEach(([freq,delay,duration,peak]) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(freq, start + delay);
                    gain.gain.setValueAtTime(.0001, start + delay);
                    gain.gain.exponentialRampToValueAtTime(peak * breakWarningVolumeScale(), start + delay + .035);
                    gain.gain.exponentialRampToValueAtTime(.0001, start + delay + duration);
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.start(start + delay); osc.stop(start + delay + duration + .03);
                });
                return true;
            } catch (e) { return false; }
        }

        function playBreakWarningEscalationFallback() {
            const ctx = getBreakWarningAudioContext();
            if (!ctx || ctx.state !== 'running') return false;
            try {
                const start = ctx.currentTime + .01;
                [[880,0,.24,.065],[1046.5,.27,.26,.055]].forEach(([freq,delay,duration,peak]) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(freq, start + delay);
                    gain.gain.setValueAtTime(.0001, start + delay);
                    gain.gain.exponentialRampToValueAtTime(peak * breakWarningVolumeScale(), start + delay + .025);
                    gain.gain.exponentialRampToValueAtTime(.0001, start + delay + duration);
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.start(start + delay); osc.stop(start + delay + duration + .03);
                });
                return true;
            } catch (e) { return false; }
        }

        async function playBreakWarningChime(options = {}) {
            if (!breakWarningAudioWanted && !options.force) return false;
            if (options.escalation && playBreakWarningEscalationFallback()) {
                breakWarningAudioBlocked = false;
                syncBreakWarningControls();
                return true;
            }
            const audio = $('breakWarningAudio');
            if (audio) {
                try {
                    audio.pause();
                    audio.currentTime = 0;
                    audio.muted = false;
                    audio.volume = breakWarningMediaVolume(options.escalation === true);
                    const playPromise = audio.play();
                    if (playPromise && typeof playPromise.then === 'function') await playPromise;
                    if (options.escalation) setTimeout(() => { try { audio.pause(); audio.currentTime = 0; } catch (e) {} }, 850);
                    breakWarningAudioBlocked = false;
                    syncBreakWarningControls();
                    return true;
                } catch (e) {}
            }
            const fallback = options.escalation ? playBreakWarningEscalationFallback() : playBreakWarningFallbackChime();
            breakWarningAudioBlocked = !fallback;
            syncBreakWarningControls();
            return fallback;
        }

