            const desktopState = !breakWarningDesktopWanted ? 'Off' : (permission === 'granted' ? 'On' : (permission === 'default' ? 'Needs permission' : (permission === 'denied' ? 'Blocked' : 'Unavailable')));
            const vibrationState = !vibrationSupported ? 'Unavailable' : (breakWarningVibrationWanted ? 'On' : 'Off');
