        function checkBreakWarning(rec, timing = null) {
            const audioToggle = $('breakAudioToggle');
            const ownBreak = isOwnAgentBreakForWarning(rec);
            if (audioToggle) audioToggle.classList.toggle('show', ownBreak);
            if (!ownBreak) {
                hideBreakWarningAlert();
                syncBreakWarningControls();
                return false;
            }
            const startMs = new Date(rec.startBreak).getTime();
            if (!Number.isFinite(startMs)) { hideBreakWarningAlert(); return false; }
            const policyMinutes = timing && Number.isFinite(timing.policyMinutes) ? timing.policyMinutes : getBreakPolicyMinutes(rec);
            const returnMs = timing && Number.isFinite(timing.returnMs) ? timing.returnMs : startMs + policyMinutes * 60000;
            const remainingMs = timing && Number.isFinite(timing.remainingMs) ? timing.remainingMs : returnMs - getTrueNowMs();
            const inWarningWindow = remainingMs > 0 && remainingMs <= BREAK_WARNING_REMAINING_MS;
            if (!inWarningWindow) {
                hideBreakWarningAlert();
                syncBreakWarningControls();
                return false;
            }

            const stage = remainingMs <= BREAK_WARNING_ESCALATION_MS ? 'one' : 'two';
            const escalated = stage === 'one';
            const panel = $('breakCountdownPanel');
            if (panel) panel.classList.add('is-warning');
            if (panel) panel.classList.toggle('is-escalated', escalated);
            const alertEl = $('breakWarningAlert');
            const titleEl = $('breakWarningAlertTitle');
            const timeEl = $('breakWarningAlertTime');
            const msgEl = $('breakWarningAlertMsg');
            const countdownText = formatBreakCountdownDuration(remainingMs);
            if (titleEl) titleEl.textContent = escalated ? `🚨 Break Ending Now · ${countdownText}` : `⚠️ Break Ending Soon · ${countdownText}`;
            if (timeEl) timeEl.textContent = countdownText;
            if (msgEl) msgEl.textContent = escalated
                ? `Return by ${formatManilaTime(new Date(returnMs))}. Please return now and be ready to punch End Break.`
                : `Return by ${formatManilaTime(new Date(returnMs))}. Please prepare to return and punch End Break on time.`;
            if (alertEl) {
                alertEl.classList.add('show');
                alertEl.classList.toggle('is-escalated', escalated);
            }
            const eyebrowEl = $('breakCountdownEyebrow');
            if (eyebrowEl) eyebrowEl.textContent = escalated ? 'Break ending now · 1 minute' : 'Break ending soon · 2 minutes';

            const key = breakWarningKey(rec);
            ensureBreakWarningMemory(key);
            auditBreakWarningTriggered(rec, stage);
            announceBreakWarningStage(rec, stage, remainingMs);
            if (key && !breakWarningStageHandled(key, stage, 'audio') && breakWarningAudioWanted) {



                markBreakWarningStageHandled(key, stage, 'audio');
                void playBreakWarningChime({ escalation:escalated }).then(ok => {
                    if (!ok) {
                        breakWarningAudioBlocked = true;
                        auditBreakWarningAudioBlocked(rec, stage);
                        syncBreakWarningControls();
                    }
                });
            }
            fireBreakWarningVibration(rec, stage);
            showBreakWarningSystemNotification(rec, stage, remainingMs, returnMs);
            syncBreakWarningControls();
            return true;
        }

        function getBreakPolicyMinutes(rec) {



            return BREAK_ALLOWANCE_MINUTES;
        }

        function formatBreakCountdownDuration(ms) {
            const totalSeconds = Math.max(0, Math.ceil(Math.abs(ms) / 1000));
            const hours = Math.floor(totalSeconds / 3600);
            const minutes = Math.floor((totalSeconds % 3600) / 60);
            const seconds = totalSeconds % 60;
            const mm = String(minutes).padStart(2, '0');
            const ss = String(seconds).padStart(2, '0');
            return hours > 0 ? `${hours}:${mm}:${ss}` : `${mm}:${ss}`;
        }

        function updateBreakCountdown(rec) {
            const panel = $('breakCountdownPanel');
            if (!panel) return;
            const active = !!(rec && rec.startBreak && !rec.endBreak && !rec.logOut && !isVoidedAttendanceRecord(rec));
            panel.classList.toggle('show', active);
            if (!active) {
                panel.classList.remove('is-overdue', 'is-warning', 'is-escalated');
                checkBreakWarning(null);
                return;
            }
            const startMs = new Date(rec.startBreak).getTime();
            if (!Number.isFinite(startMs)) {
                panel.classList.remove('show', 'is-overdue', 'is-warning', 'is-escalated');
                checkBreakWarning(null);
                return;
            }
            const policyMinutes = getBreakPolicyMinutes(rec);
            const returnMs = startMs + policyMinutes * 60000;
            const remainingMs = returnMs - getTrueNowMs();
            const overdue = remainingMs < 0;
            const returnEl = $('breakReturnTime');
            const valueEl = $('breakCountdownValue');
            const labelEl = $('breakCountdownLabel');
            const eyebrowEl = $('breakCountdownEyebrow');
            if (returnEl) returnEl.textContent = `Return by: ${formatManilaTime(new Date(returnMs))}`;
            if (valueEl) valueEl.textContent = formatBreakCountdownDuration(remainingMs);
            if (labelEl) {
                const liveDeduction = overdue ? Math.ceil(Math.abs(remainingMs) / 60000) : 0;
                labelEl.textContent = overdue ? `${liveDeduction}m deduction` : 'remaining';
            }
            if (eyebrowEl) eyebrowEl.textContent = overdue ? 'Break overdue · deduction active' : `Break in progress · ${policyMinutes} min`;
            panel.classList.toggle('is-overdue', overdue);
            checkBreakWarning(rec, { policyMinutes, returnMs, remainingMs });
            panel.setAttribute('aria-label', overdue
                ? `Break overdue by ${formatBreakCountdownDuration(remainingMs)}. Expected return ${formatManilaTime(new Date(returnMs))}.`
                : `${formatBreakCountdownDuration(remainingMs)} remaining on break. Expected return ${formatManilaTime(new Date(returnMs))}.`);
        }



        function checkBreakOvertime(rec) {
            const alertEl = $('breakOvertimeAlert');
            if (!alertEl) return;
            if (!rec || !rec.startBreak || rec.endBreak) {
                alertEl.classList.remove('show');
                return;
            }
            const limitMinutes = getBreakPolicyMinutes(rec);
            const elapsedMs = getTrueNowMs() - new Date(rec.startBreak).getTime();
            if (elapsedMs > limitMinutes * 60000) {
                if (breakAlertDismissedFor === rec.startBreak) return;
                const since = formatManilaTime(rec.startBreak);
                $('breakOvertimeAlertMsg').textContent =
                    `Your break started at ${since} and has passed the ${limitMinutes}-minute allowance. Please punch End Break. Each excess minute is automatically deducted from paid regular hours.`;
                alertEl.classList.add('show');
            } else {
                alertEl.classList.remove('show');
            }
        }

