        let stickyPunchWired = false;
        let stickyPunchThresholdY = 0;
        let stickyPunchState = false;
        let stickyPunchFrame = 0;
        let stickyPunchResizeFrame = 0;
        let stickyPunchTransitioning = false;

        function getPageScrollTop() {
            const scroller = document.scrollingElement || document.documentElement;
            return scroller ? scroller.scrollTop : (window.scrollY || 0);
        }

        function stickyPunchAllowedForCurrentRole() {




            return false;
        }

        function syncStickyPunchRoleAccess() {
            const card = $('punchCard');
            if (!card) return false;
            const enabled = stickyPunchAllowedForCurrentRole();
            card.classList.toggle('privileged-sticky-enabled', enabled);
            if (!enabled) {
                stickyPunchState = false;
                card.classList.remove('sticky');
            }
            return enabled;
        }

        function scheduleStickyPunchUpdate() {
            if (stickyPunchTransitioning || stickyPunchFrame) return;
            stickyPunchFrame = requestAnimationFrame(() => {
                stickyPunchFrame = 0;
                const card = $('punchCard');
                if (!card) return;
                if (!syncStickyPunchRoleAccess()) return;
                const y = getPageScrollTop();



                const shouldStick = stickyPunchState ?
                    y > stickyPunchThresholdY - 24 :
                    y > stickyPunchThresholdY + 1;
                if (shouldStick === stickyPunchState) return;

                const scroller = document.scrollingElement || document.documentElement;
                const scrollBefore = scroller ? scroller.scrollTop : y;
                stickyPunchTransitioning = true;


                programmaticScrollUntil = Date.now() + 250;
                stickyPunchState = shouldStick;
                card.classList.toggle('sticky', shouldStick);
                void card.offsetHeight;
                if (scroller) window.__ttInstantScroll(scroller, scrollBefore);




                requestAnimationFrame(() => {
                    requestAnimationFrame(() => {
                        if (scroller) {
                            programmaticScrollUntil = Date.now() + 100;
                            window.__ttInstantScroll(scroller, scrollBefore);
                        }
                        stickyPunchTransitioning = false;
                    });
                });
            });
        }

        function measureStickyPunchThreshold() {
            if (!syncStickyPunchRoleAccess()) return;
            const sentinel = $('punchCardSentinel');
            if (!sentinel) return;
            stickyPunchThresholdY = sentinel.getBoundingClientRect().top + getPageScrollTop();
            scheduleStickyPunchUpdate();
        }

        function initStickyPunch() {
            const card = $('punchCard');
            if (!card) return;


            if (!syncStickyPunchRoleAccess()) return;
            if (stickyPunchWired) {
                requestAnimationFrame(measureStickyPunchThreshold);
                return;
            }
            stickyPunchWired = true;

            let sentinel = $('punchCardSentinel');
            if (!sentinel) {
                sentinel = document.createElement('div');
                sentinel.id = 'punchCardSentinel';
                sentinel.setAttribute('aria-hidden', 'true');
                sentinel.style.cssText = 'height:1px;pointer-events:none;overflow-anchor:none;';
                card.parentNode.insertBefore(sentinel, card);
            }

            window.addEventListener('scroll', scheduleStickyPunchUpdate, { passive: true });
            window.addEventListener('resize', () => {
                if (stickyPunchResizeFrame) cancelAnimationFrame(stickyPunchResizeFrame);
                stickyPunchResizeFrame = requestAnimationFrame(() => {
                    stickyPunchResizeFrame = 0;
                    measureStickyPunchThreshold();
                });
            }, { passive: true });

            if (document.fonts && document.fonts.ready) {
                document.fonts.ready.then(measureStickyPunchThreshold).catch(() => {});
            }
            requestAnimationFrame(() => requestAnimationFrame(measureStickyPunchThreshold));
        }




