                if (!note) { showToast('Enter a rejection/review note before rejecting the request.'); $('tlOtReviewDecisionNote').focus(); return; }
                const rec = await reviewTLOvertimeRequest(date, name, 'rejected', note);
                await logAudit('tl_overtime_request_reject', { date, name, pod:rec.pod || overtimePodForName(name), hours:getStoredOTHoursFromRecord(rec), requestedBy:rec.submittedBy || name, rejectedBy:'Admin', reviewNote:rec.reviewNote || '' });
                closeTLOvertimeReviewModal();
                renderOTTab();
                if (typeof renderAdminOpsCenter === 'function') renderAdminOpsCenter({ force:true });
                showToast(`Rejected the TL overtime request for ${name}. No overtime was added to totals.`);
