        $('dayOffEditToggle').addEventListener('click', function() {
            const pod = $('dayOffPodSelect').value;
            if (!canManageDayOffSwapForPod(pod)) {
                showToast("You do not have permission to edit this pod's day-off schedule.");
                editMode = false;
                renderDayOffTable(pod, false);
                return;
            }
            if (!dayOffSchedule[pod]) {



                dayOffSchedule[pod] = { effective: '', rows: [] };
            }
            editMode = !editMode;
            this.textContent = editMode ? 'Cancel Edit' : dayOffEditToggleIdleLabel();
            renderDayOffTable(pod, editMode);
        });
        $('dayOffSaveBtn').addEventListener('click', () => {
            void runAsyncAction(async () => {
                const pod = $('dayOffPodSelect').value;
                if (!canManageDayOffSwapForPod(pod)) {
                    showToast("You do not have permission to edit this pod's day-off schedule.");
                    editMode = false;
                    renderDayOffTable(pod, false);
                    return;
                }
                const data = dayOffSchedule[pod];
                if (!data) return;

                const inputs = Array.from(document.querySelectorAll('.dayoff-cell-input'));
                const newRows = [];
                const rowMap = {};
                inputs.forEach(inp => {
                    const row = parseInt(inp.dataset.row), col = parseInt(inp.dataset.col);
                    if (!rowMap[row]) rowMap[row] = [];
                    rowMap[row][col] = inp.value;
                });
                Object.keys(rowMap).map(Number).sort((a,b) => a-b).forEach(r => {
                    const row = [];
                    for (let c = 0; c < 7; c++) row.push(rowMap[r][c] || '');
                    newRows.push(row);
                });

                const tlInputs = Array.from(document.querySelectorAll('[data-tl-dayoff-name][data-tl-dayoff-dow]'));
                const tlInputGroups = new Map();
                tlInputs.forEach(input => {
                    const name = String(input.dataset.tlDayoffName || '').trim();
                    if (!name) return;
                    if (!tlInputGroups.has(name)) tlInputGroups.set(name, []);
                    tlInputGroups.get(name).push(input);
                });
                const tlChanges = [];
                tlInputGroups.forEach((group, name) => {
                    if (!TrinoPermissions.can('schedule.tl_recurring_dayoff.manage', { name, pod })) return;
                    const before = teamLeaderScheduledOffDays(pod, name);
                    const after = normalizeTeamLeaderOffDays(group.filter(input => input.checked).map(input => Number(input.dataset.tlDayoffDow)));
                    if (JSON.stringify(before) !== JSON.stringify(after)) tlChanges.push({ name, before, after });
                });

                const backupChanges = [];
                Array.from(document.querySelectorAll('[data-tl-backup-primary]')).forEach(select => {
                    const primaryName = String(select.dataset.tlBackupPrimary || '').trim();
                    if (!primaryName || !TrinoPermissions.can('schedule.tl_backup.manage', { name:primaryName, pod })) return;
                    const before = teamLeaderBackupForPrimary(pod, primaryName);
                    const after = String(select.value || '').trim();
                    if (after) {
                        const valid = teamLeaderBackupCandidatesForPrimary(pod, primaryName).some(candidate => candidate.name === after);
                        if (!valid) throw new Error('Choose a valid Backup TL from the same operating team.');
                    }
                    if (before !== after) backupChanges.push({ primaryName, before, after });
                });

                if (tlChanges.length || backupChanges.length) {
                    const projectedBackupMap = { ...ensureTeamLeaderBackupMap(pod) };
                    backupChanges.forEach(change => {
                        if (change.after) projectedBackupMap[change.primaryName] = change.after;
                        else delete projectedBackupMap[change.primaryName];
                    });
                    const projectedOffDaysByName = {};
                    teamLeadersForPod(pod).forEach(tl => { projectedOffDaysByName[tl.name] = teamLeaderScheduledOffDays(pod, tl.name); });
                    tlChanges.forEach(change => { projectedOffDaysByName[change.name] = change.after.slice(); });
                    const recurringConflicts = projectedRecurringBackupCoverageConflicts(pod, { backupMap:projectedBackupMap, offDaysByName:projectedOffDaysByName });
                    if (recurringConflicts.length) {
                        throw new Error(`Backup TL double-coverage conflict. ${recurringConflicts.map(describeProjectedBackupCoverageConflict).join(' | ')}. Assign one Backup TL for each overlapping POD/day before saving.`);
                    }
                }

                let tlReason = '';
                if (tlChanges.length || backupChanges.length) {
                    const changedNames = Array.from(new Set([
                        ...tlChanges.map(change => agentDisplayName(change.name)),
                        ...backupChanges.map(change => agentDisplayName(change.primaryName))
                    ])).join(', ');
                    tlReason = await showPromptAsync(
                        (tlChanges.length + backupChanges.length) === 1 ? 'Reason for TL Schedule / Backup Change' : 'Reason for TL Schedule / Backup Changes',
                        `Record why the Team Leader schedule or Backup TL assignment is changing for <strong>${escapeHtml(changedNames)}</strong> in <strong>${escapeHtml(podDisplayName(pod))}</strong>.`,
                        { label:'Change reason', placeholder:'Required for audit trail', required:true, maxLength:240 },
                        { confirmLabel:'Save Schedule', cancelLabel:'Cancel', kind:'tl-recurring-dayoff-audit' }
                    );
                    if (tlReason === null) return;
                    tlReason = String(tlReason).trim();
                    if (!tlReason) return;
                }

                const effInput = $('dayOffEffInput');
                data.rows = newRows;
                if (effInput) data.effective = effInput.value;
                if (tlChanges.length) {
                    const byName = ensureTeamLeaderOffDaysByName(pod);
                    tlChanges.forEach(change => { byName[change.name] = change.after.slice(); });
                }
                if (backupChanges.length) {
                    const backupMap = ensureTeamLeaderBackupMap(pod);
                    backupChanges.forEach(change => {
                        if (change.after) backupMap[change.primaryName] = change.after;
                        else delete backupMap[change.primaryName];
                    });
                }
                await saveDayOffSchedule();

                for (const change of tlChanges) {
                    await logAudit('tl_recurring_dayoff_schedule_updated', {
                        targetTeamLeader:change.name,
                        targetRole:'Team Leader',
                        pod,
                        reason:tlReason,
                        schedule_action:change.after.length ? 'recurring_dayoff_update' : 'recurring_dayoff_clear',
                        storageModel:'per_team_leader',
                        modified_by:trinoPermissionActor().id || trinoPermissionActor().name,
                        old:{ offDays:change.before, labels:change.before.map(d => DAY_OFF_HEADERS[d]) },
                        new:{ offDays:change.after, labels:change.after.map(d => DAY_OFF_HEADERS[d]) }
                    });
                }
                for (const change of backupChanges) {
                    await logAudit('tl_backup_delegate_updated', {
                        targetTeamLeader:change.primaryName,
                        targetRole:'Team Leader',
                        pod,
                        reason:tlReason,
                        schedule_action:change.after ? 'backup_delegate_assign' : 'backup_delegate_clear',
                        modified_by:trinoPermissionActor().id || trinoPermissionActor().name,
                        old:{ backupTeamLeader:change.before || '' },
                        new:{ backupTeamLeader:change.after || '' },
                        automaticAccessRule:'active_only_while_primary_scheduled_day_off'
                    });
                }

                editMode = false;
                const toggle = $('dayOffEditToggle');
                if (toggle) toggle.textContent = dayOffEditToggleIdleLabel();
                renderDayOffTable(pod, false);
                renderDayOffSwapList(pod);
                const tlMessage = tlChanges.length ? ` Team Leader schedule${tlChanges.length === 1 ? '' : 's'} updated.` : '';
                const backupMessage = backupChanges.length ? ` Backup TL assignment${backupChanges.length === 1 ? '' : 's'} updated.` : '';
                showToast(`Day-off schedule saved.${tlMessage}${backupMessage}`);
            }, 'Save day-off schedule');
        });
