        (function () {
            const textarea = $('announceComposerText');
            const dropdown = $('mentionDropdown');
            if (!textarea || !dropdown) return;
            let activeIndex = -1;
            let currentMatches = [];
            let mentionAt = -1;

            function getMentionQuery() {
                const val = textarea.value;
                const pos = textarea.selectionStart;
                const uptoCursor = val.slice(0, pos);
                const at = uptoCursor.lastIndexOf('@');
                if (at === -1) return null;
                const query = uptoCursor.slice(at + 1);
                if (query.indexOf('\n') !== -1 || query.length > 60) return null;

                const lowerQuery = query.toLowerCase();
                const scopedEmployees = announcementScopeEmployees();
                const targets = scopedEmployees.flatMap(employee => {
                    const publicName = String(agentDisplayName(employee.name) || '').toLowerCase();
                    if (isPremiumAccessManagerPublicIdentity(employee.name)) return [publicName];
                    return [String(employee.name || '').toLowerCase(), publicName];
                }).filter(Boolean);
                if (canMentionEveryone()) targets.unshift(EVERYONE_MENTION);
                const completedTarget = targets.some(target => lowerQuery.startsWith(target + ' '));
                const couldStillBeLongerTarget = targets.some(target => target.startsWith(lowerQuery));
                if (completedTarget && !couldStillBeLongerTarget) return null;
                return { at, query };
            }

            function closeDropdown() {
                dropdown.classList.remove('show');
                dropdown.innerHTML = '';
                currentMatches = [];
                activeIndex = -1;
                mentionAt = -1;
            }

            function renderDropdown() {
                if (!currentMatches.length) {
                    dropdown.innerHTML = '<div class="mention-empty">No matching agents</div>';
                    dropdown.classList.add('show');
                    return;
                }
                dropdown.innerHTML = currentMatches.map((item, i) =>
                    `<div class="mention-option${item.kind === 'everyone' ? ' everyone' : ''}${i === activeIndex ? ' active' : ''}" data-idx="${i}">
                        <span>${item.kind === 'everyone' ? '@everyone' : escapeHtml(agentDisplayName(item.name))}</span>
                        <span class="mo-pod">${escapeHtml(item.pod || '')}</span>
                    </div>`
                ).join('');
                dropdown.classList.add('show');
                dropdown.querySelectorAll('.mention-option').forEach(option => {
                    option.addEventListener('mousedown', (event) => {
                        event.preventDefault();
                        selectMention(parseInt(option.getAttribute('data-idx'), 10));
                    });
                });
            }

            function selectMention(idx) {
                const item = currentMatches[idx];
                if (!item || mentionAt === -1) { closeDropdown(); return; }
                const val = textarea.value;
                const pos = textarea.selectionStart;
                const before = val.slice(0, mentionAt);
                const after = val.slice(pos);
                const inserted = item.kind === 'everyone' ? '@everyone ' : '@' + agentDisplayName(item.name) + ' ';
                textarea.value = before + inserted + after;
                const newPos = (before + inserted).length;
                textarea.focus();
                textarea.setSelectionRange(newPos, newPos);
                closeDropdown();
                updateAnnouncementAudienceHint();
            }

            function updateDropdown() {
                const q = getMentionQuery();
                if (!q) { closeDropdown(); return; }
                mentionAt = q.at;
                const query = q.query.toLowerCase();
                const val = textarea.value;
                const pos = textarea.selectionStart;
                const textWithoutCurrentMention = val.slice(0, mentionAt) + val.slice(pos);
                const alreadySelected = new Set(
                    extractMentions(textWithoutCurrentMention, { allowEveryone: false }).map(name => name.toLowerCase())
                );
                const scopedEmployees = announcementScopeEmployees();
                const matches = scopedEmployees
                    .filter(employee => {
                        if (!employee.name) return false;
                        const publicName = String(agentDisplayName(employee.name) || '');
                        const haystack = isPremiumAccessManagerPublicIdentity(employee.name) ? publicName : `${employee.name} ${publicName}`;
                        return haystack.toLowerCase().includes(query);
                    })
                    .filter(employee => !alreadySelected.has(employee.name.toLowerCase()))
                    .slice(0, ANNOUNCEMENT_AUTOCOMPLETE_LIMIT)
                    .map(employee => ({ kind: 'employee', name: employee.name, pod: employee.pod }));
                if (canMentionEveryone() && EVERYONE_MENTION.includes(query.trim())) {
                    matches.unshift({ kind: 'everyone', name: EVERYONE_MENTION, pod: 'All ' + scopedEmployees.length + ' scoped agents' });
                }
                currentMatches = matches.slice(0, ANNOUNCEMENT_AUTOCOMPLETE_LIMIT + 1);
                activeIndex = currentMatches.length ? 0 : -1;
                renderDropdown();
            }

            textarea.addEventListener('input', () => {
                updateDropdown();
                updateAnnouncementAudienceHint();
            });
            textarea.addEventListener('click', updateDropdown);
            textarea.addEventListener('keydown', (event) => {
                if (!dropdown.classList.contains('show')) return;
                if (event.key === 'ArrowDown') {
                    event.preventDefault();
                    if (currentMatches.length) { activeIndex = (activeIndex + 1) % currentMatches.length; renderDropdown(); }
                } else if (event.key === 'ArrowUp') {
                    event.preventDefault();
                    if (currentMatches.length) { activeIndex = (activeIndex - 1 + currentMatches.length) % currentMatches.length; renderDropdown(); }
                } else if (event.key === 'Enter' || event.key === 'Tab') {
                    if (activeIndex >= 0) { event.preventDefault(); selectMention(activeIndex); }
                } else if (event.key === 'Escape') {
                    closeDropdown();
                }
            });
            textarea.addEventListener('blur', () => { setTimeout(closeDropdown, 150); });
            updateAnnouncementAudienceHint();
        })();

        $('refreshStatusBtn').addEventListener('click', renderTodayStatus);

        (function () {
            const btn = $('minimizeStatusBtn');
            const grid = $('statusGrid');
            if (!btn || !grid) return;
            const applyState = (minimized) => {
                grid.style.display = minimized ? 'none' : '';
                btn.textContent = minimized ? 'Expand ▼' : 'Minimize ▲';
                btn.setAttribute('aria-expanded', String(!minimized));
            };
            applyState(false);
            btn.addEventListener('click', () => {
                applyState(grid.style.display !== 'none');
            });
        })();

        function analyzeAttendanceRecordForDashboard(rec) {
            rec = rec || {};
            const date = rec.date || '';
            if (isVoidedAttendanceRecord(rec)) {
                return { status:'Voided', statusClass:'flag-info', hasIssue:false, categories:['voided'], late:false, early:false, longBreak:false, reducedCredit:false, manualDeductionHours:0, manualCreditOverrideHours:null, missingTimeOut:false, incomplete:false, regularHours:null, otHours:0, nightDiffHours:0, hasPunch:Boolean(rec.timeIn || rec.startBreak || rec.endBreak || rec.logOut) };
            }
            const hasPunch = Boolean(rec.timeIn || rec.startBreak || rec.endBreak || rec.logOut);
            const isToday = date === todayKeyPart();
            const late = Boolean(rec.timeIn && isLateTimeIn(rec, date, rec.pod));
            const early = Boolean(rec.logOut && isEarlyLogout(rec, date, rec.pod));
            const longBreak = Boolean(rec.startBreak && isLongBreak(rec));
            const scheduledDayOffAttendance = Boolean(rec.timeIn && attendanceWasScheduledOff(rec, rec.name || '', date, rec.pod));
            let status = 'Note only', statusClass = 'flag-info';
            if (hasPunch) {
                status = 'Incomplete'; statusClass = 'status-issue';
                if (rec.timeIn && rec.logOut && !(rec.startBreak && !rec.endBreak)) { status = 'Complete'; statusClass = 'status-complete'; }
                else if (isToday && rec.timeIn && !rec.logOut && rec.startBreak && !rec.endBreak) { status = 'On Break'; statusClass = 'status-break'; }
                else if (isToday && rec.timeIn && !rec.logOut) { status = 'Active'; statusClass = 'status-active'; }
                else if (!isToday && rec.timeIn && !rec.logOut) { status = 'Missing Time Out'; statusClass = 'status-issue'; }
            }
            let regularHours = null, otHours = 0, nightDiffHours = 0;
            if (rec.logOut) {
                regularHours = computeRegularHours(rec, date, rec.pod);
                otHours = getApprovedOTHours(date, rec.name || '');
                if (nightDiffEnabledForRecord(rec, rec.name, rec.pod)) nightDiffHours = computeNightDiffHours(rec, date, rec.pod);
            }
            const manualDeductionHours = getManualDeductionHours(rec);
            const manualCreditOverrideHours = getManualCreditOverrideHours(rec);
            const breakDeductionHours = getExcessBreakHours(rec);
            const reducedCredit = status === 'Complete' && Number.isFinite(regularHours) && regularHours < 5.995 && manualCreditOverrideHours === null && !late && !early && manualDeductionHours <= 0 && breakDeductionHours <= 0;
            const missingTimeOut = status === 'Missing Time Out';
            const incomplete = hasPunch && status === 'Incomplete';
            const hasIssue = Boolean(hasPunch && (missingTimeOut || incomplete || late || early || longBreak || reducedCredit || manualDeductionHours > 0 || manualCreditOverrideHours !== null || scheduledDayOffAttendance));
            const categories = [];
            if (missingTimeOut) categories.push('missing');
            if (late) categories.push('late');
            if (early) categories.push('early');
            if (longBreak) categories.push('break');
            if (reducedCredit) categories.push('reduced');
            if (manualDeductionHours > 0) categories.push('adjustment');
            if (manualCreditOverrideHours !== null) categories.push('override');
            if (incomplete) categories.push('incomplete');
            if (scheduledDayOffAttendance) categories.push('dayoff-attendance');
            return { status, statusClass, hasIssue, categories, late, early, longBreak, reducedCredit, scheduledDayOffAttendance, manualDeductionHours, manualCreditOverrideHours, breakDeductionHours, missingTimeOut, incomplete, regularHours, otHours, nightDiffHours, hasPunch };
        }

        function dashboardState() {
            try {
                if (window.trinoAttendanceDashboard && typeof window.trinoAttendanceDashboard.getState === 'function') {
                    return window.trinoAttendanceDashboard.getState() || {};
                }
            } catch (e) {}
            return {};
        }

        function getExportRowsForCurrentView() {
            const state = dashboardState();
            const query = String(state.query || '').trim().toLowerCase().replace(/\s+/g, ' ');
            const selectedAgent = query ? String(state.selectedAgent || '').trim() : '';
            const category = String(state.category || '');
            return getFilteredRows().filter(rec => {
                if (isVoidedAttendanceRecord(rec)) return false;
                if (selectedAgent && rec.name !== selectedAgent) return false;
                if (!selectedAgent && query) {
                    const canonical=String(rec.name || '').toLowerCase().replace(/\s+/g, ' ');
                    const shown=String(agentDisplayName(rec.name) || rec.name || '').toLowerCase().replace(/\s+/g, ' ');
                    if (!canonical.includes(query) && !shown.includes(query)) return false;
                }
                const analysis = analyzeAttendanceRecordForDashboard(rec);
                if (state.issuesOnly && !analysis.hasIssue) return false;
                if (category && !analysis.categories.includes(category)) return false;
                return true;
            });
        }

        function getTodaySummaryForDashboard() {
            const today = todayKeyPart();
            const scoped = attendanceViewerEmployees();
            const scopeLabel = (!isAdmin && !isTeamLeader) ? (agentSessionAuthenticated ? `${agentSessionPod} teammates` : 'Agent view') :
                (isTeamLeader ? (lockedPod || activePod) : activePod);
            const summary = { working:0, onBreak:0, complete:0, notIn:0, issues:0, scope: scopeLabel, scheduled:0 };
            scoped.forEach(emp => {
                const source = getTodayRecord(emp.name) || {};
                const recDate = attendanceRecordDate(source, today);
                const rec = { ...source, date:recDate, name:emp.name, pod:source.pod || emp.pod };
                const availability = resolveEffectiveAvailability(emp.name, today, emp.pod, { atMs:getTrueNowMs(), includeAttendance:false });
                if (availability.available) summary.scheduled += 1;
                if (isVoidedAttendanceRecord(rec)) { if (availability.available) summary.notIn += 1; return; }
                if (!rec.timeIn) { if (availability.available) summary.notIn += 1; return; }
                if (rec.logOut) summary.complete += 1;
                else if (rec.startBreak && !rec.endBreak) summary.onBreak += 1;
                else summary.working += 1;
                if (analyzeAttendanceRecordForDashboard(rec).hasIssue) summary.issues += 1;
            });
            return summary;
        }

        function getAgentQuickStatusForDashboard(name) {
            name = name || currentEmployee;
            if (!name) return null;
            if (!isAdmin && !isTeamLeader && !canRegularAgentViewAttendanceName(name)) return null;
            const today = todayKeyPart();
            const rosterPod = podOf(name) || activePod;
            if (isTeamLeader && !isAdmin && lockedPod && rosterPod !== lockedPod) return null;
            const rec = getTodayRecord(name) || {};
            const recDate = attendanceRecordDate(rec, today);
            const pod = rec.pod || rosterPod;
            if (isVoidedAttendanceRecord(rec)) return { state:'off', label:'NOT YET IN', detail:"Today\'s attendance record is voided and excluded from payroll" };
            if (!rec.timeIn) {
                const availability = resolveEffectiveAvailability(name, today, rosterPod, { atMs:getTrueNowMs(), includeAttendance:false });
                if (!availability.available && availability.sourceKind === 'day_off') {
                    return { state:'off', label:'DAY OFF', detail:availability.reason };
                }
                if (!availability.available && availability.sourceKind === 'leave') {
                    const leave = availability.leaveRequest;
                    return { state:'off', label:'ON LEAVE', detail:(leave && leave.leaveType) || availability.reason };
                }
                return { state:'off', label:'NOT YET IN', detail:'No Time In recorded today' };
            }
            const scheduledOff = attendanceWasScheduledOff(rec, name, recDate, pod);
            const offNote = scheduledOff ? ` • ⚠ ${scheduledDayOffAttendanceNote(name, recDate, pod)}` : '';
            if (rec.logOut) {
                const regular = computeRegularHours({ ...rec, name, date:recDate, pod }, recDate, pod);
                const ot = getApprovedOTHours(recDate, name);
                const total = Number.isFinite(regular) ? regular + ot : null;
                return { state:'complete', label:scheduledOff ? 'SHIFT COMPLETE · DAY OFF' : 'SHIFT COMPLETE', detail:(total === null ? formatManilaTime(rec.logOut, true) : `${total.toFixed(2)}h credited • out ${formatManilaTime(rec.logOut, true)}`) + offNote };
            }
            if (rec.startBreak && !rec.endBreak) return { state:'break', label:scheduledOff ? 'ON BREAK · DAY OFF' : 'ON BREAK', detail:`Since ${formatManilaTime(rec.startBreak, true)}${offNote}` };
            return { state:'active', label:scheduledOff ? 'IN · DAY OFF' : 'IN', detail:`Since ${formatManilaTime(rec.timeIn, true)}${offNote}` };
        }

        function getIntegrityIssuesForDashboard() {
            const rows = getFilteredRows().filter(rec => !isVoidedAttendanceRecord(rec) && (rec.timeIn || rec.startBreak || rec.endBreak || rec.logOut));
            const issues = [];
            const add = (rec, type, message, severity='warning') => issues.push({ date:rec.date, name:rec.name, pod:rec.pod, type, message, severity });
            const ms = value => {
                if (!value) return null;
                const n = new Date(value).getTime();
                return Number.isFinite(n) ? n : NaN;
            };
            rows.forEach(rec => {
                const fields = ['timeIn','startBreak','endBreak','logOut'];
                fields.forEach(field => { if (rec[field] && Number.isNaN(ms(rec[field]))) add(rec, 'Invalid timestamp', `${field} is not a valid date/time value.`, 'error'); });
                if (rec.timeIn && attendanceWasScheduledOff(rec, rec.name, rec.date, rec.pod || podOf(rec.name))) {
                    add(rec, 'Day-off attendance', 'Time In was confirmed on a scheduled day off. Attendance remains live and visible to TL/Admin.', 'warning');
                }
                const ti=ms(rec.timeIn), sb=ms(rec.startBreak), eb=ms(rec.endBreak), lo=ms(rec.logOut);
                if (rec.startBreak && !rec.timeIn) add(rec, 'Impossible sequence', 'Start Break exists without Time In.', 'error');
                if (rec.endBreak && !rec.startBreak) add(rec, 'Impossible sequence', 'End Break exists without Start Break.', 'error');
                if (rec.logOut && !rec.timeIn) add(rec, 'Impossible sequence', 'Time Out exists without Time In.', 'error');
                if (Number.isFinite(ti) && Number.isFinite(sb) && sb <= ti) add(rec, 'Time order', 'Start Break is not after Time In.', 'error');
                if (Number.isFinite(sb) && Number.isFinite(eb) && eb <= sb) add(rec, 'Time order', 'End Break is not after Start Break.', 'error');
                if (Number.isFinite(ti) && Number.isFinite(lo) && lo <= ti) add(rec, 'Time order', 'Time Out is not after Time In.', 'error');
                if (Number.isFinite(eb) && Number.isFinite(lo) && lo <= eb) add(rec, 'Time order', 'Time Out is not after End Break.', 'error');
                if (rec.startBreak && !rec.endBreak && rec.logOut) add(rec, 'Open break', 'Time Out exists while the break is still open.', 'error');
                const seen = new Map();
                fields.forEach(field => {
                    const value = rec[field];
                    if (!value) return;
                    if (seen.has(value)) add(rec, 'Duplicate timestamp', `${field} exactly matches ${seen.get(value)}.`, 'warning');
                    else seen.set(value, field);
                });
                if (rec.date !== todayKeyPart() && rec.timeIn && !rec.logOut) add(rec, 'Missing Time Out', 'Past shift has a Time In but no Time Out.', 'warning');
            });
            const byName = new Map();
            rows.filter(r => r.timeIn).forEach(rec => {
                const list = byName.get(rec.name) || []; list.push(rec); byName.set(rec.name, list);
            });
            byName.forEach(list => {
                list.sort((a,b) => ms(a.timeIn) - ms(b.timeIn));
                for (let i=1;i<list.length;i++) {
                    const prev=list[i-1], curr=list[i];
                    const prevOut=ms(prev.logOut), currIn=ms(curr.timeIn);
                    if (!prev.logOut) add(curr, 'Possible overlap', `A newer shift starts while ${prev.date} still has no Time Out.`, 'warning');
                    else if (Number.isFinite(prevOut) && Number.isFinite(currIn) && currIn < prevOut) add(curr, 'Overlapping shifts', `Time In overlaps the prior shift from ${prev.date}.`, 'error');
                }
            });
            return { issues, scanned:rows.length, scope:activePod };
        }


        const EXPORT_CENTER_PREFS_KEY = 'trinotime.exportCenter.preferences.v2';
        const EXPORT_PAYROLL_STANDARD_DAILY_HOURS = 6;
        const EXPORT_PAYROLL_DEFAULT_REGULAR_RATE_PHP = 162;

        function exportPayrollNormalizeRate(value, fallback) {
            const parsed = Number(value);
            if (Number.isFinite(parsed) && parsed >= 0) return Math.round(parsed * 100) / 100;
            return Math.round((Number(fallback) || 0) * 100) / 100;
        }

        function exportPayrollRates(context) {
            const ctx = context || {};
            const regularRate = exportPayrollNormalizeRate(ctx.regularRate, EXPORT_PAYROLL_DEFAULT_REGULAR_RATE_PHP);
            const overtimeRate = ctx.otRateInheritsRegular !== false
                ? regularRate
                : exportPayrollNormalizeRate(ctx.otRate, regularRate);
            return { regularRate, overtimeRate };
        }

        function exportPayrollPayBreakdown(regularHours, overtimeHours, context) {
            const regular = Math.max(0, Number(regularHours) || 0);
            const overtime = Math.max(0, Number(overtimeHours) || 0);
            const rates = exportPayrollRates(context);
            const regularPay = Math.round(regular * rates.regularRate * 100) / 100;
            const overtimePay = Math.round(overtime * rates.overtimeRate * 100) / 100;
            return {
                regularRate:rates.regularRate,
                overtimeRate:rates.overtimeRate,
                regularPay,
                overtimePay,
                totalPay:Math.round((regularPay + overtimePay) * 100) / 100
            };
        }

        let exportCenterBusy = false;
        let exportCenterPreviewToken = 0;

        function exportCenterLoadPrefs() {
            try {
                const raw = localStorage.getItem(EXPORT_CENTER_PREFS_KEY);
                const parsed = raw ? JSON.parse(raw) : null;
                return parsed && typeof parsed === 'object' ? parsed : {};
            } catch (_) { return {}; }
        }

        function exportCenterSavePrefs(plan) {
            if (!plan) return;
            try {
                localStorage.setItem(EXPORT_CENTER_PREFS_KEY, JSON.stringify({
                    period:plan.period, scope:plan.scope, reportType:plan.reportType, format:plan.format,
                    regularRate:plan.regularRate, otRate:plan.otRateInheritsRegular ? '' : plan.otRate
                }));
            } catch (_) {}
        }

        function exportCenterDateRange(period, customFrom, customTo) {
            const today = exportReportDateFromValue(todayKeyPart()) || new Date();
            const day = new Date(today.getFullYear(), today.getMonth(), today.getDate());
            let from = null, to = null;
            switch (period) {
                case 'previousWeek': {
                    const currentStart = getWeekStartDate(day);
                    from = new Date(currentStart.getFullYear(), currentStart.getMonth(), currentStart.getDate() - 7);
                    to = new Date(from.getFullYear(), from.getMonth(), from.getDate() + 6);
                    break;
                }
                case 'currentMonth':
                    from = new Date(day.getFullYear(), day.getMonth(), 1);
                    to = new Date(day.getFullYear(), day.getMonth() + 1, 0);
                    break;
                case 'previousMonth':
                    from = new Date(day.getFullYear(), day.getMonth() - 1, 1);
                    to = new Date(day.getFullYear(), day.getMonth(), 0);
                    break;
                case 'custom':
                    from = exportReportDateFromValue(customFrom);
                    to = exportReportDateFromValue(customTo);
                    if (!from || !to) throw new Error('Choose both From and To dates for the custom export range.');
                    if (to < from) [from, to] = [to, from];
                    break;
                case 'currentWeek':
                default:
                    from = getWeekStartDate(day);
                    to = new Date(from.getFullYear(), from.getMonth(), from.getDate() + 6);
                    break;
            }
            return { from, to, fromIso:exportReportIsoDate(from), toIso:exportReportIsoDate(to) };
        }

        function exportCenterBaseEmployees() {
            let list = [];
            try { list = labelerRosterEmployees().slice(); } catch (_) { list = []; }
            list = list.filter(emp => emp && emp.name && !isKnownTeamLeader(emp.name));
            if (isAdmin) return list.filter(emp => teamIdForPod(emp.pod) === activeTeam);
            if (isTeamLeader) {
                const pod = lockedPod || activePod;
                return list.filter(emp => emp.pod === pod);
            }
            if (agentSessionAuthenticated && agentSessionPod) return list.filter(emp => emp.pod === agentSessionPod);
            return [];
        }

        function exportCenterScopeEmployees(plan) {
            let list = exportCenterBaseEmployees();
            const scope = plan && plan.scope ? plan.scope : 'currentPod';
            if (scope === 'allAgents' && isAdmin) return list;
            if (scope === 'individual') {
                const target = String((plan && plan.agent) || '').trim();
                return target ? list.filter(emp => emp.name === target) : [];
            }
            let pod = '';
            if (isAdmin) pod = activePod !== ALL_PODS_LABEL ? activePod : '';
            else if (isTeamLeader) pod = lockedPod || activePod;
            else pod = agentSessionPod || activePod;
            return pod ? list.filter(emp => emp.pod === pod) : list;
        }

        function exportCenterScopeLabel(plan, employees) {
            const list = employees || exportCenterScopeEmployees(plan);
            if (plan && plan.scope === 'individual') {
                const name = String(plan.agent || '').trim();
                return name ? `Agent · ${agentDisplayName(name)}` : 'Individual Agent';
            }
            const pods = Array.from(new Set(list.map(emp => emp.pod).filter(Boolean))).sort();
            if (plan && plan.scope === 'allAgents' && isAdmin) return `${teamGroupById(activeTeam).fullName} · All Agents`;
            if (pods.length === 1) return `${podDisplayName(pods[0])} · ${list.length} Agent${list.length === 1 ? '' : 's'}`;
            if (pods.length > 1) return `${teamGroupById(activeTeam).fullName} · ${pods.length} PODs`;
            return isAdmin ? `${teamGroupById(activeTeam).fullName} · Active Scope` : 'Assigned Scope';
        }

        function exportCenterReadPlan() {
            const period = $('exportCenterPeriod') ? $('exportCenterPeriod').value : 'currentWeek';
            const range = exportCenterDateRange(period,
                $('exportCenterFrom') ? $('exportCenterFrom').value : '',
                $('exportCenterTo') ? $('exportCenterTo').value : '');
            const scope = $('exportCenterScope') ? $('exportCenterScope').value : 'currentPod';
            const agent = $('exportCenterAgent') ? $('exportCenterAgent').value : '';
            if (scope === 'individual' && !agent) throw new Error('Choose an Agent for the Individual Agent export scope.');
            const regularRateRaw = $('exportCenterRegularRate') ? String($('exportCenterRegularRate').value || '').trim() : '';
            const otRateRaw = $('exportCenterOtRate') ? String($('exportCenterOtRate').value || '').trim() : '';
            const regularRate = regularRateRaw === '' ? EXPORT_PAYROLL_DEFAULT_REGULAR_RATE_PHP : Number(regularRateRaw);
            if (!Number.isFinite(regularRate) || regularRate < 0) throw new Error('Regular export rate must be zero or greater.');
            const otRateInheritsRegular = otRateRaw === '';
            const otRate = otRateInheritsRegular ? regularRate : Number(otRateRaw);
            if (!Number.isFinite(otRate) || otRate < 0) throw new Error('OT export rate must be zero or greater, or leave it blank to match the regular rate.');
            const plan = {
                period,
                scope:scope === 'allAgents' && !isAdmin ? 'currentPod' : scope,
                agent,
                reportType:$('exportCenterReportType') ? $('exportCenterReportType').value : 'full',
                format:$('exportCenterFormat') ? $('exportCenterFormat').value : 'excel',
                fromIso:range.fromIso,
                toIso:range.toIso,
                regularRate:exportPayrollNormalizeRate(regularRate, EXPORT_PAYROLL_DEFAULT_REGULAR_RATE_PHP),
                otRate:exportPayrollNormalizeRate(otRate, regularRate),
                otRateInheritsRegular
            };
            const employees = exportCenterScopeEmployees(plan);
            plan.scopeNames = employees.map(emp => emp.name);
            plan.scopeLabel = exportCenterScopeLabel(plan, employees);
            return plan;
        }

        function exportCenterDateInPlan(dateStr, plan) {
            const comp = dateStrToComparable(dateStr);
            const from = isoToComparable(plan.fromIso);
            const to = isoToComparable(plan.toIso);
            return (from === null || comp >= from) && (to === null || comp <= to);
        }

        function getExportRowsForPlan(plan) {
            const allowed = new Set((plan && plan.scopeNames) || exportCenterScopeEmployees(plan).map(emp => emp.name));
            const rows = Object.entries(allRecords).map(([key, rec]) => {
                const idx = key.indexOf('|');
                const date = key.slice(0, idx);
                const name = key.slice(idx + 1);
                const recordPod = rec.pod || podOf(name) || 'Unassigned';
                const currentPod = currentRosterPodForName(name) || recordPod;
                return { ...rec, date, name, pod:recordPod, currentPod };
            }).filter(row => {
                if (!row || isVoidedAttendanceRecord(row)) return false;
                if (isKnownTeamLeader(row.name) || String(row.attendanceRole || '').toLowerCase() === 'teamleader') return false;
                if (!allowed.has(row.name)) return false;
                return exportCenterDateInPlan(row.date, plan);
            });
            rows.sort((a,b) => dateStrToComparable(b.date) - dateStrToComparable(a.date) || a.name.localeCompare(b.name));
            return rows;
        }

        function getNetworkExportRowsForPlan(plan) {
            const allowed = new Set((plan && plan.scopeNames) || exportCenterScopeEmployees(plan).map(emp => emp.name));
            return visibleSpeedTestsForRole().filter(item => item && item.id && item.name && allowed.has(item.name) && item.date && exportCenterDateInPlan(item.date, plan))
                .sort((a,b) => new Date(b.ts).getTime() - new Date(a.ts).getTime());
        }

        function getOvertimeExportRowsForPlan(plan) {
            const allowed = new Set((plan && plan.scopeNames) || exportCenterScopeEmployees(plan).map(emp => emp.name));
            return Object.entries(allOT).map(([key, rec]) => {
                const idx = key.indexOf('|');
                const date = key.slice(0, idx);
                const name = key.slice(idx + 1);
                const status = String((rec && rec.status) || 'unknown');
                const savedMinutes = Number(rec && rec.minutes);
                const savedHours = Number.isFinite(savedMinutes) && savedMinutes >= 0 ? savedMinutes / 60 : Math.max(0, Number(rec && rec.hours) || 0);
                return {
                    date, name, pod:podDisplayName(podOf(name) || ''), status,
                    savedHours:exportReportRound2(savedHours), approvedHours:exportReportRound2(getApprovedOTHours(date,name)),
                    note:(rec && rec.note) || '', approvedBy:(rec && rec.approvedBy) || '', approvedAt:(rec && rec.approvedAt) || ''
                };
            }).filter(row => allowed.has(row.name) && exportCenterDateInPlan(row.date, plan))
              .sort((a,b)=>dateStrToComparable(b.date)-dateStrToComparable(a.date)||a.name.localeCompare(b.name));
        }

        function exportCenterContext(plan) {
            const p = plan || {};
            const employees = exportCenterScopeEmployees(p);
            return {
                ...p,
                scopeNames:p.scopeNames || employees.map(emp => emp.name),
                scopeLabel:p.scopeLabel || exportCenterScopeLabel(p, employees),
                teamLabel:teamGroupById(activeTeam).fullName,
                teamSlug:String(activeTeam || 'team').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toUpperCase()
            };
        }

        function exportCenterReportLabel(reportType) {
            return ({
                full:'Full Attendance', payroll:'Payroll Summary', weekly:'Weekly Summary', monthly:'Monthly Summary',
                exceptions:'Exceptions', overtime:'Overtime'
            })[reportType] || 'Attendance';
        }

        function exportSmartFilename(context, extension) {
            const ctx = exportCenterContext(context);
            let scopeSlug = 'Scope';
            if (ctx.scope === 'individual' && ctx.agent) scopeSlug = agentDisplayName(ctx.agent);
            else if (ctx.scope === 'allAgents') scopeSlug = 'All-Agents';
            else {
                const pods = Array.from(new Set(exportCenterScopeEmployees(ctx).map(emp => emp.pod).filter(Boolean)));
                scopeSlug = pods.length === 1 ? podDisplayName(pods[0]) : (pods.length > 1 ? 'Multi-POD' : 'Scope');
            }
            const clean = value => String(value || '').trim().replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'') || 'Report';
            return `TrinoTime_${clean(ctx.teamSlug)}_${clean(scopeSlug)}_${clean(exportCenterReportLabel(ctx.reportType))}_${ctx.fromIso}_to_${ctx.toIso}.${extension}`;
        }

        function exportCenterPopulateAgents() {
            const sel = $('exportCenterAgent');
            if (!sel) return;
            const current = sel.value;
            const list = exportCenterBaseEmployees().sort((a,b)=>agentDisplayName(a.name).localeCompare(agentDisplayName(b.name)));
            sel.innerHTML = '<option value="">Choose Agent…</option>' + list.map(emp => `<option value="${escapeHtml(emp.name)}">${escapeHtml(agentDisplayName(emp.name))} · ${escapeHtml(podDisplayName(emp.pod))}</option>`).join('');
            if (list.some(emp => emp.name === current)) sel.value = current;
        }

        function exportCenterSyncFields() {
            const period = $('exportCenterPeriod') ? $('exportCenterPeriod').value : 'currentWeek';
            const scope = $('exportCenterScope') ? $('exportCenterScope').value : 'currentPod';
            const custom = $('exportCenterCustomRange');
            const agentWrap = $('exportCenterAgentWrap');
            if (custom) custom.hidden = period !== 'custom';
            if (agentWrap) agentWrap.hidden = scope !== 'individual';
        }

        function exportCenterSetBusy(busy, message) {
            exportCenterBusy = Boolean(busy);
            ['exportCenterPreviewBtn','exportCenterCloseBtn'].forEach(id => { const el=$(id); if(el) el.disabled=exportCenterBusy; });
            const download=$('exportCenterDownloadBtn');
            if(download) download.disabled=exportCenterBusy || download.dataset.exportDisabled==='1';
            const status = $('exportCenterLiveStatus');
            if (status && message) status.textContent = message;
        }

        function exportCenterPreviewHtml(plan, rows, otRows, report) {
            const uniqueAgents = new Set(rows.map(r=>r.name));
            const pendingOt = otRows.filter(row => !['approved','rejected','cancelled'].includes(String(row.status).toLowerCase())).length;
            const appCheckOk = firebaseAppCheckSatisfied();
            const synced = fbConnected === true && !hasPendingExportDataSync();
            const primaryCount = plan.reportType === 'overtime' ? otRows.length : rows.length;
            const dataLabel = plan.reportType === 'overtime' ? 'OT records' : 'attendance rows';
            const warning = report.exceptions.length || pendingOt ?
                `<div class="export-center-warning"><strong>Review before payroll close:</strong> ${report.exceptions.length} attendance exception${report.exceptions.length===1?'':'s'}${pendingOt ? ` · ${pendingOt} pending OT item${pendingOt===1?'':'s'}` : ''}. Export remains available.</div>` :
                '<div class="export-center-ok"><strong>Validation passed.</strong> No attendance exceptions or pending OT items were detected in this scope.</div>';
            const exportRates = exportPayrollRates(plan);
            const rateNote = `<div class="export-center-ok"><strong>Export-only payroll rates:</strong> ${formatPayAmount(exportRates.regularRate)}/hr regular · ${formatPayAmount(exportRates.overtimeRate)}/hr OT. These values affect only the generated Excel/CSV and do not change TrinoTime attendance calculations.</div>`;
            return `<div class="export-center-preview-head"><div><strong>${escapeHtml(exportCenterReportLabel(plan.reportType))}</strong><span>${escapeHtml(plan.scopeLabel)} · ${escapeHtml(plan.fromIso)} → ${escapeHtml(plan.toIso)}</span></div><span class="export-center-sync-badge ${synced&&appCheckOk?'is-good':'is-warn'}">${synced&&appCheckOk?'LIVE · SYNCED':'REVIEW SYNC'}</span></div>
                <div class="export-center-metrics">
                    <div><strong>${primaryCount}</strong><span>${escapeHtml(dataLabel)}</span></div>
                    <div><strong>${uniqueAgents.size || plan.scopeNames.length}</strong><span>Agents represented</span></div>
                    <div><strong>${report.exceptions.length}</strong><span>Exceptions</span></div>
                    <div><strong>${report.reconciliation.total.toFixed(2)}</strong><span>Total credited hrs</span></div>
                </div>${rateNote}${warning}`;
        }

        async function refreshExportCenterPreview(options) {
            const opts = options || {};
            const token = ++exportCenterPreviewToken;
            const preview = $('exportCenterPreview');
            try {
                exportCenterSetBusy(true, opts.sync === false ? 'Calculating preview…' : 'Refreshing live data…');
                const plan = exportCenterReadPlan();
                if (opts.sync !== false) await prepareRealtimeExportSnapshot();
                if (token !== exportCenterPreviewToken) return;
                const rows = getExportRowsForPlan(plan);
                const otRows = getOvertimeExportRowsForPlan(plan);
                const report = buildEnhancedExportReport(rows, exportCenterContext(plan));
                if (preview) preview.innerHTML = exportCenterPreviewHtml(plan, rows, otRows, report);
                const download = $('exportCenterDownloadBtn');
                const hasData = plan.reportType === 'overtime' ? otRows.length > 0 : (rows.length > 0 || (plan.reportType === 'payroll' && plan.scopeNames.length > 0));
                if (download) { download.dataset.exportDisabled = hasData ? '0' : '1'; download.disabled = !hasData; }
                const liveStatus = $('exportCenterLiveStatus');
                if (liveStatus) liveStatus.textContent = hasData ? 'Preview is based on the latest verified live snapshot.' : 'No exportable records were found for this selection.';
                exportCenterSavePrefs(plan);
            } catch (err) {
                if (preview) preview.innerHTML = `<div class="export-center-error"><strong>Unable to validate this export.</strong><span>${escapeHtml(getErrorMessage(err))}</span></div>`;
                const download = $('exportCenterDownloadBtn'); if (download) { download.dataset.exportDisabled='1'; download.disabled = true; }
                const liveStatus = $('exportCenterLiveStatus'); if (liveStatus) liveStatus.textContent = 'Resolve the issue above before downloading.';
            } finally {
                if (token === exportCenterPreviewToken) exportCenterSetBusy(false);
            }
        }

        function openExportCenter(format) {
            const overlay = $('exportCenterOverlay');
            if (!overlay) return;
            exportCenterPopulateAgents();
            const prefs = exportCenterLoadPrefs();
            const assign = (id,value) => { const el=$(id); if(el && value && Array.from(el.options||[]).some(o=>o.value===value)) el.value=value; };
            assign('exportCenterPeriod', prefs.period || 'currentWeek');
            assign('exportCenterScope', prefs.scope || 'currentPod');
            assign('exportCenterReportType', prefs.reportType || 'full');
            assign('exportCenterFormat', format || prefs.format || 'excel');
            if ($('exportCenterRegularRate')) $('exportCenterRegularRate').value = Number.isFinite(Number(prefs.regularRate)) ? Number(prefs.regularRate).toFixed(2) : EXPORT_PAYROLL_DEFAULT_REGULAR_RATE_PHP.toFixed(2);
            if ($('exportCenterOtRate')) $('exportCenterOtRate').value = prefs.otRate === '' || prefs.otRate == null ? '' : exportPayrollNormalizeRate(prefs.otRate, EXPORT_PAYROLL_DEFAULT_REGULAR_RATE_PHP).toFixed(2);
            const allOption = $('exportCenterScope') && $('exportCenterScope').querySelector('option[value="allAgents"]');
            if (allOption) { allOption.disabled = !isAdmin; allOption.hidden = !isAdmin; }
            if (!isAdmin && $('exportCenterScope') && $('exportCenterScope').value === 'allAgents') $('exportCenterScope').value = 'currentPod';
            const currentScopeOption = $('exportCenterScope') && $('exportCenterScope').querySelector('option[value="currentPod"]');
            if (currentScopeOption) {
                const pod = isAdmin ? (activePod !== ALL_PODS_LABEL ? podDisplayName(activePod) : 'Active Team / All Pods') : podDisplayName(lockedPod || agentSessionPod || activePod);
                currentScopeOption.textContent = isAdmin ? `Current POD / Scope · ${pod}` : `Assigned POD · ${pod}`;
            }
            const defaultRange = exportCenterDateRange('currentWeek');
            const selectedPeriod = $('exportCenterPeriod').value || 'currentWeek';
            const currentRange = selectedPeriod === 'custom' ? defaultRange : exportCenterDateRange(selectedPeriod);
            if ($('exportCenterFrom') && !$('exportCenterFrom').value) $('exportCenterFrom').value = currentRange.fromIso;
            if ($('exportCenterTo') && !$('exportCenterTo').value) $('exportCenterTo').value = currentRange.toIso;
            exportCenterSyncFields();
            overlay.classList.add('open'); overlay.setAttribute('aria-hidden','false');
            if ($('exportCenterTitle')) $('exportCenterTitle').focus();
            refreshExportCenterPreview({sync:true});
        }

        function closeExportCenter() {
            const overlay = $('exportCenterOverlay');
            if (!overlay) return;
            overlay.classList.remove('open'); overlay.setAttribute('aria-hidden','true');
            exportCenterPreviewToken += 1;
        }

        function initExportCenterEvents() {
            const overlay = $('exportCenterOverlay');
            if (!overlay || overlay.dataset.bound === '1') return;
            overlay.dataset.bound = '1';
            $('exportCenterCloseBtn')?.addEventListener('click', closeExportCenter);
            $('exportCenterPreviewBtn')?.addEventListener('click', () => refreshExportCenterPreview({sync:true}));
            ['exportCenterPeriod','exportCenterScope','exportCenterAgent','exportCenterReportType','exportCenterFormat','exportCenterFrom','exportCenterTo','exportCenterRegularRate','exportCenterOtRate'].forEach(id => {
                $(id)?.addEventListener('change', () => { exportCenterSyncFields(); refreshExportCenterPreview({sync:false}); });
            });
            $('exportCenterDownloadBtn')?.addEventListener('click', async () => {
                if (exportCenterBusy) return;
                try {
                    const plan = exportCenterReadPlan();
                    exportCenterSavePrefs(plan);
                    exportCenterSetBusy(true, 'Verifying the live snapshot again before download…');
                    if (plan.format === 'csv') await downloadCsv(plan);
                    else await downloadExcel(plan);
                    if ($('exportCenterLiveStatus')) $('exportCenterLiveStatus').textContent = 'Download generated from a freshly verified live snapshot.';
                } catch (err) {
                    reportAppError('Export Center download', err, { notify:true, userMessage:'Export failed — ' + getErrorMessage(err) });
                    if ($('exportCenterLiveStatus')) $('exportCenterLiveStatus').textContent = 'Export failed. Review the notification and retry.';
                } finally { exportCenterSetBusy(false); }
            });
            overlay.addEventListener('click', e => { if (e.target === overlay) closeExportCenter(); });
            document.addEventListener('keydown', e => { if (e.key === 'Escape' && overlay.classList.contains('open')) closeExportCenter(); });
        }
        initExportCenterEvents();

        function hasPendingExportDataSync() {
            const isExportKey = key => String(key || '').startsWith('att:') || String(key || '').startsWith('ot:');
            const writes = getLocalKeysWithPrefix(PENDING_PREFIX).some(storageKey => isExportKey(storageKey.slice(PENDING_PREFIX.length)));
            const deletes = getLocalKeysWithPrefix(PENDING_DELETE_PREFIX).some(storageKey => isExportKey(storageKey.slice(PENDING_DELETE_PREFIX.length)));
            return writes || deletes || getPendingPunchEvents().some(event => isExportKey(event && event.key));
        }

        async function prepareRealtimeExportSnapshot() {
            if (!fbDb) throw new Error('Live database is unavailable. Reconnect before exporting so the report cannot be stale.');
            if (typeof navigator !== 'undefined' && navigator.onLine === false) {
                throw new Error('This device is offline. Reconnect before exporting a real-time report.');
            }

            if (hasPendingExportDataSync()) {
                if (fbConnected !== true && typeof reconnectToLiveServer === 'function') {
                    await reconnectToLiveServer({ userInitiated:false });
                }
                await flushPendingRecords();
                if (hasPendingExportDataSync()) {
                    throw new Error('Some attendance or overtime changes are still waiting for server confirmation. Retry Sync, then export again.');
                }
            }

            await loadAllFromFirebaseOnce();
            if (fbConnected !== true) throw new Error('Live server verification did not complete. Reconnect and try the export again.');
            return true;
        }

        function buildExportPeriodSummaries(rows, context) {
            const weekly = {};
            const monthly = {};
            const round2 = n => Math.round((Number(n) || 0) * 100) / 100;
            (rows || []).forEach(r => {
                if (!r || !r.logOut || isVoidedAttendanceRecord(r)) return;
                const regular = computeRegularHours(r, r.date, r.pod);
                if (!Number.isFinite(regular)) return;
                const ot = Number(getApprovedOTHours(r.date, r.name)) || 0;
                const { y, m, d } = parseDateStr(r.date);
                const dt = new Date(y, m - 1, d);

                // Rebuild every period from dated raw records. New periods begin at zero
                // automatically while completed weekly/monthly history remains available.
                const weekStartDate = getWeekStartDate(dt);
                const weekEndDate = new Date(weekStartDate.getFullYear(), weekStartDate.getMonth(), weekStartDate.getDate() + 6);
                const weekStartLabel = fmtDateManila(weekStartDate);
                const weekKey = r.name + '|' + dateStrToComparable(weekStartLabel);
                if (!weekly[weekKey]) weekly[weekKey] = {
                    name:r.name, weekStart:weekStartLabel, weekEnd:fmtDateManila(weekEndDate),
                    sortKey:dateStrToComparable(weekStartLabel), regular:0, ot:0
                };
                weekly[weekKey].regular += regular;
                weekly[weekKey].ot += ot;

                const monthKey = r.name + '|' + y + '-' + m;
                if (!monthly[monthKey]) monthly[monthKey] = {
                    name:r.name,
                    monthLabel:dt.toLocaleString('en-US', { month:'long', year:'numeric' }),
                    sortKey:y * 100 + m, regular:0, ot:0
                };
                monthly[monthKey].regular += regular;
                monthly[monthKey].ot += ot;
            });
            const attachPay = item => {
                const pay = exportPayrollPayBreakdown(item.regular, item.ot, context);
                return {
                    ...item,
                    regular:round2(item.regular), ot:round2(item.ot), total:round2(item.regular + item.ot),
                    regularRate:pay.regularRate == null ? null : round2(pay.regularRate),
                    overtimeRate:pay.overtimeRate == null ? null : round2(pay.overtimeRate),
                    regularPay:pay.regularPay == null ? null : round2(pay.regularPay),
                    overtimePay:pay.overtimePay == null ? null : round2(pay.overtimePay),
                    totalPay:pay.totalPay == null ? null : round2(pay.totalPay)
                };
            };
            return {
                weeklyRows:Object.values(weekly).map(attachPay)
                    .sort((a,b) => a.name.localeCompare(b.name) || a.sortKey - b.sortKey),
                monthlyRows:Object.values(monthly).map(attachPay)
                    .sort((a,b) => a.name.localeCompare(b.name) || a.sortKey - b.sortKey)
            };
        }

        function escapeCsvCell(value) {
            let text = String(value == null ? '' : value);
            if (/^[=+\-@\t\r]/.test(text)) text = "'" + text;
            return `"${text.replace(/"/g, '""')}"`;
        }


        function exportReportRound2(value) {
            return Math.round((Number(value) || 0) * 100) / 100;
        }

        function exportReportDateFromValue(value) {
            if (!value) return null;
            const raw = String(value).trim();
            let y, m, d;
            if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) {
                [y, m, d] = raw.split('-').map(Number);
            } else {
                try {
                    const parsed = parseDateStr(raw);
                    y = parsed.y; m = parsed.m; d = parsed.d;
                } catch (_) { return null; }
            }
            const dt = new Date(y, m - 1, d);
            return Number.isFinite(dt.getTime()) ? dt : null;
        }

        function exportReportIsoDate(date) {
            if (!(date instanceof Date) || !Number.isFinite(date.getTime())) return '';
            return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
        }

        function exportReportDateKey(date) {
            if (!(date instanceof Date) || !Number.isFinite(date.getTime())) return '';
            return `${date.getMonth()+1}/${date.getDate()}/${date.getFullYear()}`;
        }

        function exportReportDateBounds(rows, context) {
            const fromInput = context && context.fromIso ? context.fromIso : ($('filterDate') ? $('filterDate').value : '');
            const toInput = context && context.toIso ? context.toIso : ($('filterDateTo') ? $('filterDateTo').value : '');
            const recordDates = (rows || []).map(r => exportReportDateFromValue(r && r.date)).filter(Boolean).sort((a,b)=>a-b);
            let from = exportReportDateFromValue(fromInput) || (recordDates.length ? new Date(recordDates[0]) : exportReportDateFromValue(todayKeyPart()));
            let to = exportReportDateFromValue(toInput) || (recordDates.length ? new Date(recordDates[recordDates.length-1]) : exportReportDateFromValue(todayKeyPart()));
            if (!from) from = new Date();
            if (!to) to = new Date(from);
            from = new Date(from.getFullYear(), from.getMonth(), from.getDate());
            to = new Date(to.getFullYear(), to.getMonth(), to.getDate());
            if (to < from) [from, to] = [to, from];
            return { from, to, fromIso:exportReportIsoDate(from), toIso:exportReportIsoDate(to), dayCount:Math.floor((to-from)/86400000)+1 };
        }

        function exportReportRangeStatus(bounds) {
            const today = exportReportDateFromValue(todayKeyPart()) || new Date();
            const t = new Date(today.getFullYear(), today.getMonth(), today.getDate());
            if (bounds.to < t) return 'FINALIZED';
            if (bounds.from > t) return 'FUTURE';
            return 'OPEN';
        }

        function exportReportActor() {
            if (isAdmin) return { name:'Admin', role:'Admin' };
            if (isTeamLeader) return { name:teamLeaderName || currentEmployee || 'Team Leader', role:'Team Leader' };
            return { name:currentEmployee || agentSessionName || 'Agent', role:'Agent' };
        }

        function exportReportGeneratedAtPht() {
            return new Date(getTrueNowMs()).toLocaleString('en-US', {
                timeZone: MANILA_TIME_ZONE, month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit', second:'2-digit'
            }) + ' PHT';
        }

        function exportReportIssueAction(category) {
            const key = String(category || '').toLowerCase();
            if (key.includes('missing time out')) return 'Review and correct the attendance record before payroll close.';
            if (key.includes('time order') || key.includes('sequence') || key.includes('invalid')) return 'Correct the timestamps before finalizing payroll.';
            if (key.includes('overlap')) return 'Review overlapping shifts and keep only the authoritative time window.';
            if (key.includes('pending overtime')) return 'Approve or reject overtime before payroll close.';
            if (key.includes('day-off')) return 'Confirm that work on the scheduled day off was intentional.';
            if (key.includes('late') || key.includes('early') || key.includes('break')) return 'Review attendance variance and confirm credited-hour deductions.';
            return 'Review this record before payroll close.';
        }

        function buildExportExceptionRows(rows) {
            const issues = [];
            const seen = new Set();
            const add = (rec, severity, category, details) => {
                const row = {
                    severity:severity || 'Warning',
                    date:(rec && rec.date) || '',
                    name:(rec && rec.name) || '',
                    pod:podDisplayName((rec && rec.pod) || podOf((rec && rec.name) || '') || ''),
                    category:category || 'Review',
                    details:details || '',
                    action:exportReportIssueAction(category)
                };
                const key=[row.date,row.name,row.category,row.details].join('|');
                if (seen.has(key)) return;
                seen.add(key); issues.push(row);
            };
            const toMs = value => {
                if (!value) return null;
                const n = new Date(value).getTime();
                return Number.isFinite(n) ? n : NaN;
            };
            (rows || []).forEach(rec => {
                if (!rec || isVoidedAttendanceRecord(rec)) return;
                const analysis = analyzeAttendanceRecordForDashboard(rec);
                const fields=['timeIn','startBreak','endBreak','logOut'];
                fields.forEach(field => {
                    if (rec[field] && Number.isNaN(toMs(rec[field]))) add(rec,'Error','Invalid timestamp',`${field} is not a valid date/time value.`);
                });
                const ti=toMs(rec.timeIn), sb=toMs(rec.startBreak), eb=toMs(rec.endBreak), lo=toMs(rec.logOut);
                if (rec.startBreak && !rec.timeIn) add(rec,'Error','Impossible sequence','Start Break exists without Time In.');
                if (rec.endBreak && !rec.startBreak) add(rec,'Error','Impossible sequence','End Break exists without Start Break.');
                if (rec.logOut && !rec.timeIn) add(rec,'Error','Impossible sequence','Time Out exists without Time In.');
                if (Number.isFinite(ti) && Number.isFinite(sb) && sb <= ti) add(rec,'Error','Time order','Start Break is not after Time In.');
                if (Number.isFinite(sb) && Number.isFinite(eb) && eb <= sb) add(rec,'Error','Time order','End Break is not after Start Break.');
                if (Number.isFinite(ti) && Number.isFinite(lo) && lo <= ti) add(rec,'Error','Time order','Time Out is not after Time In.');
                if (Number.isFinite(eb) && Number.isFinite(lo) && lo <= eb) add(rec,'Error','Time order','Time Out is not after End Break.');
                if (rec.startBreak && !rec.endBreak && rec.logOut) add(rec,'Error','Open break','Time Out exists while the break is still open.');
                if (rec.date !== todayKeyPart() && rec.timeIn && !rec.logOut) add(rec,'Error','Missing Time Out','Past shift has a Time In but no Time Out.');
                if (analysis.late) {
                    const minutes=Math.max(0,Math.round(getLateArrivalMs(rec,rec.date,rec.pod||podOf(rec.name))/60000));
                    add(rec,'Warning','Late arrival',`${minutes} minute${minutes===1?'':'s'} late against the scheduled shift.`);
                }
                if (analysis.early && rec.logOut) {
                    const minutes=Math.max(0,Math.round(getEarlyLogoutMs(rec,rec.date,rec.pod||podOf(rec.name))/60000));
                    add(rec,'Warning','Early logout / undertime',`${minutes} minute${minutes===1?'':'s'} before scheduled shift end.`);
                }
                if (analysis.longBreak) {
                    const minutes=Math.max(0,Math.round((Number(analysis.breakDeductionHours)||0)*60));
                    add(rec,'Warning','Excess break',`${minutes} excess break minute${minutes===1?'':'s'} detected.`);
                }
                if (analysis.scheduledDayOffAttendance) add(rec,'Warning','Day-off attendance','Attendance was recorded on a scheduled day off.');
                if ((Number(analysis.manualDeductionHours)||0) > 0) add(rec,'Info','Manual adjustment',`${exportReportRound2(analysis.manualDeductionHours)} credited hour(s) were manually deducted.`);
                if (analysis.manualCreditOverrideHours !== null && analysis.manualCreditOverrideHours !== undefined) {
                    const auto = computeAutomaticRegularHours(rec, rec.date, rec.pod || podOf(rec.name));
                    add(rec,'Info','Manual credited-hours override',`${formatCreditedHours(analysis.manualCreditOverrideHours)} final regular credit${Number.isFinite(auto) ? `; automatic formula was ${formatCreditedHours(auto)}` : ''}. Reason: ${rec.manualCreditOverrideReason || 'not recorded'}.`);
                }
                if (analysis.reducedCredit) add(rec,'Warning','Reduced credited hours','Completed shift has lower-than-standard credited hours without an obvious attendance variance flag.');
                if (Number.isFinite(ti) && Number.isFinite(lo) && (lo-ti) > 16*60*60*1000) add(rec,'Warning','Unusually long shift',`Elapsed shift is ${exportReportRound2((lo-ti)/3600000)} hours.`);
                const ot = getOTRecord(rec.date, rec.name);
                if (ot && ot.status && !['approved','rejected','cancelled'].includes(String(ot.status).toLowerCase())) {
                    add(rec,'Warning','Pending overtime',`Overtime status is ${String(ot.status)} and is not included in Approved OT Hrs.`);
                }
            });
            const byName=new Map();
            (rows||[]).filter(r=>r&&r.timeIn&&!isVoidedAttendanceRecord(r)).forEach(rec=>{
                const list=byName.get(rec.name)||[]; list.push(rec); byName.set(rec.name,list);
            });
            byName.forEach(list=>{
                list.sort((a,b)=>(toMs(a.timeIn)||0)-(toMs(b.timeIn)||0));
                for(let i=1;i<list.length;i++){
                    const prev=list[i-1], curr=list[i];
                    const prevOut=toMs(prev.logOut), currIn=toMs(curr.timeIn);
                    if (!prev.logOut) add(curr,'Warning','Possible overlap',`A newer shift starts while ${prev.date} still has no Time Out.`);
                    else if (Number.isFinite(prevOut)&&Number.isFinite(currIn)&&currIn<prevOut) add(curr,'Error','Overlapping shifts',`Time In overlaps the prior shift from ${prev.date}.`);
                }
            });
            const severityRank={Error:0,Warning:1,Info:2};
            return issues.sort((a,b)=>(severityRank[a.severity]??9)-(severityRank[b.severity]??9)||String(a.date).localeCompare(String(b.date))||a.name.localeCompare(b.name));
        }

        function buildPayrollSummaryRows(rows, exceptions, bounds, scopeNames, context) {
            const byName = new Map();
            (scopeNames || []).forEach(name => { if (name) byName.set(name, []); });
            (rows || []).forEach(rec => {
                if (!rec || isVoidedAttendanceRecord(rec) || !rec.name) return;
                if (!byName.has(rec.name)) byName.set(rec.name, []);
                byName.get(rec.name).push(rec);
            });
            const issueCount = new Map();
            (exceptions || []).forEach(issue => issueCount.set(issue.name, (issueCount.get(issue.name)||0)+1));
            const result=[];
            byName.forEach((records,name)=>{
                let regular=0, ot=0, lateMinutes=0, undertimeMinutes=0;
                const workedDates=new Set();
                let pod=(records.find(r=>r.pod)||{}).pod || podOf(name) || '';
                records.forEach(rec=>{
                    if (rec.timeIn) lateMinutes += Math.max(0,Math.round(getLateArrivalMs(rec,rec.date,rec.pod||pod)/60000));
                    if (rec.logOut) {
                        const reg=computeRegularHours(rec,rec.date,rec.pod||pod);
                        if (Number.isFinite(reg)) regular += reg;
                        ot += Number(getApprovedOTHours(rec.date,name))||0;
                        undertimeMinutes += Math.max(0,Math.round(getEarlyLogoutMs(rec,rec.date,rec.pod||pod)/60000));
                        workedDates.add(rec.date);
                    }
                });
                let dayOff=0, leave=0;
                const cursor=new Date(bounds.from);
                let guard=0;
                while(cursor<=bounds.to && guard<1100){
                    const dateKey=exportReportDateKey(cursor);
                    try {
                        const atMs=new Date(cursor.getFullYear(),cursor.getMonth(),cursor.getDate(),12,0,0,0).getTime();
                        const availability=resolveEffectiveAvailability(name,dateKey,pod,{atMs,includeAttendance:false});
                        if (availability && availability.available===false) {
                            if (availability.sourceKind==='leave') leave += 1;
                            else if (availability.sourceKind==='day_off') dayOff += 1;
                        }
                    } catch (_) {}
                    cursor.setDate(cursor.getDate()+1); guard += 1;
                }
                const pay=exportPayrollPayBreakdown(regular,ot,context);
                result.push({
                    name,pod:podDisplayName(pod),regular:exportReportRound2(regular),ot:exportReportRound2(ot),
                    total:exportReportRound2(regular+ot),standardDailyHours:EXPORT_PAYROLL_STANDARD_DAILY_HOURS,
                    regularRate:pay.regularRate==null?null:exportReportRound2(pay.regularRate),
                    overtimeRate:pay.overtimeRate==null?null:exportReportRound2(pay.overtimeRate),
                    regularPay:pay.regularPay==null?null:exportReportRound2(pay.regularPay),
                    overtimePay:pay.overtimePay==null?null:exportReportRound2(pay.overtimePay),
                    totalPay:pay.totalPay==null?null:exportReportRound2(pay.totalPay),
                    daysWorked:workedDates.size,daysOff:dayOff,leaveDays:leave,
                    lateMinutes,undertimeMinutes,exceptions:issueCount.get(name)||0,periodStatus:exportReportRangeStatus(bounds)
                });
            });
            return result.sort((a,b)=>a.name.localeCompare(b.name));
        }

        function buildPeriodSnapshotRows(rows, exceptions, bounds, context) {
            const summary=buildExportPeriodSummaries(rows||[], context);
            const today=exportReportDateFromValue(todayKeyPart())||new Date();
            const todayMid=new Date(today.getFullYear(),today.getMonth(),today.getDate());
            const snapshots=[];
            const issueDateCount=(from,to)=>{
                const f=from.getTime(), t=to.getTime();
                return (exceptions||[]).filter(issue=>{
                    const d=exportReportDateFromValue(issue.date); return d&&d.getTime()>=f&&d.getTime()<=t;
                }).length;
            };
            const weeklyGroups=new Map();
            summary.weeklyRows.forEach(w=>{
                const key=`${w.weekStart}|${w.weekEnd}`;
                if(!weeklyGroups.has(key)) weeklyGroups.set(key,{start:w.weekStart,end:w.weekEnd,regular:0,ot:0,total:0,regularPay:0,otPay:0,totalPay:0,agents:new Set()});
                const g=weeklyGroups.get(key); g.regular+=w.regular; g.ot+=w.ot; g.total+=w.total; g.regularPay+=Number(w.regularPay)||0; g.otPay+=Number(w.overtimePay)||0; g.totalPay+=Number(w.totalPay)||0; if(w.total>0) g.agents.add(w.name);
            });
            weeklyGroups.forEach(g=>{
                const from=exportReportDateFromValue(g.start), to=exportReportDateFromValue(g.end);
                const fullyCovered=from&&to&&bounds&&bounds.from<=from&&bounds.to>=to;
                snapshots.push({type:'Weekly',start:g.start,end:g.end,status:!fullyCovered?'PARTIAL':(to&&to<todayMid?'FINALIZED':'OPEN'),agents:g.agents.size,
                    regular:exportReportRound2(g.regular),ot:exportReportRound2(g.ot),total:exportReportRound2(g.total),regularPay:exportReportRound2(g.regularPay),otPay:exportReportRound2(g.otPay),totalPay:exportReportRound2(g.totalPay),exceptions:from&&to?issueDateCount(from,to):0});
            });
            const monthlyGroups=new Map();
            summary.monthlyRows.forEach(m=>{
                const key=String(m.sortKey);
                if(!monthlyGroups.has(key)) monthlyGroups.set(key,{sortKey:m.sortKey,label:m.monthLabel,regular:0,ot:0,total:0,regularPay:0,otPay:0,totalPay:0,agents:new Set()});
                const g=monthlyGroups.get(key); g.regular+=m.regular; g.ot+=m.ot; g.total+=m.total; g.regularPay+=Number(m.regularPay)||0; g.otPay+=Number(m.overtimePay)||0; g.totalPay+=Number(m.totalPay)||0; if(m.total>0) g.agents.add(m.name);
            });
            monthlyGroups.forEach(g=>{
                const y=Math.floor(g.sortKey/100), m=g.sortKey%100;
                const from=new Date(y,m-1,1), to=new Date(y,m,0);
                const fullyCovered=bounds&&bounds.from<=from&&bounds.to>=to;
                snapshots.push({type:'Monthly',start:exportReportDateKey(from),end:exportReportDateKey(to),status:!fullyCovered?'PARTIAL':(to<todayMid?'FINALIZED':'OPEN'),agents:g.agents.size,
                    regular:exportReportRound2(g.regular),ot:exportReportRound2(g.ot),total:exportReportRound2(g.total),regularPay:exportReportRound2(g.regularPay),otPay:exportReportRound2(g.otPay),totalPay:exportReportRound2(g.totalPay),exceptions:issueDateCount(from,to)});
            });
            return snapshots.sort((a,b)=>a.type.localeCompare(b.type)||(exportReportDateFromValue(a.start)||0)-(exportReportDateFromValue(b.start)||0));
        }

        function buildEnhancedExportReport(rows, context) {
            const ctx=context || {};
            const bounds=exportReportDateBounds(rows,ctx);
            const exceptions=buildExportExceptionRows(rows);
            const payroll=buildPayrollSummaryRows(rows,exceptions,bounds,ctx.scopeNames || [],ctx);
            const periods=buildPeriodSnapshotRows(rows,exceptions,bounds,ctx);
            const reconciliation=payroll.reduce((a,p)=>{
                a.regular+=p.regular; a.ot+=p.ot; a.total+=p.total; a.late+=p.lateMinutes; a.undertime+=p.undertimeMinutes;
                a.regularPay+=Number(p.regularPay)||0; a.overtimePay+=Number(p.overtimePay)||0; a.totalPay+=Number(p.totalPay)||0;
                if(p.total>0) a.withHours+=1; else a.noHours+=1;
                if(p.exceptions>0) a.withExceptions+=1;
                return a;
            },{regular:0,ot:0,total:0,regularPay:0,overtimePay:0,totalPay:0,withHours:0,noHours:0,withExceptions:0,late:0,undertime:0});
            Object.keys(reconciliation).forEach(k=>{ if(['regular','ot','total','regularPay','overtimePay','totalPay'].includes(k)) reconciliation[k]=exportReportRound2(reconciliation[k]); });
            const actor=exportReportActor();
            const generatedAt=exportReportGeneratedAtPht();
            const appVersion=(document.querySelector('meta[name="trinotime-version"]')||{}).content || 'Unknown';
            const info=[
                ['Generated At',generatedAt],
                ['Data Through',generatedAt],
                ['Export Status',(fbConnected===true&&!hasPendingExportDataSync())?'LIVE / FULLY SYNCED':'SYNC STATUS REQUIRES REVIEW'],
                ['Firebase',fbConnected===true?'Connected':'Not connected'],
                ['App Check',!FIREBASE_APP_CHECK_REQUIRED?'Temporarily unenforced':((firebaseAppCheckLastVerifiedAt&&!firebaseAppCheckBlocked)?'Verified':'Not verified in this session')],
                ['Team',ctx.teamLabel || teamGroupById(activeTeam).fullName],
                ['POD / Scope',ctx.scopeLabel || (activePod===ALL_PODS_LABEL?ALL_PODS_LABEL:podDisplayName(activePod))],
                ['Report Type',exportCenterReportLabel(ctx.reportType || 'full')],
                ['Date Range',`${bounds.fromIso} to ${bounds.toIso}`],
                ['Standard Workday (Reference Only)',`${EXPORT_PAYROLL_STANDARD_DAILY_HOURS} hours`],
                ['Regular Rate Used',`${formatPayAmount(exportPayrollRates(ctx).regularRate)}/hr`],
                ['OT Rate Used',`${formatPayAmount(exportPayrollRates(ctx).overtimeRate)}/hr`],
                ['Rate Source','Export Center only. These rates are not written to employee profiles, Firebase attendance records, or live dashboard calculations.'],
                ['Hours Source','Regular Credited Hrs and Approved OT Hrs are consumed exactly from TrinoTime\'s existing locked calculation logic; the export does not recalculate, re-cap, or alter attendance hours.'],
                ['Pay Formula','Regular Pay = exported Regular Credited Hrs × export Regular Rate; OT Pay = exported Approved OT Hrs × export OT Rate; Total Pay = Regular Pay + OT Pay'],
                ['Pay Scope','Total Pay is gross time-based pay only. No taxes, deductions, bonuses, or other adjustments are assumed.'],
                ['OT Classification','Only existing Approved OT Hrs are paid as OT. The 6-hour workday is informational and does not auto-convert additional attendance time into overtime.'],
                ['Range Status',exportReportRangeStatus(bounds)],
                ['Generated By',actor.name],
                ['Role',actor.role],
                ['TrinoTime Version',appVersion],
                ['Attendance Rows',String((rows||[]).length)],
                ['Payroll Agents',String(payroll.length)],
                ['Data Quality Exceptions',String(exceptions.length)],
                ['Automatic Period Reset','Enabled - weekly/monthly totals are rebuilt from dated source records; source attendance is never deleted.'],
                ['Period Finalization','Fully covered ended periods are marked FINALIZED and locked in the exported snapshot; active periods remain OPEN and incomplete date ranges are marked PARTIAL.']
            ];
            return {bounds,exceptions,payroll,periods,info,generatedAt,reconciliation};
        }

        function appendEnhancedCsvSections(lines, report) {
            const csvRow=values=>lines.push(values.map(escapeCsvCell).join(','));
            lines.push(''); csvRow(['Payroll Summary']);
            csvRow(['Agent','POD','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Standard Day Hrs','Regular Rate (PHP)','OT Rate (PHP)','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)','Days Worked','Days Off','Approved Leave Days','Late Min','Undertime Min','Exceptions','Period Status']);
            report.payroll.forEach(p=>csvRow([p.name,p.pod,p.regular.toFixed(2),p.ot.toFixed(2),p.total.toFixed(2),p.standardDailyHours,p.regularRate==null?'':p.regularRate.toFixed(2),p.overtimeRate==null?'':p.overtimeRate.toFixed(2),p.regularPay==null?'':p.regularPay.toFixed(2),p.overtimePay==null?'':p.overtimePay.toFixed(2),p.totalPay==null?'':p.totalPay.toFixed(2),p.daysWorked,p.daysOff,p.leaveDays,p.lateMinutes,p.undertimeMinutes,p.exceptions,p.periodStatus]));
            if(report.payroll.length){
                const t=report.payroll.reduce((a,p)=>({regular:a.regular+p.regular,ot:a.ot+p.ot,total:a.total+p.total,regularPay:a.regularPay+(Number(p.regularPay)||0),otPay:a.otPay+(Number(p.overtimePay)||0),totalPay:a.totalPay+(Number(p.totalPay)||0),worked:a.worked+p.daysWorked,off:a.off+p.daysOff,leave:a.leave+p.leaveDays,late:a.late+p.lateMinutes,under:a.under+p.undertimeMinutes,issues:a.issues+p.exceptions}),{regular:0,ot:0,total:0,regularPay:0,otPay:0,totalPay:0,worked:0,off:0,leave:0,late:0,under:0,issues:0});
                csvRow(['Total (All Agents)','',exportReportRound2(t.regular).toFixed(2),exportReportRound2(t.ot).toFixed(2),exportReportRound2(t.total).toFixed(2),'','','',exportReportRound2(t.regularPay).toFixed(2),exportReportRound2(t.otPay).toFixed(2),exportReportRound2(t.totalPay).toFixed(2),t.worked,t.off,t.leave,t.late,t.under,t.issues,'']);
            }
            lines.push(''); csvRow(['Reconciliation Totals']);
            csvRow(['Metric','Value']);
            csvRow(['Total Regular Hours',report.reconciliation.regular.toFixed(2)]);
            csvRow(['Total Approved OT',report.reconciliation.ot.toFixed(2)]);
            csvRow(['Grand Total Hours',report.reconciliation.total.toFixed(2)]);
            csvRow(['Total Regular Pay (PHP)',report.reconciliation.regularPay.toFixed(2)]);
            csvRow(['Total OT Pay (PHP)',report.reconciliation.overtimePay.toFixed(2)]);
            csvRow(['Grand Total Pay (PHP)',report.reconciliation.totalPay.toFixed(2)]);
            csvRow(['Agents With Hours',report.reconciliation.withHours]);
            csvRow(['Agents With No Hours',report.reconciliation.noHours]);
            csvRow(['Agents With Exceptions',report.reconciliation.withExceptions]);
            csvRow(['Total Late Minutes',report.reconciliation.late]);
            csvRow(['Total Undertime Minutes',report.reconciliation.undertime]);
            lines.push(''); csvRow(['Exceptions / Data Quality']);
            csvRow(['Severity','Date','Agent','POD','Category','Details','Action Needed']);
            if(report.exceptions.length) report.exceptions.forEach(i=>csvRow([i.severity,i.date,i.name,i.pod,i.category,i.details,i.action]));
            else csvRow(['OK','','','','No exceptions detected','The selected records passed the export data-quality checks.','']);
            lines.push(''); csvRow(['Period Snapshots']);
            csvRow(['Period Type','Start','End','Status','Agents With Hours','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)','Exceptions','Snapshot Generated At','Reset Behavior']);
            report.periods.forEach(p=>csvRow([p.type,p.start,p.end,p.status,p.agents,p.regular.toFixed(2),p.ot.toFixed(2),p.total.toFixed(2),p.regularPay.toFixed(2),p.otPay.toFixed(2),p.totalPay.toFixed(2),p.exceptions,report.generatedAt,'Next period starts at 0 from its own dated records']));
            lines.push(''); csvRow(['Export Info']);
            csvRow(['Field','Value']); report.info.forEach(item=>csvRow(item));
        }

        function autoFitEnhancedWorksheet(ws, minWidth=10, maxWidth=42) {
            ws.columns.forEach(column=>{
                let length=minWidth;
                column.eachCell({includeEmpty:true},cell=>{
                    const text=cell.text || (cell.value==null?'':String(cell.value));
                    length=Math.max(length,Math.min(maxWidth,text.length+2));
                });
                column.width=Math.min(maxWidth,Math.max(minWidth,length));
            });
        }

        function buildFullWorkbookOvertimeRows(context, rows, report) {
            const ctx=context || {};
            let names=(ctx.scopeNames && ctx.scopeNames.length) ? ctx.scopeNames.slice() : [];
            if(!names.length){ try { names=attendanceViewerEmployees().filter(emp=>emp&&emp.name&&!isKnownTeamLeader(emp.name)).map(emp=>emp.name); } catch (_) { names=[]; } }
            if(!names.length) names=Array.from(new Set((rows||[]).map(r=>r&&r.name).filter(Boolean)));
            const plan={...ctx,scopeNames:names,fromIso:(ctx.fromIso || report.bounds.fromIso),toIso:(ctx.toIso || report.bounds.toIso)};
            try { return getOvertimeExportRowsForPlan(plan); } catch (_) { return []; }
        }

        function buildLeaveDayOffExportRows(context, rows, report) {
            const ctx=context || {};
            let employees=[];
            try { employees=context ? exportCenterScopeEmployees(ctx).slice() : attendanceViewerEmployees().filter(emp=>emp&&emp.name&&!isKnownTeamLeader(emp.name)); } catch (_) { employees=[]; }
            if(!employees.length){
                const seen=new Map();
                (ctx.scopeNames||[]).forEach(name=>{ if(name&&!seen.has(name)) seen.set(name,{name,pod:podOf(name)||''}); });
                (rows||[]).forEach(rec=>{ if(rec&&rec.name&&!seen.has(rec.name)) seen.set(rec.name,{name:rec.name,pod:rec.pod||podOf(rec.name)||''}); });
                employees=Array.from(seen.values());
            }
            const out=[];
            employees.filter(emp=>emp&&emp.name&&!isKnownTeamLeader(emp.name)).forEach(emp=>{
                const name=emp.name;
                const pod=emp.pod || podOf(name) || '';
                const cursor=new Date(report.bounds.from.getFullYear(),report.bounds.from.getMonth(),report.bounds.from.getDate());
                let guard=0;
                while(cursor<=report.bounds.to && guard<1100){
                    const dateKey=exportReportDateKey(cursor);
                    let scheduledOff=false, leave=null;
                    try { scheduledOff=Boolean(isScheduledDayOffForEmployee(name,dateKey,pod)); } catch (_) {}
                    try { leave=getActiveLeaveForEmployeeOnDate(name,dateKey,pod); } catch (_) { leave=null; }
                    if(scheduledOff || leave){
                        const leaveStatus=leave ? normalizeLeaveStatus(leave.status) : '';
                        const duration=leave ? (typeof leaveV2DurationLabel==='function' ? leaveV2DurationLabel(leave) : String(leave.duration||leave.leaveDuration||'')) : '';
                        let chargeable=false;
                        try { chargeable=Boolean(leave && effectiveLeaveChargeableResolver(leave,dateKey)); } catch (_) {}
                        let attendance=false;
                        try { attendance=Boolean(hasAttendanceActivity(name,dateKey)); } catch (_) {}
                        const category=scheduledOff && leave ? 'DAY OFF + LEAVE' : leave ? 'LEAVE' : 'DAY OFF';
                        let payrollTreatment='Scheduled day off';
                        if(leave){
                            if(leaveStatus==='APPROVED') payrollTreatment=chargeable ? 'Approved leave' : 'Approved leave · non-chargeable date';
                            else if(leaveStatus==='PENDING') payrollTreatment='Pending leave · no payroll effect yet';
                            else payrollTreatment=`${leaveStatus || 'Leave'} · no payroll effect`;
                        }
                        const notes=[];
                        if(scheduledOff) notes.push('Scheduled day off');
                        if(leave && leave.reason) notes.push(String(leave.reason));
                        if(leave && leave.decisionNote) notes.push(`Decision note: ${leave.decisionNote}`);
                        out.push({
                            date:dateKey,name,pod:podDisplayName(pod),category,
                            leaveType:leave ? (leave.leaveType || 'Leave') : '',leaveStatus,duration,payrollTreatment,
                            attendance:attendance?'Yes':'No',reason:notes.join(' · '),
                            decisionBy:leave ? (leave.decisionBy || '') : '',decisionAt:leave ? (leave.decisionAt || '') : '',requestId:leave ? (leave.id || '') : ''
                        });
                    }
                    cursor.setDate(cursor.getDate()+1); guard+=1;
                }
            });
            return out.sort((a,b)=>dateStrToComparable(a.date)-dateStrToComparable(b.date)||a.name.localeCompare(b.name)||a.category.localeCompare(b.category));
        }

        async function appendEnhancedExcelReportingSheets(wb, rows, reportHeaderText, context) {
            const report=buildEnhancedExportReport(rows, context);
            if(report.exceptions.length) showToast(`Export includes ${report.exceptions.length} data-quality exception${report.exceptions.length===1?'':'s'} — see the Exceptions sheet.`);
            const title=(ws,text,span)=>{
                const r=ws.addRow([text]); ws.mergeCells(r.number,1,r.number,span);
                r.eachCell({includeEmpty:true},cell=>{cell.font=XLS_STYLE.titleFont;cell.fill=XLS_STYLE.titleFill;cell.alignment={vertical:'middle',horizontal:'left'};cell.border=XLS_GRID_BORDER;});
                r.height=22; return r;
            };
            const subtitle=(ws,text,span)=>{
                const r=ws.addRow([text]); ws.mergeCells(r.number,1,r.number,span);
                r.eachCell({includeEmpty:true},cell=>{cell.font={color:{argb:'FF475569'},italic:true,size:10};cell.alignment={vertical:'middle',horizontal:'left'};});
                return r;
            };

            const payrollHeaders=['Agent','POD','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Standard Day Hrs','Regular Rate (PHP)','OT Rate (PHP)','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)','Days Worked','Days Off','Approved Leave Days','Late Min','Undertime Min','Exceptions','Period Status'];
            const wsPayroll=wb.addWorksheet('Payroll Summary',{views:[{state:'frozen',ySplit:4,xSplit:1}]});
            wsPayroll.properties.tabColor={argb:'FF16A34A'};
            title(wsPayroll,'Payroll Summary',payrollHeaders.length); subtitle(wsPayroll,reportHeaderText,payrollHeaders.length); wsPayroll.addRow([]);
            if(report.payroll.length){
                wsPayroll.addTable({name:'PayrollSummaryTable',ref:'A4',headerRow:true,totalsRow:false,style:{theme:'TableStyleMedium2',showRowStripes:true},columns:payrollHeaders.map(name=>({name})),rows:report.payroll.map(p=>[p.name,p.pod,p.regular,p.ot,p.total,p.standardDailyHours,p.regularRate,p.overtimeRate,p.regularPay,p.overtimePay,p.totalPay,p.daysWorked,p.daysOff,p.leaveDays,p.lateMinutes,p.undertimeMinutes,p.exceptions,p.periodStatus])});
                styleHeaderRow(wsPayroll.getRow(4));
                const first=5,last=4+report.payroll.length;
                report.payroll.forEach((p,index)=>{
                    const row=wsPayroll.getRow(first+index);
                    row.getCell(5).value={formula:`C${row.number}+D${row.number}`,result:p.total};
                    row.getCell(9).value={formula:`IF(AND(ISNUMBER(C${row.number}),ISNUMBER(G${row.number})),C${row.number}*G${row.number},"")`,result:p.regularPay};
                    row.getCell(10).value={formula:`IF(AND(ISNUMBER(D${row.number}),ISNUMBER(H${row.number})),D${row.number}*H${row.number},"")`,result:p.overtimePay};
                    row.getCell(11).value={formula:`IF(AND(ISNUMBER(I${row.number}),ISNUMBER(J${row.number})),I${row.number}+J${row.number},"")`,result:p.totalPay};
                    [3,4,5,6].forEach(c=>row.getCell(c).numFmt='0.00');
                    [7,8,9,10,11].forEach(c=>row.getCell(c).numFmt='₱#,##0.00');
                    styleDataRow(row,index%2===1?XLS_STYLE.zebraFill:null); unlockNonFormulaCells(row);
                });
                const totals=report.payroll.reduce((a,p)=>({regular:a.regular+p.regular,ot:a.ot+p.ot,total:a.total+p.total,regularPay:a.regularPay+(Number(p.regularPay)||0),otPay:a.otPay+(Number(p.overtimePay)||0),totalPay:a.totalPay+(Number(p.totalPay)||0),worked:a.worked+p.daysWorked,off:a.off+p.daysOff,leave:a.leave+p.leaveDays,late:a.late+p.lateMinutes,under:a.under+p.undertimeMinutes,issues:a.issues+p.exceptions}),{regular:0,ot:0,total:0,regularPay:0,otPay:0,totalPay:0,worked:0,off:0,leave:0,late:0,under:0,issues:0});
                const tr=wsPayroll.addRow(['Total (All Agents)','',null,null,null,'','','',null,null,null,totals.worked,totals.off,totals.leave,totals.late,totals.under,totals.issues,'']);
                tr.getCell(3).value={formula:`SUM(C${first}:C${last})`,result:exportReportRound2(totals.regular)};
                tr.getCell(4).value={formula:`SUM(D${first}:D${last})`,result:exportReportRound2(totals.ot)};
                tr.getCell(5).value={formula:`C${tr.number}+D${tr.number}`,result:exportReportRound2(totals.total)};
                tr.getCell(9).value={formula:`SUM(I${first}:I${last})`,result:exportReportRound2(totals.regularPay)};
                tr.getCell(10).value={formula:`SUM(J${first}:J${last})`,result:exportReportRound2(totals.otPay)};
                tr.getCell(11).value={formula:`I${tr.number}+J${tr.number}`,result:exportReportRound2(totals.totalPay)};
                [3,4,5].forEach(c=>tr.getCell(c).numFmt='0.00'); [9,10,11].forEach(c=>tr.getCell(c).numFmt='₱#,##0.00'); styleTotalRow(tr);
                wsPayroll.addRow([]);
                const reconTitle=wsPayroll.addRow(['Reconciliation Totals']); wsPayroll.mergeCells(reconTitle.number,1,reconTitle.number,2); styleTotalRow(reconTitle);
                const reconRows=[
                    ['Total Regular Hours',report.reconciliation.regular],['Total Approved OT',report.reconciliation.ot],['Grand Total Hours',report.reconciliation.total],
                    ['Total Regular Pay (PHP)',report.reconciliation.regularPay],['Total OT Pay (PHP)',report.reconciliation.overtimePay],['Grand Total Pay (PHP)',report.reconciliation.totalPay],
                    ['Agents With Hours',report.reconciliation.withHours],['Agents With No Hours',report.reconciliation.noHours],['Agents With Exceptions',report.reconciliation.withExceptions],
                    ['Total Late Minutes',report.reconciliation.late],['Total Undertime Minutes',report.reconciliation.undertime]
                ];
                reconRows.forEach((item,i)=>{ const rr=wsPayroll.addRow(item); if(i<3) rr.getCell(2).numFmt='0.00'; if(i>=3&&i<=5) rr.getCell(2).numFmt='₱#,##0.00'; styleDataRow(rr,i%2===1?XLS_STYLE.zebraFill:null); });
                wsPayroll.addConditionalFormatting({ref:`A${first}:R${last}`,rules:[
                    {type:'expression',formulae:[`$D${first}>0`],style:{fill:XLS_STYLE.otFill}},
                    {type:'expression',formulae:[`$Q${first}>0`],style:{fill:{type:'pattern',pattern:'solid',fgColor:{argb:'FFFEF2F2'}}}}
                ]});
            } else {
                wsPayroll.addRow(['No payroll rows in the selected export scope.']);
            }
            autoFitEnhancedWorksheet(wsPayroll,11,34);

            const overtimeRows=buildFullWorkbookOvertimeRows(context,rows,report);
            const overtimeHeaders=['Date','Agent','POD','Status','Saved OT Hrs','Approved OT Hrs','Note','Approved By','Approved At'];
            const wsOvertime=wb.addWorksheet('Overtime',{views:[{state:'frozen',ySplit:4,xSplit:1}]});
            wsOvertime.properties.tabColor={argb:'FFF59E0B'};
            title(wsOvertime,'Overtime Detail',overtimeHeaders.length); subtitle(wsOvertime,'Live overtime records for the selected Full Attendance scope. Approved OT is the value credited into Total Hrs.',overtimeHeaders.length); wsOvertime.addRow([]);
            if(overtimeRows.length){
                wsOvertime.addTable({name:'FullOvertimeTable',ref:'A4',headerRow:true,totalsRow:false,style:{theme:'TableStyleMedium4',showRowStripes:true},columns:overtimeHeaders.map(name=>({name})),rows:overtimeRows.map(r=>[r.date,r.name,r.pod,r.status,r.savedHours,r.approvedHours,r.note,r.approvedBy,r.approvedAt])});
                styleHeaderRow(wsOvertime.getRow(4));
                const first=5,last=4+overtimeRows.length;
                overtimeRows.forEach((item,index)=>{
                    const row=wsOvertime.getRow(first+index); [5,6].forEach(c=>row.getCell(c).numFmt='0.00'); styleDataRow(row,index%2===1?XLS_STYLE.zebraFill:null);
                    const status=String(item.status||'').toLowerCase();
                    row.getCell(4).fill=status==='approved'?{type:'pattern',pattern:'solid',fgColor:{argb:'FFDCFCE7'}}:(status==='rejected'||status==='cancelled'?{type:'pattern',pattern:'solid',fgColor:{argb:'FFF1F5F9'}}:{type:'pattern',pattern:'solid',fgColor:{argb:'FFFFFBEB'}});
                });
                const total=wsOvertime.addRow(['Total','','','',null,null,'','','']);
                total.getCell(5).value={formula:`SUM(E${first}:E${last})`,result:exportReportRound2(overtimeRows.reduce((sum,r)=>sum+(Number(r.savedHours)||0),0))};
                total.getCell(6).value={formula:`SUM(F${first}:F${last})`,result:exportReportRound2(overtimeRows.reduce((sum,r)=>sum+(Number(r.approvedHours)||0),0))};
                [5,6].forEach(c=>total.getCell(c).numFmt='0.00'); styleTotalRow(total);
            } else {
                const empty=wsOvertime.addRow(['No overtime records in the selected date/people scope.']); wsOvertime.mergeCells(empty.number,1,empty.number,overtimeHeaders.length); styleDataRow(empty);
            }
            autoFitEnhancedWorksheet(wsOvertime,11,44);

            const leaveDayOffRows=buildLeaveDayOffExportRows(context,rows,report);
            const leaveDayOffHeaders=['Date','Agent','POD','Category','Leave Type','Leave Status','Duration','Payroll Treatment','Attendance Activity','Reason / Notes','Decision By','Decision At','Request ID'];
            const wsLeave=wb.addWorksheet('Leave & Day Off',{views:[{state:'frozen',ySplit:4,xSplit:1}]});
            wsLeave.properties.tabColor={argb:'FF8B5CF6'};
            title(wsLeave,'Leave & Day Off Detail',leaveDayOffHeaders.length); subtitle(wsLeave,'Days Off and active Approved/Pending Leave are listed by date. Approved leave only affects payroll when the date is chargeable under the existing schedule policy.',leaveDayOffHeaders.length); wsLeave.addRow([]);
            if(leaveDayOffRows.length){
                wsLeave.addTable({name:'LeaveDayOffTable',ref:'A4',headerRow:true,totalsRow:false,style:{theme:'TableStyleMedium5',showRowStripes:true},columns:leaveDayOffHeaders.map(name=>({name})),rows:leaveDayOffRows.map(r=>[r.date,r.name,r.pod,r.category,r.leaveType,r.leaveStatus,r.duration,r.payrollTreatment,r.attendance,r.reason,r.decisionBy,r.decisionAt,r.requestId])});
                styleHeaderRow(wsLeave.getRow(4));
                leaveDayOffRows.forEach((item,index)=>{
                    const row=wsLeave.getRow(5+index); styleDataRow(row,index%2===1?XLS_STYLE.zebraFill:null);
                    if(item.category.includes('LEAVE')) row.getCell(4).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFEDE9FE'}};
                    else row.getCell(4).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFFEF3C7'}};
                    if(item.leaveStatus==='APPROVED') row.getCell(6).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFDCFCE7'}};
                    else if(item.leaveStatus==='PENDING') row.getCell(6).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFFFFBEB'}};
                    if(item.attendance==='Yes') row.getCell(9).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFFEF2F2'}};
                });
            } else {
                const empty=wsLeave.addRow(['No scheduled Days Off or active Approved/Pending Leave in the selected scope.']); wsLeave.mergeCells(empty.number,1,empty.number,leaveDayOffHeaders.length); styleDataRow(empty);
            }
            autoFitEnhancedWorksheet(wsLeave,11,48);

            const wsExceptions=wb.addWorksheet('Exceptions',{views:[{state:'frozen',ySplit:4,xSplit:1}]});
            wsExceptions.properties.tabColor={argb:'FFDC2626'};
            const exceptionHeaders=['Severity','Date','Agent','POD','Category','Details','Action Needed'];
            title(wsExceptions,'Exceptions / Data Quality',exceptionHeaders.length); subtitle(wsExceptions,'Review these items before payroll close. Export is not blocked unless live sync itself is stale.',exceptionHeaders.length); wsExceptions.addRow([]);
            if(report.exceptions.length){
                wsExceptions.addTable({name:'ExceptionsTable',ref:'A4',headerRow:true,totalsRow:false,style:{theme:'TableStyleMedium9',showRowStripes:true},columns:exceptionHeaders.map(name=>({name})),rows:report.exceptions.map(i=>[i.severity,i.date,i.name,i.pod,i.category,i.details,i.action])});
                styleHeaderRow(wsExceptions.getRow(4));
                report.exceptions.forEach((issue,index)=>{
                    const row=wsExceptions.getRow(5+index); styleDataRow(row,index%2===1?XLS_STYLE.zebraFill:null);
                    const fill=issue.severity==='Error'?{type:'pattern',pattern:'solid',fgColor:{argb:'FFFEF2F2'}}:issue.severity==='Warning'?{type:'pattern',pattern:'solid',fgColor:{argb:'FFFFFBEB'}}:{type:'pattern',pattern:'solid',fgColor:{argb:'FFEFF6FF'}};
                    row.getCell(1).fill=fill;
                });
            } else {
                const ok=wsExceptions.addRow(['OK','','','','No exceptions detected','The selected records passed the export data-quality checks.','']); styleDataRow(ok);
            }
            autoFitEnhancedWorksheet(wsExceptions,11,48);

            const wsInfo=wb.addWorksheet('Export Info',{views:[{state:'frozen',ySplit:4}]});
            wsInfo.properties.tabColor={argb:'FF64748B'};
            title(wsInfo,'Export Info / Audit Trail',2); subtitle(wsInfo,'This sheet documents the live-data state used to create this workbook.',2); wsInfo.addRow([]);
            wsInfo.addTable({name:'ExportInfoTable',ref:'A4',headerRow:true,totalsRow:false,style:{theme:'TableStyleMedium2',showRowStripes:true},columns:[{name:'Field'},{name:'Value'}],rows:report.info});
            styleHeaderRow(wsInfo.getRow(4));
            for(let r=5;r<5+report.info.length;r++) styleDataRow(wsInfo.getRow(r),(r-5)%2===1?XLS_STYLE.zebraFill:null);
            autoFitEnhancedWorksheet(wsInfo,18,70);

            const wsPeriods=wb.addWorksheet('Period Snapshots',{views:[{state:'frozen',ySplit:4,xSplit:1}]});
            wsPeriods.properties.tabColor={argb:'FF7C3AED'};
            const periodHeaders=['Period Type','Start','End','Status','Agents With Hours','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)','Exceptions','Snapshot Generated At','Reset Behavior'];
            title(wsPeriods,'Period Finalization Snapshots',periodHeaders.length); subtitle(wsPeriods,'Ended periods are marked FINALIZED. New periods start from zero because totals are rebuilt from dated source records; attendance history is never deleted.',periodHeaders.length); wsPeriods.addRow([]);
            if(report.periods.length){
                wsPeriods.addTable({name:'PeriodSnapshotsTable',ref:'A4',headerRow:true,totalsRow:false,style:{theme:'TableStyleMedium4',showRowStripes:true},columns:periodHeaders.map(name=>({name})),rows:report.periods.map(p=>[p.type,p.start,p.end,p.status,p.agents,p.regular,p.ot,p.total,p.regularPay,p.otPay,p.totalPay,p.exceptions,report.generatedAt,'Next period starts at 0 from its own dated records'])});
                styleHeaderRow(wsPeriods.getRow(4));
                report.periods.forEach((p,index)=>{
                    const row=wsPeriods.getRow(5+index); [6,7,8].forEach(c=>row.getCell(c).numFmt='0.00'); [9,10,11].forEach(c=>row.getCell(c).numFmt='₱#,##0.00'); styleDataRow(row,index%2===1?XLS_STYLE.zebraFill:null);
                    row.getCell(4).fill=p.status==='FINALIZED'?{type:'pattern',pattern:'solid',fgColor:{argb:'FFDCFCE7'}}:p.status==='PARTIAL'?{type:'pattern',pattern:'solid',fgColor:{argb:'FFFFFBEB'}}:{type:'pattern',pattern:'solid',fgColor:{argb:'FFDBEAFE'}};
                });
            } else {
                wsPeriods.addRow(['No finalized weekly/monthly periods in this export scope.']);
            }
            autoFitEnhancedWorksheet(wsPeriods,11,46);
            await wsPeriods.protect('',{selectLockedCells:true,selectUnlockedCells:false,formatCells:false,formatColumns:false,formatRows:false,sort:false,autoFilter:true});
            return report;
        }


        function exportSpecializedCsvLines(plan, rows, otRows) {
            const ctx=exportCenterContext(plan);
            const report=buildEnhancedExportReport(rows,ctx);
            const lines=[]; const csvRow=values=>lines.push(values.map(escapeCsvCell).join(','));
            const type=ctx.reportType;
            if(type==='payroll'){
                csvRow(['Payroll Summary']);
                csvRow(['Agent','POD','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Standard Day Hrs','Regular Rate (PHP)','OT Rate (PHP)','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)','Days Worked','Days Off','Approved Leave Days','Late Min','Undertime Min','Exceptions','Period Status']);
                report.payroll.forEach(p=>csvRow([p.name,p.pod,p.regular.toFixed(2),p.ot.toFixed(2),p.total.toFixed(2),p.standardDailyHours,p.regularRate==null?'':p.regularRate.toFixed(2),p.overtimeRate==null?'':p.overtimeRate.toFixed(2),p.regularPay==null?'':p.regularPay.toFixed(2),p.overtimePay==null?'':p.overtimePay.toFixed(2),p.totalPay==null?'':p.totalPay.toFixed(2),p.daysWorked,p.daysOff,p.leaveDays,p.lateMinutes,p.undertimeMinutes,p.exceptions,p.periodStatus]));
                lines.push(''); csvRow(['Reconciliation Totals']); csvRow(['Metric','Value']);
                [['Total Regular Hours',report.reconciliation.regular.toFixed(2)],['Total Approved OT',report.reconciliation.ot.toFixed(2)],['Grand Total Hours',report.reconciliation.total.toFixed(2)],['Total Regular Pay (PHP)',report.reconciliation.regularPay.toFixed(2)],['Total OT Pay (PHP)',report.reconciliation.overtimePay.toFixed(2)],['Grand Total Pay (PHP)',report.reconciliation.totalPay.toFixed(2)],['Agents With Hours',report.reconciliation.withHours],['Agents With No Hours',report.reconciliation.noHours],['Agents With Exceptions',report.reconciliation.withExceptions],['Total Late Minutes',report.reconciliation.late],['Total Undertime Minutes',report.reconciliation.undertime]].forEach(csvRow);
            } else if(type==='weekly' || type==='monthly'){
                const summaries=buildExportPeriodSummaries(rows,ctx);
                const source=type==='weekly'?summaries.weeklyRows:summaries.monthlyRows;
                csvRow([type==='weekly'?'Weekly Summary':'Monthly Summary']);
                if(type==='weekly'){
                    csvRow(['Agent','Week Start','Week End','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Regular Rate (PHP)','OT Rate (PHP)','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)']);
                    source.forEach(w=>csvRow([w.name,w.weekStart,w.weekEnd,w.regular.toFixed(2),w.ot.toFixed(2),w.total.toFixed(2),w.regularRate==null?'':w.regularRate.toFixed(2),w.overtimeRate==null?'':w.overtimeRate.toFixed(2),w.regularPay==null?'':w.regularPay.toFixed(2),w.overtimePay==null?'':w.overtimePay.toFixed(2),w.totalPay==null?'':w.totalPay.toFixed(2)]));
                } else {
                    csvRow(['Agent','Month','Regular Credited Hrs','Approved OT Hrs','Total Hrs','Regular Rate (PHP)','OT Rate (PHP)','Regular Pay (PHP)','OT Pay (PHP)','Total Pay (PHP)']);
                    source.forEach(m=>csvRow([m.name,m.monthLabel,m.regular.toFixed(2),m.ot.toFixed(2),m.total.toFixed(2),m.regularRate==null?'':m.regularRate.toFixed(2),m.overtimeRate==null?'':m.overtimeRate.toFixed(2),m.regularPay==null?'':m.regularPay.toFixed(2),m.overtimePay==null?'':m.overtimePay.toFixed(2),m.totalPay==null?'':m.totalPay.toFixed(2)]));
                }
                const total=source.reduce((a,r)=>({regular:a.regular+r.regular,ot:a.ot+r.ot,total:a.total+r.total,regularPay:a.regularPay+(Number(r.regularPay)||0),otPay:a.otPay+(Number(r.overtimePay)||0),totalPay:a.totalPay+(Number(r.totalPay)||0)}),{regular:0,ot:0,total:0,regularPay:0,otPay:0,totalPay:0});
                if(type==='weekly') csvRow(['Total','','',exportReportRound2(total.regular).toFixed(2),exportReportRound2(total.ot).toFixed(2),exportReportRound2(total.total).toFixed(2),'','',exportReportRound2(total.regularPay).toFixed(2),exportReportRound2(total.otPay).toFixed(2),exportReportRound2(total.totalPay).toFixed(2)]);
                else csvRow(['Total','',exportReportRound2(total.regular).toFixed(2),exportReportRound2(total.ot).toFixed(2),exportReportRound2(total.total).toFixed(2),'','',exportReportRound2(total.regularPay).toFixed(2),exportReportRound2(total.otPay).toFixed(2),exportReportRound2(total.totalPay).toFixed(2)]);
            } else if(type==='exceptions'){
                csvRow(['Exceptions / Data Quality']); csvRow(['Severity','Date','Agent','POD','Category','Details','Action Needed']);
                if(report.exceptions.length) report.exceptions.forEach(i=>csvRow([i.severity,i.date,i.name,i.pod,i.category,i.details,i.action]));
                else csvRow(['OK','','','','No exceptions detected','The selected records passed the export data-quality checks.','']);
            } else if(type==='overtime'){
                csvRow(['Overtime Report']); csvRow(['Date','Agent','POD','Status','Saved OT Hrs','Approved OT Hrs','Note','Approved By','Approved At']);
                otRows.forEach(r=>csvRow([r.date,r.name,r.pod,r.status,r.savedHours.toFixed(2),r.approvedHours.toFixed(2),r.note,r.approvedBy,r.approvedAt]));
            }
            lines.push(''); csvRow(['Export Info']); csvRow(['Field','Value']); report.info.forEach(csvRow);
            return {lines,report};
        }

        async function downloadSpecializedCsv(plan, rows, otRows) {
            const ctx=exportCenterContext(plan);
            const built=exportSpecializedCsvLines(ctx,rows,otRows);
            const blob=new Blob(['\ufeff'+built.lines.join('\n')],{type:'text/csv;charset=utf-8;'});
            const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=exportSmartFilename(ctx,'csv');
            document.body.appendChild(a); a.click(); setTimeout(()=>{a.remove();URL.revokeObjectURL(url);},1000);
            if(built.report.exceptions.length) showToast(`Report includes ${built.report.exceptions.length} exception${built.report.exceptions.length===1?'':'s'} for review.`);
        }

