        let securityIdleTimer = null;
        const SECURITY_IDLE_AUTO_LOGOUT_ENABLED = true;
        const SECURITY_IDLE_TIMEOUTS = Object.freeze({
            agent: 4 * 60 * 60 * 1000,
            teamLeader: 2 * 60 * 60 * 1000,
            admin: 30 * 60 * 1000
        });
        function currentSecurityIdleTimeout() {
            if (!SECURITY_IDLE_AUTO_LOGOUT_ENABLED) return 0;
            if (isAdmin) return SECURITY_IDLE_TIMEOUTS.admin;
            if (isTeamLeader) return SECURITY_IDLE_TIMEOUTS.teamLeader;
            if (agentSessionAuthenticated) return SECURITY_IDLE_TIMEOUTS.agent;
            return 0;
        }
        function resetSecurityIdleTimer() {
            if (securityIdleTimer) clearTimeout(securityIdleTimer);
            securityIdleTimer = null;
            const timeout = currentSecurityIdleTimeout();
            if (!timeout) {


                touchPersistentAppSession();
                return;
            }
            const saved = readPersistentAppSession();
            const previousActivity = saved ? Number(saved.lastActivityAt || saved.createdAt || 0) : 0;
            if (previousActivity && Date.now() - previousActivity > timeout) {
                clearPersistentAppSession();
                void leavePrivilegedSession();
                return;
            }
            touchPersistentAppSession();
            securityIdleTimer = setTimeout(() => {
                securityIdleTimer = null;
                void leavePrivilegedSession();
            }, timeout);
        }
        if (SECURITY_IDLE_AUTO_LOGOUT_ENABLED) {
            ['pointerdown', 'keydown', 'touchstart'].forEach(eventName => {
                document.addEventListener(eventName, resetSecurityIdleTimer, { passive: true });
            });
        }
        async function enforceSessionFreshnessAfterResume(reason = 'resume') {
            const timeout = currentSecurityIdleTimeout();
            const saved = readPersistentAppSession();
            if (!saved) return true;
            if (timeout > 0) {
                const lastActivityAt = Number(saved.lastActivityAt || saved.createdAt || 0);
                if (!lastActivityAt || Date.now() - lastActivityAt > timeout) {
                    clearPersistentAppSession();
                    showToast('Your TrinoTime session expired while this device was inactive. Please sign in again.', 6500);
                    await leavePrivilegedSession();
                    return false;
                }
            }


            const credentialValid = await revalidateActiveCredentialSession(reason);
            if (!credentialValid) return false;
            if (timeout > 0) resetSecurityIdleTimer();
            else touchPersistentAppSession(true);
            return true;
        }
