        (function setupAgentLoginPasswordReveal() {
            const input = $('agentLoginPassword');
            const holdButton = $('agentLoginPassHoldToggle');
            if (!input || !holdButton) return;
            let activePointerId = null;
            const reveal = () => { input.type='text'; holdButton.classList.add('is-revealing'); holdButton.setAttribute('aria-pressed','true'); };
            const hide = () => { activePointerId=null; input.type='password'; holdButton.classList.remove('is-revealing'); holdButton.setAttribute('aria-pressed','false'); };
            holdButton.addEventListener('pointerdown', event => { if(event.pointerType==='mouse' && event.button!==0)return; activePointerId=event.pointerId; try{holdButton.setPointerCapture(event.pointerId);}catch(e){} reveal(); });
            holdButton.addEventListener('pointerup', event => { if(activePointerId!==null && event.pointerId!==activePointerId)return; hide(); });
            holdButton.addEventListener('pointercancel', hide);
            holdButton.addEventListener('lostpointercapture', hide);
            holdButton.addEventListener('keydown', event => { if(event.key===' '||event.key==='Enter'){event.preventDefault();reveal();} });
            holdButton.addEventListener('keyup', event => { if(event.key===' '||event.key==='Enter')hide(); });
            holdButton.addEventListener('blur', hide);
            window.addEventListener('blur', hide);
            document.addEventListener('visibilitychange', () => { if(document.hidden)hide(); });
        })();


