        const GATE_AUTH_GUARD_KEY = 'oosTimeClockGateAuthGuardV1';
        let gateAuthGuardTimer = null;

        function readGateAuthGuard() {
            try {
                const raw = sessionStorage.getItem(GATE_AUTH_GUARD_KEY);
                const parsed = raw ? JSON.parse(raw) : null;
                if (!parsed || !Number.isFinite(parsed.failures) || !Number.isFinite(parsed.lockedUntil)) {
                    return { failures: 0, lockedUntil: 0 };
                }
                return { failures: Math.max(0, parsed.failures), lockedUntil: Math.max(0, parsed.lockedUntil) };
            } catch (e) {
                return { failures: 0, lockedUntil: 0 };
            }
        }

        function writeGateAuthGuard(state) {
            try { sessionStorage.setItem(GATE_AUTH_GUARD_KEY, JSON.stringify(state)); } catch (e) {}
        }

        function resetGateAuthGuard() {
            if (gateAuthGuardTimer) clearTimeout(gateAuthGuardTimer);
            gateAuthGuardTimer = null;
            try { sessionStorage.removeItem(GATE_AUTH_GUARD_KEY); } catch (e) {}
            const submit = $('gateAdminSubmit');
            if (submit) submit.disabled = false;
            try { syncGateSecureAccessUi(); } catch (e) {}
        }

        function gateAuthLockSeconds(failures) {
            if (failures >= 12) return 300;
            if (failures >= 8) return 120;
            if (failures >= 5) return 30;
            return 0;
        }

        function refreshGateAuthLockUi() {
            const state = readGateAuthGuard();
            const submit = $('gateAdminSubmit');
            const error = $('gateAdminError');
            const remainingMs = state.lockedUntil - Date.now();
            if (remainingMs <= 0) {
                if (submit) submit.disabled = false;
                if (state.lockedUntil) writeGateAuthGuard({ failures: state.failures, lockedUntil: 0 });
                if (error && error.textContent.startsWith('Too many failed attempts')) {
                    error.textContent = '';
                    error.classList.remove('show');
                }
                gateAuthGuardTimer = null;
                try { syncGateSecureAccessUi(); } catch (e) {}
                return false;
            }
            const seconds = Math.max(1, Math.ceil(remainingMs / 1000));
            if (submit) submit.disabled = true;
            if (error) {
                error.textContent = `Too many failed attempts. Try again in ${seconds}s.`;
                error.classList.add('show');
            }
            if (gateAuthGuardTimer) clearTimeout(gateAuthGuardTimer);
            gateAuthGuardTimer = setTimeout(refreshGateAuthLockUi, Math.min(1000, remainingMs));
            return true;
        }

        function recordGateAuthFailure() {
            const state = readGateAuthGuard();
            state.failures += 1;
            const lockSeconds = gateAuthLockSeconds(state.failures);
            state.lockedUntil = lockSeconds ? Date.now() + lockSeconds * 1000 : 0;
            writeGateAuthGuard(state);
            if (lockSeconds) refreshGateAuthLockUi();
            return lockSeconds;
        }

        async function tryAdminUnlock() {
            if (refreshGateAuthLockUi()) return;
            let access = syncGateSecureAccessUi();
            if (!access.ready && !access.blocked) {
                const submit = $('gateAdminSubmit');
                if (submit) { submit.disabled = true; submit.textContent = 'Verifying…'; }
                await retryGateSecureConnection();
                access = syncGateSecureAccessUi();
            }
            if (!guardGateSecureAccess('admin')) return;
            const role = document.querySelector('input[name="gateRole"]:checked');
            const roleVal = role ? role.value : 'admin';
            const val = String($('gateAdminPass').value || '');
            let success = false;
            let isAdminRole = false;
            let isTeamLeaderRole = false;
            let selectedTlName = null;
            let selectedTlPod = null;
            let tlLoginUsesDefault = false;
            let tlLoginRecord = null;

            if (roleVal === 'admin') {
                const email = String($('gateAdminEmail') ? $('gateAdminEmail').value : '').trim();
                if (!email || !val) {
                    $('gateAdminError').textContent = 'Enter your Firebase Admin email and password.';
                    $('gateAdminError').classList.add('show');
                    (!email && $('gateAdminEmail') ? $('gateAdminEmail') : $('gateAdminPass')).focus();
                    return;
                }
                try {
                    await signInFirebaseAdmin(email, val);
                    success = true;
                    isAdminRole = true;
                    isTeamLeaderRole = true;
                } catch (error) {
                    const lockSeconds = recordGateAuthFailure();
                    if (!lockSeconds) {


                        $('gateAdminError').textContent = 'Admin sign-in failed. Check your credentials and authorization.';
                        $('gateAdminError').classList.add('show');
                    }
                    $('gateAdminPass').value = '';
                    if (!lockSeconds) $('gateAdminPass').focus();
                    return;
                }
            } else {
                const tlSelect = $('gateTlSelect');
                selectedTlName = tlSelect ? tlSelect.value : '';
                selectedTlPod = TEAM_LEADER_POD_BY_NAME[selectedTlName] || null;
                if (!selectedTlName || !selectedTlPod || teamIdForPod(selectedTlPod) !== gateSelectedTeam) {
                    $('gateAdminError').textContent = 'Select your Team Leader name from the current team.';
                    $('gateAdminError').classList.add('show');
                    if (tlSelect) tlSelect.focus();
                    return;
                }
                if (!val) {
                    $('gateAdminError').textContent = 'Enter the Team Leader password.';
                    $('gateAdminError').classList.add('show');
                    $('gateAdminPass').focus();
                    return;
                }
                const result = await verifyTeamLeaderPassword(selectedTlName, val);
                if (!result.ok) {
                    if (result.inactive) {
                        $('gateAdminError').textContent = 'This Team Leader account is inactive. Contact an administrator.';
                    } else if (result.needsSetup || result.needsReset) {
                        $('gateAdminError').textContent = result.needsSetup
                            ? 'This Team Leader account has not been set up. An Admin must generate a one-time temporary password.'
                            : 'This Team Leader account still has a retired shared temporary credential. An Admin must generate a new one-time password.';
                    } else if (result.locked) {
                        const minutes = Math.max(1, Math.ceil((result.lockedUntil - agentAuthNowMs()) / 60000));
                        $('gateAdminError').textContent = `This Team Leader account is locked. Try again in about ${minutes} minute${minutes === 1 ? '' : 's'}.`;
                    } else if (result.invalid) {
                        $('gateAdminError').textContent = 'This Team Leader credential is unavailable. Contact an administrator.';
                    } else {
                        const securityRecord = await recordTeamLeaderFailedLogin(selectedTlName, result.record || null);
                        const remaining = Math.max(0, TEAM_LEADER_MAX_FAILED_LOGINS - Number((securityRecord && securityRecord.failedAttempts) || 0));
                        $('gateAdminError').textContent = securityRecord && securityRecord.lockedUntil > agentAuthNowMs()
                            ? 'Too many failed attempts. This Team Leader account is locked for 15 minutes.'
                            : (remaining > 0 ? `Incorrect password. ${remaining} attempt${remaining === 1 ? '' : 's'} remaining before lockout.` : 'Incorrect password.');
                    }
                    $('gateAdminError').classList.add('show');
                    recordGateAuthFailure();
                    $('gateAdminPass').value = '';
                    return;
                }
                tlLoginRecord = await recordTeamLeaderSuccessfulLogin(selectedTlName, result.record || null, val);
                void establishLeaveServerSession('teamleader', selectedTlName, val, selectedTlPod);
                tlLoginUsesDefault = !!(tlLoginRecord ? tlLoginRecord.isDefault : result.usesDefault);
                success = true;
                isAdminRole = false;
                isTeamLeaderRole = true;
            }

            if (success) {
                resetGateAuthGuard();
                $('gateAdminPass').value = '';
                let pod;
                if (isAdminRole) {
                    const launchTeam = validTeamId(gateSelectedTeam) ? gateSelectedTeam : storedGateTeam();
                    pod = lastPodForTeam(launchTeam) || podsForTeam(launchTeam)[0] || 'POD 0';
                } else {
                    pod = selectedTlPod;
                }
                await enterApp({ admin: isAdminRole, teamLeader: isTeamLeaderRole, pod: pod, teamLeaderName: selectedTlName, verifiedWorkforceIdentity:!isAdminRole && isTeamLeaderRole });
                if (!isAdminRole && isTeamLeaderRole && selectedTlName && selectedTlPod) {
                    // v1.1.70: run migration after the TL dashboard is already available.
                    if (!(tlLoginRecord && tlLoginRecord.isDefault)) {
                        void establishWorkforceFirebaseIdentity('team_leader', selectedTlName, selectedTlPod, val, tlLoginRecord).then(outcome => {
                            if (outcome && outcome.rulesRequired) showToast('Team Leader login is working. Firebase identity migration is waiting for Admin Stage A rules.');
                        });
                    }
                }
                resetSecurityIdleTimer();
                if (!isAdminRole && isTeamLeaderRole) {
                    teamLeaderUsesDefaultPassword = tlLoginUsesDefault;
                    teamLeaderPasswordChangeRequired = tlLoginUsesDefault;
                    updateAdminUI();
                    if (tlLoginUsesDefault) openTeamLeaderPasswordModal({ mandatory: true });
                    else {
                        setDashboardPasswordGate(false);
                        await savePersistentAppSession();
                    }
                } else if (isAdminRole) {
                    await savePersistentAppSession();
                }
                if (gateLaunchTarget === 'tlAttendance') {
                    pendingTlAttendanceOpen = true;
                    if (isAdminRole || !tlLoginUsesDefault) {
                        pendingTlAttendanceOpen = false;
                        setTimeout(openTeamLeaderAttendance, 0);
                    }
                }
            } else {
                const lockSeconds = recordGateAuthFailure();
                if (!lockSeconds) {
                    $('gateAdminError').textContent = 'That Team Leader password is not correct.';
                    $('gateAdminError').classList.add('show');
                }
                $('gateAdminPass').value = '';
                if (!lockSeconds) $('gateAdminPass').focus();
            }
        }
        $('gateAdminSubmit').addEventListener('click', () => {
            void runAsyncAction(tryAdminUnlock, 'Unlock access');
        });
        const gateAdminEmail = $('gateAdminEmail');
        if (gateAdminEmail) gateAdminEmail.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') { e.preventDefault(); $('gateAdminPass').focus(); }
        });
        $('gateAdminPass').addEventListener('keydown', (e) => {
            if (e.key === 'Enter') void runAsyncAction(tryAdminUnlock, 'Unlock access');
        });
        refreshGateAuthLockUi();






        (function setupGatePassHoldReveal() {
            const input = $('gateAdminPass');
            const holdButton = $('gatePassHoldToggle');
            if (!input || !holdButton) return;

            let revealing = false;
            let activePointerId = null;

            function revealPasscode() {
                if (revealing) return;
                revealing = true;
                input.type = 'text';
                holdButton.classList.add('is-revealing');
                holdButton.setAttribute('aria-pressed', 'true');
            }

            function hidePasscode() {
                if (!revealing && input.type === 'password') return;
                revealing = false;
                activePointerId = null;
                input.type = 'password';
                holdButton.classList.remove('is-revealing');
                holdButton.setAttribute('aria-pressed', 'false');
            }

            holdButton.addEventListener('pointerdown', (event) => {
                if (event.pointerType === 'mouse' && event.button !== 0) return;
                activePointerId = event.pointerId;
                try { holdButton.setPointerCapture(event.pointerId); } catch (e) {}
                revealPasscode();
            });
            holdButton.addEventListener('pointerup', (event) => {
                if (activePointerId !== null && event.pointerId !== activePointerId) return;
                hidePasscode();
            });
            holdButton.addEventListener('pointercancel', hidePasscode);
            holdButton.addEventListener('lostpointercapture', hidePasscode);

            holdButton.addEventListener('keydown', (event) => {
                if (event.key !== ' ' && event.key !== 'Enter') return;
                event.preventDefault();
                revealPasscode();
            });
            holdButton.addEventListener('keyup', (event) => {
                if (event.key === ' ' || event.key === 'Enter') hidePasscode();
            });
            holdButton.addEventListener('blur', hidePasscode);
            window.addEventListener('blur', hidePasscode);
            document.addEventListener('visibilitychange', () => {
                if (document.hidden) hidePasscode();
            });
        })();








        (function setupModalAccessibility() {
            const closeButtonByDialogId = {
                integrityOverlay: 'integrityCloseBtn',
                assignOverlay: 'assignCancelBtn',
                editOverlay: 'editCancelBtn',
                otOverlay: 'otCancelBtn',
                notePreviewOverlay: 'notePreviewCloseBtn',
                noteEditorOverlay: 'noteEditorCancelBtn',
                editNameOverlay: 'editNameCancelBtn',
                dayOffOverlay: 'dayOffCloseBtn',
                scheduleExceptionsOverlay: 'scheduleExceptionsCloseBtn',
                dayOffSwapOverlay: 'dayOffSwapCancelBtn',
                shiftOverrideOverlay: 'shiftOverrideCancelBtn',
                auditOverlay: 'auditCloseBtn',
                otTabOverlay: 'otTabCloseBtn',
                todayStatusOverlay: 'todayStatusCloseBtn',
                historyOverlay: 'historyCloseBtn',
                noteHistoryOverlay: 'noteHistoryCloseBtn',
                rosterOverlay: 'rosterCloseBtn',
                moveAgentsOverlay: 'moveAgentsCloseBtn',
                backupTlOverlay: 'backupTlCloseBtn',
                backupTlHandoffOverlay: 'backupTlHandoffCloseBtn',
                totalsOverlay: 'totalsCloseBtn',
                leaveRequestOverlay: 'leaveRequestCloseBtn',
                leaveV2DecisionOverlay: 'leaveV2DecisionCancel',
                networkOverlay: 'networkCloseBtn',
                networkAgentOverlay: 'networkAgentCloseBtn',
                shiftSettingsOverlay: 'shiftSettingsCancelBtn',
                confirmOverlay: 'confirmCancelBtn',
                secureCredentialOverlay: 'secureCredentialCloseBtn',
                announceModal: 'announceCloseBtn',
                settingsModal: 'settingsCloseBtn'
            };

            const tracked = new Map();
            const openerByDialog = new WeakMap();
            const dialogOrder = new WeakMap();
            let orderCounter = 0;

            function isActuallyVisible(element) {
                if (!element || !element.isConnected) return false;
                const style = window.getComputedStyle(element);
                if (style.display === 'none' || style.visibility === 'hidden') return false;
                const rects = element.getClientRects();
                return rects.length > 0;
            }

            function getDialogContainer(dialog) {
                if (!dialog) return null;
                if (dialog.classList.contains('announce-modal')) return $('announceOverlay');
                if (dialog.classList.contains('settings-modal')) return $('settingsOverlay');
                return dialog;
            }

            function isDialogOpen(dialog) {
                const container = getDialogContainer(dialog);
                return isActuallyVisible(dialog) && isActuallyVisible(container);
            }

            function getFocusable(dialog) {
                const selector = [
                    'a[href]',
                    'button:not([disabled])',
                    'input:not([disabled]):not([type="hidden"])',
                    'select:not([disabled])',
                    'textarea:not([disabled])',
                    '[tabindex]:not([tabindex="-1"])'
                ].join(',');
                return Array.from(dialog.querySelectorAll(selector)).filter((element) => {
                    if (!isActuallyVisible(element)) return false;
                    if (element.getAttribute('aria-hidden') === 'true') return false;
                    return true;
                });
            }

            function focusDialog(dialog) {
                requestAnimationFrame(() => {
                    if (!isDialogOpen(dialog)) return;
                    const focusable = getFocusable(dialog);
                    const preferred = focusable.find((el) => el.hasAttribute('autofocus')) || focusable[0];
                    if (preferred) {
                        try { preferred.focus({ preventScroll: true }); } catch (e) { preferred.focus(); }
                        return;
                    }
                    if (!dialog.hasAttribute('tabindex')) dialog.setAttribute('tabindex', '-1');
                    try { dialog.focus({ preventScroll: true }); } catch (e) { dialog.focus(); }
                });
            }

            function rememberOpen(dialog) {
                if (tracked.get(dialog) === true) return;
                tracked.set(dialog, true);
                orderCounter += 1;
                dialogOrder.set(dialog, orderCounter);
                const active = document.activeElement;
                if (active && active !== document.body && active !== document.documentElement && !dialog.contains(active)) {
                    openerByDialog.set(dialog, active);
                }
                focusDialog(dialog);
            }

            function rememberClosed(dialog) {
                if (tracked.get(dialog) !== true) return;
                tracked.set(dialog, false);
                const opener = openerByDialog.get(dialog);
                openerByDialog.delete(dialog);
                requestAnimationFrame(() => {
                    if (!opener || !opener.isConnected || !isActuallyVisible(opener)) return;
                    const active = document.activeElement;
                    if (active && active !== document.body && active !== document.documentElement && isActuallyVisible(active)) return;
                    try { opener.focus({ preventScroll: true }); } catch (e) { opener.focus(); }
                });
            }

            function syncDialog(dialog) {
                if (isDialogOpen(dialog)) rememberOpen(dialog);
                else rememberClosed(dialog);
            }

            function topmostDialog() {
                return Array.from(document.querySelectorAll('[role="dialog"][aria-modal="true"]'))
                    .filter(isDialogOpen)
                    .sort((a, b) => {




                        const containerA = getDialogContainer(a) || a;
                        const containerB = getDialogContainer(b) || b;
                        const zA = Number.parseInt(window.getComputedStyle(containerA).zIndex, 10);
                        const zB = Number.parseInt(window.getComputedStyle(containerB).zIndex, 10);
                        const safeZA = Number.isFinite(zA) ? zA : 0;
                        const safeZB = Number.isFinite(zB) ? zB : 0;
                        if (safeZA !== safeZB) return safeZA - safeZB;
                        return (dialogOrder.get(a) || 0) - (dialogOrder.get(b) || 0);
                    })
                    .pop() || null;
            }

            function closeTopmostDialog(dialog) {
                if (!dialog || dialog.id === 'gateOverlay') return false;
                const logicalId = dialog.classList.contains('announce-modal') ? 'announceModal' :
                    dialog.classList.contains('settings-modal') ? 'settingsModal' : dialog.id;
                const closeId = closeButtonByDialogId[logicalId];
                let closeButton = closeId ? $(closeId) : null;
                if (logicalId === 'confirmOverlay' && closeButton && !isActuallyVisible(closeButton)) closeButton = $('confirmOkBtn');
                if (!closeButton || closeButton.disabled || !isActuallyVisible(closeButton)) return false;
                closeButton.click();
                return true;
            }

            document.addEventListener('keydown', (event) => {
                const dialog = topmostDialog();
                if (!dialog) return;

                if (event.key === 'Escape') {
                    if (closeTopmostDialog(dialog)) {
                        event.preventDefault();
                        event.stopImmediatePropagation();
                    }
                    return;
                }

                if (event.key !== 'Tab') return;
                const focusable = getFocusable(dialog);
                if (!focusable.length) {
                    event.preventDefault();
                    focusDialog(dialog);
                    return;
                }
                const first = focusable[0];
                const last = focusable[focusable.length - 1];
                const active = document.activeElement;
                if (event.shiftKey) {
                    if (active === first || !dialog.contains(active)) {
                        event.preventDefault();
                        last.focus();
                    }
                } else if (active === last || !dialog.contains(active)) {
                    event.preventDefault();
                    first.focus();
                }
            }, true);

            document.addEventListener('focusin', (event) => {
                const dialog = topmostDialog();
                if (!dialog || dialog.contains(event.target)) return;
                const focusable = getFocusable(dialog);
                const target = focusable[0] || dialog;
                if (target === dialog && !dialog.hasAttribute('tabindex')) dialog.setAttribute('tabindex', '-1');
                try { target.focus({ preventScroll: true }); } catch (e) { target.focus(); }
            });

            const dialogs = Array.from(document.querySelectorAll('[role="dialog"][aria-modal="true"]'));
            const observedContainers = new Set();
            dialogs.forEach((dialog) => {
                tracked.set(dialog, false);
                const container = getDialogContainer(dialog);
                if (!container || observedContainers.has(container)) return;
                observedContainers.add(container);
                new MutationObserver(() => dialogs.forEach(syncDialog)).observe(container, {
                    attributes: true,
                    attributeFilter: ['class', 'style', 'aria-hidden']
                });
            });



            requestAnimationFrame(() => dialogs.forEach(syncDialog));
        })();




