        function currentProfileIdentityName() {
            if (!isAdmin && isTeamLeader && teamLeaderName) return teamLeaderName;
            if (!isAdmin && !isTeamLeader && agentSessionAuthenticated && agentSessionName) return agentSessionName;
            return currentEmployee || null;
        }

        function canEditAgentProfile(agentName) {
            return TrinoPermissions.can('profile.self.edit', { name: agentName });
        }

        function currentProfilePresenceAgent() {
            return (!isAdmin && !isTeamLeader && agentSessionAuthenticated && agentSessionName) ? agentSessionName : null;
        }

        function profileServerTimestamp() {
            try {
                return firebase && firebase.database && firebase.database.ServerValue ? firebase.database.ServerValue.TIMESTAMP : Date.now();
            } catch (e) {
                return Date.now();
            }
        }

        function getProfilePresenceSessionId() {
            const key = 'trino_profile_presence_session';
            try {
                let id = sessionStorage.getItem(key);
                if (!id) {
                    id = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : createMutationToken();
                    sessionStorage.setItem(key, id);
                }
                return id.replace(/[.#$\[\]\/]/g, '_');
            } catch (e) {
                return createMutationToken().replace(/[.#$\[\]\/]/g, '_');
            }
        }

        const profilePresenceSessionId = getProfilePresenceSessionId();

        function clearProfilePresenceHeartbeat() {
            if (!profilePresenceHeartbeatTimer) return;
            clearInterval(profilePresenceHeartbeatTimer);
            profilePresenceHeartbeatTimer = null;
        }

        function clearOwnProfilePresence() {
            clearProfilePresenceHeartbeat();
            const ref = profilePresenceRef;
            profilePresenceRef = null;
            profilePresenceAgent = null;
            if (!ref) return;
            try {
                const onDisconnect = ref.onDisconnect && ref.onDisconnect();
                if (onDisconnect && typeof onDisconnect.cancel === 'function') onDisconnect.cancel().catch(() => {});
            } catch (e) {}
            try { ref.remove().catch(() => {}); } catch (e) {}
        }

        async function setOwnProfilePresence(agentName) {
            if (!agentName || !fbDb || fbConnected === false || isAdmin || isTeamLeader) return;
            if (profilePresenceAgent === agentName && profilePresenceRef) return;
            clearOwnProfilePresence();
            const id = profileIdForAgent(agentName);
            const ref = fbDb.ref(PROFILE_PRESENCE_ROOT + '/' + id + '/' + profilePresenceSessionId);
            profilePresenceRef = ref;
            profilePresenceAgent = agentName;
            const payload = {
                online: true,
                agentName,
                displayName: agentDisplayName(agentName),
                pod: podOf(agentName) || '',
                updatedAt: profileServerTimestamp()
            };
            try {
                const onDisconnect = ref.onDisconnect();
                if (onDisconnect && typeof onDisconnect.remove === 'function') await onDisconnect.remove();
                await ref.set(payload);
                profilePresenceAvailable = true;
                profilePresenceErrorReported = false;
                clearProfilePresenceHeartbeat();
                profilePresenceHeartbeatTimer = setInterval(() => {
                    if (!profilePresenceRef || fbConnected === false) return;
                    try { profilePresenceRef.update({ updatedAt: profileServerTimestamp() }).catch(() => {}); } catch (e) {}
                }, 30000);
            } catch (error) {
                profilePresenceAvailable = false;
                clearOwnProfilePresence();
                if (!profilePresenceErrorReported) {
                    profilePresenceErrorReported = true;
                    reportAppError('Agent profile presence', error);
                }
            }
        }

        function ensureProfilePresenceListener() {
            if (!fbDb || profilePresenceListenerAttached) return;
            profilePresenceListenerAttached = true;
            try {
                fbDb.ref(PROFILE_PRESENCE_ROOT).on('value', snap => {
                    profilePresence = snap.val() || {};
                    profilePresenceAvailable = true;
                    profilePresenceErrorReported = false;
                    renderAgentProfileFeature();
                }, error => {
                    profilePresenceAvailable = false;
                    if (!profilePresenceErrorReported) {
                        profilePresenceErrorReported = true;
                        reportAppError('Agent profile presence listener', error);
                    }
                    renderAgentProfileFeature();
                });
            } catch (error) {
                profilePresenceAvailable = false;
                profilePresenceListenerAttached = false;
            }
        }

        function syncProfilePresenceIdentity() {
            ensureProfilePresenceListener();
            const desired = currentProfilePresenceAgent();
            if (!desired) {
                if (profilePresenceAgent) clearOwnProfilePresence();
                return;
            }
            if (fbDb && fbConnected !== false && (profilePresenceAgent !== desired || !profilePresenceRef)) {
                void setOwnProfilePresence(desired);
            }
        }

        function handleAgentProfileRemoteUpsert(key, raw) {
            if (!key || key.indexOf(PROFILE_KEY_PREFIX) !== 0 || typeof raw !== 'string') return false;
            try {
                const parsed = JSON.parse(raw);
                if (!parsed || !parsed.agentName) return false;
                const id = key.slice(PROFILE_KEY_PREFIX.length);
                allAgentProfiles[id] = parsed;
                profileServerSnapshotIds.add(id);
                void putProfileOfflineRecord(key, raw, false);
                if (!hasPendingWrite(key)) recordAgentProfileCloudSync(parsed.agentName);
                renderAgentProfileFeature();
                refreshAgentDisplayNameSurfaces(parsed.agentName);
                return true;
            } catch (e) {
                return false;
            }
        }

        function handleAgentProfileRemoteRemove(key) {
            if (!key || key.indexOf(PROFILE_KEY_PREFIX) !== 0) return false;
            const id = key.slice(PROFILE_KEY_PREFIX.length);
            const removedProfile = allAgentProfiles[id];
            delete allAgentProfiles[id];
            profileServerSnapshotIds.delete(id);
            void deleteProfileOfflineRecord(key);
            if (removedProfile && removedProfile.agentName) clearAgentProfileCloudSyncMeta(removedProfile.agentName);
            renderAgentProfileFeature();
            refreshAgentDisplayNameSurfaces(removedProfile && removedProfile.agentName);
            return true;
        }

        async function verifyAgentProfileOnServer(key, expectedPayload) {
            if (!fbDb) return false;
            try {
                const snap = await withTimeout(
                    fbDb.ref('kv/' + fbEncodeKey(key)).once('value'),
                    FIREBASE_READ_TIMEOUT_MS,
                    'Timed out verifying the saved profile.'
                );
                return snap.exists() && String(snap.val()) === String(expectedPayload);
            } catch (e) {
                return false;
            }
        }

        async function saveAgentProfile(profile) {
            if (!profile || !profile.agentName) return { localSaved:false, remoteSaved:false, remoteVerified:false };
            const id = profileIdForAgent(profile.agentName);
            const key = PROFILE_KEY_PREFIX + id;
            const payload = JSON.stringify(profile);
            allAgentProfiles[id] = profile;
            if (profilePresenceRef && profilePresenceAgent === profile.agentName) {
                try { profilePresenceRef.update({ displayName:agentDisplayName(profile.agentName), updatedAt:profileServerTimestamp() }).catch(() => {}); } catch (_) {}
            }
            refreshAgentDisplayNameSurfaces(profile.agentName);

            await putProfileOfflineRecord(key, payload, true);
            const pendingSaved = safeLocalSet(PENDING_PREFIX + key, payload);
            setLocalMirrorForKey(key, payload, { cacheProfile:false });
            markPendingMutation();
            publishUpdate();
            updatePendingSyncUi();
            renderAgentProfileFeature();

            try {
                const result = await appStorage.set(key, payload);
                const remoteSaved = Boolean(result && result.remoteSaved);
                const remoteVerified = remoteSaved ? await verifyAgentProfileOnServer(key, payload) : false;
                if (remoteVerified) {
                    if (safeLocalGet(PENDING_PREFIX + key) === payload) safeLocalRemove(PENDING_PREFIX + key);
                    await markProfileOfflineRecordSynced(key, payload);
                    recordAgentProfileCloudSync(profile.agentName);
                } else {
                    await putProfileOfflineRecord(key, payload, true);
                    schedulePendingSyncRetry();
                }
                updatePendingSyncUi();
                return { localSaved:Boolean(pendingSaved || result && result.localSaved), remoteSaved, remoteVerified };
            } catch (error) {
                reportAppError('Agent profile sync', error);
                await putProfileOfflineRecord(key, payload, true);
                schedulePendingSyncRetry();
                updatePendingSyncUi();
                return { localSaved:Boolean(pendingSaved), remoteSaved:false, remoteVerified:false, error };
            }
        }

        function estimateDataUrlBytes(dataUrl) {
            const comma = String(dataUrl || '').indexOf(',');
            if (comma < 0) return Infinity;
            const payloadLength = dataUrl.length - comma - 1;
            return Math.ceil(payloadLength * 3 / 4);
        }

        function loadImageFile(file) {
            return new Promise((resolve, reject) => {
                const url = URL.createObjectURL(file);
                const img = new Image();
                img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
                img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Could not read that image.')); };
                img.src = url;
            });
        }

        async function compressProfileImageCrop(img, sourceRect) {
            const sourceWidth = Math.max(1, img.naturalWidth || img.width || 1);
            const sourceHeight = Math.max(1, img.naturalHeight || img.height || 1);
            const sideDefault = Math.min(sourceWidth, sourceHeight);
            const rect = sourceRect || {
                sx: Math.max(0, (sourceWidth - sideDefault) / 2),
                sy: Math.max(0, (sourceHeight - sideDefault) / 2),
                side: sideDefault
            };
            const cropSide = Math.max(1, Math.min(rect.side || sideDefault, sourceWidth, sourceHeight));
            const sx = Math.max(0, Math.min(Number(rect.sx) || 0, sourceWidth - cropSide));
            const sy = Math.max(0, Math.min(Number(rect.sy) || 0, sourceHeight - cropSide));
            let targetSize = Math.min(PROFILE_PHOTO_MAX_DIMENSION, Math.round(cropSide));
            let best = '';
            const qualities = [0.82, 0.74, 0.66, 0.58, 0.50, 0.42];
            for (let sizePass = 0; sizePass < 4; sizePass++) {
                const canvas = document.createElement('canvas');
                canvas.width = Math.max(96, Math.round(targetSize));
                canvas.height = canvas.width;
                const ctx = canvas.getContext('2d', { alpha:false });
                if (!ctx) throw new Error('This browser could not process the profile image.');
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, sx, sy, cropSide, cropSide, 0, 0, canvas.width, canvas.height);
                for (const quality of qualities) {
                    let dataUrl = canvas.toDataURL('image/webp', quality);
                    if (!/^data:image\/webp/i.test(dataUrl)) dataUrl = canvas.toDataURL('image/jpeg', quality);
                    best = dataUrl;
                    if (estimateDataUrlBytes(dataUrl) <= PROFILE_PHOTO_TARGET_BYTES) return dataUrl;
                }
                targetSize *= .82;
            }
            return best;
        }

        async function compressProfilePhoto(file) {
            if (!file || !/^image\//i.test(file.type || '')) throw new Error('Please choose an image file.');
            if (file.size > PROFILE_PHOTO_MAX_SOURCE_BYTES) throw new Error('Profile photos must be 8 MB or smaller.');
            const img = await loadImageFile(file);
            const sourceWidth = Math.max(1, img.naturalWidth || img.width || 1);
            const sourceHeight = Math.max(1, img.naturalHeight || img.height || 1);
            const side = Math.min(sourceWidth, sourceHeight);
            const sx = Math.max(0, Math.round((sourceWidth - side) / 2));
            const sy = Math.max(0, Math.round((sourceHeight - side) / 2));
            let targetSize = Math.min(PROFILE_PHOTO_MAX_DIMENSION, side);
            let best = '';
            const qualities = [0.82, 0.74, 0.66, 0.58, 0.50, 0.42];
            for (let sizePass = 0; sizePass < 4; sizePass++) {
                const canvas = document.createElement('canvas');
                canvas.width = Math.max(96, Math.round(targetSize));
                canvas.height = canvas.width;
                const ctx = canvas.getContext('2d', { alpha:false });
                if (!ctx) throw new Error('This browser could not process the profile image.');
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, sx, sy, side, side, 0, 0, canvas.width, canvas.height);
                for (const quality of qualities) {
                    let dataUrl = canvas.toDataURL('image/webp', quality);
                    if (!/^data:image\/webp/i.test(dataUrl)) dataUrl = canvas.toDataURL('image/jpeg', quality);
                    best = dataUrl;
                    if (estimateDataUrlBytes(dataUrl) <= PROFILE_PHOTO_TARGET_BYTES) return dataUrl;
                }
                targetSize *= .82;
            }
            return best;
        }

        function clampProfilePhotoCropCenter() {
            const state = profilePhotoCropState;
            if (!state || !state.image) return;
            const img = state.image;
            const sourceW = Math.max(1, img.naturalWidth || img.width || 1);
            const sourceH = Math.max(1, img.naturalHeight || img.height || 1);
            const side = Math.min(sourceW, sourceH) / Math.max(1, state.zoom || 1);
            const halfX = Math.min(.5, side / (2 * sourceW));
            const halfY = Math.min(.5, side / (2 * sourceH));
            const centerX = Number(state.centerX);
            const centerY = Number(state.centerY);
            state.centerX = Math.max(halfX, Math.min(1 - halfX, Number.isFinite(centerX) ? centerX : .5));
            state.centerY = Math.max(halfY, Math.min(1 - halfY, Number.isFinite(centerY) ? centerY : .5));
        }

        function scheduleProfilePhotoCropPreview() {
            if (profilePhotoCropRenderRaf) return;
            profilePhotoCropRenderRaf = requestAnimationFrame(() => {
                profilePhotoCropRenderRaf = 0;
                renderProfilePhotoCropPreview();
            });
        }

        function createProfilePhotoCropUi() {
            let overlay = document.getElementById('profilePhotoCropOverlay');
            if (overlay) return overlay;
            overlay = document.createElement('div');
            overlay.id = 'profilePhotoCropOverlay';
            overlay.className = 'profile-photo-crop-overlay';
            overlay.setAttribute('aria-hidden', 'true');
            overlay.innerHTML = `
                <div class="profile-photo-crop-card" role="dialog" aria-modal="true" aria-labelledby="profilePhotoCropTitle">
                    <div class="profile-photo-crop-head">
                        <div><span class="profile-health-kicker">Profile Picture</span><h3 id="profilePhotoCropTitle">Adjust Photo</h3></div>
                        <button type="button" class="profile-photo-crop-close" id="profilePhotoCropCloseBtn" aria-label="Close photo editor">&times;</button>
                    </div>
                    <p class="profile-photo-crop-help">Drag the photo to reposition it, then use the zoom slider. The saved avatar is still compressed for fast syncing.</p>
                    <div class="profile-photo-crop-stage" id="profilePhotoCropStage">
                        <canvas id="profilePhotoCropCanvas" width="720" height="720"></canvas>
                        <span class="profile-photo-crop-ring" aria-hidden="true"></span>
                    </div>
                    <label class="profile-photo-crop-zoom" for="profilePhotoCropZoom"><span>Zoom</span><strong id="profilePhotoCropZoomLabel">1.00x</strong></label>
                    <input id="profilePhotoCropZoom" class="profile-photo-crop-range" type="range" min="1" max="3" step="0.01" value="1">
                    <div class="profile-photo-crop-actions">
                        <button type="button" class="profile-cancel-btn" id="profilePhotoCropResetBtn">Reset</button>
                        <span class="profile-photo-crop-spacer"></span>
                        <button type="button" class="profile-cancel-btn" id="profilePhotoCropCancelBtn">Cancel</button>
                        <button type="button" class="profile-save-btn" id="profilePhotoCropUseBtn">Use Photo</button>
                    </div>
                </div>`;
            document.body.appendChild(overlay);
            const canvas = document.getElementById('profilePhotoCropCanvas');
            const zoom = document.getElementById('profilePhotoCropZoom');
            const close = () => closeProfilePhotoCropper();
            document.getElementById('profilePhotoCropCloseBtn').addEventListener('click', close);
            document.getElementById('profilePhotoCropCancelBtn').addEventListener('click', close);
            overlay.addEventListener('click', event => { if (event.target === overlay) close(); });
            document.getElementById('profilePhotoCropResetBtn').addEventListener('click', () => {
                if (!profilePhotoCropState) return;
                profilePhotoCropState.zoom = 1;
                profilePhotoCropState.centerX = .5;
                profilePhotoCropState.centerY = .5;
                if (zoom) zoom.value = '1';
                clampProfilePhotoCropCenter();
                renderProfilePhotoCropPreview();
            });
            if (zoom) zoom.addEventListener('input', () => {
                if (!profilePhotoCropState) return;
                profilePhotoCropState.zoom = Math.max(1, Math.min(3, Number(zoom.value) || 1));
                clampProfilePhotoCropCenter();
                scheduleProfilePhotoCropPreview();
            });
            let dragging = false;
            let lastX = 0;
            let lastY = 0;
            if (canvas) {
                canvas.addEventListener('pointerdown', event => {
                    if (!profilePhotoCropState) return;
                    dragging = true;
                    lastX = event.clientX;
                    lastY = event.clientY;
                    canvas.setPointerCapture(event.pointerId);
                    canvas.classList.add('is-dragging');
                });
                canvas.addEventListener('pointermove', event => {
                    if (!dragging || !profilePhotoCropState) return;
                    const rect = canvas.getBoundingClientRect();
                    const dx = event.clientX - lastX;
                    const dy = event.clientY - lastY;
                    lastX = event.clientX;
                    lastY = event.clientY;
                    const img = profilePhotoCropState.image;
                    const sourceW = Math.max(1, img.naturalWidth || img.width || 1);
                    const sourceH = Math.max(1, img.naturalHeight || img.height || 1);
                    const cropSide = Math.min(sourceW, sourceH) / profilePhotoCropState.zoom;
                    profilePhotoCropState.centerX -= (dx / Math.max(1, rect.width)) * (cropSide / sourceW);
                    profilePhotoCropState.centerY -= (dy / Math.max(1, rect.height)) * (cropSide / sourceH);
                    clampProfilePhotoCropCenter();
                    scheduleProfilePhotoCropPreview();
                });
                const endDrag = () => { dragging = false; canvas.classList.remove('is-dragging'); };
                canvas.addEventListener('pointerup', endDrag);
                canvas.addEventListener('pointercancel', endDrag);
            }
            document.getElementById('profilePhotoCropUseBtn').addEventListener('click', async () => {
                if (!profilePhotoCropState) return;
                const useBtn = document.getElementById('profilePhotoCropUseBtn');
                if (useBtn) { useBtn.disabled = true; useBtn.textContent = 'Applying...'; }
                try {
                    const rect = profilePhotoCropSourceRect();
                    const dataUrl = await compressProfileImageCrop(profilePhotoCropState.image, rect);
                    profilePendingPhoto = dataUrl;
                    profilePendingPhotoSet = true;
                    closeProfilePhotoCropper();
                    persistAgentProfileDraftFromForm();
                    renderAgentProfileDetail();
                    const chooseAgain = document.getElementById('agentProfilePhotoBtn');
                    if (chooseAgain) setTimeout(() => chooseAgain.focus(), 0);
                    showToast('Adjusted profile picture saved to your draft.');
                } catch (error) {
                    showToast(getErrorMessage(error) || 'Could not apply that profile picture.');
                } finally {
                    if (useBtn && document.body.contains(useBtn)) { useBtn.disabled = false; useBtn.textContent = 'Use Photo'; }
                }
            });
            return overlay;
        }

        function profilePhotoCropSourceRect() {
            const state = profilePhotoCropState;
            if (!state || !state.image) return null;
            const img = state.image;
            const sourceW = Math.max(1, img.naturalWidth || img.width || 1);
            const sourceH = Math.max(1, img.naturalHeight || img.height || 1);
            const side = Math.min(sourceW, sourceH) / Math.max(1, state.zoom || 1);
            const wantedX = state.centerX * sourceW - side / 2;
            const wantedY = state.centerY * sourceH - side / 2;
            return {
                sx: Math.max(0, Math.min(wantedX, sourceW - side)),
                sy: Math.max(0, Math.min(wantedY, sourceH - side)),
                side
            };
        }

        function renderProfilePhotoCropPreview() {
            const state = profilePhotoCropState;
            const canvas = document.getElementById('profilePhotoCropCanvas');
            if (!state || !canvas) return;
            const ctx = canvas.getContext('2d', { alpha:false });
            if (!ctx) return;
            const rect = profilePhotoCropSourceRect();
            ctx.fillStyle = '#0F172A';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(state.image, rect.sx, rect.sy, rect.side, rect.side, 0, 0, canvas.width, canvas.height);
            const zoomLabel = document.getElementById('profilePhotoCropZoomLabel');
            if (zoomLabel) zoomLabel.textContent = `${state.zoom.toFixed(2)}x`;
        }

        async function openProfilePhotoCropper(file) {
            if (!file || !/^image\//i.test(file.type || '')) throw new Error('Please choose an image file.');
            if (file.size > PROFILE_PHOTO_MAX_SOURCE_BYTES) throw new Error('Profile photos must be 8 MB or smaller.');
            const img = await loadImageFile(file);
            const overlay = createProfilePhotoCropUi();
            profilePhotoCropOpener = document.getElementById('agentProfilePhotoBtn') || document.activeElement || null;
            profilePhotoCropState = { image:img, zoom:1, centerX:.5, centerY:.5 };
            clampProfilePhotoCropCenter();
            const zoom = document.getElementById('profilePhotoCropZoom');
            if (zoom) zoom.value = '1';
            overlay.classList.add('open');
            overlay.setAttribute('aria-hidden', 'false');
            renderProfilePhotoCropPreview();
            const useBtn = document.getElementById('profilePhotoCropUseBtn');
            if (useBtn) setTimeout(() => useBtn.focus(), 0);
        }

        function closeProfilePhotoCropper() {
            const overlay = document.getElementById('profilePhotoCropOverlay');
            if (overlay) {
                overlay.classList.remove('open');
                overlay.setAttribute('aria-hidden', 'true');
            }
            if (profilePhotoCropRenderRaf) {
                cancelAnimationFrame(profilePhotoCropRenderRaf);
                profilePhotoCropRenderRaf = 0;
            }
            profilePhotoCropState = null;
            const input = document.getElementById('agentProfilePhotoInput');
            if (input) input.value = '';
            const opener = profilePhotoCropOpener;
            profilePhotoCropOpener = null;
            requestAnimationFrame(() => {
                if (!opener || !opener.isConnected || typeof opener.focus !== 'function') return;
                try { opener.focus({ preventScroll:true }); } catch (e) { try { opener.focus(); } catch (_) {} }
            });
        }

        function createAgentProfileUi() {
            if (profileUiInitialized) return;
            profileUiInitialized = true;
            const slot = document.getElementById('headerProfileSlot');
            if (slot && !document.getElementById('agentProfileHeaderBtn')) {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.id = 'agentProfileHeaderBtn';
                btn.className = 'agent-profile-header-btn';
                btn.setAttribute('aria-label', 'Open my profile');
                btn.setAttribute('title', 'My Profile');
                btn.setAttribute('aria-haspopup', 'dialog');
                btn.innerHTML = '<span class="agent-profile-header-avatar" id="agentProfileHeaderAvatar">PR</span><span class="tt-profile-header-copy"><strong id="agentProfileHeaderName">My Profile</strong><span class="tt-profile-role" id="agentProfileHeaderRole">Workforce profile</span><span class="tt-profile-workspace-chip" aria-hidden="true">Premium Workspace</span></span><span class="agent-profile-header-status is-unavailable" id="agentProfileHeaderStatus" aria-hidden="true"></span><span class="tt-profile-header-chevron" aria-hidden="true">›</span>';
                slot.appendChild(btn);
                btn.addEventListener('click', openAgentProfileModal);
            }

            if (!document.getElementById('agentProfileOverlay')) {
                document.body.insertAdjacentHTML('beforeend', `
                    <div class="modal-overlay" id="agentProfileOverlay" role="dialog" aria-modal="true" aria-labelledby="agentProfileModalTitle">
                        <div class="modal-box agent-profile-modal">
                            <div class="agent-profile-modal-head">
                                <div class="agent-profile-modal-title-wrap">
                                    <h3 class="agent-profile-modal-title" id="agentProfileModalTitle">My Profile</h3>
                                    <p class="agent-profile-modal-sub">Your personal TrinoTime profile.</p>
                                </div>
                                <div class="context-help-actions"><button class="context-help-btn" type="button" data-help-topic="profile" aria-label="Help for My Profile" title="Open profile guide">?</button><button class="agent-profile-close-btn" id="agentProfileCloseBtn" type="button" aria-label="Close my profile">&times;</button></div>
                            </div>
                            <div class="agent-profile-shell">
                                <section class="agent-profile-detail" id="agentProfileDetail" aria-live="polite"></section>
                            </div>
                        </div>
                    </div>`);
                const overlay = document.getElementById('agentProfileOverlay');
                const close = document.getElementById('agentProfileCloseBtn');
                const detail = document.getElementById('agentProfileDetail');
                if (close) close.addEventListener('click', closeAgentProfileModal);
                if (overlay) overlay.addEventListener('click', event => { if (event.target === overlay) closeAgentProfileModal(); });
                if (detail) detail.addEventListener('click', async event => {
                    if (event.target.closest('#agentProfileEditBtn')) {
                        if (!canEditAgentProfile(profileSelectedAgent)) return;
                        profileEditing = true;
                        profilePendingPhoto = null;
                        profilePendingPhotoSet = false;
                        renderAgentProfileDetail();
                        return;
                    }
                    if (event.target.closest('#agentProfileCancelEditBtn')) {
                        persistAgentProfileDraftFromForm();
                        profileEditing = false;
                        profilePendingPhoto = null;
                        profilePendingPhotoSet = false;
                        renderAgentProfileDetail();
                        return;
                    }
                    if (event.target.closest('#agentProfileDiscardDraftBtn')) {
                        const agentName = profileSelectedAgent || currentEmployee;
                        if (!agentName || !canEditAgentProfile(agentName)) return;
                        const existingDraft = readAgentProfileDraft(agentName);
                        if (!existingDraft && !profilePendingPhotoSet) {
                            updateAgentProfileDraftStatus(null);
                            showToast('There is no unsaved profile draft to discard.');
                            return;
                        }
                        if (!(await showConfirmAsync(
                            'Discard Unsaved Profile Changes?',
                            'Discard all unsaved profile changes, including any unsaved profile picture? The last saved profile will be restored.',
                            { confirmLabel:'Discard Changes', cancelLabel:'Keep Editing', tone:'danger', kind:'profile-discard' }
                        ))) return;
                        clearAgentProfileDraft(agentName);
                        profilePendingPhoto = null;
                        profilePendingPhotoSet = false;
                        renderAgentProfileDetail();
                        showToast('Unsaved profile draft discarded.');
                        return;
                    }
                    if (event.target.closest('#agentProfilePhotoBtn')) {
                        const input = document.getElementById('agentProfilePhotoInput');
                        if (input) input.click();
                        return;
                    }
                    if (event.target.closest('#agentProfilePhotoRemoveBtn')) {
                        profilePendingPhoto = '';
                        profilePendingPhotoSet = true;
                        persistAgentProfileDraftFromForm();
                        renderAgentProfileDetail();
                        return;
                    }
                    if (event.target.closest('#agentProfileSaveBtn')) {
                        void saveAgentProfileFromForm();
                    }
                });
            }
            document.addEventListener('keydown', event => {
                if (event.key === 'Escape' && document.getElementById('profilePhotoCropOverlay')?.classList.contains('open')) {
                    closeProfilePhotoCropper();
                    return;
                }
                if (event.key === 'Escape' && isOverlayOpen(document.getElementById('agentPasswordOverlay'))) {
                    closeAgentPasswordModal();
                    return;
                }
                if (event.key === 'Escape' && isOverlayOpen(document.getElementById('agentProfileOverlay'))) closeAgentProfileModal();
            });
        }

        function openAgentProfileModal() {
            createAgentProfileUi();
            const profileIdentity = currentProfileIdentityName();
            if (!profileIdentity) {
                showToast('Sign in to your personal account to open your profile.');
                return;
            }
            const overlay = document.getElementById('agentProfileOverlay');
            if (!overlay) return;
            profileSelectedAgent = profileIdentity;
            profileEditing = false;
            profilePendingPhoto = null;
            profilePendingPhotoSet = false;
            overlay.classList.add('open');
            renderAgentProfileFeature();
            const close = document.getElementById('agentProfileCloseBtn');
            if (close) setTimeout(() => close.focus(), 0);
        }

        function closeAgentProfileModal() {
            if (profileEditing) persistAgentProfileDraftFromForm();
            const overlay = document.getElementById('agentProfileOverlay');
            if (overlay) overlay.classList.remove('open');
            profileEditing = false;
            profilePendingPhoto = null;
            profilePendingPhotoSet = false;
        }

        function renderAgentProfileHeader() {
            const avatar = document.getElementById('agentProfileHeaderAvatar');
            const status = document.getElementById('agentProfileHeaderStatus');
            const btn = document.getElementById('agentProfileHeaderBtn');
            const slot = document.getElementById('headerProfileSlot');
            if (!avatar || !status || !btn) return;
            const profileIdentity = currentProfileIdentityName();
            const hasProfileIdentity = Boolean(profileIdentity);
            btn.style.display = hasProfileIdentity ? 'inline-flex' : 'none';
            if (slot) slot.style.display = hasProfileIdentity ? 'flex' : 'none';
            if (!hasProfileIdentity) return;

            const profile = getAgentProfile(profileIdentity);
            avatar.dataset.agentAvatar = profileIdentity;
            avatar.innerHTML = profileAvatarInnerMarkup(profileIdentity);
            const state = agentProfilePresenceState(profileIdentity);
            const online = state === 'online';
            status.className = 'agent-profile-header-status' + (online ? ' is-online' : (state === 'unavailable' ? ' is-unavailable' : ''));
            const publicProfileName = agentDisplayName(profileIdentity);
            const headerName = document.getElementById('agentProfileHeaderName');
            const headerRole = document.getElementById('agentProfileHeaderRole');
            const profilePod = TEAM_LEADER_POD_BY_NAME[profileIdentity] || podOf(profileIdentity) || (activePod !== ALL_PODS_LABEL ? activePod : '');
            if (headerName) headerName.textContent = publicProfileName;
            if (headerRole) headerRole.textContent = TEAM_LEADER_POD_BY_NAME[profileIdentity]
                ? `Team Leader · ${profilePod || 'Assigned POD'}`
                : `Data Labeler${profilePod ? ' · ' + profilePod : ''}`;
            btn.title = `My Profile - ${publicProfileName}`;
            btn.setAttribute('aria-label', `Open ${publicProfileName}'s profile`);
        }

        function profileValueMarkup(value, fallback) {
            const text = String(value == null ? '' : value).trim();
            return text ? escapeHtml(text) : `<span class="profile-info-empty">${escapeHtml(fallback)}</span>`;
        }


