        function bindAgentProfileEditFormNormal() {
            const photoInput = document.getElementById('agentProfilePhotoInput');
            const address = document.getElementById('agentProfileAddress');
            const bio = document.getElementById('agentProfileBio');
            const addressCount = document.getElementById('agentProfileAddressCount');
            const bioCount = document.getElementById('agentProfileBioCount');
            if (address && addressCount) address.addEventListener('input', () => {
                addressCount.textContent = `${address.value.length}/${PROFILE_ADDRESS_MAX}`;
                persistAgentProfileDraftFromFormNormal();
            });
            if (bio && bioCount) bio.addEventListener('input', () => {
                bioCount.textContent = `${bio.value.length}/${PROFILE_BIO_MAX}`;
                persistAgentProfileDraftFromFormNormal();
            });
            if (photoInput) photoInput.addEventListener('change', async () => {
                const file = photoInput.files && photoInput.files[0];
                if (!file) return;
                try {
                    showToast('Optimizing profile picture...');
                    const dataUrl = await compressProfilePhoto(file);
                    persistAgentProfileDraftFromFormNormal();
                    profilePendingPhoto = dataUrl;
                    profilePendingPhotoSet = true;
                    renderAgentProfileDetail();
                    showToast('Profile picture ready to save.');
                } catch (error) {
                    showToast(getErrorMessage(error) || 'Could not process that profile picture.');
                }
            });
        }


        async function saveAgentProfileFromFormNormal() {
            const agentName = profileSelectedAgent;
            if (!canEditAgentProfile(agentName)) {
                showToast('You can edit only your own personal profile.');
                return;
            }
            const current = getAgentProfile(agentName);
            const fullName = cleanProfileString((document.getElementById('agentProfileFullName') || {}).value, PROFILE_NAME_MAX) || agentName;
            const ageRaw = cleanProfileString((document.getElementById('agentProfileAge') || {}).value, 3);
            let age = null;
            if (ageRaw) {
                age = Number(ageRaw);
                if (!Number.isInteger(age) || age < 1 || age > 120) {
                    showToast('Age must be a whole number from 1 to 120.');
                    return;
                }
            }
            const gender = cleanProfileString((document.getElementById('agentProfileGender') || {}).value, PROFILE_GENDER_MAX);
            const location = cleanProfileString((document.getElementById('agentProfileAddress') || {}).value, PROFILE_ADDRESS_MAX);
            const bio = cleanProfileString((document.getElementById('agentProfileBio') || {}).value, PROFILE_BIO_MAX);
            let photoUrl = safeProfilePhotoUrl(current.photoUrl);
            let photoStoragePath = String(current.photoStoragePath || '');
            let photoDataUrl = safeProfilePhoto(current.photoDataUrl);

            if (profilePendingPhotoSet) {
                const preparedPhoto = safeProfilePhoto(profilePendingPhoto);
                if (preparedPhoto) {


                    photoUrl = '';
                    photoStoragePath = '';
                    photoDataUrl = preparedPhoto;
                } else {

                    photoUrl = '';
                    photoStoragePath = '';
                    photoDataUrl = '';
                }
            }

            const updatedAt = typeof nowIso === 'function' ? nowIso() : new Date().toISOString();
            const next = {
                profileVersion: 3,
                agentName,
                fullName,
                age,
                gender,
                address: location,
                location,
                bio,
                photoUrl,
                photoStoragePath,
                photoDataUrl,
                pod: TEAM_LEADER_POD_BY_NAME[agentName] || podOf(agentName) || current.pod || '',
                publicVisibility: false,
                profilePrivacyVersion: 2,
                updatedAt
            };
            const saveBtn = document.getElementById('agentProfileSaveBtn');
            if (saveBtn) {
                saveBtn.disabled = true;
                saveBtn.textContent = 'Saving...';
            }
            let saveResult;
            try {
                saveResult = await saveAgentProfile(next);
            } catch (error) {
                if (saveBtn) {
                    saveBtn.disabled = false;
                    saveBtn.textContent = 'Save Profile';
                }
                reportAppError('Agent profile save', error);
                showToast('Could not save the profile yet. Your Location and Bio draft is still saved on this device.');
                return;
            }
            clearAgentProfileDraft(agentName);
            profileEditing = false;
            profilePendingPhoto = null;
            profilePendingPhotoSet = false;
            renderAgentProfileFeature();
            if (saveResult && saveResult.remoteVerified) {
                showToast('Profile and compressed avatar saved to the cloud.');
            } else {
                showToast('Profile saved on this device and queued for cloud sync.');
            }
        }


        function persistAgentProfileDraftFromFormNormal() {
            const agentName = profileSelectedAgent || currentEmployee;
            if (!profileEditing || !agentName) return;
            const locationEl = document.getElementById('agentProfileAddress');
            const bioEl = document.getElementById('agentProfileBio');
            if (!locationEl && !bioEl) return;
            const current = getAgentProfile(agentName);
            const location = locationEl ? locationEl.value : (current.location || current.address || '');
            const bio = bioEl ? bioEl.value : (current.bio || '');
            writeAgentProfileDraftNormal(agentName, location, bio);
        }


        function writeAgentProfileDraftNormal(agentName, location, bio) {
            if (!agentName) return false;
            const draft = {
                draftVersion: 1,
                agentName,
                location: profileDraftText(location, PROFILE_ADDRESS_MAX),
                bio: profileDraftText(bio, PROFILE_BIO_MAX),
                updatedAt: typeof nowIso === 'function' ? nowIso() : new Date().toISOString()
            };
            return safeLocalSet(profileDraftStorageKey(agentName), JSON.stringify(draft));
        }

