        function leaveV3Clone(value) {
            return JSON.parse(JSON.stringify(value));
        }

        function leaveV3AgentId(name) {
            try { return agentAuthId(name); } catch (e) {}
            return encodeURIComponent(String(name || '').trim().toLowerCase()).replace(/\./g,'%2E');
        }

        function leaveV3TypePolicy(type, policy = leavePolicyV3) {
            const raw = policy && policy.types && policy.types[type] ? policy.types[type] : {};
            const base = leaveV3Clone(LEAVE_V3_DEFAULT_TYPE_POLICY);
            Object.assign(base, raw || {});
            if (type === 'Unpaid Leave') base.paid = false;
            base.tracked = base.tracked !== false;
            base.reservePending = base.reservePending !== false;
            base.enforceBalance = base.enforceBalance === true;
            base.allowNegative = base.allowNegative === true;
            base.prorateFirstYear = base.prorateFirstYear === true;
            base.accrualMode = LEAVE_V3_ACCRUAL_MODES.includes(String(base.accrualMode || '').toUpperCase()) ? String(base.accrualMode).toUpperCase() : 'MANUAL';
            ['annualEntitlement','accrualAmount','cap','carryoverCap','expirationMonths'].forEach(key => {
                const value = base[key];
                base[key] = value === '' || value === null || value === undefined ? null : (Number.isFinite(Number(value)) ? Math.round(Number(value) * 10000) / 10000 : null);
            });
            base.payPeriodDays = Math.max(1, Math.min(60, Number(base.payPeriodDays) || 14));
            base.eligibilityDays = Math.max(0, Math.min(3650, Number(base.eligibilityDays) || 0));
            return base;
        }

        function leaveV3NormalizePolicy(value) {
            const source = value && typeof value === 'object' ? value : {};
            const next = leaveV3Clone(LEAVE_V3_DEFAULT_POLICY);
            next.version = 3;
            next.effectiveDate = source.effectiveDate || null;
            next.lockedThrough = source.lockedThrough || null;
            next.updatedAt = source.updatedAt || null;
            next.updatedBy = source.updatedBy || null;
            next.policyVersionId = source.policyVersionId || null;
            next.holidays = Array.from(new Set((Array.isArray(source.holidays)?source.holidays:[]).map(v=>String(v||'').trim()).filter(v=>/^\d{4}-\d{2}-\d{2}$/.test(v)))).sort();
            LEAVE_V3_TYPES.forEach(type => {
                const incoming = source.types && source.types[type] ? leaveV3Clone(source.types[type]) : {};
                if ((!source.types || !source.types[type]) && leavePolicyV2 && leavePolicyV2.entitlements && leavePolicyV2.entitlements[type] !== undefined) {
                    incoming.annualEntitlement = leavePolicyV2.entitlements[type];
                }
                next.types[type] = leaveV3TypePolicy(type,{types:{[type]:incoming}});
            });
            return next;
        }




        leaveChargeableDateResolver = function(request, dateStr) {
            if (!request) return false;
            const name = String(request.agentName || '');
            const swap = getDayOffSwapForEmployee(name, dateStr, request.pod);
            let scheduledWorking = !isRecurringDayOffForEmployee(name, dateStr, request.pod);
            if (swap) {
                if (swap.offAgent === name) scheduledWorking = true;
                if (swap.workAgent === name) scheduledWorking = false;
            }
            if (!scheduledWorking) return false;
            const iso = mdyToIsoDateInput(dateStr);
            const holidays = leavePolicyV3 && Array.isArray(leavePolicyV3.holidays) ? leavePolicyV3.holidays : [];
            return !iso || !holidays.includes(iso);
        };
        effectiveLeaveChargeableResolver = leaveChargeableDateResolver;

        function leaveV3NormalizeEntry(value) {
            if (!value || typeof value !== 'object') return null;
            const units = Number(value.units);
            if (!Number.isFinite(units)) return null;
            const kind = String(value.kind || 'ADJUSTMENT').toUpperCase();
            return {
                ...value,
                id:String(value.id || ''),
                agentName:String(value.agentName || ''),
                agentId:String(value.agentId || leaveV3AgentId(value.agentName || '')),
                pod:String(value.pod || ''),
                leaveType:String(value.leaveType || 'Other'),
                year:Number(value.year) || Number(String(value.effectiveDate || '').slice(0,4)) || new Date().getFullYear(),
                effectiveDate:String(value.effectiveDate || '').slice(0,10),
                units:Math.round(units * 10000) / 10000,
                kind:LEAVE_V3_ENTRY_KINDS.includes(kind) ? kind : 'ADJUSTMENT',
                memo:String(value.memo || ''),
                sourceRequestId:String(value.sourceRequestId || ''),
                immutable:true
            };
        }

        function leaveV3EntryKey(entry) {
            return String(entry && entry.id || '');
        }

        function leaveV3PolicyLocked(dateIso) {
            const lock = leavePolicyV3 && leavePolicyV3.lockedThrough ? String(leavePolicyV3.lockedThrough) : '';
            return !!(lock && dateIso && String(dateIso) <= lock);
        }

        function leaveV3VisibleAgents() {
            const list = unifiedLeaveRosterMembers().map(member => ({ name:member.name, pod:member.pod, hrRole:member.roleLabel }));
            if (isAdmin) return list;
            const identity = leaveRequesterIdentity();
            return identity ? list.filter(emp => emp && String(emp.name || '').toLowerCase() === String(identity.name || '').toLowerCase()) : [];
        }

        function leaveV3ActorCanSeeEntry(entry) {
            if (!entry) return false;
            if (isAdmin) return true;
            if (isTeamLeader) return teamLeaderCanAccessPod(entry.pod || podOf(entry.agentName));
            const identity = leaveRequesterIdentity();
            return !!(identity && String(entry.agentName || '').toLowerCase() === String(identity.name || '').toLowerCase());
        }

        function leaveV3PostedEntries(name, type, year) {
            const target = String(name || '').toLowerCase();
            return Object.values(allLeaveLedgerV3).map(leaveV3NormalizeEntry).filter(entry => entry && leaveV3ActorCanSeeEntry(entry) && (!target || entry.agentName.toLowerCase() === target) && (!type || entry.leaveType === type) && (!year || Number(entry.year) === Number(year)));
        }

        function leaveV3VirtualLegacyEntries(name, type, year) {
            const target = String(name || '').toLowerCase();
            const postedPairs = new Set(Object.values(allLeaveLedgerV3).map(item => item&&item.sourceRequestId ? String(item.sourceRequestId)+'|'+String(item.year||'') : '').filter(Boolean));
            const out=[];
            Object.values(allLeaveRequests).forEach(request => {
                if(!request||normalizeLeaveStatus(request.status)!=='APPROVED')return;
                if(target&&String(request.agentName||'').toLowerCase()!==target)return;
                if(type&&request.leaveType!==type)return;
                const startYear=Number(String(request.startDate||'').slice(0,4)),endYear=Number(String(request.endDate||request.startDate||'').slice(0,4));
                for(let y=startYear;y<=endYear;y++){
                    if(year&&Number(year)!==y)continue;if(postedPairs.has(String(request.id)+'|'+y))continue;const units=leaveV3RequestUnitsForYear(request,y);if(units<=0)continue;
                    const effective=leaveV3UsageEffectiveDateForYear(request,y);
                    const entry=leaveV3NormalizeEntry({id:'virtual-legacy:'+request.id+':'+y,agentName:request.agentName,agentId:leaveV3AgentId(request.agentName),pod:request.pod,leaveType:request.leaveType,year:y,effectiveDate:effective,units:-units,kind:'LEAVE_USAGE',sourceRequestId:request.id,memo:'Virtual migration bridge for approved V2 request',createdAt:request.decisionAt||request.updatedAt||request.createdAt,createdBy:request.decisionBy||'Legacy migration',createdRole:request.decisionRole||'system',_virtualLegacy:true});
                    if(entry)out.push(entry);
                }
            });
            return out;
        }


        function leaveV3RequestUnitsForYear(request,year) {
            if(!request) return 0;
            const targetYear=Number(year);
            const duration=leaveV2DurationCode(request); const days=leaveDateRangeDays(request.startDate,request.endDate);
            if(!days.length) return 0;
            if(duration===LEAVE_V2_DURATION.FULL){return days.reduce((sum,dateStr)=>{const iso=mdyToIsoDateInput(dateStr);if(Number(String(iso).slice(0,4))!==targetYear)return sum;return sum+(leaveChargeableDateResolver(request,dateStr)?1:0);},0);}
            if(Number(String(request.startDate||'').slice(0,4))!==targetYear||!leaveChargeableDateResolver(request,isoDateInputToMdy(request.startDate))) return 0;
            return leaveV2PartialUnitsForRequest(request);
        }
        function leaveV3RequestUnits(request) {
            if(!request)return 0; const startYear=Number(String(request.startDate||'').slice(0,4)),endYear=Number(String(request.endDate||request.startDate||'').slice(0,4));let total=0;
            if(!startYear||!endYear)return leaveV3LegacyRequestUnits(request); for(let year=startYear;year<=endYear;year++)total+=leaveV3RequestUnitsForYear(request,year); return Math.round(total*10000)/10000;
        }
        function leaveV3UsageEffectiveDateForYear(request, year) {
            const targetYear = Number(year);
            for (const dateStr of leaveDateRangeDays(request && request.startDate, request && request.endDate)) {
                const iso = mdyToIsoDateInput(dateStr);
                if (iso && Number(iso.slice(0,4)) === targetYear && leaveChargeableDateResolver(request,dateStr)) return iso;
            }
            return String(targetYear) + '-01-01';
        }
        leaveV2RequestUnits = leaveV3RequestUnits;

        function leaveV3PendingReserved(name, type, year, excludeId) {
            const policy = leaveV3TypePolicy(type);
            if (!policy.reservePending) return 0;
            const target = String(name || '').toLowerCase();
            let total = 0;
            Object.values(allLeaveRequests).forEach(request => {
                if (!request || request.id === excludeId || normalizeLeaveStatus(request.status) !== 'PENDING') return;
                if (String(request.agentName || '').toLowerCase() !== target || request.leaveType !== type) return;
                const startYear=Number(String(request.startDate||'').slice(0,4)),endYear=Number(String(request.endDate||request.startDate||'').slice(0,4));
                if (Number(year) < startYear || Number(year) > endYear) return;
                total += leaveV3RequestUnitsForYear(request,year);
            });
            return Math.round(total * 10000) / 10000;
        }

        function leaveV3ApprovedTiming(name, type, year) {
            const target = String(name || '').toLowerCase();
            const targetYear = Number(year);
            const today = leaveV3IsoToday();
            let taken = 0, upcoming = 0;
            Object.values(allLeaveRequests).forEach(request => {
                if (!request || normalizeLeaveStatus(request.status) !== 'APPROVED') return;
                if (String(request.agentName || '').toLowerCase() !== target || request.leaveType !== type) return;
                const duration = leaveV2DurationCode(request);
                if (duration === LEAVE_V2_DURATION.FULL) {
                    leaveDateRangeDays(request.startDate,request.endDate).forEach(dateStr => {
                        const iso = mdyToIsoDateInput(dateStr);
                        if (!iso || Number(iso.slice(0,4)) !== targetYear || !leaveChargeableDateResolver(request,dateStr)) return;
                        if (iso <= today) taken += 1; else upcoming += 1;
                    });
                    return;
                }
                if (Number(String(request.startDate || '').slice(0,4)) !== targetYear) return;
                const units = leaveV3RequestUnitsForYear(request,targetYear);
                if (!(units > 0)) return;
                if (String(request.startDate) <= today) taken += units; else upcoming += units;
            });
            return { taken:Math.round(taken*10000)/10000, upcoming:Math.round(upcoming*10000)/10000 };
        }

        function leaveV3BalanceFor(name, type, year, excludeId) {
            const posted = leaveV3PostedEntries(name,type,year);
            const virtual = leaveV3VirtualLegacyEntries(name,type,year);
            const entries = posted.concat(virtual);
            const postedBalance = Math.round(entries.reduce((sum,entry) => sum + Number(entry.units || 0),0) * 10000) / 10000;
            const credits = Math.round(entries.filter(entry => entry.units > 0).reduce((sum,entry) => sum + entry.units,0) * 10000) / 10000;
            const usageNet = entries.filter(entry => entry.kind === 'LEAVE_USAGE' || entry.kind === 'LEAVE_REVERSAL').reduce((sum,entry) => sum + entry.units,0);
            const approvedUsage = Math.round(Math.max(0,-usageNet) * 10000) / 10000;
            const timing = leaveV3ApprovedTiming(name,type,year);
            const timedTotal = Math.round((timing.taken + timing.upcoming) * 10000) / 10000;


            const unmatchedUsage = Math.max(0, Math.round((approvedUsage - timedTotal) * 10000) / 10000);
            const used = Math.round((timing.taken + unmatchedUsage) * 10000) / 10000;
            const pending = leaveV3PendingReserved(name,type,year,excludeId);
            const available = Math.round((postedBalance - pending) * 10000) / 10000;
            const scheduled = timing.upcoming;
            return { entitlement:credits || null, approved:approvedUsage, approvedUsage, pending, remaining:postedBalance, available, postedBalance, credits, used, scheduled, entries };
        }


        leaveV2BalanceFor = function(name, leaveType, year, excludeId) {
            const b = leaveV3BalanceFor(name,leaveType,year,excludeId);
            const policy = leaveV3TypePolicy(leaveType);
            return {
                entitlement:policy.annualEntitlement,
                approved:b.approvedUsage,
                pending:b.pending,
                remaining:b.postedBalance,
                available:b.available,
                ledger:true,
                enforceBalance:policy.enforceBalance === true,
                allowNegative:policy.allowNegative === true
            };
        };

        function leaveV3FormatUnits(value) {
            const n = Math.round(Number(value || 0) * 100) / 100;
            return n.toLocaleString(undefined,{maximumFractionDigits:2}) + ' day' + (Math.abs(n) === 1 ? '' : 's');
        }

        function leaveV3IsoToday() { return mdyToIsoDateInput(todayKeyPart()); }

        async function leaveV3Api(path, options = {}) {
            if (window.TRINOTIME_LEAVE_FREE_PILOT === true) return {ok:false,status:0,pilot:true,unavailable:true};
            const headers = { ...(options.headers || {}), ...(await leaveV2AuthorizationHeaders()) };
            try {
                const response = await fetch(leaveV2ApiRoot() + path,{...options,headers,credentials:'omit'});
                let data = null;
                try { data = await response.json(); } catch (e) {}
                return {ok:response.ok,status:response.status,data};
            } catch (error) { return {ok:false,status:0,error}; }
        }

        async function leaveV3DetectServer() {
            if (window.TRINOTIME_LEAVE_FREE_PILOT === true) {
                leaveV3ServerCapable = false;
                renderLeaveV3Authority();
                return false;
            }
            const result = await leaveV3Api('/health',{method:'GET',cache:'no-store'});
            const version = result.data && Number(result.data.version || 0);
            leaveV3ServerCapable = !!(result.ok && version >= 3);
            renderLeaveV3Authority();
            return leaveV3ServerCapable;
        }

        function renderLeaveV3Authority() {
            const el = $('leaveV3Authority');
            if (!el) return;
            if (window.TRINOTIME_LEAVE_FREE_PILOT === true) {
                el.className = 'leave-v3-authority pilot';
                el.textContent = 'FREE PILOT · Firebase';
                el.title = 'Testing mode only — server-authoritative HR controls are not active';
                return;
            }
            el.className = 'leave-v3-authority ' + (leaveV3ServerCapable ? 'server' : leaveV2ServerRequired() ? 'blocked' : 'fallback');
            el.textContent = leaveV3ServerCapable ? 'Authoritative server ledger' : leaveV2ServerRequired() ? 'Ledger server required' : 'Compatibility ledger mode';
        }

        async function leaveV3LoadSecureRequests() {
            if(!leaveV3ServerCapable) return false;
            const result=await leaveV3Api('/leave-requests',{method:'GET',cache:'no-store'});
            if(!result.ok || !result.data || !Array.isArray(result.data.requests)) return false;
            const next={}; result.data.requests.forEach(request=>{if(request&&request.id){const normalized=normalizeLeaveRequestForRoster({...request,_serverAuthoritative:true,serverAuthoritative:true},request.id);if(normalized)next[request.id]=normalized;}});
            allLeaveRequests=next; leaveV3SecureRequestsLoaded=true;
            return true;
        }

        function leaveV3PilotRawValue(key) {
            if (!key || hasPendingDelete(key)) return null;
            const pending = pendingWritePayload(key);
            if (pending !== null) return pending;
            if (fbKvCache && Object.prototype.hasOwnProperty.call(fbKvCache,key)) return fbKvCache[key];
            return safeLocalGet(key);
        }

        function leaveV3PilotKeys(prefix) {
            const keys = new Set(getLocalKeysWithPrefix(prefix).filter(key => !hasPendingDelete(key)));
            if (fbKvCache) Object.keys(fbKvCache).forEach(key => { if (key.startsWith(prefix) && !hasPendingDelete(key)) keys.add(key); });
            getLocalKeysWithPrefix(PENDING_PREFIX+prefix).forEach(pendingKey => {
                const key=pendingKey.slice(PENDING_PREFIX.length); if(key&&!hasPendingDelete(key))keys.add(key);
            });
            return Array.from(keys);
        }

        async function leaveV3LoadPolicy(force = false) {
            if (!force && leavePolicyV3) return leavePolicyV3;
            if (leaveV3ServerCapable) {
                const result = await leaveV3Api('/leave-policy-v3',{method:'GET',cache:'no-store'});
                if (result.ok && result.data) {
                    leavePolicyV3 = leaveV3NormalizePolicy(result.data.policy || null);
                    safeLocalSet(LEAVE_V3_POLICY_KEY,JSON.stringify(leavePolicyV3));
                    return leavePolicyV3;
                }
            }
            try {
                const raw = window.TRINOTIME_LEAVE_FREE_PILOT === true ? leaveV3PilotRawValue(LEAVE_V3_POLICY_KEY) : await appStorage.get(LEAVE_V3_POLICY_KEY);
                if (raw) leavePolicyV3 = leaveV3NormalizePolicy(JSON.parse(raw));
            } catch (e) {}
            if (!leavePolicyV3) leavePolicyV3 = leaveV3NormalizePolicy(null);
            return leavePolicyV3;
        }

        async function leaveV3LoadLedger(force = false) {
            if (leaveV3Loading) return;
            leaveV3Loading = true;
            try {
                if (leaveV3ServerCapable) {
                    const result = await leaveV3Api('/leave-ledger',{method:'GET',cache:'no-store'});
                    if (result.ok && result.data && Array.isArray(result.data.entries)) {
                        const next = {};
                        result.data.entries.forEach(raw => { const entry=leaveV3NormalizeEntry(raw); if(entry && entry.id) next[entry.id]=entry; });
                        allLeaveLedgerV3 = next;
                    }
                    const profiles = await leaveV3Api('/leave-employment-profiles',{method:'GET',cache:'no-store'});
                    if (profiles.ok && profiles.data && profiles.data.profiles) leaveEmploymentProfilesV3 = profiles.data.profiles || {};
                } else {
                    const next = {};
                    const nextProfiles = {};
                    const keys = window.TRINOTIME_LEAVE_FREE_PILOT === true ? leaveV3PilotKeys(LEAVE_V3_LOCAL_LEDGER_PREFIX) : await appStorage.list(LEAVE_V3_LOCAL_LEDGER_PREFIX);
                    for (const key of keys) {
                        try {
                            const raw = window.TRINOTIME_LEAVE_FREE_PILOT === true ? leaveV3PilotRawValue(key) : await appStorage.get(key);
                            const entry = raw ? leaveV3NormalizeEntry(JSON.parse(raw)) : null;
                            if (entry && entry.id) next[entry.id] = entry;
                        } catch (e) {}
                    }
                    allLeaveLedgerV3 = next;
                    const pkeys = window.TRINOTIME_LEAVE_FREE_PILOT === true ? leaveV3PilotKeys(LEAVE_V3_PROFILE_PREFIX) : await appStorage.list(LEAVE_V3_PROFILE_PREFIX);
                    for (const key of pkeys) {
                        try { const raw=window.TRINOTIME_LEAVE_FREE_PILOT === true ? leaveV3PilotRawValue(key) : await appStorage.get(key); if(raw) nextProfiles[key.slice(LEAVE_V3_PROFILE_PREFIX.length)] = JSON.parse(raw); } catch(e){}
                    }
                    leaveEmploymentProfilesV3 = nextProfiles;
                }
            } finally {
                leaveV3Loading = false;
                leaveV3LastLoadedAt = Date.now();
            }
            renderLeaveV3All();
        }

        function leaveV3LocalEntryId(kind, sourceId) {
            return String(kind || 'ENTRY').toLowerCase() + ':' + (sourceId || createMutationToken());
        }

        async function leaveV3PersistLocalEntry(entry) {
            const normalized = leaveV3NormalizeEntry(entry);
            if (!normalized || !normalized.id) throw new Error('Invalid leave ledger entry.');
            if (leaveV3PolicyLocked(normalized.effectiveDate)) throw new Error('This HR leave period is locked through ' + leavePolicyV3.lockedThrough + '. Post a correction in an open period instead.');
            if (allLeaveLedgerV3[normalized.id]) return allLeaveLedgerV3[normalized.id];
            normalized.createdAt = normalized.createdAt || nowIso();
            normalized.immutable = true;
            const payload = JSON.stringify(normalized);
            allLeaveLedgerV3[normalized.id] = normalized;
            safeLocalSet(LEAVE_V3_LOCAL_LEDGER_PREFIX + normalized.id,payload);
            safeLocalSet(PENDING_PREFIX + LEAVE_V3_LOCAL_LEDGER_PREFIX + normalized.id,payload);
            markPendingMutation();
            publishUpdate();
            await appStorage.set(LEAVE_V3_LOCAL_LEDGER_PREFIX + normalized.id,payload).then(result => {
                if (result && result.remoteSaved && safeLocalGet(PENDING_PREFIX + LEAVE_V3_LOCAL_LEDGER_PREFIX + normalized.id) === payload) safeLocalRemove(PENDING_PREFIX + LEAVE_V3_LOCAL_LEDGER_PREFIX + normalized.id);
            }).catch(error => reportAppError('Leave ledger fallback sync',error));
            return normalized;
        }

        async function leaveV3EnsureRequestLedger(request) {
            if (!request || !request.id) return;
            const status = normalizeLeaveStatus(request.status);
            if (leaveV3ServerCapable) { await leaveV3LoadLedger(true); return; }
            const source=String(request.id); const startYear=Number(String(request.startDate||'').slice(0,4)),endYear=Number(String(request.endDate||request.startDate||'').slice(0,4));
            if(status==='APPROVED'){
                for(let year=startYear;year<=endYear;year++){const units=leaveV3RequestUnitsForYear(request,year);if(units<=0)continue;const existing=Object.values(allLeaveLedgerV3).find(entry=>entry&&entry.sourceRequestId===source&&entry.kind==='LEAVE_USAGE'&&Number(entry.year)===year);if(existing)continue;const actor=leaveDecisionActor();const effective=leaveV3UsageEffectiveDateForYear(request,year);await leaveV3PersistLocalEntry({id:leaveV3LocalEntryId('usage',source+':'+year),agentName:request.agentName,agentId:leaveV3AgentId(request.agentName),pod:request.pod,leaveType:request.leaveType,year,effectiveDate:effective,units:-units,kind:'LEAVE_USAGE',sourceRequestId:source,memo:'Approved leave '+source+' · '+year,createdAt:request.decisionAt||nowIso(),createdBy:request.decisionBy||actor.name,createdRole:request.decisionRole||actor.role});}
            }
            if(status==='CANCELLED'){
                const usages=Object.values(allLeaveLedgerV3).filter(entry=>entry&&entry.sourceRequestId===source&&entry.kind==='LEAVE_USAGE');const actor=leaveDecisionActor();
                for(const usage of usages){const existingReverse=Object.values(allLeaveLedgerV3).find(entry=>entry&&entry.kind==='LEAVE_REVERSAL'&&String(entry.voidsEntryId||'')===String(usage.id||''));if(existingReverse)continue;const reversalEffective=String(usage.effectiveDate||request.startDate||leaveV3IsoToday()).slice(0,10);const reversalYear=Number(usage.year)||Number(reversalEffective.slice(0,4));await leaveV3PersistLocalEntry({id:leaveV3LocalEntryId('reversal',source+':'+usage.year),agentName:request.agentName,agentId:leaveV3AgentId(request.agentName),pod:request.pod,leaveType:request.leaveType,year:reversalYear,effectiveDate:reversalEffective,units:Math.abs(usage.units),kind:'LEAVE_REVERSAL',sourceRequestId:source,memo:'Cancellation reversal for '+source+' · '+usage.year,createdAt:nowIso(),createdBy:actor.name,createdRole:actor.role,voidsEntryId:usage.id});}
            }
        }


        function leaveV3ViewerDefaultAgent() {
            const identity = leaveRequesterIdentity();
            if (identity) return identity.name;
            const visible = leaveV3VisibleAgents();
            return leaveV3SelectedAgent || (visible[0] && visible[0].name) || '';
        }

        function leaveV3SelectedBalance() {
            const name = leaveV3SelectedAgent || leaveV3ViewerDefaultAgent();
            const year = Number(leaveV3SelectedYear) || new Date().getFullYear();
            return leaveV3BalanceFor(name,leaveV3SelectedType,year,null);
        }

        function renderLeaveV3BalancePreview() {
            const el = $('leaveV2BalancePreview');
            if (!el) return;
            const identity = leaveRequesterIdentity();
            const type = $('leaveType') ? $('leaveType').value : '';
            const start = $('leaveStartDate') ? $('leaveStartDate').value : '';
            if (!identity || !type) {
                el.innerHTML = '<strong>HR Leave Ledger</strong> Select a leave type to see posted balance, pending reservation, and available leave.';
                return;
            }
            const year = leaveV2YearFromIso(start || mdyToIsoDateInput(todayKeyPart()));
            const balance = leaveV3BalanceFor(identity.name,type,year,null);
            const policy = leaveV3TypePolicy(type);
            const negative = balance.available < 0;
            el.innerHTML = '<strong>' + escapeHtml(type) + ' · ' + year + '</strong> Posted balance <b>' + escapeHtml(leaveV3FormatUnits(balance.postedBalance)) + '</b> · Pending reserved <b>' + escapeHtml(leaveV3FormatUnits(balance.pending)) + '</b> · Available <b' + (negative ? ' style="color:#B91C1C"' : '') + '>' + escapeHtml(leaveV3FormatUnits(balance.available)) + '</b> · Taken <b>' + escapeHtml(leaveV3FormatUnits(balance.used)) + '</b>' + (policy.enforceBalance ? ' · Balance enforcement active' : '');
        }

        function leaveV3PolicyRow(type,index) {
            const p = leaveV3TypePolicy(type);
            const num = (value) => value === null || value === undefined ? '' : String(value);
            return '<tr data-leave-v3-policy-row="' + escapeHtml(type) + '">' +
                '<td><strong>' + escapeHtml(type) + '</strong></td>' +
                '<td><input type="checkbox" data-v3-policy="tracked" ' + (p.tracked ? 'checked' : '') + '></td>' +
                '<td><input type="checkbox" data-v3-policy="paid" ' + (p.paid ? 'checked' : '') + '></td>' +
                '<td><select data-v3-policy="accrualMode">' + LEAVE_V3_ACCRUAL_MODES.map(mode => '<option value="'+mode+'" '+(p.accrualMode===mode?'selected':'')+'>'+mode.replace('_',' ')+'</option>').join('') + '</select></td>' +
                '<td><input type="number" min="0" step="0.01" data-v3-policy="annualEntitlement" value="' + num(p.annualEntitlement) + '" placeholder="—"></td>' +
                '<td><input type="number" min="0" step="0.0001" data-v3-policy="accrualAmount" value="' + num(p.accrualAmount) + '" placeholder="auto"></td>' +
                '<td><input type="number" min="1" max="60" step="1" data-v3-policy="payPeriodDays" value="' + num(p.payPeriodDays) + '"></td>' +
                '<td><input type="number" min="0" step="0.01" data-v3-policy="cap" value="' + num(p.cap) + '" placeholder="none"></td>' +
                '<td><input type="number" min="0" step="0.01" data-v3-policy="carryoverCap" value="' + num(p.carryoverCap) + '" placeholder="0"></td>' +
                '<td><input type="number" min="1" step="1" data-v3-policy="expirationMonths" value="' + num(p.expirationMonths) + '" placeholder="none"></td>' +
                '<td><input type="number" min="0" step="1" data-v3-policy="eligibilityDays" value="' + num(p.eligibilityDays) + '"></td>' +
                '<td><input type="checkbox" data-v3-policy="prorateFirstYear" ' + (p.prorateFirstYear ? 'checked' : '') + '></td>' +
                '<td><input type="checkbox" data-v3-policy="reservePending" ' + (p.reservePending ? 'checked' : '') + '></td>' +
                '<td><input type="checkbox" data-v3-policy="enforceBalance" ' + (p.enforceBalance ? 'checked' : '') + '></td>' +
                '<td><input type="checkbox" data-v3-policy="allowNegative" ' + (p.allowNegative ? 'checked' : '') + '></td>' +
                '</tr>';
        }

