            results.push(productionDiagnosticResult('Agent','agent-roster','Agent roster identity and POD contract', duplicateAgents.length || invalidAgentPods.length ? 'fail' : 'pass', duplicateAgents.length || invalidAgentPods.length ? `${duplicateAgents.length} duplicate/blank name issue(s); ${invalidAgentPods.length} invalid POD assignment(s).` : `${roster.length} Agent roster entries have unique names and valid POD assignments.`));
            results.push(productionDiagnosticResult('Agent','agent-credentials','Agent credential record integrity', invalidCredentialAgents.length ? 'fail' : (missingCredentialAgents.length ? 'warn' : 'pass'), invalidCredentialAgents.length ? `${invalidCredentialAgents.length} invalid credential record(s): ${invalidCredentialAgents.slice(0,5).join(', ')}` : (missingCredentialAgents.length ? `${missingCredentialAgents.length} Agent account(s) still need initial credential setup.` : 'Configured Agent credential records parse successfully.')));
            results.push(productionDiagnosticResult('Agent','password-policy','Password hashing policy', PASSWORD_HASH_ALGORITHM === 'PBKDF2-SHA256' && PASSWORD_HASH_ITERATIONS >= 600000 ? 'pass' : 'fail', `${PASSWORD_HASH_ALGORITHM} / ${PASSWORD_HASH_ITERATIONS.toLocaleString('en-US')} iterations.`));

