async function leaveV25ConfirmTlApproval() {
const id = leaveV2DecisionRequestId;
const request = id ? allLeaveRequests[id] : null;
const note = String($('leaveV2DecisionNote') ? $('leaveV2DecisionNote').value : '').trim();
const error = $('leaveV2DecisionError');
if (!request || leaveV2DecisionAction !== 'APPROVED') return;
if (note.length < 2) { if(error){error.textContent='A decision note is required for approval.';error.classList.add('show');} return; }
const options = leaveV25DecisionCoverageOptions();
const btn = $('leaveV2DecisionSave'); if (btn) btn.disabled=true;
try {
await updateLeaveRequestStatus(id,'APPROVED',note,options);
closeLeaveV2DecisionModal();
} catch (e) {
if (error) { error.textContent=getErrorMessage(e); error.classList.add('show'); }
leaveV25RefreshDecisionCoverageUi();
} finally {
if (btn && leaveV2DecisionRequestId) leaveV25RefreshDecisionCoverageUi();
}
}
const leaveV25LegacyUpdateLeaveStatus = updateLeaveRequestStatus;
updateLeaveRequestStatus = async function(id,nextStatus,decisionNote='',decisionOptions={}) {
const current = allLeaveRequests[id];
const status = normalizeLeaveStatus(nextStatus);
let coveragePatch = {};
if (current && status === 'APPROVED' && leaveRequestSubjectRole(current) === 'teamleader') {
coveragePatch = leaveV25CoverageDecisionPatch(current,decisionOptions || {});
allLeaveRequests[id] = { ...current, ...coveragePatch };
}
try {
const result = await leaveV25LegacyUpdateLeaveStatus(id,nextStatus,decisionNote);
const next = allLeaveRequests[id] || result;
if (next && Object.keys(coveragePatch).length) {
Object.assign(next,coveragePatch);
allLeaveRequests[id] = next;
try { await saveLeaveRequest(next); } catch (e) { reportAppError('Leave coverage sync',e); }
void logAudit('leave_coverage_assigned', { requestId:id, name:next.agentName || '', pod:leaveRequestEffectivePod(next), backupTeamLeader:next.coverageTlName || '', backupPod:next.coverageTlPod || '', coverageStatus:next.coverageStatusAtDecision || '', gapAcknowledged:next.coverageGapAcknowledged === true });
}
renderLeaveV25Calendar();
return next;
} catch (error) {
if (current && allLeaveRequests[id] && normalizeLeaveStatus(allLeaveRequests[id].status) === normalizeLeaveStatus(current.status)) allLeaveRequests[id] = current;
throw error;
}
};
